<?php
/**
 * HTML.PHP — production template-processing library.
 *
 * VERSION: 5.0.0 (PHP 8.5 edition) — single-file build.
 *
 * A zero-dependency template engine + Apache SSI processor + gettext i18n:
 *  - `%{NAME|filters}` substitution with auto-escaping, loops, expression
 *    conditionals, layout inheritance, scoped partials, translation blocks;
 *  - full mod_include SSI: #config #set #include(stub/wait) #echo(encoding)
 *    #if/#elif/#else #exec(policy-gated) #fsize #flastmod #printenv #block;
 *  - i18n: PO/MO/JSON/PHP catalogues, 60+ plural rules, contexts, domains,
 *    fallback chains, extraction + audit tooling;
 *  - immutable Config object, DI container, PSR-shaped cache/log/event
 *    contracts, render cache, diagnostics, linter, profiling — NO globals;
 *  - optional WordPress bridge + maintenance toolkit (HtmlPhp\WordPress\*).
 *
 * Generated by tools/build.php from the PSR-4 source tree — do not edit.
 * Source, docs and tests: https://github.com/paulmann/HTML.PHP
 *
 * Author:  Mikhail Deynekin
 * Site:    https://Deynekin.com
 * License: MIT
 */

namespace {
    if (PHP_VERSION_ID < 80500) {
        fwrite(STDERR, sprintf(
            "HTML.PHP 5.0.0 (8.5 edition) requires PHP 8.5 or newer; running %s." . PHP_EOL,
            PHP_VERSION
        ));

        if (PHP_SAPI === 'cli') {
            exit(1);
        }

        http_response_code(500);
        exit;
    }
}

namespace HtmlPhp\Exception {

/** Cache operation failure. */
final class CacheException extends HtmlPhpException {}

/** Invalid configuration. */
final class ConfigException extends HtmlPhpException {}

/** Service container failure. */
final class ContainerException extends HtmlPhpException {}

/**
 * Base class of every exception thrown by the library.
 *
 * Carries a structured `context` map (template name, line, directive, …)
 * so logs and the WordPress admin screen can show actionable detail. In
 * debug mode the context is appended to the message; in production it is
 * available programmatically only.
 */
class HtmlPhpException extends \RuntimeException
{
    /** @param array<string, mixed> $context */
    public function __construct(
        string $message,
        public readonly array $context = [],
        int $code = 0,
        ?\Throwable $previous = null,
    ) {
        parent::__construct($message, $code, $previous);
    }

    /**
     * Re-throws with extra context merged in (fluent helper for catch sites).
     * Every concrete subclass is final, so `new static` is safe.
     *
     * @param array<string, mixed> $context
     */
    public function withContext(array $context): static
    {
        // @phpstan-ignore new.static
        return new static(
            $this->getMessage(),
            array_merge($this->context, $context),
            (int) $this->getCode(),
            $this->getPrevious(),
        );
    }

    /** Human-readable one-liner including context, safe for logs. */
    public function describe(): string
    {
        if ($this->context === []) {
            return $this->getMessage();
        }

        $pairs = [];
        foreach ($this->context as $key => $value) {
            $pairs[] = $key . '=' . (\is_scalar($value) || $value === null
                ? var_export($value, true)
                : (json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) ?: '?'));
        }

        return $this->getMessage() . ' [' . implode(' ', $pairs) . ']';
    }
}

/** Internationalisation failure. */
final class I18nException extends HtmlPhpException {}

/** Filesystem operation failure. */
final class IoException extends HtmlPhpException {}

/** Regular expression failure. */
final class RegexException extends HtmlPhpException {}

/** SSI processing failure. */
final class SsiException extends HtmlPhpException {}

/** Template processing failure. */
class TemplateException extends HtmlPhpException {}

/** Template could not be located. */
final class TemplateNotFoundException extends TemplateException {}

/** Invalid template syntax. */
final class TemplateSyntaxException extends TemplateException {}

}

namespace HtmlPhp\Support {

use HtmlPhp\Exception\RegexException;

/**
 * Time source abstraction.
 *
 * Injected wherever "now" is needed (SSI built-ins, date filters, cache
 * expiry) so behaviour is deterministic in tests and long-running workers.
 */
interface ClockInterface
{
    /** Current UNIX timestamp. */
    public function now(): int;

    /** Current time as an immutable DateTime in the given timezone. */
    public function dateTime(?string $timezone = null): \DateTimeImmutable;
}

/**
 * Manually controlled clock for tests, CLI tooling and cache warm-up.
 */
final class FrozenClock implements ClockInterface
{
    public function __construct(private int $timestamp) {}

    public function set(int $timestamp): void
    {
        $this->timestamp = $timestamp;
    }

    public function advance(int $seconds): void
    {
        $this->timestamp += $seconds;
    }

    public function now(): int
    {
        return $this->timestamp;
    }

    public function dateTime(?string $timezone = null): \DateTimeImmutable
    {
        return (new \DateTimeImmutable('@' . $this->timestamp))
            ->setTimezone(new \DateTimeZone($timezone === null || $timezone === '' ? date_default_timezone_get() : $timezone));
    }
}

/**
 * PCRE wrappers that never return `null`.
 *
 * A failed match is a template bug or a ReDoS attempt; both surface as
 * {@see RegexException} instead of a silent `null` that callers forget to
 * check. `match()` is the exception: it reports "no match" and lets the
 * caller decide, because user-supplied data legitimately fails to match.
 */
final class Pcre
{
    private function __construct() {}

    /**
     * `preg_replace_callback()` that throws on PCRE failure.
     *
     * @param callable(array<array-key, string|null>): string $callback
     */
    public static function replaceCallback(string $pattern, callable $callback, string $subject, int $limit = -1): string
    {
        $result = preg_replace_callback($pattern, $callback, $subject, $limit);

        return $result ?? throw self::failure($pattern);
    }

    /** `preg_replace()` that throws on PCRE failure. */
    public static function replace(string $pattern, string $replacement, string $subject, int $limit = -1): string
    {
        $result = preg_replace($pattern, $replacement, $subject, $limit);

        return $result ?? throw self::failure($pattern);
    }

    /**
     * `preg_match()` where a PCRE error means "no match" (never `false`).
     *
     * @param array<array-key, string|null> $matches
     */
    public static function match(string $pattern, string $subject, array &$matches = []): bool
    {
        $result = @preg_match($pattern, $subject, $matches);

        if ($result === false) {
            $matches = [];

            return false;
        }

        return $result === 1;
    }

    /**
     * `preg_match_all()` where a PCRE error means "zero matches".
     *
     * @param array<array-key, array<array-key, string|null>> $matches
     */
    public static function matchAll(string $pattern, string $subject, array &$matches = []): int
    {
        $result = @preg_match_all($pattern, $subject, $matches);

        if ($result === false) {
            $matches = [];

            return 0;
        }

        return $result;
    }

    /**
     * Applies a Unicode pattern and retries with a byte-safe pattern when
     * the subject is not valid UTF-8 (legacy normalize()/cleanHtml() input).
     */
    public static function replaceUnicode(
        string $unicodePattern,
        string $bytePattern,
        string $replacement,
        string $subject,
    ): string {
        $result = preg_replace($unicodePattern, $replacement, $subject);

        if ($result !== null) {
            return $result;
        }

        $result = preg_replace($bytePattern, $replacement, $subject);

        return $result ?? $subject;
    }

    /**
     * `preg_split()` that throws on PCRE failure.
     *
     * @return list<string>
     */
    public static function split(string $pattern, string $subject, int $limit = -1, int $flags = 0): array
    {
        $result = preg_split($pattern, $subject, $limit, $flags);

        return $result === false ? throw self::failure($pattern) : $result;
    }

    /** True when the pattern compiles (used by `lint`). */
    public static function isValid(string $pattern): bool
    {
        return @preg_match($pattern, '') !== false;
    }

    private static function failure(string $pattern): RegexException
    {
        return new RegexException(
            'Regular expression failed: ' . preg_last_error_msg(),
            ['pattern' => Pcre::safePattern($pattern)],
        );
    }

    private static function safePattern(string $pattern): string
    {
        return Str::length($pattern) > 200 ? Str::substr($pattern, 0, 200) . '…' : $pattern;
    }
}

/**
 * Stateless string helpers.
 *
 * Every method is pure: no configuration, no globals, no I/O. Callers that
 * need policy (precision caps, transliteration maps) pass it in.
 */
final class Str
{
    /** Fallback transliteration used by {@see self::slugify()} without intl. */
    public const TRANSLITERATION = [
        'а' => 'a', 'б' => 'b', 'в' => 'v', 'г' => 'g', 'д' => 'd',
        'е' => 'e', 'ё' => 'e', 'ж' => 'zh', 'з' => 'z', 'и' => 'i',
        'й' => 'y', 'к' => 'k', 'л' => 'l', 'м' => 'm', 'н' => 'n',
        'о' => 'o', 'п' => 'p', 'р' => 'r', 'с' => 's', 'т' => 't',
        'у' => 'u', 'ф' => 'f', 'х' => 'h', 'ц' => 'c', 'ч' => 'ch',
        'ш' => 'sh', 'щ' => 'sch', 'ъ' => '', 'ы' => 'y', 'ь' => '',
        'э' => 'e', 'ю' => 'yu', 'я' => 'ya',
        'і' => 'i', 'ї' => 'yi', 'є' => 'ye', 'ґ' => 'g',
        'ў' => 'u', 'ђ' => 'dj', 'ј' => 'j', 'љ' => 'lj', 'њ' => 'nj',
        'ћ' => 'c', 'џ' => 'dz',
        'ä' => 'ae', 'ö' => 'oe', 'ü' => 'ue', 'ß' => 'ss',
        'å' => 'a', 'æ' => 'ae', 'ø' => 'o',
        'ç' => 'c', 'é' => 'e', 'è' => 'e', 'ê' => 'e', 'ë' => 'e',
        'à' => 'a', 'á' => 'a', 'â' => 'a', 'ã' => 'a', 'î' => 'i',
        'ï' => 'i', 'í' => 'i', 'ó' => 'o', 'ô' => 'o', 'õ' => 'o',
        'ú' => 'u', 'ù' => 'u', 'û' => 'u', 'ñ' => 'n', 'ł' => 'l',
        'ą' => 'a', 'ć' => 'c', 'ę' => 'e', 'ń' => 'n',
        'ś' => 's', 'ź' => 'z', 'ż' => 'z', 'ő' => 'o', 'ű' => 'u',
        'š' => 's', 'ž' => 'z', 'č' => 'c', 'ř' => 'r', 'ď' => 'd',
        'ť' => 't', 'ň' => 'n', 'ě' => 'e', 'ů' => 'u',
    ];

    private const MAX_PRECISION = 100;

    /**
     * Hard iteration budget for aggregate walks (`sum`/`avg`/`count` over
     * `Traversable`) — an infinite generator from host code must not hang
     * a render. Mirrors the expression language's loop-range cap.
     */
    public const int MAX_AGGREGATE_ITEMS = 100_000;

    private function __construct() {}

    /**
     * Converts any template value to a string without emitting notices.
     *
     * Arrays and resources become `''`; floats keep up to 14 significant
     * decimals with trailing zeroes trimmed; booleans become `'1'`/`''`.
     */
    public static function stringify(mixed $value): string
    {
        return match (true) {
            $value === null => '',
            \is_string($value) => $value,
            \is_int($value) => (string) $value,
            \is_float($value) => is_finite($value)
                ? rtrim(rtrim(number_format($value, 14, '.', ''), '0'), '.')
                : '',
            \is_bool($value) => $value ? '1' : '',
            $value instanceof \Stringable => (string) $value,
            $value instanceof \BackedEnum => self::stringify($value->value),
            default => '',
        };
    }

    /**
     * Parses numbers written with dot or comma decimals and the usual group
     * separators (`1 234 567,89`, `1,234,567.89`, `1'234'567.89`).
     */
    public static function numericValue(mixed $value): float
    {
        if (\is_int($value) || \is_float($value)) {
            return is_finite((float) $value) ? (float) $value : 0.0;
        }

        if (!\is_string($value)) {
            return 0.0;
        }

        $number = str_replace(
            [' ', "\t", "\r", "\n", "\v", "\f", "\u{00A0}", "\u{202F}", "\u{2009}", "'"],
            '',
            trim($value),
        );

        if ($number === '') {
            return 0.0;
        }

        $number = self::normalizeSeparators($number);

        if (preg_match('/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?/', $number, $m) !== 1) {
            return 0.0;
        }

        $result = (float) $m[0];

        return is_finite($result) ? $result : 0.0;
    }

    private static function normalizeSeparators(string $number): string
    {
        $lastComma = strrpos($number, ',');
        $lastDot = strrpos($number, '.');

        if ($lastComma !== false && $lastDot !== false) {
            return $lastComma > $lastDot
                ? str_replace(',', '.', str_replace('.', '', $number))
                : str_replace(',', '', $number);
        }

        if ($lastComma === false) {
            return $number;
        }

        $parts = explode(',', $number);

        // Three comma groups of exactly three digits are thousands separators.
        return \count($parts) > 2 && \strlen((string) end($parts)) === 3
            ? str_replace(',', '', $number)
            : str_replace(',', '.', $number);
    }

    /** True when the trimmed string is a finite decimal literal. */
    public static function isNumericString(string $value): bool
    {
        return preg_match('/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/', trim($value)) === 1;
    }

    /**
     * Returns a bounded decimal precision (0 … 100). Only integers and
     * digit-strings count; everything else degrades to 0.
     */
    public static function precision(mixed $precision): int
    {
        $value = \is_int($precision) || (\is_string($precision) && preg_match('/^\d+$/', $precision) === 1)
            ? (int) $precision
            : 0;

        return max(0, min(self::MAX_PRECISION, $value));
    }

    /**
     * Divides two values, returning 0 for a zero divisor or non-finite
     * results (html4.pl `Divide()` semantics, kept as a pure utility).
     */
    public static function divide(mixed $a, mixed $b): float|int
    {
        $left = self::numericValue($a);
        $right = self::numericValue($b);

        if ($right === 0.0) {
            return 0;
        }

        $result = $left / $right;

        return is_finite($result) ? $result : 0;
    }

    /**
     * Exponentiation with the same fail-safe semantics as {@see self::divide()}:
     * overflow (`10 ** 9999`), `0 ** -1` and `sqrt`-style `NAN` results
     * (negative base, fractional exponent) all degrade to `0.0` instead of
     * poisoning downstream arithmetic with `INF`/`NAN`.
     */
    public static function power(float $base, float $exponent): float
    {
        if (!is_finite($base) || !is_finite($exponent)) {
            return 0.0;
        }

        if ($base === 0.0 && $exponent < 0) {
            return 0.0; // PHP yields INF; a template dividing by zero is a bug, not a number
        }

        $result = $base ** $exponent;

        return is_finite($result) ? $result : 0.0;
    }

    /** Square root; negative and non-finite inputs degrade to `0.0`. */
    public static function sqrt(float $value): float
    {
        return $value > 0.0 && is_finite($value) ? sqrt($value) : 0.0;
    }

    /**
     * Sums and counts any template value in one capped pass.
     *
     * Arrays and `Traversable`s are walked (each item coerced through
     * {@see self::numericValue()}); scalars count as a single item; `null`
     * counts as nothing. The iteration cap keeps an infinite generator
     * passed from host code from hanging the render — the same budget the
     * expression language applies to loop ranges.
     *
     * @return array{0: float, 1: int} `[sum, count]`, count capped at {@see self::MAX_AGGREGATE_ITEMS}
     */
    public static function accumulate(mixed $value): array
    {
        if (\is_array($value) || $value instanceof \Traversable) {
            $sum = 0.0;
            $count = 0;

            foreach ($value as $item) {
                if ($count >= self::MAX_AGGREGATE_ITEMS) {
                    break;
                }

                $sum += self::numericValue($item);
                $count++;
            }

            return [is_finite($sum) ? $sum : 0.0, $count];
        }

        if ($value === null) {
            return [0.0, 0];
        }

        return [self::numericValue($value), 1];
    }

    /** `number_format()` with a dot decimal and no `-0` artefacts. */
    public static function round(float $value, mixed $precision = 0): string
    {
        $digits = self::precision($precision);
        $value = is_finite($value) ? $value : 0.0;
        $formatted = number_format($value, $digits, '.', '');

        return self::fixNegativeZero($formatted, $digits, '.');
    }

    /** Like {@see self::round()} but drops the fraction for whole numbers. */
    public static function cleanRound(float $value, mixed $precision = 0): string
    {
        if (!is_finite($value)) {
            return '0';
        }

        if (fmod($value, 1.0) === 0.0) {
            $integer = number_format($value, 0, '.', '');

            return $integer === '-0' ? '0' : $integer;
        }

        return self::round($value, self::precision($precision));
    }

    /** `number_format()` with caller-chosen separators and no `-0` artefacts. */
    public static function number(
        float $value,
        int $decimals = 2,
        string $decimalPoint = '.',
        string $thousandsSeparator = ',',
    ): string {
        $decimals = max(0, min(20, $decimals));
        $value = is_finite($value) ? $value : 0.0;

        return self::fixNegativeZero(
            number_format($value, $decimals, $decimalPoint, $thousandsSeparator),
            $decimals,
            $decimalPoint,
        );
    }

    private static function fixNegativeZero(string $formatted, int $decimals, string $point): string
    {
        if (preg_match('/^-0(?:\.0+)?$/', $formatted) !== 1) {
            return $formatted;
        }

        return $decimals > 0 ? '0' . $point . str_repeat('0', $decimals) : '0';
    }

    /**
     * Truncates to at most `$length` characters on a word boundary when
     * possible; multibyte-safe when mbstring is available. `$suffix` is
     * appended only when something was removed.
     */
    public static function truncate(string $text, int $length = 80, string $suffix = '…'): string
    {
        $length = max(1, $length);

        if (self::hasMb()) {
            if (mb_strlen($text, 'UTF-8') <= $length) {
                return $text;
            }

            $cut = mb_substr($text, 0, $length, 'UTF-8');
            $space = mb_strrpos($cut, ' ', 0, 'UTF-8');

            if ($space !== false && $space > intdiv($length, 2)) {
                $cut = mb_substr($cut, 0, $space, 'UTF-8');
            }

            return rtrim($cut, " \t\n\r\0\x0B.,;:!?") . $suffix;
        }

        if (\strlen($text) <= $length) {
            return $text;
        }

        $cut = substr($text, 0, $length);
        $space = strrpos($cut, ' ');

        if ($space !== false && $space > intdiv($length, 2)) {
            $cut = substr($cut, 0, $space);
        }

        return rtrim($cut, " \t\n\r\0\x0B.,;:!?") . $suffix;
    }

    /** Character count, multibyte-aware. */
    public static function length(string $text): int
    {
        return self::hasMb() ? mb_strlen($text, 'UTF-8') : \strlen($text);
    }

    /** Substring, multibyte-aware (`null` length means "to the end"). */
    public static function substr(string $text, int $start, ?int $length = null): string
    {
        return self::hasMb()
            ? mb_substr($text, $start, $length, 'UTF-8')
            : substr($text, $start, $length);
    }

    public static function upper(string $text): string
    {
        return self::hasMb() ? mb_strtoupper($text, 'UTF-8') : strtoupper($text);
    }

    public static function lower(string $text): string
    {
        return self::hasMb() ? mb_strtolower($text, 'UTF-8') : strtolower($text);
    }

    public static function ucfirst(string $text): string
    {
        if ($text === '') {
            return '';
        }

        if (\function_exists('mb_ucfirst')) {
            return mb_ucfirst($text, 'UTF-8');
        }

        return self::hasMb()
            ? mb_strtoupper(mb_substr($text, 0, 1, 'UTF-8'), 'UTF-8') . mb_substr($text, 1, null, 'UTF-8')
            : ucfirst($text);
    }

    /** Title-cases every word, multibyte-aware. */
    public static function words(string $text): string
    {
        if (!self::hasMb()) {
            return ucwords($text);
        }

        return (string) preg_replace_callback(
            '/[\p{L}\p{N}]+/u',
            static fn(array $m): string => self::ucfirst($m[0]),
            $text,
        );
    }

    private static function hasMb(): bool
    {
        return \function_exists('mb_strlen');
    }

    /**
     * URL slug: lower-case, apply the built-in transliteration map, collapse
     * everything outside `[a-z0-9]` into `$separator`.
     *
     * Deterministic by contract: the map runs **before** any ICU call, so
     * every character the map covers (Cyrillic + common European letters)
     * produces the same slug whether or not `ext-intl` is loaded — slugs end
     * up in URLs and storage, and must not depend on the host. ICU
     * (`Any-Latin; Latin-ASCII; Lower()`) is consulted only when non-ASCII
     * characters remain, i.e. for scripts the map does not cover (Greek,
     * Georgian, …); without intl those are stripped like any other
     * non-`[a-z0-9]` character.
     */
    public static function slugify(string $text, string $separator = '-'): string
    {
        $text = trim($text);

        if ($text === '') {
            return '';
        }

        $separator = $separator === '' ? '-' : $separator;

        // 1. Deterministic core: lower-case, then the built-in map. Map
        //    coverage wins over ICU so the result never depends on ext-intl.
        $text = strtr(self::lower($text), self::TRANSLITERATION);

        // 2. ICU fallback for scripts the map does not cover, only while
        //    non-ASCII characters remain (the `@` guards E_WARNING on
        //    malformed UTF-8 input — transliterate() returns false then).
        if ($text !== '' && preg_match('/[^\x00-\x7F]/', $text) === 1
            && \function_exists('transliterator_transliterate')
        ) {
            /** @var string|false $converted */
            $converted = @transliterator_transliterate(
                'Any-Latin; Latin-ASCII; Lower()',
                $text,
            );

            if (\is_string($converted) && $converted !== '') {
                $text = $converted;
            }
        }

        $text = (string) preg_replace('~[^a-z0-9]+~', $separator, $text);
        $text = trim($text, $separator);

        return $text !== '' ? $text : 'n-a';
    }

    /**
     * Keeps only Unicode letters, digits and `_` (legacy `TrimSpaces`).
     */
    public static function keepWordChars(string $text): string
    {
        $result = preg_replace('/[^\p{L}\p{N}_]+/u', '', $text);

        if ($result !== null) {
            return $result;
        }

        // Invalid UTF-8: fall back to a byte-safe ASCII filter.
        return (string) preg_replace('/[^A-Za-z0-9_]+/', '', $text);
    }

    /**
     * Checks whether a template variable name is syntactically safe.
     * Allows `NAME`, `NAME_1`, `Translate.NAME`, `user.name`; rejects empty
     * names, null bytes, path-like names and superglobal tricks.
     */
    public static function isValidVariableName(string $name): bool
    {
        if ($name === '' || str_contains($name, "\0")) {
            return false;
        }

        return preg_match('/^[A-Za-z_][A-Za-z0-9_.-]{0,127}$/', $name) === 1;
    }

    /**
     * Normalises the legacy entity subset used by html4.pl: hex entities
     * become decimal, an optional map renames selected decimal entities and
     * a handful of Latin-1 entities are folded into plain text.
     *
     * @param array<string, string>|null $map decimal-entity-number => name
     */
    public static function normalizeEntities(string $text, ?array $map = null): string
    {
        $text = Pcre::replaceCallback(
            '~&#x([0-9A-Fa-f]{1,6});~',
            static fn(array $matches): string => '&#' . hexdec($matches[1]) . ';',
            $text,
        );

        $text = Pcre::replaceCallback(
            '~&#(\d{1,7});~',
            static function (array $matches) use ($map): string {
                $number = $matches[1];

                if (\is_array($map) && isset($map[$number])) {
                    return '&' . self::stringify($map[$number]) . ';';
                }

                return '&#' . $number . ';';
            },
            $text,
        );

        return str_ireplace(['&thorn;', '&eth;', '&szlig;', '&nbsp;'], ['th', 'd', 'ss', ' '], $text);
    }

    /**
     * Formats a byte size Apache-style (`abbrev`: `12K`, `1.2M`) or as exact
     * bytes — the engine behind SSI `#fsize` and `#config sizefmt`.
     */
    public static function formatSize(int $bytes, string $style = 'abbrev'): string
    {
        if ($bytes < 0) {
            $bytes = 0;
        }

        if (strtolower($style) === 'bytes') {
            return (string) $bytes;
        }

        if ($bytes < 1024) {
            return (string) $bytes;
        }

        $units = ['K', 'M', 'G', 'T'];
        $value = (float) $bytes;
        $unit = '';

        foreach ($units as $unit) {
            $value /= 1024.0;

            if ($value < 1024.0) {
                break;
            }
        }

        // Apache prints "12K" but "1.2M": one decimal from megabytes up.
        $formatted = $unit === 'K'
            ? number_format(ceil($value * 10.0) / 10.0, $value < 10.0 ? 1 : 0, '.', '')
            : number_format($value, 1, '.', '');

        return rtrim(rtrim($formatted, '0'), '.') . $unit;
    }

    /**
     * Recursively applies `htmlspecialchars()` to a string or nested array
     * (the v3 `sanitizeXSS()` behaviour, without touching superglobals).
     *
     * @param array<array-key, mixed>|string $input
     * @return array<array-key, mixed>|string
     */
    public static function sanitizeRecursive(array|string $input): array|string
    {
        if (\is_string($input)) {
            return htmlspecialchars($input, ENT_QUOTES | ENT_SUBSTITUTE | ENT_HTML5, 'UTF-8');
        }

        $result = [];

        foreach ($input as $key => $value) {
            $result[$key] = \is_array($value) || \is_string($value)
                ? self::sanitizeRecursive($value)
                : $value;
        }

        return $result;
    }
}

/** Wall-clock time source for production use. */
final class SystemClock implements ClockInterface
{
    public function now(): int
    {
        return time();
    }

    public function dateTime(?string $timezone = null): \DateTimeImmutable
    {
        return $timezone === null || $timezone === ''
            ? new \DateTimeImmutable()
            : new \DateTimeImmutable('now', new \DateTimeZone($timezone));
    }
}

}

namespace HtmlPhp\Contracts {

/**
 * Render-cache backend contract (PSR-16 shaped, strings only).
 *
 * Implementations: {@see \HtmlPhp\Cache\FileCache}, ArrayCache, ApcuCache,
 * NullCache, Psr16Adapter and the WordPress object-cache adapter.
 */
interface CacheInterface
{
    /** Returns the stored value or `null` on miss/expiry. */
    public function get(string $key): ?string;

    /** Stores `$value` for `$ttl` seconds (`0` = backend default). */
    public function set(string $key, string $value, int $ttl = 0): bool;

    public function has(string $key): bool;

    public function delete(string $key): bool;

    /** Removes every entry of this backend; returns how many were dropped. */
    public function clear(): int;
}

}

namespace HtmlPhp\Config {

use HtmlPhp\Config;
use HtmlPhp\Exception\ConfigException;

/**
 * Render-cache options. The concrete backend is chosen by `driver`; hosts
 * needing something exotic register their own
 * {@see \HtmlPhp\Contracts\CacheInterface} in the container instead.
 */
final readonly class Cache
{
    public function __construct(
        public bool $enabled = false,
        public CacheDriver $driver = CacheDriver::File,
        public string $directory = '',
        public int $ttl = 0,
        public string $prefix = 'htmlphp',
        public bool $lockWrites = true,
        public bool $hardenDirectory = true,
    ) {
        if ($ttl < 0 || $ttl > 86400 * 30) {
            throw new \HtmlPhp\Exception\ConfigException(
                'cache.ttl must be between 0 and 30 days (seconds).',
                ['value' => $ttl],
            );
        }
    }

    /** @param array<string, mixed> $config */
    public static function fromArray(array $config): self
    {
        $driver = (string) Config::value($config, 'driver', CacheDriver::File->value);

        return new self(
            enabled: Config::bool($config, 'enabled', false),
            driver: CacheDriver::tryFrom($driver)
                ?? throw new \HtmlPhp\Exception\ConfigException(
                    'cache.driver must be one of: null, array, file, apcu, wordpress.',
                    ['value' => $driver],
                ),
            directory: (string) Config::value($config, 'directory', ''),
            ttl: Config::int($config, 'ttl', 0),
            prefix: (string) Config::value($config, 'prefix', 'htmlphp'),
            lockWrites: Config::bool($config, 'lock_writes', true),
            hardenDirectory: Config::bool($config, 'harden_directory', true),
        );
    }

    /** @return array<string, mixed> */
    public function toArray(): array
    {
        return [
            'enabled' => $this->enabled,
            'driver' => $this->driver->value,
            'directory' => $this->directory,
            'ttl' => $this->ttl,
            'prefix' => $this->prefix,
            'lock_writes' => $this->lockWrites,
            'harden_directory' => $this->hardenDirectory,
        ];
    }

    public const array KEYS = [
        'enabled', 'driver', 'directory', 'ttl', 'prefix', 'lock_writes', 'harden_directory',
    ];
}

/**
 * Render-cache backends shipped with the library.
 *
 * `WordPress` resolves to the object-cache/transient adapter and is only
 * usable inside WordPress; the container throws a clear error otherwise.
 * Custom backends are registered by putting any
 * {@see \HtmlPhp\Contracts\CacheInterface} implementation into the container.
 */
enum CacheDriver: string
{
    case Null = 'null';
    case Array = 'array';
    case File = 'file';
    case Apcu = 'apcu';
    case WordPress = 'wordpress';
}

/**
 * How `<!--#exec cmd="…"-->` and `<!--#exec cgi="…"-->` are handled.
 *
 * `Deny` is the default: a template is data, not a shell prompt. Allow-list
 * still refuses anything not matched by an explicit pattern.
 */
enum ExecMode: string
{
    /** Refuse every `#exec`, emit `errmsg` and record a diagnostic. */
    case Deny = 'deny';

    /** Run only commands/CGI paths matching the configured allow-list. */
    case AllowList = 'allow-list';

    /** Delegate the decision to a host-supplied callable. */
    case Delegate = 'delegate';
}

/**
 * Internationalisation options.
 */
final readonly class I18n
{
    /**
     * @param list<string> $fallback locale fallback chain, most specific first
     * @param list<string> $paths directories scanned for catalogues using the
     *        `{domain}-{locale}.{mo|po|php|json}`, `{locale}.{mo|po|php|json}`
     *        or `{locale}/LC_MESSAGES/{domain}.{mo|po}` conventions
     * @param bool|null $useWordPress `null` = auto-detect (delegate when the
     *        WP translation functions exist), `true`/`false` force the choice
     */
    public function __construct(
        public string $locale = 'en',
        public array $fallback = ['en'],
        public string $domain = 'messages',
        public array $paths = [],
        public bool $detect = false,
        public ?bool $useWordPress = null,
        public int $numberDecimals = 2,
        public string $decimalPoint = '.',
        public string $thousandsSeparator = ',',
        public string $dateFormat = 'Y-m-d',
        public string $timeFormat = 'H:i',
        public string $dateTimeFormat = 'Y-m-d H:i',
    ) {}

    /** @param array<string, mixed> $config */
    public static function fromArray(array $config): self
    {
        $useWp = Config::nullableBool($config, 'use_wordpress');

        return new self(
            locale: \HtmlPhp\I18n\Locale::normalize((string) Config::value($config, 'locale', 'en')),
            fallback: array_map(
                static fn(string $locale): string => \HtmlPhp\I18n\Locale::normalize($locale),
                Config::stringList($config, 'fallback') ?: ['en'],
            ),
            domain: (string) Config::value($config, 'domain', 'messages'),
            paths: array_values(array_map(strval(...), Config::arrayValue($config, 'paths', []))),
            detect: Config::bool($config, 'detect', false),
            useWordPress: $useWp,
            numberDecimals: Config::int($config, 'number_decimals', 2),
            decimalPoint: (string) Config::value($config, 'decimal_point', '.'),
            thousandsSeparator: (string) Config::value($config, 'thousands_separator', ','),
            dateFormat: (string) Config::value($config, 'date_format', 'Y-m-d'),
            timeFormat: (string) Config::value($config, 'time_format', 'H:i'),
            dateTimeFormat: (string) Config::value($config, 'datetime_format', 'Y-m-d H:i'),
        );
    }

    /** @return array<string, mixed> */
    public function toArray(): array
    {
        return [
            'locale' => $this->locale,
            'fallback' => $this->fallback,
            'domain' => $this->domain,
            'paths' => $this->paths,
            'detect' => $this->detect,
            'use_wordpress' => $this->useWordPress,
            'number_decimals' => $this->numberDecimals,
            'decimal_point' => $this->decimalPoint,
            'thousands_separator' => $this->thousandsSeparator,
            'date_format' => $this->dateFormat,
            'time_format' => $this->timeFormat,
            'datetime_format' => $this->dateTimeFormat,
        ];
    }

    public const array KEYS = [
        'locale', 'fallback', 'domain', 'paths', 'detect', 'use_wordpress',
        'number_decimals', 'decimal_point', 'thousands_separator',
        'date_format', 'time_format', 'datetime_format',
    ];
}

/**
 * Resource ceilings that keep a hostile or buggy template from exhausting
 * CPU, memory or the filesystem.
 *
 * Every value is clamped to a documented hard bound at construction time,
 * so a mis-typed config array degrades to a safe value instead of disabling
 * the guard.
 */
final readonly class Limits
{
    public const int MAX_TEMPLATE_BYTES_CEILING = 512 * 1024 * 1024;
    public const int MAX_INCLUDE_BYTES_CEILING = 256 * 1024 * 1024;

    public function __construct(
        public int $maxTemplateBytes = 16 * 1024 * 1024,
        public int $maxIncludeBytes = 8 * 1024 * 1024,
        public int $maxSsiDepth = 16,
        public int $maxSsiTags = 256,
        public int $maxLoopRows = 10_000,
        public int $maxLoopDepth = 32,
        public int $maxBlockDepth = 64,
        public int $maxPasses = 2,
        public int $maxExpressionLength = 4096,
        public int $maxExecOutputBytes = 65_536,
        public int $execTimeoutSeconds = 5,
        public int $maxDiagnostics = 100,
        public int $maxPrecision = 100,
    ) {
        $this->guard('maxTemplateBytes', $this->maxTemplateBytes, 1024, self::MAX_TEMPLATE_BYTES_CEILING);
        $this->guard('maxIncludeBytes', $this->maxIncludeBytes, 1024, self::MAX_INCLUDE_BYTES_CEILING);
        $this->guard('maxSsiDepth', $this->maxSsiDepth, 1, 128);
        $this->guard('maxSsiTags', $this->maxSsiTags, 1, 10_000);
        $this->guard('maxLoopRows', $this->maxLoopRows, 1, 1_000_000);
        $this->guard('maxLoopDepth', $this->maxLoopDepth, 1, 128);
        $this->guard('maxBlockDepth', $this->maxBlockDepth, 1, 1024);
        $this->guard('maxPasses', $this->maxPasses, 1, 16);
        $this->guard('maxExpressionLength', $this->maxExpressionLength, 16, 65_536);
        $this->guard('maxExecOutputBytes', $this->maxExecOutputBytes, 1, 16 * 1024 * 1024);
        $this->guard('execTimeoutSeconds', $this->execTimeoutSeconds, 1, 60);
        $this->guard('maxDiagnostics', $this->maxDiagnostics, 1, 10_000);
        $this->guard('maxPrecision', $this->maxPrecision, 0, 1000);
    }

    /**
     * @param array<string, mixed> $config
     */
    public static function fromArray(array $config): self
    {
        return new self(
            maxTemplateBytes: Config::int($config, 'max_template_bytes', 16 * 1024 * 1024),
            maxIncludeBytes: Config::int($config, 'max_include_bytes', 8 * 1024 * 1024),
            maxSsiDepth: Config::int($config, 'max_ssi_depth', 16),
            maxSsiTags: Config::int($config, 'max_ssi_tags', 256),
            maxLoopRows: Config::int($config, 'max_loop_rows', 10_000),
            maxLoopDepth: Config::int($config, 'max_loop_depth', 32),
            maxBlockDepth: Config::int($config, 'max_block_depth', 64),
            maxPasses: Config::int($config, 'max_passes', 2),
            maxExpressionLength: Config::int($config, 'max_expression_length', 4096),
            maxExecOutputBytes: Config::int($config, 'max_exec_output_bytes', 65_536),
            execTimeoutSeconds: Config::int($config, 'exec_timeout', 5),
            maxDiagnostics: Config::int($config, 'max_diagnostics', 100),
            maxPrecision: Config::int($config, 'max_precision', 100),
        );
    }

    /** @return array<string, int> */
    public function toArray(): array
    {
        return [
            'max_template_bytes' => $this->maxTemplateBytes,
            'max_include_bytes' => $this->maxIncludeBytes,
            'max_ssi_depth' => $this->maxSsiDepth,
            'max_ssi_tags' => $this->maxSsiTags,
            'max_loop_rows' => $this->maxLoopRows,
            'max_loop_depth' => $this->maxLoopDepth,
            'max_block_depth' => $this->maxBlockDepth,
            'max_passes' => $this->maxPasses,
            'max_expression_length' => $this->maxExpressionLength,
            'max_exec_output_bytes' => $this->maxExecOutputBytes,
            'exec_timeout' => $this->execTimeoutSeconds,
            'max_diagnostics' => $this->maxDiagnostics,
            'max_precision' => $this->maxPrecision,
        ];
    }

    private function guard(string $name, int $value, int $min, int $max): void
    {
        if ($value < $min || $value > $max) {
            throw new ConfigException(
                "Limit '{$name}' must be between {$min} and {$max}.",
                ['limit' => $name, 'value' => $value, 'min' => $min, 'max' => $max],
            );
        }
    }
}

/**
 * Logging/diagnostics sink options.
 */
final readonly class Log
{
    public const array LEVELS = [
        'debug' => 0, 'info' => 1, 'notice' => 2, 'warning' => 3,
        'error' => 4, 'critical' => 5, 'alert' => 6, 'emergency' => 7,
    ];

    public function __construct(
        public LogDriver $driver = LogDriver::Null,
        public string $path = '',
        public string $level = 'warning',
        public string $channel = 'htmlphp',
        public bool $forwardDiagnostics = true,
    ) {
        if (!isset(self::LEVELS[$this->level])) {
            throw new \HtmlPhp\Exception\ConfigException(
                'log.level must be a PSR-3 level name.',
                ['value' => $level],
            );
        }
    }

    /** @param array<string, mixed> $config */
    public static function fromArray(array $config): self
    {
        $driver = (string) Config::value($config, 'driver', LogDriver::Null->value);

        return new self(
            driver: LogDriver::tryFrom($driver)
                ?? throw new \HtmlPhp\Exception\ConfigException(
                    'log.driver must be one of: null, array, errorlog, file, syslog, wordpress.',
                    ['value' => $driver],
                ),
            path: (string) Config::value($config, 'path', ''),
            level: (string) Config::value($config, 'level', 'warning'),
            channel: (string) Config::value($config, 'channel', 'htmlphp'),
            forwardDiagnostics: Config::bool($config, 'forward_diagnostics', true),
        );
    }

    public function accepts(string $level): bool
    {
        return self::levelAccepted($this->level, $level);
    }

    /** True when `$level` is at least as severe as `$minimum`. */
    public static function levelAccepted(string $minimum, string $level): bool
    {
        return (self::LEVELS[$level] ?? 0) >= (self::LEVELS[$minimum] ?? 0);
    }

    /** @return array<string, mixed> */
    public function toArray(): array
    {
        return [
            'driver' => $this->driver->value,
            'path' => $this->path,
            'level' => $this->level,
            'channel' => $this->channel,
            'forward_diagnostics' => $this->forwardDiagnostics,
        ];
    }

    public const array KEYS = ['driver', 'path', 'level', 'channel', 'forward_diagnostics'];
}

/** Diagnostics sinks shipped with the library. */
enum LogDriver: string
{
    case Null = 'null';
    case Array = 'array';
    case ErrorLog = 'errorlog';
    case File = 'file';
    case Syslog = 'syslog';
    case WordPress = 'wordpress';
}

/**
 * What a `%{NAME}` resolves to when the name is absent from every scope frame.
 */
enum MissingVarPolicy: string
{
    /** Substitute an empty string (recorded in diagnostics). */
    case Empty = 'empty';

    /** Leave the placeholder text untouched. */
    case Keep = 'keep';

    /** Substitute a visible debug marker such as `[missing:NAME]`. */
    case Placeholder = 'placeholder';

    /** Abort the render with a {@see \HtmlPhp\Exception\TemplateException}. */
    case Throw = 'throw';
}

/**
 * Defence-in-depth switches that apply regardless of template trust level.
 */
final readonly class Security
{
    /**
     * Extensions that may never be served through `#include`, `@Partial` or
     * `@Extends` — prevents source disclosure of scripts and dotfile configs.
     */
    public const array DENIED_EXTENSIONS_DEFAULT = [
        'php', 'phtml', 'php3', 'php4', 'php5', 'php7', 'php8', 'phps', 'phar',
        'cgi', 'pl', 'py', 'rb', 'sh', 'bash', 'exe', 'dll', 'so',
        'inc', 'conf', 'config', 'env', 'htaccess', 'htpasswd', 'ini', 'log',
        'sql', 'bak', 'swp', 'dist',
    ];

    /**
     * @param array<string, true>|null $allowedTags allow-list for
     *        {@see \HtmlPhp\Html\Cleaner}; `null` selects the documented default
     * @param list<string> $deniedExtensions lowercase extension blacklist for includes
     */
    public function __construct(
        public ?array $allowedTags = null,
        public array $deniedExtensions = self::DENIED_EXTENSIONS_DEFAULT,
        public bool $denyPhpIncludes = true,
        public bool $sanitizeExecOutput = true,
    ) {}

    /** @param array<string, mixed> $config */
    public static function fromArray(array $config): self
    {
        $allowed = Config::arrayValue($config, 'allowed_tags', []);

        return new self(
            allowedTags: $allowed === [] && !\array_key_exists('allowed_tags', $config)
                ? null
                : self::normalizeTags($allowed),
            deniedExtensions: array_values(array_map(
                static fn($ext): string => strtolower(ltrim((string) $ext, '.')),
                Config::arrayValue($config, 'denied_extensions', self::DENIED_EXTENSIONS_DEFAULT),
            )),
            denyPhpIncludes: Config::bool($config, 'deny_php_includes', true),
            sanitizeExecOutput: Config::bool($config, 'sanitize_exec_output', true),
        );
    }

    /**
     * @param array<array-key, mixed> $tags
     * @return array<string, true>
     */
    private static function normalizeTags(array $tags): array
    {
        $normalized = [];

        foreach ($tags as $key => $value) {
            $name = strtolower(trim((string) (\is_int($key) ? $value : $key)));

            if ($name !== '' && preg_match('/^[a-z][a-z0-9-]*$/', $name) === 1) {
                $normalized[$name] = true;
            }
        }

        return $normalized;
    }

    /** @return array<string, mixed> */
    public function toArray(): array
    {
        return [
            'allowed_tags' => $this->allowedTags ?? [],
            'denied_extensions' => $this->deniedExtensions,
            'deny_php_includes' => $this->denyPhpIncludes,
            'sanitize_exec_output' => $this->sanitizeExecOutput,
        ];
    }

    public const array KEYS = ['allowed_tags', 'denied_extensions', 'deny_php_includes', 'sanitize_exec_output'];
}

/** Apache `#config sizefmt` values. */
enum SizeFormat: string
{
    case Abbrev = 'abbrev';
    case Bytes = 'bytes';
}

/**
 * SSI behaviour: document root, escaping, `#exec` policy and formats.
 */
final readonly class Ssi
{
    /**
     * @param list<string> $echoAllow allow-list of echo-able variable names (empty = all)
     * @param list<string> $execCmdAllow regex patterns matched against `cmd=` binaries
     * @param list<string> $execCgiExtensions allowed `cgi=` file extensions
     * @param (callable(string, array<string, string>): bool|string|null)|null $execDelegate
     *        host decision callback for {@see ExecMode::Delegate}: return `true`
     *        to run, `false` to deny, or a string to use as the output
     */
    public function __construct(
        public bool $enabled = true,
        public ?string $documentRoot = null,
        public bool $allowParentPaths = false,
        public bool $escapeEcho = true,
        public array $echoAllow = [],
        public string $timeFormat = '%A, %d-%b-%Y %H:%M:%S %Z',
        public SizeFormat $sizeFormat = SizeFormat::Abbrev,
        public ?string $errorMessage = null,
        public ExecMode $execMode = ExecMode::Deny,
        public array $execCmdAllow = [],
        public array $execCgiExtensions = ['php'],
        public string $execCgiMode = 'spawn',
        public mixed $execDelegate = null,
        public bool $processRenderedOutput = true,
        public bool $printenvEnabled = true,
    ) {
        if ($execCgiMode !== 'spawn' && $execCgiMode !== 'include') {
            throw new ConfigException("ssi.exec_cgi_mode must be 'spawn' or 'include'.", ['value' => $execCgiMode]);
        }

        if ($execDelegate !== null && !\is_callable($execDelegate)) {
            throw new ConfigException('ssi.exec_delegate must be callable or null.');
        }

        if ($execMode === ExecMode::Delegate && $execDelegate === null) {
            throw new ConfigException('ssi.exec_mode "delegate" requires ssi.exec_delegate.');
        }
    }

    /** @param array<string, mixed> $config */
    public static function fromArray(array $config): self
    {
        $execMode = Config::value($config, 'exec_mode', ExecMode::Deny->value);

        // v3 stored a boolean master switch; accept `true/false` as deny/allows-nothing.
        if (\is_bool($execMode)) {
            $execMode = $execMode ? ExecMode::AllowList->value : ExecMode::Deny->value;
        }

        $sizeFormat = SizeFormat::tryFrom((string) Config::value($config, 'size_format', SizeFormat::Abbrev->value))
            ?? throw new ConfigException('ssi.size_format must be "abbrev" or "bytes".');

        return new self(
            enabled: Config::bool($config, 'enabled', true),
            documentRoot: Config::nullableString($config, 'document_root'),
            allowParentPaths: Config::bool($config, 'allow_parent_paths', false),
            escapeEcho: Config::bool($config, 'escape_echo', true),
            echoAllow: Config::stringList($config, 'echo_allow'),
            timeFormat: (string) Config::value($config, 'time_format', '%A, %d-%b-%Y %H:%M:%S %Z'),
            sizeFormat: $sizeFormat,
            errorMessage: Config::nullableString($config, 'error_message'),
            execMode: ExecMode::tryFrom((string) $execMode)
                ?? throw new ConfigException('ssi.exec_mode must be one of: deny, allow-list, delegate.'),
            execCmdAllow: Config::stringList($config, 'exec_cmd_allow'),
            execCgiExtensions: Config::stringList($config, 'exec_cgi_extensions') ?: ['php'],
            execCgiMode: (string) Config::value($config, 'exec_cgi_mode', 'spawn'),
            execDelegate: Config::callableOrNull($config, 'exec_delegate'),
            processRenderedOutput: Config::bool($config, 'process_rendered_output', true),
            printenvEnabled: Config::bool($config, 'printenv_enabled', true),
        );
    }

    /** @return array<string, mixed> */
    public function toArray(): array
    {
        return [
            'enabled' => $this->enabled,
            'document_root' => $this->documentRoot,
            'allow_parent_paths' => $this->allowParentPaths,
            'escape_echo' => $this->escapeEcho,
            'echo_allow' => $this->echoAllow,
            'time_format' => $this->timeFormat,
            'size_format' => $this->sizeFormat->value,
            'error_message' => $this->errorMessage,
            'exec_mode' => $this->execMode->value,
            'exec_cmd_allow' => $this->execCmdAllow,
            'exec_cgi_extensions' => $this->execCgiExtensions,
            'exec_cgi_mode' => $this->execCgiMode,
            'exec_delegate' => $this->execDelegate === null ? null : '(callable)',
            'process_rendered_output' => $this->processRenderedOutput,
            'printenv_enabled' => $this->printenvEnabled,
        ];
    }

    /** Known keys of this group — used to reject typos. */
    public const array KEYS = [
        'enabled', 'document_root', 'allow_parent_paths', 'escape_echo', 'echo_allow',
        'time_format', 'size_format', 'error_message', 'exec_mode', 'exec_cmd_allow',
        'exec_cgi_extensions', 'exec_cgi_mode', 'exec_delegate', 'process_rendered_output',
        'printenv_enabled',
    ];
}

/**
 * Template language options: delimiters, escaping, the missing-variable
 * policy and the inline-expression gate.
 *
 * `expressions` (v5, default true) controls whether `%{= …}` / `#{= …}`
 * substitutions may evaluate the safe expression language. Structural
 * directives (`@If`, `@Set`, loop ranges) always use it — turning the flag
 * off removes *inline output* of computed values, the recommended hardening
 * for hosts that render user-editable templates with data-driven markup.
 */
final readonly class Syntax
{
    public function __construct(
        public string $varOpen = '%{',
        public string $varClose = '}',
        public string $altOpen = '#{',
        public string $transOpen = '@{',
        public string $tagOpen = '<!--@',
        public string $tagClose = '-->',
        public bool $autoEscape = true,
        public MissingVarPolicy $missingVar = MissingVarPolicy::Empty,
        public string $missingPlaceholderFormat = '[missing:%s]',
        public bool $singleBraces = false,
        public bool $allowRawFilter = true,
        public bool $strict = false,
        public bool $expressions = true,
    ) {}

    /** @param array<string, mixed> $config */
    public static function fromArray(array $config): self
    {
        $missing = (string) Config::value($config, 'missing_var', MissingVarPolicy::Empty->value);

        return new self(
            varOpen: (string) Config::value($config, 'var_open', '%{'),
            varClose: (string) Config::value($config, 'var_close', '}'),
            altOpen: (string) Config::value($config, 'alt_open', '#{'),
            transOpen: (string) Config::value($config, 'trans_open', '@{'),
            tagOpen: (string) Config::value($config, 'tag_open', '<!--@'),
            tagClose: (string) Config::value($config, 'tag_close', '-->'),
            autoEscape: Config::bool($config, 'auto_escape', true),
            missingVar: MissingVarPolicy::tryFrom($missing)
                ?? throw new \HtmlPhp\Exception\ConfigException(
                    'syntax.missing_var must be one of: empty, keep, placeholder, throw.',
                ),
            missingPlaceholderFormat: (string) Config::value($config, 'missing_placeholder_format', '[missing:%s]'),
            singleBraces: Config::bool($config, 'single_braces', false),
            allowRawFilter: Config::bool($config, 'allow_raw_filter', true),
            strict: Config::bool($config, 'strict', false),
            expressions: Config::bool($config, 'expressions', true),
        );
    }

    /** @return array<string, mixed> */
    public function toArray(): array
    {
        return [
            'var_open' => $this->varOpen,
            'var_close' => $this->varClose,
            'alt_open' => $this->altOpen,
            'trans_open' => $this->transOpen,
            'tag_open' => $this->tagOpen,
            'tag_close' => $this->tagClose,
            'auto_escape' => $this->autoEscape,
            'missing_var' => $this->missingVar->value,
            'missing_placeholder_format' => $this->missingPlaceholderFormat,
            'single_braces' => $this->singleBraces,
            'allow_raw_filter' => $this->allowRawFilter,
            'strict' => $this->strict,
            'expressions' => $this->expressions,
        ];
    }

    public const array KEYS = [
        'var_open', 'var_close', 'alt_open', 'trans_open', 'tag_open', 'tag_close',
        'auto_escape', 'missing_var', 'missing_placeholder_format', 'single_braces',
        'allow_raw_filter', 'strict', 'expressions',
    ];
}

/**
 * Template discovery: search paths, `@namespace` roots and the default
 * file extension appended to extension-less names.
 */
final readonly class Templates
{
    /**
     * @param list<string> $paths ordered template roots (first match wins)
     * @param array<string, string> $namespaces `@name` => root directory
     */
    public function __construct(
        public array $paths = [],
        public array $namespaces = [],
        public string $extension = '.html',
        public bool $cacheFileMTimes = true,
    ) {
        foreach ($this->paths as $path) {
            if (!\is_string($path) || $path === '') {
                throw new \HtmlPhp\Exception\ConfigException('templates.paths must contain non-empty strings.');
            }
        }
    }

    /** @param array<string, mixed> $config */
    public static function fromArray(array $config): self
    {
        $paths = Config::arrayValue($config, 'paths', []);
        $namespaces = [];

        foreach (Config::arrayValue($config, 'namespaces', []) as $alias => $dir) {
            $alias = ltrim((string) $alias, '@');

            if ($alias !== '') {
                $namespaces[$alias] = (string) $dir;
            }
        }

        return new self(
            paths: array_values(array_map(strval(...), $paths)),
            namespaces: $namespaces,
            extension: (string) Config::value($config, 'extension', '.html'),
            cacheFileMTimes: Config::bool($config, 'cache_file_mtimes', true),
        );
    }

    /** @return array<string, mixed> */
    public function toArray(): array
    {
        return [
            'paths' => $this->paths,
            'namespaces' => $this->namespaces,
            'extension' => $this->extension,
            'cache_file_mtimes' => $this->cacheFileMTimes,
        ];
    }

    public const array KEYS = ['paths', 'namespaces', 'extension', 'cache_file_mtimes'];
}

}

namespace HtmlPhp\Io {

use HtmlPhp\Config\Security as SecurityConfig;
use HtmlPhp\Exception\IoException;

/**
 * Crash-safe file writer.
 *
 * Sequence: temp file in the destination directory → full write under
 * `LOCK_EX` → verified payload length → mode preservation → `rename()`,
 * with a locked in-place write as fallback for filesystems that refuse
 * cross-directory renames (some Windows/SMB setups).
 */
final class AtomicWriter
{
    private function __construct() {}

    /**
     * Writes `$data` to `$file` atomically.
     *
     * @param int|null $mode explicit permissions; `null` preserves the
     *        existing file mode or uses the umask default for new files
     * @throws IoException when the directory or file is not writable
     */
    public static function write(string $file, string $data, ?int $mode = null): bool
    {
        if ($file === '' || str_contains($file, "\0")) {
            throw new IoException('The output file path is invalid.', ['file' => $file]);
        }

        $directory = \dirname($file);

        if (!is_dir($directory) || !is_writable($directory)) {
            throw new IoException("Output directory '{$directory}' is not writable.", ['dir' => $directory]);
        }

        if (is_file($file) && !is_writable($file)) {
            throw new IoException("Output file '{$file}' is not writable.", ['file' => $file]);
        }

        $expected = \strlen($data);

        $prefix = substr((string) preg_replace('~[^A-Za-z0-9._-]~', '_', basename($file)), 0, 32);

        if ($prefix === '') {
            $prefix = 'html';
        }

        $temporary = tempnam($directory, $prefix . '.tmp.');

        if ($temporary === false) {
            throw new IoException("Cannot create a temporary file in '{$directory}'.", ['dir' => $directory]);
        }

        $mode ??= self::targetMode($file);

        try {
            $written = file_put_contents($temporary, $data, LOCK_EX);

            if ($written === false || $written !== $expected) {
                throw new IoException("Cannot completely write temporary file '{$temporary}'.", ['file' => $temporary]);
            }

            @chmod($temporary, $mode);

            if (!@rename($temporary, $file)) {
                $fallback = @file_put_contents($file, $data, LOCK_EX);

                if ($fallback === false || $fallback !== $expected) {
                    throw new IoException("Cannot completely write output file '{$file}'.", ['file' => $file]);
                }

                @chmod($file, $mode);
            }
        } finally {
            if (is_file($temporary)) {
                @unlink($temporary);
            }
        }

        return true;
    }

    private static function targetMode(string $file): int
    {
        if (is_file($file)) {
            $perms = fileperms($file);

            return ($perms === false ? 0644 : $perms) & 0777;
        }

        $oldUmask = umask();
        umask($oldUmask);

        return 0666 & ~$oldUmask;
    }
}

/**
 * Guarded filesystem reads shared by templates, SSI includes and catalogues.
 */
final class Files
{
    public const int DEFAULT_MAX_BYTES = 8 * 1024 * 1024;

    private function __construct() {}

    /**
     * Reads a whole file with a byte cap.
     *
     * Returns `null` when the file is missing, unreadable or too large —
     * callers decide whether that is an error or a cache miss.
     */
    public static function slurp(string $path, ?int $maxBytes = null): ?string
    {
        if ($path === '' || str_contains($path, "\0") || !is_file($path) || !is_readable($path)) {
            return null;
        }

        $maxBytes ??= self::DEFAULT_MAX_BYTES;
        $size = @filesize($path);

        if ($size !== false && $size > $maxBytes) {
            return null;
        }

        $contents = @file_get_contents($path);

        return $contents === false ? null : $contents;
    }

    /** Lowercase extension without the dot (`''` when there is none). */
    public static function extension(string $path): string
    {
        $base = basename(str_contains($path, "\0") ? '' : $path);
        $dot = strrpos($base, '.');

        return $dot === false || $dot === 0 ? '' : strtolower(substr($base, $dot + 1));
    }

    /** Modification time, or `0` when unavailable. */
    public static function mtime(string $path): int
    {
        $mtime = @filemtime($path);

        return $mtime === false ? 0 : $mtime;
    }

    /**
     * Normalises a path for prefix comparisons: native separators become
     * `/` and, on case-insensitive filesystems, the path is lowercased.
     */
    public static function normalizeForCompare(string $path): string
    {
        $normalized = rtrim(str_replace('\\', '/', $path), '/');

        if (PHP_OS_FAMILY === 'Windows' || PHP_OS_FAMILY === 'Darwin') {
            $normalized = strtolower($normalized);
        }

        return $normalized;
    }

    /** True when `$path` is `$root` itself or lives inside `$root`. */
    public static function isInside(string $path, string $root): bool
    {
        $path = self::normalizeForCompare($path);
        $root = self::normalizeForCompare($root);

        if ($root === '') {
            return false;
        }

        return $path === $root || str_starts_with($path, $root . '/');
    }
}

/**
 * Path resolution with containment — the single choke point every include
 * in the library goes through (SSI `#include`, `@Partial`, `@Extends`,
 * catalogue files).
 *
 * A reference is accepted only when, after `realpath()` (which collapses
 * `..` segments *and* resolves symlinks), it lives inside one of the
 * configured roots and its extension is not on the deny list. The deny
 * list stops both script execution leaks (`*.php`, `*.phar`) and source
 * disclosure (`*.env`, `*.sql`, `wp-config.php`, `.htaccess`, …).
 */
final class PathGuard
{
    /** @var list<string> realpath'd roots */
    private readonly array $roots;

    /** @var array<string, true> */
    private readonly array $deniedExtensions;

    /**
     * @param list<string> $roots directories includes may resolve into
     * @param list<string> $deniedExtensions
     */
    public function __construct(
        array $roots,
        array $deniedExtensions = SecurityConfig::DENIED_EXTENSIONS_DEFAULT,
        private readonly bool $allowParentPaths = false,
    ) {
        $resolved = [];

        foreach ($roots as $root) {
            if (!\is_string($root) || $root === '') {
                continue;
            }

            $real = realpath($root);
            $resolved[] = $real === false ? Files::normalizeForCompare(rtrim($root, '/\\')) : $real;
        }

        $this->roots = array_values(array_unique($resolved));

        $denied = [];
        foreach ($deniedExtensions as $extension) {
            $extension = strtolower(ltrim((string) $extension, '.'));

            if ($extension !== '') {
                $denied[$extension] = true;
            }
        }
        $this->deniedExtensions = $denied;
    }

    /**
     * Resolves `$reference` against `$baseDir` (falling back to each root)
     * and validates it. Returns the realpath'd file or `null` when the
     * reference is rejected or does not exist.
     */
    public function resolve(string $reference, ?string $baseDir = null): ?string
    {
        if ($reference === '' || str_contains($reference, "\0")) {
            return null;
        }

        if (!$this->extensionAllowed($reference)) {
            return null;
        }

        $candidates = [];

        if ($this->isAbsolute($reference)) {
            $candidates[] = $reference;
        } else {
            if ($baseDir !== null && $baseDir !== '') {
                $candidates[] = rtrim($baseDir, '/\\') . '/' . $reference;
            }

            foreach ($this->roots as $root) {
                $candidates[] = $root . '/' . $reference;
            }
        }

        foreach ($candidates as $candidate) {
            $real = realpath($candidate);

            if ($real === false || !is_file($real)) {
                continue;
            }

            if (!$this->extensionAllowed($real)) {
                return null; // never fall through to another root once denied
            }

            if ($this->contained($real)) {
                return $real;
            }

            if ($this->allowParentPaths) {
                return $real;
            }
        }

        return null;
    }

    /** True when the resolved path sits inside one of the roots. */
    public function contained(string $realPath): bool
    {
        foreach ($this->roots as $root) {
            if (Files::isInside($realPath, $root)) {
                return true;
            }
        }

        return false;
    }

    /** Extension deny-list check (`htaccess`-style dotfiles are denied too). */
    public function extensionAllowed(string $path): bool
    {
        $base = basename(str_replace('\\', '/', $path));

        if (str_starts_with($base, '.') && $base !== '.' && $base !== '..') {
            return false; // .htaccess, .env, .git …
        }

        $extension = Files::extension($base);

        return $extension === '' || !isset($this->deniedExtensions[$extension]);
    }

    /** @return list<string> */
    public function roots(): array
    {
        return $this->roots;
    }

    /** @return list<string> */
    public function deniedExtensionsList(): array
    {
        return array_keys($this->deniedExtensions);
    }

    private function isAbsolute(string $path): bool
    {
        return str_starts_with($path, '/')
            || preg_match('~^[A-Za-z]:[\\\\/]~', $path) === 1
            || str_starts_with($path, '\\\\');
    }
}

}

namespace HtmlPhp\Html {

use HtmlPhp\Support\Pcre;
use HtmlPhp\Support\Str;

/**
 * HTML cleaning and normalisation (v3 `clean_html()`, `normalize()`,
 * `lc_Tags()` semantics) with the allow-list injected instead of read
 * from `$GLOBALS`.
 */
final class Cleaner
{
    /** Sentinel protecting `<br>` markers inside {@see self::normalize()}. */
    public const string BR_MARKER = "\x01HTML_BR\x01";

    /** @var array<string, true> */
    public const array DEFAULT_ALLOWED_TAGS = [
        'br' => true, 'p' => true, 'h1' => true, 'h2' => true, 'h3' => true,
        'h4' => true, 'strong' => true, 'b' => true, 'ul' => true, 'ol' => true,
        'li' => true, 'hr' => true,
    ];

    /** @param array<string, true> $allowedTags */
    public function __construct(private readonly array $allowedTags = self::DEFAULT_ALLOWED_TAGS) {}

    /** Converts HTML tag names to lowercase without touching attributes. */
    public function lcTags(string $input): string
    {
        return Pcre::replaceCallback(
            '~<(\s*/?\s*)([A-Za-z][A-Za-z0-9:_-]*)((?:"[^"]*"|\'[^\']*\'|[^\'">])*)>~',
            static fn(array $matches): string => '<' . $matches[1] . strtolower($matches[2]) . $matches[3] . '>',
            $input,
        );
    }

    /**
     * Normalises HTML to a single text line while optionally preserving
     * `<br>` tags (legacy `normalize()` semantics).
     *
     * @param mixed $br preserve `<br>` when null/0, strip when truthy
     */
    public function normalize(string $buffer, mixed $br = null, mixed $cleanEdges = false): string
    {
        $preserveBreaks = $br === null || (int) $br === 0;
        $marker = self::BR_MARKER;

        $buffer = str_replace("\x01", '', $buffer);
        $buffer = Pcre::replace('~<!--.*?-->~s', '', $buffer);

        if ($preserveBreaks) {
            $buffer = Pcre::replace('~<br\s*/?>~i', $marker, $buffer);
        }

        $buffer = Pcre::replace('~<(?:"[^"]*"|\'[^\']*\'|[^\'">])*>~s', ' ', $buffer);
        $buffer = Str::normalizeEntities($buffer);
        $buffer = Pcre::replace('~[\x00\x02-\x08\x0B\x0C\x0E-\x1F\x7F]~', '', $buffer);
        $buffer = Pcre::replace('~[\t\n\r ]+~', ' ', $buffer);
        $buffer = $preserveBreaks ? str_replace($marker, '<br>', $buffer) : $buffer;
        $buffer = trim($buffer);
        $buffer = Pcre::replace('~,\\z~', '', $buffer);

        if (!empty($cleanEdges)) {
            $buffer = Pcre::replaceUnicode(
                '~^[.,:\\\\/><!]+\s*|\s*[.,:\\\\/><!]+$~u',
                '~^[.,:\\\\/><!]+\s*|\s*[.,:\\\\/><!]+$~',
                '',
                $buffer,
            );
            $buffer = trim($buffer);
        }

        return $buffer;
    }

    /** Returns an allow-listed HTML tag without attributes ('' otherwise). */
    public function cleanTag(string $closing, string $tag): string
    {
        $tag = strtolower($tag);

        return !empty($this->allowedTags[$tag]) ? '<' . $closing . $tag . '>' : '';
    }

    /**
     * Keeps only allow-listed HTML tags and removes their attributes.
     *
     * `<script>`/`<style>` elements are dropped **with their contents**
     * (including an unterminated opener); every other removed tag keeps
     * its text.
     */
    public function cleanHtml(string $html): string
    {
        $html = Pcre::replace('~<!--.*?-->~s', '', $html);
        $html = Pcre::replace('~<(script|style)\b[^>]*>.*?</\1\s*>~is', '', $html);
        $html = Pcre::replace('~<(script|style)\b[^>]*>.*$~is', '', $html);

        $html = Pcre::replaceCallback(
            '~<(/?)([A-Za-z][A-Za-z0-9:_-]*)(?:"[^"]*"|\'[^\']*\'|[^\'">])*>~s',
            fn(array $matches): string => $this->cleanTag($matches[1], $matches[2]),
            $html,
        );

        $html = Str::normalizeEntities($html);
        $html = Pcre::replaceUnicode('~\s+~u', '~[\s\x00-\x1F]+~', ' ', $html);

        return trim($html);
    }

    /** Removes whitespace and non-word characters (legacy `TrimSpaces()`). */
    public function trimSpaces(mixed $string): string
    {
        return Str::keepWordChars(Str::stringify($string));
    }

    /** @return array<string, true> */
    public function allowedTags(): array
    {
        return $this->allowedTags;
    }
}

/**
 * Context-aware output escaping.
 *
 * Not final: hosts that need a different HTML policy can subclass and
 * register their instance in the container. The defaults match v3
 * semantics exactly (including `double_encode: false` for text/attribute
 * contexts, so already-escaped snippets survive a render pass).
 */
class Escaper
{
    /**
     * @param (callable(string): string)|null $customHtmlEscaper replaces the
     *        built-in text escaper only — attribute/URL/JSON escaping always
     *        uses the built-ins so security never depends on user code
     */
    public function __construct(private readonly mixed $customHtmlEscaper = null)
    {
        if ($this->customHtmlEscaper !== null && !\is_callable($this->customHtmlEscaper)) {
            throw new \InvalidArgumentException('The custom HTML escaper must be callable.');
        }
    }

    /** HTML text context — the default for `%{VAR}` auto-escaping and `#echo`. */
    public function html(string $value): string
    {
        if ($this->customHtmlEscaper !== null) {
            return Str::stringify(($this->customHtmlEscaper)($value));
        }

        return htmlspecialchars($value, ENT_QUOTES | ENT_HTML5 | ENT_SUBSTITUTE, 'UTF-8', false);
    }

    /** Attribute context — always the built-in encoder. */
    public function attr(string $value): string
    {
        return htmlspecialchars($value, ENT_QUOTES | ENT_HTML5 | ENT_SUBSTITUTE, 'UTF-8', false);
    }

    /**
     * URL-value escaping: `rawurlencode()` every character that is not
     * unreserved or a structural URL delimiter. `&` and `'` **are** encoded
     * because this sanitises values placed *into* URLs, not whole query
     * strings.
     */
    public function url(string $value): string
    {
        $result = preg_replace_callback(
            '/[^A-Za-z0-9\-._~:\/?#\[\]@!$()*+,;=%]/',
            static fn(array $m): string => rawurlencode($m[0]),
            $value,
        );

        return $result ?? $value;
    }

    /** JSON escaping safe for inline `<script>` contexts. */
    public function json(mixed $value): string
    {
        $encoded = json_encode(
            $value,
            JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_HEX_AMP | JSON_UNESCAPED_UNICODE,
        );

        return $encoded === false ? 'null' : $encoded;
    }

    /**
     * Inline JavaScript string-literal escaping (alias semantics of `json`
     * for scalar values: quotes included, `<`/`&` hex-encoded).
     */
    public function js(mixed $value): string
    {
        return $this->json(\is_scalar($value) || $value === null ? $value : Str::stringify($value));
    }

    /** CSS-value escaping: every non-alphanumeric becomes `\HHHHHH `. */
    public function css(string $value): string
    {
        return (string) preg_replace_callback(
            '/[^a-zA-Z0-9]/',
            static fn(array $m): string => \sprintf('\\%06X ', \ord($m[0])),
            $value,
        );
    }

    /**
     * Recursively sanitises a nested input array for safe HTML output
     * (the v3 `sanitizeXSS()` semantics, `double_encode: true`).
     *
     * @param array<array-key, mixed> $input
     * @return array<array-key, mixed>
     */
    public function sanitizeArray(array $input): array
    {
        $sanitized = [];

        foreach ($input as $key => $value) {
            $sanitized[$key] = \is_array($value)
                ? $this->sanitizeArray($value)
                : htmlspecialchars(Str::stringify($value), ENT_QUOTES | ENT_HTML5 | ENT_SUBSTITUTE, 'UTF-8', true);
        }

        return $sanitized;
    }

    /** Escapes by strategy name — the engine behind `|escape:'js'`. */
    public function byStrategy(string $strategy, mixed $value): string
    {
        $string = Str::stringify($value);

        return match (strtolower($strategy)) {
            'html', 'text', '' => $this->html($string),
            'attr', 'attribute', 'html_attr' => $this->attr($string),
            'url' => $this->url($string),
            'json' => $this->json($value),
            'js', 'javascript' => $this->js($value),
            'css' => $this->css($string),
            'none', 'raw' => $string,
            default => $this->html($string),
        };
    }
}

}

namespace HtmlPhp\Log {

use HtmlPhp\Config\Log as LogConfig;
use HtmlPhp\Config\LogDriver;

/**
 * Implements the level shortcuts by delegating to {@see self::log()}.
 */
abstract class AbstractLogger implements LoggerInterface
{
    /** @param array<string, mixed> $context */
    public function debug(string $message, array $context = []): void
    {
        $this->log('debug', $message, $context);
    }

    /** @param array<string, mixed> $context */
    public function info(string $message, array $context = []): void
    {
        $this->log('info', $message, $context);
    }

    /** @param array<string, mixed> $context */
    public function notice(string $message, array $context = []): void
    {
        $this->log('notice', $message, $context);
    }

    /** @param array<string, mixed> $context */
    public function warning(string $message, array $context = []): void
    {
        $this->log('warning', $message, $context);
    }

    /** @param array<string, mixed> $context */
    public function error(string $message, array $context = []): void
    {
        $this->log('error', $message, $context);
    }

    /** @param array<string, mixed> $context */
    public function critical(string $message, array $context = []): void
    {
        $this->log('critical', $message, $context);
    }

    /** @param array<string, mixed> $context */
    public function alert(string $message, array $context = []): void
    {
        $this->log('alert', $message, $context);
    }

    /** @param array<string, mixed> $context */
    public function emergency(string $message, array $context = []): void
    {
        $this->log('emergency', $message, $context);
    }

    /**
     * Interpolates `{placeholder}` tokens from `$context` (PSR-3 style).
     *
     * @param array<string, mixed> $context
     */
    protected function interpolate(string $message, array $context): string
    {
        if ($context === [] || !str_contains($message, '{')) {
            return $message;
        }

        $replacements = [];

        foreach ($context as $key => $value) {
            if (\is_scalar($value) || $value === null || $value instanceof \Stringable) {
                $replacements['{' . $key . '}'] = (string) ($value ?? 'null');
            }
        }

        return strtr($message, $replacements);
    }
}

/**
 * Keeps records in memory — the sink used by tests, `lint` reports and the
 * WordPress admin health screen.
 */
final class ArrayLogger extends AbstractLogger
{
    /** @var list<array{level: string, message: string, context: array<string, mixed>}> */
    private array $records = [];

    public function __construct(private readonly int $cap = 1000) {}

    /** @param array<string, mixed> $context */
    public function log(string $level, string $message, array $context = []): void
    {
        if (\count($this->records) < $this->cap) {
            $this->records[] = ['level' => $level, 'message' => $message, 'context' => $context];
        }
    }

    /** @return list<array{level: string, message: string, context: array<string, mixed>}> */
    public function records(): array
    {
        return $this->records;
    }

    /** @return list<string> */
    public function messages(): array
    {
        return array_map(static fn(array $r): string => $r['level'] . ': ' . $r['message'], $this->records);
    }

    public function clear(): void
    {
        $this->records = [];
    }
}

/**
 * Forwards to PHP's `error_log()` — under WordPress this lands in
 * `debug.log` when `WP_DEBUG_LOG` is on, and in the SAPI log elsewhere.
 */
final class ErrorLogLogger extends AbstractLogger
{
    public function __construct(
        private readonly string $channel = 'htmlphp',
        private readonly string $minLevel = 'debug',
    ) {}

    /** @param array<string, mixed> $context */
    public function log(string $level, string $message, array $context = []): void
    {
        if (!\HtmlPhp\Config\Log::levelAccepted($this->minLevel, $level)) {
            return;
        }

        $line = \sprintf(
            '[%s] %s.%s: %s%s',
            date('Y-m-d H:i:s'),
            $this->channel,
            $level,
            $this->interpolate($message, $context),
            $context === [] ? '' : ' ' . (json_encode($context, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) ?: '{}'),
        );

        error_log($line);
    }
}

/**
 * Line-oriented file log: `[ts] channel.LEVEL: message {json-context}`.
 *
 * Appends with a single `file_put_contents()` in append mode; concurrent
 * writers on the same line size are safe enough for diagnostics, and the
 * WordPress bridge offers rotating logs on top of it.
 */
final class FileLogger extends AbstractLogger
{
    public function __construct(
        private readonly string $path,
        private readonly string $channel = 'htmlphp',
        private readonly string $minLevel = 'warning',
    ) {}

    /** @param array<string, mixed> $context */
    public function log(string $level, string $message, array $context = []): void
    {
        if (!\HtmlPhp\Config\Log::levelAccepted($this->minLevel, $level)) {
            return;
        }

        $line = \sprintf(
            "[%s] %s.%s: %s%s\n",
            date('Y-m-d H:i:s'),
            $this->channel,
            $level,
            $this->interpolate($message, $context),
            $context === [] ? '' : ' ' . (json_encode($context, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) ?: '{}'),
        );

        $dir = \dirname($this->path);

        if (!is_dir($dir)) {
            @mkdir($dir, 0775, true);
        }

        @file_put_contents($this->path, $line, FILE_APPEND | LOCK_EX);
    }
}

/**
 * Chooses the logger implementation described by the configuration.
 */
final class LoggerFactory
{
    private function __construct() {}

    public static function create(LogConfig $config): LoggerInterface
    {
        return match ($config->driver) {
            LogDriver::Array => new ArrayLogger(),
            LogDriver::ErrorLog => new ErrorLogLogger($config->channel, $config->level),
            LogDriver::Syslog => new SyslogLogger($config->channel),
            LogDriver::File => $config->path === ''
                ? new NullLogger()
                : new FileLogger($config->path, $config->channel, $config->level),
            LogDriver::WordPress => class_exists('\HtmlPhp\WordPress\WpLogger')
                ? new \HtmlPhp\WordPress\WpLogger($config->channel, $config->level)
                : new ErrorLogLogger($config->channel, $config->level),
            LogDriver::Null => new NullLogger(),
        };
    }

    /**
     * Wraps a host `Psr\Log\LoggerInterface` (or anything with the same
     * method shape) so Monolog, Symfony and Laravel loggers plug straight in.
     */
    public static function wrap(object $psrLogger): LoggerInterface
    {
        return new Psr3Adapter($psrLogger);
    }
}

/**
 * PSR-3 shaped logging contract (self-contained — the library ships with
 * zero dependencies, so it declares its own interface; `Psr3Adapter`
 * forwards to a real `Psr\Log\LoggerInterface` when one is installed).
 */
interface LoggerInterface
{
    /** @param array<string, mixed> $context */
    public function log(string $level, string $message, array $context = []): void;

    /** @param array<string, mixed> $context */
    public function debug(string $message, array $context = []): void;

    /** @param array<string, mixed> $context */
    public function info(string $message, array $context = []): void;

    /** @param array<string, mixed> $context */
    public function notice(string $message, array $context = []): void;

    /** @param array<string, mixed> $context */
    public function warning(string $message, array $context = []): void;

    /** @param array<string, mixed> $context */
    public function error(string $message, array $context = []): void;

    /** @param array<string, mixed> $context */
    public function critical(string $message, array $context = []): void;

    /** @param array<string, mixed> $context */
    public function alert(string $message, array $context = []): void;

    /** @param array<string, mixed> $context */
    public function emergency(string $message, array $context = []): void;
}

/** Discards everything. The default sink. */
final class NullLogger implements LoggerInterface
{
    /** @param array<string, mixed> $context */
    public function log(string $level, string $message, array $context = []): void {}

    /** @param array<string, mixed> $context */
    public function debug(string $message, array $context = []): void {}

    /** @param array<string, mixed> $context */
    public function info(string $message, array $context = []): void {}

    /** @param array<string, mixed> $context */
    public function notice(string $message, array $context = []): void {}

    /** @param array<string, mixed> $context */
    public function warning(string $message, array $context = []): void {}

    /** @param array<string, mixed> $context */
    public function error(string $message, array $context = []): void {}

    /** @param array<string, mixed> $context */
    public function critical(string $message, array $context = []): void {}

    /** @param array<string, mixed> $context */
    public function alert(string $message, array $context = []): void {}

    /** @param array<string, mixed> $context */
    public function emergency(string $message, array $context = []): void {}
}

/**
 * Bridges any PSR-3 logger (Monolog, Symfony, Laravel, …) to the library's
 * own {@see LoggerInterface}.
 *
 * The dependency stays optional: the adapter only calls `log()` on the
 * wrapped object, so no `psr/log` installation is required.
 */
final class Psr3Adapter extends AbstractLogger
{
    public function __construct(private readonly object $logger)
    {
        if (!method_exists($this->logger, 'log')) {
            throw new \InvalidArgumentException(
                'Psr3Adapter expects an object with a log($level, $message, array $context) method.',
            );
        }
    }

    /** @param array<string, mixed> $context */
    public function log(string $level, string $message, array $context = []): void
    {
        $this->logger->log($level, $message, $context);
    }
}

/** Forwards to the system syslog facility. */
final class SyslogLogger extends AbstractLogger
{
    private const int IDENT = LOG_USER;

    private bool $opened = false;

    public function __construct(private readonly string $channel = 'htmlphp') {}

    /** @param array<string, mixed> $context */
    public function log(string $level, string $message, array $context = []): void
    {
        if (!$this->opened) {
            openlog($this->channel, LOG_PID, self::IDENT);
            $this->opened = true;
        }

        syslog(self::priority($level), $this->interpolate($message, $context));
    }

    public function __destruct()
    {
        if ($this->opened) {
            closelog();
        }
    }

    private static function priority(string $level): int
    {
        return match ($level) {
            'emergency' => LOG_EMERG,
            'alert' => LOG_ALERT,
            'critical' => LOG_CRIT,
            'error' => LOG_ERR,
            'warning' => LOG_WARNING,
            'notice' => LOG_NOTICE,
            'info' => LOG_INFO,
            default => LOG_DEBUG,
        };
    }
}

}

namespace HtmlPhp\Cache {

use HtmlPhp\Config\Cache as CacheConfig;
use HtmlPhp\Config\CacheDriver;
use HtmlPhp\Contracts\CacheInterface;
use HtmlPhp\Diagnostics;
use HtmlPhp\Exception\CacheException;
use HtmlPhp\Io\AtomicWriter;
use HtmlPhp\Support\ClockInterface;

/**
 * APCu-backed cache for single-host high-throughput installs.
 *
 * Requires the `apcu` extension; {@see self::isSupported()} lets the
 * factory fall back gracefully.
 */
final class ApcuCache implements CacheInterface
{
    public function __construct(private readonly string $prefix = 'htmlphp', private readonly int $defaultTtl = 0) {}

    public static function isSupported(): bool
    {
        return \function_exists('apcu_fetch') && (PHP_SAPI !== 'cli' || (bool) \ini_get('apc.enable_cli'));
    }

    public function get(string $key): ?string
    {
        $success = false;
        $value = apcu_fetch($this->prefix($key), $success);

        return $success && \is_string($value) ? $value : null;
    }

    public function set(string $key, string $value, int $ttl = 0): bool
    {
        return apcu_store($this->prefix($key), $value, $ttl > 0 ? $ttl : $this->defaultTtl);
    }

    public function has(string $key): bool
    {
        return apcu_exists($this->prefix($key));
    }

    public function delete(string $key): bool
    {
        return apcu_delete($this->prefix($key));
    }

    public function clear(): int
    {
        $removed = 0;

        if (class_exists(\APCUIterator::class)) {
            $iterator = new \APCUIterator('/^' . preg_quote($this->prefix . ':', '/') . '/');
            $removed = iterator_count($iterator);
            apcu_delete($iterator);
        }

        return $removed;
    }

    private function prefix(string $key): string
    {
        return $this->prefix . ':' . $key;
    }
}

/**
 * Per-process cache. Useful for CLI runs, tests and as a first tier in
 * front of slower backends.
 */
final class ArrayCache implements CacheInterface
{
    /** @var array<string, array{0: string, 1: int}> value + expiry (0 = never) */
    private array $entries = [];

    public function __construct(private readonly ?ClockInterface $clock = null, private readonly int $defaultTtl = 0) {}

    public function get(string $key): ?string
    {
        $entry = $this->entries[$key] ?? null;

        if ($entry === null) {
            return null;
        }

        if ($entry[1] !== 0 && $entry[1] <= $this->now()) {
            unset($this->entries[$key]);

            return null;
        }

        return $entry[0];
    }

    public function set(string $key, string $value, int $ttl = 0): bool
    {
        $ttl = $ttl > 0 ? $ttl : $this->defaultTtl;
        $this->entries[$key] = [$value, $ttl > 0 ? $this->now() + $ttl : 0];

        return true;
    }

    public function has(string $key): bool
    {
        return $this->get($key) !== null;
    }

    public function delete(string $key): bool
    {
        $existed = isset($this->entries[$key]);
        unset($this->entries[$key]);

        return $existed;
    }

    public function clear(): int
    {
        $count = \count($this->entries);
        $this->entries = [];

        return $count;
    }

    public function count(): int
    {
        return \count($this->entries);
    }

    private function now(): int
    {
        return $this->clock?->now() ?? time();
    }
}

/**
 * Instantiates the cache backend described by the configuration, with
 * safe fallbacks (APCu missing → array cache + diagnostic).
 */
final class CacheFactory
{
    private function __construct() {}

    public static function create(CacheConfig $config, ?Diagnostics $diagnostics = null): CacheInterface
    {
        if (!$config->enabled) {
            return new NullCache();
        }

        return match ($config->driver) {
            CacheDriver::Null => new NullCache(),
            CacheDriver::Array => new ArrayCache(defaultTtl: $config->ttl),
            CacheDriver::File => $config->directory === ''
                ? throw new CacheException('cache.driver "file" requires cache.directory.')
                : new FileCache(
                    $config->directory,
                    $config->prefix,
                    $config->ttl,
                    $config->hardenDirectory,
                    diagnostics: $diagnostics,
                ),
            CacheDriver::Apcu => ApcuCache::isSupported()
                ? new ApcuCache($config->prefix, $config->ttl)
                : self::fallback($diagnostics, $config->ttl),
            CacheDriver::WordPress => class_exists('\HtmlPhp\WordPress\WpCache') && \function_exists('wp_cache_get')
                ? new \HtmlPhp\WordPress\WpCache($config->prefix, $config->ttl, $diagnostics)
                : self::fallback($diagnostics, $config->ttl),
        };
    }

    private static function fallback(?Diagnostics $diagnostics, int $ttl): CacheInterface
    {
        $diagnostics?->record(
            Diagnostics::CACHE_IO,
            'Configured cache driver unavailable; falling back to an in-process array cache.',
        );

        return new ArrayCache(defaultTtl: $ttl);
    }
}

/**
 * Filesystem render cache.
 *
 * Layout: `{dir}/{prefix}/{shard}/{sha256}.cache`, payload = one JSON meta
 * line (`{"e":expiry}`) followed by the raw value, so values never pay an
 * escaping round-trip. Writes go through {@see AtomicWriter}; reads verify
 * expiry against the injected clock.
 *
 * When `harden` is on the directory receives a deny-all `.htaccess` and an
 * empty `index.html`, matching WordPress upload-hardening conventions.
 */
final class FileCache implements CacheInterface
{
    private bool $prepared = false;

    public function __construct(
        private readonly string $directory,
        private readonly string $prefix = 'htmlphp',
        private readonly int $defaultTtl = 0,
        private readonly bool $harden = true,
        private readonly ?ClockInterface $clock = null,
        private readonly ?Diagnostics $diagnostics = null,
    ) {}

    public function get(string $key): ?string
    {
        $file = $this->path($key);

        if (!is_file($file)) {
            return null;
        }

        $handle = @fopen($file, 'rb');

        if ($handle === false) {
            return null;
        }

        try {
            $meta = fgets($handle);
            $decoded = \is_string($meta) ? json_decode(trim($meta), true) : null;

            if (!\is_array($decoded)) {
                return null;
            }

            $expiry = (int) ($decoded['e'] ?? 0);

            if ($expiry !== 0 && $expiry <= $this->now()) {
                return null;
            }

            $value = stream_get_contents($handle);

            return \is_string($value) ? $value : null;
        } finally {
            fclose($handle);
        }
    }

    public function set(string $key, string $value, int $ttl = 0): bool
    {
        if (!$this->prepare()) {
            return false;
        }

        $ttl = $ttl > 0 ? $ttl : $this->defaultTtl;
        $meta = json_encode(['e' => $ttl > 0 ? $this->now() + $ttl : 0]) . "\n";
        $path = $this->path($key);
        $shard = \dirname($path);

        if (!is_dir($shard) && !@mkdir($shard, 0775, true) && !is_dir($shard)) {
            $this->diagnostics?->record(Diagnostics::CACHE_IO, 'Cannot create cache shard.', ['dir' => $shard]);

            return false;
        }

        $this->sweep();

        try {
            return AtomicWriter::write($path, $meta . $value, 0664);
        } catch (\HtmlPhp\Exception\IoException $error) {
            $this->diagnostics?->record(Diagnostics::CACHE_IO, $error->getMessage(), $error->context);

            return false;
        }
    }

    public function has(string $key): bool
    {
        return $this->get($key) !== null;
    }

    public function delete(string $key): bool
    {
        $file = $this->path($key);

        return is_file($file) && @unlink($file);
    }

    public function clear(): int
    {
        $removed = 0;

        foreach ($this->files() as $file) {
            if (@unlink($file)) {
                $removed++;
            }
        }

        return $removed;
    }

    /** Directory size in bytes (admin health screen, WP-CLI info). */
    public function size(): int
    {
        $bytes = 0;

        foreach ($this->files() as $file) {
            $bytes += (int) @filesize($file);
        }

        return $bytes;
    }

    public function count(): int
    {
        return iterator_count($this->files());
    }

    /** @return \Generator<int, string> */
    private function files(): \Generator
    {
        $root = $this->root();

        if (!is_dir($root)) {
            return;
        }

        $iterator = new \RecursiveIteratorIterator(
            new \RecursiveDirectoryIterator($root, \FilesystemIterator::SKIP_DOTS),
        );

        /** @var \SplFileInfo $info */
        foreach ($iterator as $info) {
            if ($info->isFile() && $info->getExtension() === 'cache') {
                yield $info->getPathname();
            }
        }
    }

    /**
     * Probabilistic garbage collection: ~1 % of writes sweep expired files
     * so a busy site never needs a cron job, and an idle one pays nothing.
     */
    private function sweep(): void
    {
        if (random_int(1, 100) !== 1) {
            return;
        }

        $now = $this->now();

        foreach ($this->files() as $file) {
            $handle = @fopen($file, 'rb');

            if ($handle === false) {
                continue;
            }

            $meta = fgets($handle);
            fclose($handle);
            $decoded = \is_string($meta) ? json_decode(trim($meta), true) : null;
            $expiry = \is_array($decoded) ? (int) ($decoded['e'] ?? 0) : 0;

            if ($expiry !== 0 && $expiry <= $now) {
                @unlink($file);
            }
        }
    }

    private function path(string $key): string
    {
        $hash = hash('sha256', $key);

        return $this->root() . '/' . substr($hash, 0, 2) . '/' . $hash . '.cache';
    }

    private function root(): string
    {
        $safe = preg_replace('/[^A-Za-z0-9_.-]/', '_', $this->prefix) ?: 'htmlphp';

        return rtrim($this->directory, '/\\') . '/' . $safe;
    }

    private function prepare(): bool
    {
        if ($this->prepared) {
            return true;
        }

        $root = $this->root();

        if (!is_dir($root) && !@mkdir($root, 0775, true) && !is_dir($root)) {
            $this->diagnostics?->record(Diagnostics::CACHE_IO, 'Cannot create cache directory.', ['dir' => $root]);

            return false;
        }

        if ($this->harden) {
            try {
                AtomicWriter::write($root . '/.htaccess', "Require all denied\nDeny from all\n", 0644);
                AtomicWriter::write($root . '/index.html', '', 0644);
            } catch (\HtmlPhp\Exception\IoException) {
                $this->diagnostics?->record(
                    Diagnostics::CACHE_IO,
                    'Cannot harden cache directory; serve it outside the web root or deny access in your vhost.',
                    ['dir' => $root],
                );
            }
        }

        return $this->prepared = true;
    }

    private function now(): int
    {
        return $this->clock?->now() ?? time();
    }
}

/** Always-miss cache; disables caching without `null` checks at call sites. */
final class NullCache implements CacheInterface
{
    public function get(string $key): ?string
    {
        return null;
    }

    public function set(string $key, string $value, int $ttl = 0): bool
    {
        return true;
    }

    public function has(string $key): bool
    {
        return false;
    }

    public function delete(string $key): bool
    {
        return false;
    }

    public function clear(): int
    {
        return 0;
    }
}

/**
 * Wraps any PSR-16 SimpleCache implementation (Symfony Cache, laminas,
 * WordPress object-cache proxies, …) without requiring `psr/simple-cache`.
 */
final class Psr16Adapter implements CacheInterface
{
    public function __construct(private readonly object $cache, private readonly int $defaultTtl = 0)
    {
        foreach (['get', 'set', 'delete', 'has', 'clear'] as $method) {
            if (!method_exists($this->cache, $method)) {
                throw new \InvalidArgumentException(
                    "Psr16Adapter expects a SimpleCache-shaped object; '{$method}' is missing.",
                );
            }
        }
    }

    public function get(string $key): ?string
    {
        $value = $this->cache->get($key, null);

        return \is_string($value) ? $value : ($value === null ? null : (string) $value);
    }

    public function set(string $key, string $value, int $ttl = 0): bool
    {
        return (bool) $this->cache->set($key, $value, $ttl > 0 ? $ttl : ($this->defaultTtl > 0 ? $this->defaultTtl : null));
    }

    public function has(string $key): bool
    {
        return (bool) $this->cache->has($key);
    }

    public function delete(string $key): bool
    {
        return (bool) $this->cache->delete($key);
    }

    public function clear(): int
    {
        return $this->cache->clear() ? -1 : 0;
    }
}

}

namespace HtmlPhp\Event {

/**
 * Priority-ordered event dispatcher (WordPress-hook shaped by design).
 *
 * Two flavours share one registry:
 *  - `dispatch($tag, ...$args)` — fire-and-forget notifications
 *    (`htmlphp.render.before`, `htmlphp.error`, …);
 *  - `filter($tag, $value, ...$args)` — the value travels through every
 *    listener and the last result wins, exactly like `apply_filters()`.
 *
 * The WordPress bridge mirrors every tag onto `do_action`/`apply_filters`,
 * so themes can hook the engine without knowing it exists.
 */
final class Dispatcher
{
    /** @var array<string, array<int, array<int, callable>>> tag => priority => listeners */
    private array $listeners = [];

    /** @var array<string, int> recursion guard per tag */
    private array $running = [];

    private int $sequence = 0;

    /**
     * Registers a listener; returns a closure that removes it again.
     */
    public function on(string $tag, callable $listener, int $priority = 10): \Closure
    {
        $order = $this->sequence++;
        $this->listeners[$tag][$priority][$order] = $listener;

        return function () use ($tag, $priority, $order): void {
            unset($this->listeners[$tag][$priority][$order]);

            if (($this->listeners[$tag][$priority] ?? null) === []) {
                unset($this->listeners[$tag][$priority]);
            }

            if (($this->listeners[$tag] ?? null) === []) {
                unset($this->listeners[$tag]);
            }
        };
    }

    public function off(string $tag, ?int $priority = null): void
    {
        if ($priority === null) {
            unset($this->listeners[$tag]);

            return;
        }

        unset($this->listeners[$tag][$priority]);
    }

    public function has(string $tag): bool
    {
        foreach ($this->listeners[$tag] ?? [] as $bucket) {
            if ($bucket !== []) {
                return true;
            }
        }

        return false;
    }

    /** @return list<string> */
    public function tags(): array
    {
        return array_keys($this->listeners);
    }

    public function dispatch(string $tag, mixed ...$args): void
    {
        foreach ($this->sorted($tag) as $listener) {
            $listener(...$args);
        }
    }

    /**
     * Runs `$value` through every listener of `$tag` (chainable filters).
     * A listener returning `null` keeps the previous value, which makes
     * "observe-only" filters safe.
     */
    public function filter(string $tag, mixed $value, mixed ...$args): mixed
    {
        if (($this->running[$tag] ?? 0) > 32) {
            return $value; // runaway recursion guard
        }

        $this->running[$tag] = ($this->running[$tag] ?? 0) + 1;

        try {
            foreach ($this->sorted($tag) as $listener) {
                $result = $listener($value, ...$args);

                if ($result !== null) {
                    $value = $result;
                }
            }
        } finally {
            $this->running[$tag]--;
        }

        return $value;
    }

    public function reset(): void
    {
        $this->listeners = [];
        $this->running = [];
    }

    /** @return list<callable> */
    private function sorted(string $tag): array
    {
        $buckets = $this->listeners[$tag] ?? [];

        if ($buckets === []) {
            return [];
        }

        ksort($buckets);

        $sorted = [];

        foreach ($buckets as $listeners) {
            ksort($listeners);

            foreach ($listeners as $listener) {
                $sorted[] = $listener;
            }
        }

        return $sorted;
    }
}

}

namespace HtmlPhp {

use HtmlPhp\Config\Cache as CacheConfig;
use HtmlPhp\Config\I18n as I18nConfig;
use HtmlPhp\Config\Limits;
use HtmlPhp\Config\Log as LogConfig;
use HtmlPhp\Config\Security as SecurityConfig;
use HtmlPhp\Config\Ssi as SsiConfig;
use HtmlPhp\Config\Syntax as SyntaxConfig;
use HtmlPhp\Config\Templates as TemplatesConfig;
use HtmlPhp\Contracts\CacheInterface;
use HtmlPhp\Event\Dispatcher;
use HtmlPhp\Exception\ConfigException;
use HtmlPhp\Exception\ContainerException;
use HtmlPhp\I18n\Translator;
use HtmlPhp\I18n\TranslatorInterface;
use HtmlPhp\Log\LoggerInterface;
use HtmlPhp\Ssi\DocumentInfo;
use HtmlPhp\Ssi\Processor as SsiProcessor;
use HtmlPhp\Support\ClockInterface;
use HtmlPhp\Support\Str;
use HtmlPhp\Template\Filters;
use HtmlPhp\Template\LintIssue;
use HtmlPhp\Template\Linter;
use HtmlPhp\Template\RenderOptions;
use HtmlPhp\Template\RenderStats;
use HtmlPhp\Template\Renderer;
use HtmlPhp\Template\TemplateLocator;

/**
 * Immutable configuration aggregate.
 *
 * One `Config` value object replaces the ~35 `$GLOBALS['HTML_*']` keys of
 * v3. It is built once (`Config::fromArray()`, `Config::default()` or the
 * constructor), validated eagerly — unknown keys are rejected so typos fail
 * fast — and then handed to {@see Engine::create()}. `with*()` methods
 * return modified clones; the original never changes.
 *
 * ```php
 * $config = Config::fromArray([
 *     'debug'     => true,
 *     'templates' => ['paths' => [__DIR__ . '/tpl']],
 *     'ssi'       => ['exec_mode' => 'deny'],
 * ]);
 * ```
 */
final readonly class Config
{
    public function __construct(
        public bool $debug = false,
        public string $charset = 'UTF-8',
        public TemplatesConfig $templates = new TemplatesConfig(),
        public SyntaxConfig $syntax = new SyntaxConfig(),
        public SsiConfig $ssi = new SsiConfig(),
        public I18nConfig $i18n = new I18nConfig(),
        public CacheConfig $cache = new CacheConfig(),
        public LogConfig $log = new LogConfig(),
        public SecurityConfig $security = new SecurityConfig(),
        public Limits $limits = new Limits(),
    ) {}

    public static function default(): self
    {
        return new self();
    }

    /**
     * Builds a config from a nested array, rejecting unknown keys at every
     * level so a misspelled option is a hard error, not a silent no-op.
     *
     * @param array<string, mixed> $config
     */
    public static function fromArray(array $config): self
    {
        self::rejectUnknown($config, [
            'debug', 'charset', 'templates', 'syntax', 'ssi', 'i18n',
            'cache', 'log', 'security', 'limits',
        ], 'config');

        $group = static function (string $key, array $known) use ($config): array {
            $value = $config[$key] ?? [];

            if (!\is_array($value)) {
                throw new ConfigException("Config group '{$key}' must be an array.", ['value' => $value]);
            }

            self::rejectUnknown($value, $known, $key);

            return $value;
        };

        return new self(
            debug: self::bool($config, 'debug', false),
            charset: (string) self::value($config, 'charset', 'UTF-8'),
            templates: TemplatesConfig::fromArray($group('templates', TemplatesConfig::KEYS)),
            syntax: SyntaxConfig::fromArray($group('syntax', SyntaxConfig::KEYS)),
            ssi: SsiConfig::fromArray($group('ssi', SsiConfig::KEYS)),
            i18n: I18nConfig::fromArray($group('i18n', I18nConfig::KEYS)),
            cache: CacheConfig::fromArray($group('cache', CacheConfig::KEYS)),
            log: LogConfig::fromArray($group('log', LogConfig::KEYS)),
            security: SecurityConfig::fromArray($group('security', SecurityConfig::KEYS)),
            limits: Limits::fromArray($group('limits', [
                'max_template_bytes', 'max_include_bytes', 'max_ssi_depth', 'max_ssi_tags',
                'max_loop_rows', 'max_loop_depth', 'max_block_depth', 'max_passes',
                'max_expression_length', 'max_exec_output_bytes', 'exec_timeout',
                'max_diagnostics', 'max_precision',
            ])),
        );
    }

    /** @return array<string, mixed> */
    public function toArray(): array
    {
        return [
            'debug' => $this->debug,
            'charset' => $this->charset,
            'templates' => $this->templates->toArray(),
            'syntax' => $this->syntax->toArray(),
            'ssi' => $this->ssi->toArray(),
            'i18n' => $this->i18n->toArray(),
            'cache' => $this->cache->toArray(),
            'log' => $this->log->toArray(),
            'security' => $this->security->toArray(),
            'limits' => $this->limits->toArray(),
        ];
    }

    public function withDebug(bool $debug): self
    {
        return new self(
            $debug,
            $this->charset,
            $this->templates,
            $this->syntax,
            $this->ssi,
            $this->i18n,
            $this->cache,
            $this->log,
            $this->security,
            $this->limits,
        );
    }

    public function withSsi(SsiConfig $ssi): self
    {
        return new self(
            $this->debug,
            $this->charset,
            $this->templates,
            $this->syntax,
            $ssi,
            $this->i18n,
            $this->cache,
            $this->log,
            $this->security,
            $this->limits,
        );
    }

    public function withI18n(I18nConfig $i18n): self
    {
        return new self(
            $this->debug,
            $this->charset,
            $this->templates,
            $this->syntax,
            $this->ssi,
            $i18n,
            $this->cache,
            $this->log,
            $this->security,
            $this->limits,
        );
    }

    public function withCache(CacheConfig $cache): self
    {
        return new self(
            $this->debug,
            $this->charset,
            $this->templates,
            $this->syntax,
            $this->ssi,
            $this->i18n,
            $cache,
            $this->log,
            $this->security,
            $this->limits,
        );
    }

    public function withTemplates(TemplatesConfig $templates): self
    {
        return new self(
            $this->debug,
            $this->charset,
            $templates,
            $this->syntax,
            $this->ssi,
            $this->i18n,
            $this->cache,
            $this->log,
            $this->security,
            $this->limits,
        );
    }

    public function withSyntax(SyntaxConfig $syntax): self
    {
        return new self(
            $this->debug,
            $this->charset,
            $this->templates,
            $syntax,
            $this->ssi,
            $this->i18n,
            $this->cache,
            $this->log,
            $this->security,
            $this->limits,
        );
    }

    /**
     * Merges a partial array over this config (same shape as fromArray input).
     *
     * @param array<string, mixed> $overrides
     */
    public function merge(array $overrides): self
    {
        return self::fromArray(self::mergeArrays($this->toArray(), $overrides));
    }

    // ---------------------------------------------------------------- readers

    /** First present key wins; values are returned untyped. */
    /** @param array<string, mixed> $config */
    public static function value(array $config, string $key, mixed $default): mixed
    {
        return \array_key_exists($key, $config) && $config[$key] !== null ? $config[$key] : $default;
    }

    /** @param array<string, mixed> $config */
    public static function bool(array $config, string $key, bool $default): bool
    {
        if (!\array_key_exists($key, $config) || $config[$key] === null) {
            return $default;
        }

        $value = $config[$key];

        return match (true) {
            \is_bool($value) => $value,
            \is_int($value) => $value !== 0,
            \is_string($value) => !\in_array(strtolower($value), ['', '0', 'false', 'off', 'no'], true),
            default => (bool) $value,
        };
    }

    /** @param array<string, mixed> $config */
    public static function nullableBool(array $config, string $key): ?bool
    {
        if (!\array_key_exists($key, $config) || $config[$key] === null) {
            return null;
        }

        $value = $config[$key];

        if (\is_string($value) && strtolower($value) === 'auto') {
            return null;
        }

        return self::bool($config, $key, false);
    }

    /** @param array<string, mixed> $config */
    public static function int(array $config, string $key, int $default): int
    {
        if (!\array_key_exists($key, $config) || $config[$key] === null) {
            return $default;
        }

        $value = $config[$key];

        if (\is_int($value)) {
            return $value;
        }

        if (is_numeric($value)) {
            return (int) $value;
        }

        throw new ConfigException("Config key '{$key}' must be an integer.", ['value' => $value]);
    }

    /** @param array<string, mixed> $config */
    public static function nullableString(array $config, string $key): ?string
    {
        $value = $config[$key] ?? null;

        if ($value === null || $value === '') {
            return null;
        }

        if (!\is_scalar($value)) {
            throw new ConfigException("Config key '{$key}' must be a string or null.", ['key' => $key]);
        }

        return (string) $value;
    }

    /**
     * @param array<string, mixed> $config
     * @return list<string>
     */
    public static function stringList(array $config, string $key): array
    {
        $value = $config[$key] ?? [];

        if (!\is_array($value)) {
            throw new ConfigException("Config key '{$key}' must be an array of strings.", ['key' => $key]);
        }

        return array_values(array_map(
            static fn($item): string => \is_scalar($item) ? (string) $item : throw new ConfigException(
                "Config key '{$key}' must contain only strings.",
                ['key' => $key],
            ),
            $value,
        ));
    }

    /**
     * @param array<string, mixed> $config
     * @param array<array-key, mixed> $default
     * @return array<array-key, mixed>
     */
    public static function arrayValue(array $config, string $key, array $default): array
    {
        $value = $config[$key] ?? $default;

        if (!\is_array($value)) {
            throw new ConfigException("Config key '{$key}' must be an array.", ['key' => $key]);
        }

        return $value;
    }

    /** @param array<string, mixed> $config */
    public static function callableOrNull(array $config, string $key): ?callable
    {
        $value = $config[$key] ?? null;

        if ($value === null) {
            return null;
        }

        if (!\is_callable($value)) {
            throw new ConfigException("Config key '{$key}' must be callable.", ['key' => $key]);
        }

        return $value;
    }

    /**
     * @param array<array-key, mixed> $config
     * @param list<string> $known
     */
    private static function rejectUnknown(array $config, array $known, string $group): void
    {
        foreach (array_keys($config) as $key) {
            if (!\is_string($key) || !\in_array($key, $known, true)) {
                throw new ConfigException(
                    \sprintf(
                        'Unknown configuration key "%s" in group "%s". Known keys: %s.',
                        (string) $key,
                        $group,
                        implode(', ', $known),
                    ),
                    ['group' => $group, 'key' => $key],
                );
            }
        }
    }

    /**
     * Recursive merge where lists are replaced, not appended.
     *
     * @param array<array-key, mixed> $base
     * @param array<array-key, mixed> $overrides
     * @return array<array-key, mixed>
     */
    private static function mergeArrays(array $base, array $overrides): array
    {
        foreach ($overrides as $key => $value) {
            if (\is_array($value) && isset($base[$key]) && \is_array($base[$key]) && self::isAssoc($value) && self::isAssoc($base[$key])) {
                $base[$key] = self::mergeArrays($base[$key], $value);
                continue;
            }

            $base[$key] = $value;
        }

        return $base;
    }

    /** @param array<array-key, mixed> $array */
    private static function isAssoc(array $array): bool
    {
        if ($array === []) {
            return false;
        }

        return array_keys($array) !== range(0, \count($array) - 1);
    }
}

/**
 * Minimal lazy service container (PSR-11 shaped: `get()`/`has()`).
 *
 * The engine wires its own services through {@see self::withDefaults()};
 * hosts override any of them **before first use** by calling `instance()`
 * or `factory()`:
 *
 * ```php
 * $engine = Engine::create($config, function (Container $c): void {
 *     $c->instance(CacheInterface::class, new RedisCache($redis));
 * });
 * ```
 *
 * Deliberately tiny: no autowiring, no tags, no compilation — a full DI
 * component belongs to the host framework, and this container delegates
 * cleanly to one when present (register the host container as a factory).
 */
final class Container
{
    /** @var array<string, callable(Container): mixed> */
    private array $factories = [];

    /** @var array<string, mixed> */
    private array $instances = [];

    /**
     * Registers a lazy factory. The factory runs at most once; its result is
     * shared (singleton semantics).
     *
     * @param callable(Container): mixed $factory
     */
    public function factory(string $id, callable $factory): void
    {
        unset($this->instances[$id]);
        $this->factories[$id] = $factory;
    }

    /** Registers an already-built instance. */
    public function instance(string $id, mixed $instance): void
    {
        unset($this->factories[$id]);
        $this->instances[$id] = $instance;
    }

    public function has(string $id): bool
    {
        return isset($this->instances[$id]) || isset($this->factories[$id]);
    }

    public function get(string $id): mixed
    {
        if (\array_key_exists($id, $this->instances)) {
            return $this->instances[$id];
        }

        if (!isset($this->factories[$id])) {
            throw new ContainerException("Service '{$id}' is not registered.", ['id' => $id]);
        }

        return $this->instances[$id] = ($this->factories[$id])($this);
    }

    /**
     * Typed convenience wrapper around {@see self::get()}.
     *
     * @template T of object
     * @param class-string<T> $id
     * @return T
     */
    public function service(string $id): object
    {
        $service = $this->get($id);

        if (!$service instanceof $id) {
            throw new ContainerException(
                "Service '{$id}' resolved to " . get_debug_type($service) . '.',
                ['id' => $id],
            );
        }

        return $service;
    }

    /** @return list<string> */
    public function ids(): array
    {
        return array_values(array_unique([...array_keys($this->instances), ...array_keys($this->factories)]));
    }

    /** Drops every factory and instance (tests, long-running workers). */
    public function reset(): void
    {
        $this->factories = [];
        $this->instances = [];
    }

    /**
     * Container pre-wired with the full default service graph for `$config`.
     * Every service is lazy: unused services are never instantiated.
     */
    public static function withDefaults(Config $config): self
    {
        $container = new self();
        $container->instance(Config::class, $config);

        $container->factory(Support\ClockInterface::class, static fn(): Support\ClockInterface => new Support\SystemClock());

        $container->factory(Log\LoggerInterface::class, static fn(Container $c): Log\LoggerInterface
            => Log\LoggerFactory::create($c->service(Config::class)->log));

        $container->factory(Diagnostics::class, static fn(Container $c): Diagnostics => new Diagnostics(
            $c->service(Config::class)->limits->maxDiagnostics,
            $c->service(Config::class)->log->forwardDiagnostics ? $c->service(Log\LoggerInterface::class) : null,
            $c->service(Event\Dispatcher::class),
        ));

        $container->factory(Event\Dispatcher::class, static fn(): Event\Dispatcher => new Event\Dispatcher());

        $container->factory(Contracts\CacheInterface::class, static fn(Container $c): Contracts\CacheInterface
            => Cache\CacheFactory::create(
                $c->service(Config::class)->cache,
                $c->service(Diagnostics::class),
            ));

        $container->factory(Html\Escaper::class, static fn(): Html\Escaper => new Html\Escaper());

        $container->factory(I18n\Formats::class, static fn(Container $c): I18n\Formats
            => new I18n\Formats(
                $c->service(Config::class)->i18n,
                $c->service(Support\ClockInterface::class),
            ));

        $container->factory(Template\Filters::class, static fn(Container $c): Template\Filters => new Template\Filters(
            $c->service(Diagnostics::class),
            $c->service(Event\Dispatcher::class),
            $c->service(Html\Escaper::class),
            $c->service(I18n\TranslatorInterface::class),
            $c->service(I18n\Formats::class),
            $c->service(Config::class)->syntax->strict,
        ));

        $container->factory(Template\TemplateLocator::class, static fn(Container $c): Template\TemplateLocator
            => new Template\TemplateLocator(
                $c->service(Config::class)->templates,
                $c->service(Config::class)->security,
            ));

        $container->factory(I18n\TranslatorInterface::class, static fn(Container $c): I18n\TranslatorInterface
            => I18n\TranslatorFactory::create($c));

        $container->factory(Ssi\Processor::class, static fn(Container $c): Ssi\Processor => new Ssi\Processor(
            $c->service(Config::class),
            $c->service(Diagnostics::class),
            $c->service(Event\Dispatcher::class),
            $c->service(Html\Escaper::class),
            $c->service(Support\ClockInterface::class),
        ));

        $container->factory(Template\Renderer::class, static fn(Container $c): Template\Renderer => new Template\Renderer(
            $c->service(Config::class),
            $c->service(Diagnostics::class),
            $c->service(Event\Dispatcher::class),
            $c->service(Contracts\CacheInterface::class),
            $c->service(Ssi\Processor::class),
            $c->service(Template\Filters::class),
            $c->service(I18n\TranslatorInterface::class),
            $c->service(Html\Escaper::class),
            $c->service(Template\TemplateLocator::class),
        ));

        $container->factory(Template\Linter::class, static fn(Container $c): Template\Linter => new Template\Linter(
            $c->service(Config::class),
            $c->service(Diagnostics::class),
            $c->service(Template\Filters::class),
            $c->service(Template\TemplateLocator::class),
            ($t = $c->service(I18n\TranslatorInterface::class)) instanceof I18n\Translator ? $t : null,
        ));

        $container->factory(Engine::class, static fn(Container $c): Engine => new Engine(
            $c->service(Config::class),
            $c,
        ));

        return $container;
    }
}

/**
 * Bounded, structured diagnostics collector.
 *
 * Replaces the v3 static `Errors` registry: one instance per engine, wired
 * through the container. Non-fatal problems (missing variables, denied
 * `#exec`, failed includes, unknown filters) are recorded here instead of
 * throwing, optionally forwarded to a {@see LoggerInterface} and always
 * broadcast on the `htmlphp.error` event so hosts can react.
 */
final class Diagnostics
{
    // Diagnostic codes — stable identifiers, keep in sync with the docs.
    public const string MISSING_VAR = 'missing-var';
    public const string SSI_INCLUDE_FAILED = 'ssi-include-failed';
    public const string SSI_INCLUDE_CYCLE = 'ssi-include-cycle';
    public const string SSI_LIMIT_REACHED = 'ssi-limit-reached';
    public const string SSI_EXEC_DENIED = 'ssi-exec-denied';
    public const string SSI_EXEC_FAILED = 'ssi-exec-failed';
    public const string SSI_EXPR_ERROR = 'ssi-expr-error';
    public const string SSI_UNKNOWN_DIRECTIVE = 'ssi-unknown-directive';
    public const string FILTER_UNKNOWN = 'filter-unknown';
    public const string EXPR_INVALID = 'expr-invalid';
    public const string EXPR_DISABLED = 'expr-disabled';
    public const string REGEX_FAILED = 'regex-failed';
    public const string CATALOG_PARSE = 'catalog-parse';
    public const string CACHE_IO = 'cache-io';
    public const string LOOP_GUARD = 'loop-guard';
    public const string TEMPLATE_LINT = 'template-lint';
    public const string WP_BRIDGE = 'wp-bridge';

    /** @var list<array{code: string, message: string, context: array<string, mixed>, where: string, time: int}> */
    private array $entries = [];

    public function __construct(
        private readonly int $cap = 100,
        private readonly ?LoggerInterface $logger = null,
        private readonly ?Dispatcher $events = null
    ) {
    }

    /**
     * Records one entry. Entries beyond the cap are silently dropped — the
     * collector must never become a memory leak inside a loop-heavy render.
     *
     * @param array<string, mixed> $context
     */
    public function record(string $code, string $message, array $context = []): void
    {
        if (count($this->entries) < $this->cap) {
            $this->entries[] = [
                'code' => $code,
                'message' => $message,
                'context' => $context,
                'where' => $this->caller(),
                'time' => time(),
            ];
        }

        $this->logger?->warning($message, ['code' => $code, ...$context]);
        $this->events?->dispatch('htmlphp.error', $code, $message, $context);
    }

    /** @return list<array{code: string, message: string, context: array<string, mixed>, where: string, time: int}> */
    public function all(): array
    {
        return $this->entries;
    }

    /**
     * Entries whose code equals `$code` (empty string = all).
     *
     * @return list<array{code: string, message: string, context: array<string, mixed>, where: string, time: int}>
     */
    public function byCode(string $code): array
    {
        if ($code === '') {
            return $this->entries;
        }

        return array_values(array_filter(
            $this->entries,
            static fn(array $entry): bool => $entry['code'] === $code
        ));
    }

    public function count(string $code = ''): int
    {
        return $code === '' ? count($this->entries) : count($this->byCode($code));
    }

    /** @return array{code: string, message: string, context: array<string, mixed>, where: string, time: int}|null */
    #[\NoDiscard]
    public function last(): ?array
    {
        return array_last($this->entries); // PHP 8.5
    }

    public function clear(): void
    {
        $this->entries = [];
    }

    /** True when nothing was recorded — handy in tests and health checks. */
    public function clean(): bool
    {
        return $this->entries === [];
    }

    /** First frame outside this library, for actionable "where" info. */
    private function caller(): string
    {
        foreach (debug_backtrace(DEBUG_BACKTRACE_IGNORE_ARGS, 10) as $frame) {
            $file = (string) ($frame['file'] ?? '');

            if ($file !== '' && !str_contains($file, '/src/') && !str_contains($file, 'html.php')) {
                return $file . ':' . (int) ($frame['line'] ?? 0);
            }
        }

        return '(library)';
    }
}

/**
 * The public facade — everything a host application needs.
 *
 * ```php
 * $engine = Engine::create([
 *     'templates' => ['paths' => [__DIR__ . '/tpl']],
 *     'i18n'      => ['locale' => 'de', 'paths' => [__DIR__ . '/lang']],
 * ]);
 *
 * echo $engine->render('page.html', ['title' => 'Hello']);
 * ```
 *
 * Construction is explicit: a {@see Config} value object in, a wired
 * {@see Container} out. No globals, no statics, no hidden state — multiple
 * engines with different configurations coexist in one process.
 */
final class Engine
{
    private readonly Container $container;
    private ?RenderStats $lastStats = null;

    public function __construct(
        private readonly Config $config,
        ?Container $container = null,
    ) {
        $this->container = $container ?? Container::withDefaults($config);
        $this->container->instance(self::class, $this);

        $this->events()->on('htmlphp.rendered', function (RenderStats $stats): void {
            $this->lastStats = $stats;
        });
    }

    /**
     * Builds an engine from an array or Config, running `$setup` against the
     * container **before** any service is instantiated (override anything).
     *
     * @param Config|array<string, mixed> $config
     * @param (callable(Container): void)|null $setup
     */
    public static function create(Config|array $config = [], ?callable $setup = null): self
    {
        $config = $config instanceof Config ? $config : Config::fromArray($config);
        $container = Container::withDefaults($config);

        if ($setup !== null) {
            $setup($container);
        }

        return new self($config, $container);
    }

    // --------------------------------------------------------------- render

    /**
     * Renders a template located through the configured paths/namespaces.
     *
     * @param array<string, mixed> $vars
     */
    public function render(string $name, array $vars = [], ?RenderOptions $options = null): string
    {
        $path = $this->locator()->locate($name);

        if ($path === null) {
            throw new Exception\TemplateNotFoundException(
                "Template '{$name}' could not be located.",
                ['template' => $name, 'roots' => $this->locator()->roots()],
            );
        }

        return $this->renderer()->renderFile($path, $vars, $options);
    }

    /**
     * Renders a file by path (host-trusted; bypasses the locator but still
     * passes every size/security guard).
     *
     * @param array<string, mixed> $vars
     */
    public function renderFile(string $path, array $vars = [], ?RenderOptions $options = null): string
    {
        return $this->renderer()->renderFile($path, $vars, $options);
    }

    /**
     * Renders a template given as a string (database content, WP options,
     * ad-hoc fragments).
     *
     * @param array<string, mixed> $vars
     */
    public function renderString(string $source, array $vars = [], ?RenderOptions $options = null): string
    {
        return $this->renderer()->render($source, $vars, $options);
    }

    /**
     * Renders and echoes.
     *
     * @param array<string, mixed> $vars
     */
    public function display(string $name, array $vars = [], ?RenderOptions $options = null): void
    {
        echo $this->render($name, $vars, $options);
    }

    /** @param array<string, mixed> $vars */
    public function displayString(string $source, array $vars = [], ?RenderOptions $options = null): void
    {
        echo $this->renderString($source, $vars, $options);
    }

    // ------------------------------------------------------------------ SSI

    /**
     * Runs the SSI pass over arbitrary content (post bodies, option values,
     * legacy pages) — the public successor of v3's `html_ssi()`.
     */
    public function processSsi(string $content, ?DocumentInfo $document = null): string
    {
        return $this->ssi()->process($content, $document);
    }

    /**
     * The built-in SSI variable map for a document (successor of
     * `html_ssi_variables()`).
     *
     * @return array<string, string>
     */
    public function ssiVariables(?DocumentInfo $document = null): array
    {
        return $this->ssi()->variables($document);
    }

    // ----------------------------------------------------------------- i18n

    /** @param array<array-key, mixed> $args */
    public function t(string $msgid, array $args = [], ?string $domain = null): string
    {
        return $this->translator()->t($msgid, $args, $domain);
    }

    /** @param array<array-key, mixed> $args */
    public function n(string $singular, string $plural, int $count, array $args = [], ?string $domain = null): string
    {
        return $this->translator()->n($singular, $plural, $count, $args, $domain);
    }

    /** @param array<array-key, mixed> $args */
    public function x(string $msgid, string $context, array $args = [], ?string $domain = null): string
    {
        return $this->translator()->x($msgid, $context, $args, $domain);
    }

    /** @param array<array-key, mixed> $args */
    public function nx(string $singular, string $plural, int $count, string $context, array $args = [], ?string $domain = null): string
    {
        return $this->translator()->nx($singular, $plural, $count, $context, $args, $domain);
    }

    public function setLocale(string $locale): void
    {
        $this->translator()->setLocale($locale);
    }

    public function locale(): string
    {
        return $this->translator()->locale();
    }

    /**
     * Loads catalogues for a locale from the configured `i18n.paths`.
     *
     * @return list<string> loaded files
     */
    public function loadTranslations(string $locale, ?string $domain = null): array
    {
        $translator = $this->translator();

        if (!$translator instanceof Translator) {
            return [];
        }

        return $translator->loadConfigured($locale, $domain ?? $this->config->i18n->domain);
    }

    // ----------------------------------------------------------------- lint

    /** @return list<LintIssue> */
    public function lintString(string $source, string $origin = '-'): array
    {
        return $this->linter()->lint($source, $origin);
    }

    /** @return list<LintIssue> */
    public function lint(string $nameOrPath): array
    {
        $path = is_file($nameOrPath) ? $nameOrPath : $this->locator()->locate($nameOrPath);

        if ($path === null) {
            return [new LintIssue('error', 'template-unreadable', "Template '{$nameOrPath}' could not be located.", $nameOrPath)];
        }

        return $this->linter()->lintFile($path);
    }

    /** @return array<string, list<LintIssue>> */
    public function lintDirectory(string $directory): array
    {
        return $this->linter()->lintDirectory($directory);
    }

    // --------------------------------------------------------------- services

    public function config(): Config
    {
        return $this->config;
    }

    public function container(): Container
    {
        return $this->container;
    }

    public function renderer(): Renderer
    {
        return $this->container->service(Renderer::class);
    }

    public function locator(): TemplateLocator
    {
        return $this->container->service(TemplateLocator::class);
    }

    public function ssi(): SsiProcessor
    {
        return $this->container->service(SsiProcessor::class);
    }

    public function translator(): TranslatorInterface
    {
        return $this->container->service(TranslatorInterface::class);
    }

    public function filters(): Filters
    {
        return $this->container->service(Filters::class);
    }

    public function events(): Dispatcher
    {
        return $this->container->service(Dispatcher::class);
    }

    public function cache(): CacheInterface
    {
        return $this->container->service(CacheInterface::class);
    }

    public function logger(): LoggerInterface
    {
        return $this->container->service(LoggerInterface::class);
    }

    public function diagnostics(): Diagnostics
    {
        return $this->container->service(Diagnostics::class);
    }

    public function clock(): ClockInterface
    {
        return $this->container->service(ClockInterface::class);
    }

    public function linter(): Linter
    {
        return $this->container->service(Linter::class);
    }

    public function escaper(): Html\Escaper
    {
        return $this->container->service(Html\Escaper::class);
    }

    /** Stats of the most recent render (null before the first one). */
    public function stats(): ?RenderStats
    {
        return $this->lastStats;
    }

    /** Purges the render cache and drops memoized parse trees. */
    public function clearCache(): int
    {
        $this->renderer()->clearParsed();
        Template\Expression::reset();

        return $this->cache()->clear();
    }

    public function version(): string
    {
        return Version::banner();
    }
}

/**
 * Sanitised copies of the PHP input superglobals.
 *
 * This class is the single place in the whole library allowed to *read*
 * `$_GET`/`$_POST`/`$_COOKIE`/`$_REQUEST`, and it never writes to them.
 * Hosts that want the old `HTML_Sanitized_Input()` behaviour call
 * {@see self::all()} once at the edge and pass the result around explicitly.
 */
final class Input
{
    private function __construct() {}

    /**
     * `['get' => …, 'post' => …, 'cookie' => …, 'request' => …]` with every
     * string recursively `htmlspecialchars()`-encoded.
     *
     * @return array{get: array<array-key, mixed>, post: array<array-key, mixed>, cookie: array<array-key, mixed>, request: array<array-key, mixed>}
     */
    public static function all(): array
    {
        return [
            'get' => Support\Str::sanitizeRecursive($_GET),
            'post' => Support\Str::sanitizeRecursive($_POST),
            'cookie' => Support\Str::sanitizeRecursive($_COOKIE),
            'request' => Support\Str::sanitizeRecursive($_REQUEST),
        ];
    }

    /**
     * Sanitised `$_GET`/`$_POST`/`$_COOKIE`/`$_REQUEST` by name.
     *
     * @return array<array-key, mixed>
     */
    public static function source(string $name): array
    {
        $source = match (strtolower($name)) {
            'get' => $_GET,
            'post' => $_POST,
            'cookie' => $_COOKIE,
            'request' => $_REQUEST,
            default => throw new \InvalidArgumentException("Unknown input source '{$name}'."),
        };

        return Support\Str::sanitizeRecursive($source);
    }
}

/**
 * Immutable snapshot of the host request environment.
 *
 * This is the **only** sanctioned way request data reaches the engine: the
 * host builds it once at the edge (`RequestContext::fromServer($_SERVER)`)
 * and passes it explicitly. Nothing inside the library reads `$_SERVER`.
 */
final class RequestContext
{
    /**
     * @param array<string, string> $server sanitised string copy of the
     *        server variables that back `HTTP_*` SSI echo lookups
     */
    public function __construct(
        public readonly string $documentRoot = '',
        public readonly string $scriptName = '',
        public readonly string $requestUri = '',
        public readonly string $documentName = '',
        public readonly string $documentUri = '',
        public readonly string $queryString = '',
        public readonly string $method = 'GET',
        public readonly string $remoteAddr = '',
        public readonly string $userAgent = '',
        public readonly string $acceptLanguage = '',
        public readonly string $referer = '',
        public readonly array $server = [],
    ) {}

    /**
     * Builds a context from a `$_SERVER`-shaped array.
     *
     * @param array<string, mixed> $server
     */
    public static function fromServer(array $server): self
    {
        $string = static fn(string $key): string => isset($server[$key]) && \is_scalar($server[$key])
            ? (string) $server[$key]
            : '';

        $requestUri = $string('REQUEST_URI');
        $scriptName = $string('SCRIPT_NAME');
        $path = parse_url($requestUri, PHP_URL_PATH);

        $clean = [];
        foreach ($server as $key => $value) {
            if (\is_string($key) && \is_scalar($value)) {
                $clean[$key] = (string) $value;
            }
        }

        return new self(
            documentRoot: $string('DOCUMENT_ROOT'),
            scriptName: $scriptName,
            requestUri: $requestUri,
            documentName: \is_string($path) && $path !== ''
                ? basename($path)
                : ($scriptName !== '' ? basename($scriptName) : ''),
            documentUri: \is_string($path) && $path !== '' ? $path : ($scriptName !== '' ? $scriptName : '/'),
            queryString: $string('QUERY_STRING'),
            method: strtoupper($string('REQUEST_METHOD') ?: 'GET'),
            remoteAddr: $string('REMOTE_ADDR'),
            userAgent: $string('HTTP_USER_AGENT'),
            acceptLanguage: $string('HTTP_ACCEPT_LANGUAGE'),
            referer: $string('HTTP_REFERER'),
            server: $clean,
        );
    }

    /** A neutral context for CLI runs, queue workers and tests. */
    public static function cli(string $cwd = ''): self
    {
        $cwd = $cwd !== '' ? $cwd : (getcwd() ?: '');

        return new self(documentRoot: $cwd, scriptName: '', requestUri: '/', documentUri: '/', method: 'CLI');
    }

    /** HTTP_* lookup used by SSI `#echo`/`#printenv`. */
    public function http(string $name): ?string
    {
        $key = strtoupper($name);

        if (isset($this->server[$key])) {
            return $this->server[$key];
        }

        $key = str_starts_with($key, 'HTTP_') ? $key : 'HTTP_' . $key;

        return $this->server[$key] ?? null;
    }
}

/**
 * A named stack of variable scopes used while rendering.
 *
 * Lookups walk the stack top-down (innermost wins), which gives loops and
 * partials natural shadowing semantics. There is deliberately **no**
 * fallback to `$GLOBALS`: a name either exists in some frame or it is
 * missing, and the configured {@see Config\MissingVarPolicy} decides what
 * happens then.
 */
final class Scope
{
    /** Ceiling for dynamic (`[…]`) keys — a lookup key is data, not a document. */
    private const int MAX_KEY_LENGTH = 256;

    /** @var list<array<string, mixed>> */
    private array $frames;

    /**
     * @param array<string, mixed> $root outermost frame
     */
    public function __construct(array $root = [])
    {
        $this->frames = [$root];
    }

    /**
     * Pushes a new innermost frame.
     *
     * @param array<string, mixed> $vars
     */
    public function push(array $vars = []): void
    {
        $this->frames[] = $vars;
    }

    /** Removes the innermost frame (the root frame is never removed). */
    public function pop(): void
    {
        if (\count($this->frames) > 1) {
            array_pop($this->frames);
        }
    }

    /**
     * Runs `$callback` with an extra frame on the stack.
     *
     * @param array<string, mixed> $vars
     */
    public function with(array $vars, callable $callback): mixed
    {
        $this->push($vars);

        try {
            return $callback($this);
        } finally {
            $this->pop();
        }
    }

    public function depth(): int
    {
        return \count($this->frames);
    }

    /**
     * Finds a name in the innermost frame that defines it.
     * Dot notation (`user.address.city`) walks arrays, objects and
     * ArrayAccess. Returns `[found, value]`.
     *
     * @return array{0: bool, 1: mixed}
     */
    public function find(string $name): array
    {
        if ($name === '') {
            return [false, null];
        }

        // Fast path: plain key in any frame, innermost first.
        if (!str_contains($name, '.')) {
            for ($i = \count($this->frames) - 1; $i >= 0; $i--) {
                if (\array_key_exists($name, $this->frames[$i])) {
                    return [true, $this->frames[$i][$name]];
                }
            }

            return [false, null];
        }

        [$head, $rest] = explode('.', $name, 2);

        for ($i = \count($this->frames) - 1; $i >= 0; $i--) {
            if (\array_key_exists($head, $this->frames[$i])) {
                $value = $this->frames[$i][$head];
                $found = self::step($value, $rest);

                if ($found[0]) {
                    return $found;
                }
            }
        }

        return [false, null];
    }

    public function has(string $name): bool
    {
        return $this->find($name)[0];
    }

    public function get(string $name, mixed $default = null): mixed
    {
        [$found, $value] = $this->find($name);

        return $found ? $value : $default;
    }

    /**
     * Writes into the innermost frame (used by `<!--@Set-->` and loop vars).
     */
    public function set(string $name, mixed $value): void
    {
        $last = \count($this->frames) - 1;
        $this->frames[$last][$name] = $value;
    }

    /**
     * Merged view of all frames (innermost wins) — used by partials that
     * inherit the caller scope and by `#printenv`-style debugging.
     *
     * @return array<string, mixed>
     */
    public function all(): array
    {
        $merged = [];

        foreach ($this->frames as $frame) {
            $merged = array_merge($merged, $frame);
        }

        return $merged;
    }

    /**
     * Walks a dotted path (`a.b.c`) through arrays, `ArrayAccess`, objects
     * and public properties — the shared accessor for `%{user.name}` style
     * lookups and for expression index/property chains.
     *
     * Deliberately conservative: only *public* properties and zero-argument
     * methods (including `getX()`/`isX()`/`hasX()` accessors) are reachable,
     * magic `__get` aside. There is no way to write, no method arguments and
     * no static/class-constant access, so a template can read a DTO but can
     * never invoke behaviour on it.
     *
     * @return array{0: bool, 1: mixed} `[found, value]`
     */
    public static function step(mixed $value, string $path): array
    {
        foreach (explode('.', $path) as $segment) {
            if ($segment === '') {
                return [false, null];
            }

            if (\is_array($value)) {
                if (!\array_key_exists($segment, $value)) {
                    return [false, null];
                }
                $value = $value[$segment];
                continue;
            }

            if ($value instanceof \ArrayAccess) {
                if (!$value->offsetExists($segment)) {
                    return [false, null];
                }
                $value = $value->offsetGet($segment);
                continue;
            }

            if (\is_object($value)) {
                if (isset($value->{$segment})) {
                    $value = $value->{$segment};
                    continue;
                }

                if (method_exists($value, $segment)) {
                    $value = $value->{$segment}();
                    continue;
                }

                // Support getX()/isX() accessors used by many DTOs.
                foreach (['get', 'is', 'has'] as $prefix) {
                    $method = $prefix . ucfirst($segment);
                    if (method_exists($value, $method)) {
                        $value = $value->{$method}();
                        continue 2;
                    }
                }
            }

            return [false, null];
        }

        return [true, $value];
    }

    /**
     * Reads one element out of a value by an *arbitrary* key — the
     * `name[expr]` primitive behind nested/dynamic variable access.
     *
     * Unlike {@see self::step()}, the key is computed at render time from
     * template data, so it is validated hard: only `int` and `string` keys
     * are honoured (anything else — including arrays, objects and `null` —
     * yields "not found"), keys are length-capped, and only arrays,
     * `ArrayAccess` and strings are indexable. Plain objects are **not**
     * reachable by dynamic key: property access requires a literal dotted
     * path, so data flowing in from a request can never be turned into a
     * property/method name.
     *
     * @return array{0: bool, 1: mixed} `[found, value]`
     */
    public static function index(mixed $value, mixed $key): array
    {
        if (\is_int($key)) {
            // Fast path below.
        } elseif (\is_string($key)) {
            if ($key === '' || \strlen($key) > self::MAX_KEY_LENGTH || str_contains($key, "\0")) {
                return [false, null];
            }
        } else {
            return [false, null];
        }

        if (\is_string($value)) {
            if (!\is_int($key) && !self::isIntegerString($key)) {
                return [false, null];
            }

            $offset = (int) $key;
            $length = Str::length($value);

            if ($offset < 0) {
                $offset += $length;
            }

            return $offset >= 0 && $offset < $length
                ? [true, Str::substr($value, $offset, 1)]
                : [false, null];
        }

        if (\is_array($value)) {
            return \array_key_exists($key, $value) ? [true, $value[$key]] : [false, null];
        }

        if ($value instanceof \ArrayAccess) {
            return $value->offsetExists($key) ? [true, $value->offsetGet($key)] : [false, null];
        }

        return [false, null];
    }

    private static function isIntegerString(string $value): bool
    {
        return preg_match('/^-?\d+$/', $value) === 1;
    }
}

/**
 * Version metadata and the runtime guard used by the single-file bundles.
 */
final class Version
{
    public const string VERSION = '5.0.0';

    /** This is the PHP 8.5 edition overlay (see tools/build.php). */
    public const string EDITION = '8.5';

    public const int MIN_PHP = 80500;

    public const string BUILD_DATE = '2026-10-12';

    private function __construct()
    {
    }

    /** `"5.0.0 (8.5 edition)"` */
    #[\NoDiscard('The version banner is never meant to be discarded.')]
    public static function banner(): string
    {
        return self::VERSION . ' (' . self::EDITION . ' edition)';
    }

    /**
     * Fails fast with a clear message when the running PHP is too old —
     * called from the bundle guard; Composer users are protected by the
     * platform requirement instead.
     */
    public static function assertRuntime(): void
    {
        if (PHP_VERSION_ID < self::MIN_PHP) {
            throw new Exception\HtmlPhpException(sprintf(
                'HTML.PHP %s (%s edition) requires PHP %d.%d or newer; running %s.',
                self::VERSION,
                self::EDITION,
                intdiv(self::MIN_PHP, 10000),
                intdiv(self::MIN_PHP % 10000, 100),
                PHP_VERSION
            ));
        }
    }
}

}

namespace HtmlPhp\Ssi {

use HtmlPhp\Config;
use HtmlPhp\Config\ExecMode;
use HtmlPhp\Config\Limits;
use HtmlPhp\Config\Security as SecurityConfig;
use HtmlPhp\Config\Ssi as SsiConfig;
use HtmlPhp\Diagnostics;
use HtmlPhp\Event\Dispatcher;
use HtmlPhp\Html\Escaper;
use HtmlPhp\Io\Files;
use HtmlPhp\RequestContext;
use HtmlPhp\Support\ClockInterface;
use HtmlPhp\Support\Pcre;
use HtmlPhp\Support\Str;
use HtmlPhp\Version;

/**
 * Parser for SSI directive attribute lists.
 *
 * Accepts double-quoted, single-quoted and (unlike mod_include, as a
 * documented convenience) unquoted values; attribute order is irrelevant.
 * Example: var="NAME" value='VALUE' stub=plain
 */
final class Attributes
{
    private function __construct() {}

    /**
     * @return array<string, string> lower-cased attribute name => raw value
     */
    public static function parse(string $source): array
    {
        $attributes = [];

        preg_match_all(
            '~([A-Za-z_][A-Za-z0-9_-]*)\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s\'"]+))~s',
            $source,
            $matches,
            \PREG_SET_ORDER | \PREG_UNMATCHED_AS_NULL,
        );

        foreach ($matches as $match) {
            $name = strtolower((string) $match[1]);
            $attributes[$name] = (string) ($match[2] ?? $match[3] ?? $match[4] ?? '');
        }

        return $attributes;
    }
}

/**
 * Computes the mod_include built-in variables from the injected request
 * context and clock — never from `$_SERVER`.
 */
final class Builtins
{
    private function __construct() {}

    public static function isBuiltin(string $name): bool
    {
        return isset(SsiContext::BUILTIN_NAMES[$name]);
    }

    /**
     * The whole built-in map for one render context.
     *
     * @return array<string, string>
     */
    public static function map(SsiContext $context): array
    {
        $timefmt = $context->timefmt;
        $now = $context->timestamp();
        $request = $context->request();
        $documentUri = self::documentUri($request, $context->document->file, $context->documentRoot());
        $documentRoot = $context->documentRoot();

        $lastModified = '';
        $currentFile = $context->document->file;

        if (\is_string($currentFile) && $currentFile !== '' && is_file($currentFile)) {
            $modified = @filemtime($currentFile);

            if ($modified !== false) {
                $lastModified = TimeFormat::format($modified, $timefmt);
            }
        }

        return [
            'DATE_LOCAL' => TimeFormat::format($now, $timefmt),
            'DATE_GMT' => TimeFormat::format($now, $timefmt, true),
            'DOCUMENT_URI' => $documentUri,
            'DOCUMENT_NAME' => $documentUri === '' ? '' : basename($documentUri),
            'DOCUMENT_ROOT' => $documentRoot,
            'QUERY_STRING' => $request->queryString,
            'SERVER_NAME' => self::server($request, 'SERVER_NAME'),
            'SERVER_SOFTWARE' => self::server($request, 'SERVER_SOFTWARE', 'HTML.PHP/' . Version::VERSION),
            'SERVER_PROTOCOL' => self::server($request, 'SERVER_PROTOCOL', 'HTTP/1.1'),
            'REQUEST_METHOD' => $request->method !== '' ? $request->method : 'GET',
            'REQUEST_URI' => self::server($request, 'REQUEST_URI', $documentUri),
            'SCRIPT_NAME' => $request->scriptName,
            'CONTENT_TYPE' => self::server($request, 'CONTENT_TYPE', self::server($request, 'HTTP_CONTENT_TYPE')),
            'REMOTE_ADDR' => $request->remoteAddr,
            'HTTP_USER_AGENT' => $request->userAgent,
            'LAST_MODIFIED' => $lastModified,
        ];
    }

    /**
     * DOCUMENT_URI: the request path when known, otherwise the current file
     * expressed relative to the document root (CLI renders, string renders).
     */
    private static function documentUri(RequestContext $request, ?string $file, string $root): string
    {
        $uri = $request->documentUri;

        if ($uri === '' || $uri === '/') {
            $uri = self::fromFile($request->requestUri !== '' ? $request->requestUri : $request->scriptName);
        }

        if ($uri === '' && \is_string($file) && $file !== '') {
            $real = realpath($file);

            if ($real !== false && $root !== '') {
                $normalized = str_replace('\\', '/', $real);
                $rootNormalized = rtrim(str_replace('\\', '/', $root), '/');

                if (str_starts_with($normalized, $rootNormalized . '/')) {
                    return '/' . substr($normalized, \strlen($rootNormalized) + 1);
                }
            }
        }

        return $uri;
    }

    private static function fromFile(string $uri): string
    {
        if ($uri === '') {
            return '';
        }

        $uri = (string) preg_replace('~\?.*$~s', '', $uri);
        $uri = str_replace('\\', '/', $uri);

        return str_starts_with($uri, '/') ? $uri : '/' . $uri;
    }

    private static function server(RequestContext $request, string $key, string $default = ''): string
    {
        return Str::stringify($request->server[$key] ?? $default);
    }
}

/**
 * Contract for custom SSI directives.
 *
 * Register through {@see DirectiveRegistry::register()}; a registered name
 * overrides a built-in of the same name, letting hosts replace e.g.
 * `#include` resolution with their own (WordPress template parts, S3, …).
 */
interface DirectiveInterface
{
    /** Directive name without the `#` (lowercase, e.g. `mywidget`). */
    public function name(): string;

    /**
     * Renders the directive.
     *
     * @param array<string, string> $attributes lower-cased attribute map
     * @param SsiContext $context current document state (vars, budgets, paths)
     * @return string output to splice into the document ('' for side-effect-only directives)
     */
    public function render(array $attributes, SsiContext $context): string;
}

/**
 * Registry of custom (or overriding) SSI directives.
 */
final class DirectiveRegistry
{
    /** @var array<string, DirectiveInterface> */
    private array $directives = [];

    public function register(DirectiveInterface $directive): void
    {
        $name = strtolower(trim($directive->name()));

        if ($name === '' || preg_match('/^[a-z][a-z0-9_-]*$/', $name) !== 1) {
            throw new \InvalidArgumentException(
                'Directive names must match [a-z][a-z0-9_-]* — got "' . $directive->name() . '".',
            );
        }

        $this->directives[$name] = $directive;
    }

    public function has(string $name): bool
    {
        return isset($this->directives[strtolower($name)]);
    }

    public function get(string $name): ?DirectiveInterface
    {
        return $this->directives[strtolower($name)] ?? null;
    }

    /** @return list<string> */
    public function names(): array
    {
        return array_keys($this->directives);
    }

    public function clear(): void
    {
        $this->directives = [];
    }
}

/**
 * Identity of the document being processed.
 *
 * Anchors relative `file=` includes, `LAST_MODIFIED`, `DOCUMENT_URI` and the
 * containment root. Built by the caller (Engine, WordPress bridge, CLI) —
 * the SSI layer never reaches for `$_SERVER` itself.
 *
 * @param array<string, mixed> $vars extra variables visible to `#if`/`#echo`
 *        (the Engine injects the current render scope here)
 */
final readonly class DocumentInfo
{
    /**
     * @param array<string, mixed> $vars
     */
    public function __construct(
        public ?string $file = null,
        public ?string $root = null,
        public ?RequestContext $request = null,
        public array $vars = [],
    ) {}

    /** Document for a plain string render (no file on disk). */
    public static function forString(?string $root = null, ?RequestContext $request = null): self
    {
        return new self(null, $root, $request);
    }

    /**
     * @param array<string, mixed> $vars
     */
    public function withVars(array $vars): self
    {
        return new self($this->file, $this->root, $this->request, $vars);
    }
}

/**
 * `<!--#exec cmd="…" -->` / `<!--#exec cgi="…" -->` execution.
 *
 * Deny-by-default. Three policies ({@see ExecMode}):
 *  - `Deny`      — refuse everything (default; a template is data, not a shell);
 *  - `AllowList` — `cmd=` binaries must resolve against `ssi.exec_cmd_allow`
 *                  entries (realpath-compared or basename-matched); `cgi=`
 *                  scripts must live under the document root and carry an
 *                  allowed extension;
 *  - `Delegate`  — a host callable decides per directive (`true`, `false` or
 *                  a string used as the output).
 *
 * Spawned processes get a minimal CGI environment, a hard timeout and an
 * output byte cap; both are enforced through `proc_open()` + `stream_select()`.
 */
final class Exec
{
    public function __construct(
        private readonly SsiConfig $config,
        private readonly Limits $limits,
        private readonly SecurityConfig $security,
        private readonly Diagnostics $diagnostics,
    ) {}

    /** Runs `#exec cmd="…"`. */
    public function runCmd(string $command, SsiContext $context): string
    {
        $decision = $this->decide('cmd', $command, $context);

        if ($decision['output'] !== null) {
            return $decision['output'];
        }

        if ($decision['mode'] === 'deny') {
            return $context->errorText();
        }

        $argv = self::tokenizeCommand($command);

        if ($argv === []) {
            $this->diagnostics->record(Diagnostics::SSI_EXEC_FAILED, 'SSI #exec cmd is empty.');

            return $context->errorText();
        }

        $skipAllowList = $decision['mode'] === 'delegate';

        if (!$skipAllowList) {
            $binary = $this->resolveAllowedBinary($argv[0]);

            if ($binary === null) {
                $this->diagnostics->record(
                    Diagnostics::SSI_EXEC_DENIED,
                    'SSI #exec cmd binary is not on ssi.exec_cmd_allow.',
                    ['command' => $argv[0]],
                );

                return $context->errorText();
            }

            $argv[0] = $binary;
        }

        $environment = [
            'PATH' => $this->environment($context, 'PATH', getenv('PATH') ?: '/usr/bin:/bin'),
            'DOCUMENT_ROOT' => $context->documentRoot(),
            'SERVER_NAME' => $this->environment($context, 'SERVER_NAME'),
            'GATEWAY_INTERFACE' => 'CGI/1.1',
        ];

        return $this->runProcess($argv, $environment, $context->documentRoot());
    }

    /** Runs `#exec cgi="…"`. */
    public function runCgi(string $virtual, SsiContext $context): string
    {
        $decision = $this->decide('cgi', $virtual, $context);

        if ($decision['output'] !== null) {
            return $decision['output'];
        }

        if ($decision['mode'] === 'deny') {
            return $context->errorText();
        }

        $script = $context->resolveExecutable($virtual);

        if ($script === null) {
            $this->diagnostics->record(
                Diagnostics::SSI_EXEC_DENIED,
                'SSI #exec cgi script did not resolve inside the document root.',
                ['virtual' => $virtual],
            );

            return $context->errorText();
        }

        $extension = strtolower(pathinfo($script, PATHINFO_EXTENSION));
        $allowedExtensions = array_map(
            static fn(string $value): string => strtolower($value),
            $this->config->execCgiExtensions,
        );

        if ($decision['mode'] !== 'delegate' && !\in_array($extension, $allowedExtensions, true)) {
            $this->diagnostics->record(
                Diagnostics::SSI_EXEC_DENIED,
                'SSI #exec cgi extension is not allowed.',
                ['script' => $script, 'extension' => $extension],
            );

            return $context->errorText();
        }

        if ($this->config->execCgiMode === 'include') {
            return $this->runInclude($script, $context);
        }

        $environment = [
            'PATH' => $this->environment($context, 'PATH', getenv('PATH') ?: '/usr/bin:/bin'),
            'DOCUMENT_ROOT' => $context->documentRoot(),
            'SCRIPT_NAME' => '/' . ltrim(str_replace('\\', '/', $virtual), '/'),
            'SCRIPT_FILENAME' => $script,
            'REQUEST_METHOD' => $this->environment($context, 'REQUEST_METHOD', 'GET'),
            'QUERY_STRING' => $this->environment($context, 'QUERY_STRING'),
            'SERVER_NAME' => $this->environment($context, 'SERVER_NAME', 'localhost'),
            'SERVER_PROTOCOL' => $this->environment($context, 'SERVER_PROTOCOL', 'HTTP/1.1'),
            'GATEWAY_INTERFACE' => 'CGI/1.1',
            'REDIRECT_STATUS' => '200',
            'HTTP_USER_AGENT' => $this->environment($context, 'HTTP_USER_AGENT'),
        ];

        $argv = [PHP_BINARY, '-d', 'display_errors=0', '-d', 'log_errors=0', '-f', $script];

        return $this->runProcess($argv, $environment, \dirname($script));
    }

    // ---------------------------------------------------------------- policy

    /**
     * Applies the configured policy.
     *
     * @return array{mode: 'allow'|'deny'|'delegate', output: string|null}
     *         `output` non-null means "use this literal output"; mode
     *         `delegate` allows execution outright, `allow` still runs the
     *         allow-list checks.
     */
    private function decide(string $kind, string $target, SsiContext $context): array
    {
        if ($target === '' || str_contains($target, "\0")) {
            return ['mode' => 'deny', 'output' => null];
        }

        return match ($this->config->execMode) {
            ExecMode::Deny => $this->deny($kind, 'SSI #exec is disabled (ssi.exec_mode=deny).'),
            ExecMode::Delegate => $this->delegate($kind, $target, $context),
            ExecMode::AllowList => ['mode' => 'allow', 'output' => null],
        };
    }

    /** @return array{mode: 'allow'|'deny'|'delegate', output: string|null} */
    private function delegate(string $kind, string $target, SsiContext $context): array
    {
        $callback = $this->config->execDelegate;

        if (!\is_callable($callback)) {
            return $this->deny($kind, 'SSI #exec delegate is not callable.');
        }

        $result = $callback($kind, [
            'target' => $target,
            'document' => (string) $context->document->file,
            'root' => $context->documentRoot(),
        ]);

        if (\is_string($result)) {
            return ['mode' => 'deny', 'output' => $this->sanitize($result)];
        }

        if ($result === true) {
            return ['mode' => 'delegate', 'output' => null];
        }

        return $this->deny($kind, 'SSI #exec was refused by the host delegate.');
    }

    /** @return array{mode: 'deny', output: null} */
    private function deny(string $kind, string $reason): array
    {
        $this->diagnostics->record(Diagnostics::SSI_EXEC_DENIED, $reason, ['kind' => $kind]);

        return ['mode' => 'deny', 'output' => null];
    }

    /**
     * Splits a command line into argv tokens honouring single and double
     * quotes. No shell interpretation takes place (`proc_open` array form).
     *
     * @return list<string>
     */
    public static function tokenizeCommand(string $command): array
    {
        $tokens = [];
        $length = \strlen($command);
        $current = '';
        $quoted = false;
        $hasToken = false;

        for ($index = 0; $index < $length; ++$index) {
            $char = $command[$index];

            if ($quoted) {
                if ($char === '\\' && $index + 1 < $length && $command[$index + 1] === '"') {
                    $current .= '"';
                    ++$index;
                    continue;
                }

                if ($char === '"') {
                    $quoted = false;
                    continue;
                }

                $current .= $char;
                continue;
            }

            if ($char === '"') {
                $quoted = true;
                $hasToken = true;
                continue;
            }

            if ($char === "'") {
                $end = strpos($command, "'", $index + 1);
                $end = $end === false ? $length : $end;
                $current .= substr($command, $index + 1, $end - $index - 1);
                $index = $end;
                $hasToken = true;
                continue;
            }

            if ($char === ' ' || $char === "\t") {
                if ($hasToken || $current !== '') {
                    $tokens[] = $current;
                    $current = '';
                    $hasToken = false;
                }

                continue;
            }

            $current .= $char;
            $hasToken = true;
        }

        if ($hasToken || $current !== '') {
            $tokens[] = $current;
        }

        return $tokens;
    }

    /** Resolves the command's binary against the allow-list. */
    private function resolveAllowedBinary(string $binary): ?string
    {
        $allow = $this->config->execCmdAllow;

        if ($allow === []) {
            return null;
        }

        $allowStrings = array_map(static fn(mixed $value): string => Str::stringify($value), $allow);
        $candidates = [];

        if (str_contains($binary, '/') || str_contains($binary, '\\')) {
            $candidates[] = $binary;
        } else {
            foreach (explode(PATH_SEPARATOR, (string) (getenv('PATH') ?: '')) as $directory) {
                if ($directory !== '') {
                    $candidates[] = rtrim($directory, "/\\") . DIRECTORY_SEPARATOR . $binary;
                }
            }
        }

        foreach ($candidates as $candidate) {
            $resolved = realpath($candidate);

            if ($resolved === false || !is_file($resolved) || !is_executable($resolved)) {
                continue;
            }

            foreach ($allowStrings as $allowed) {
                if ($allowed === '') {
                    continue;
                }

                $allowedResolved = realpath($allowed);

                if ($allowedResolved !== false) {
                    if (Files::normalizeForCompare($resolved) === Files::normalizeForCompare($allowedResolved)) {
                        return $resolved;
                    }

                    continue;
                }

                if ($allowed === basename($resolved)) {
                    return $resolved;
                }
            }
        }

        return null;
    }

    private function environment(SsiContext $context, string $key, string $default = ''): string
    {
        $value = $context->request()->server[$key] ?? null;

        return \is_string($value) && $value !== '' ? $value : $default;
    }

    // ------------------------------------------------------------- execution

    /**
     * Spawns a process, capturing at most `limits.maxExecOutputBytes` of
     * stdout within `limits.execTimeoutSeconds`.
     *
     * @param list<string> $argv
     * @param array<string, string> $environment
     */
    private function runProcess(array $argv, array $environment, string $cwd): string
    {
        $timeout = $this->limits->execTimeoutSeconds;
        $maxBytes = $this->limits->maxExecOutputBytes;

        $descriptors = [
            0 => ['pipe', 'r'],
            1 => ['pipe', 'w'],
            2 => ['pipe', 'w'],
        ];

        $filteredEnvironment = array_filter($environment, static fn(string $value): bool => $value !== '');

        $process = @proc_open($argv, $descriptors, $pipes, $cwd, $filteredEnvironment);

        if (!\is_resource($process)) {
            $this->diagnostics->record(
                Diagnostics::SSI_EXEC_FAILED,
                'SSI #exec could not spawn the process.',
                ['argv' => $argv],
            );

            return '';
        }

        fclose($pipes[0]);
        stream_set_blocking($pipes[1], false);

        $output = '';
        $started = microtime(true);
        $timedOut = false;
        $truncated = false;

        while (true) {
            $read = [$pipes[1]];
            $write = null;
            $except = null;
            $select = @stream_select($read, $write, $except, 0, 200000);

            if ($select === false) {
                break;
            }

            if ($select > 0) {
                $chunk = fread($pipes[1], 8192);

                if ($chunk === false || ($chunk === '' && feof($pipes[1]))) {
                    break;
                }

                if ($chunk !== '') {
                    $remaining = $maxBytes - \strlen($output);

                    if ($remaining <= 0) {
                        $truncated = true;
                        break;
                    }

                    if (\strlen($chunk) > $remaining) {
                        $chunk = substr($chunk, 0, $remaining);
                        $truncated = true;
                    }

                    $output .= $chunk;

                    if ($truncated) {
                        break;
                    }
                }
            } elseif (feof($pipes[1])) {
                break;
            }

            if (microtime(true) - $started > $timeout) {
                $timedOut = true;
                break;
            }
        }

        if ($timedOut || $truncated) {
            @proc_terminate($process, \defined('SIGKILL') ? SIGKILL : 9);
        }

        foreach ($pipes as $pipe) {
            if (\is_resource($pipe)) {
                @fclose($pipe);
            }
        }

        $status = proc_close($process);

        if ($timedOut) {
            $this->diagnostics->record(
                Diagnostics::SSI_EXEC_FAILED,
                \sprintf('SSI #exec timed out after %d second(s).', $timeout),
                ['argv' => $argv],
            );
        } elseif ($truncated) {
            $this->diagnostics->record(
                Diagnostics::SSI_EXEC_FAILED,
                \sprintf('SSI #exec output truncated at %d byte(s).', $maxBytes),
                ['argv' => $argv],
            );
        } elseif ($status !== 0) {
            $this->diagnostics->record(
                Diagnostics::SSI_EXEC_FAILED,
                \sprintf('SSI #exec exited with status %d.', $status),
                ['argv' => $argv],
            );
        }

        return $this->sanitize($output);
    }

    /** In-process CGI mode: include the script inside an output buffer. */
    private function runInclude(string $script, SsiContext $context): string
    {
        $maxBytes = $this->limits->maxExecOutputBytes;

        $runner = static function () use ($script): void {
            include $script;
        };

        ob_start();

        try {
            $runner();
        } catch (\Throwable $error) {
            ob_end_clean();
            $this->diagnostics->record(
                Diagnostics::SSI_EXEC_FAILED,
                'SSI #exec cgi include threw: ' . $error->getMessage(),
                ['script' => $script],
            );

            return $context->errorText();
        }

        $output = (string) ob_get_clean();

        if (\strlen($output) > $maxBytes) {
            $output = substr($output, 0, $maxBytes);
            $this->diagnostics->record(
                Diagnostics::SSI_EXEC_FAILED,
                \sprintf('SSI #exec output truncated at %d byte(s).', $maxBytes),
                ['script' => $script],
            );
        }

        return $this->sanitize($output);
    }

    /** Strips NUL and control bytes from captured output when configured. */
    private function sanitize(string $output): string
    {
        if (!$this->security->sanitizeExecOutput || $output === '') {
            return $output;
        }

        $cleaned = preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F]/', '', $output);

        return $cleaned ?? $output;
    }
}

/**
 * mod_include `#if` expression evaluator.
 *
 * Grammar (Apache-compatible): OR/AND/NOT, comparisons (`=`, `==`, `!=`,
 * `<`, `<=`, `>`, `>=`), `/regex/` operands, file tests (`-f -d -e -s -x
 * -r -w -F`; `-A`/`-U` are accepted but always false — a template engine
 * performs no subrequests), `$VAR`/`${VAR}` expansion, quoted strings and
 * grouping. Everything is a string (mod_include semantics); numeric-looking
 * operands compare numerically for the ordering operators.
 *
 * Evaluation never throws: syntax errors become diagnostics + `false`.
 */
final class Expression
{
    /** @var list<array{0: string, 1: string}> token stream [type, value] */
    private array $tokens = [];
    private int $position = 0;
    private SsiContext $context;

    private function __construct(SsiContext $context)
    {
        $this->context = $context;
    }

    /**
     * Evaluates an expression string; errors yield false.
     */
    public static function evaluate(string $expression, SsiContext $context): bool
    {
        $expression = trim($expression);

        if ($expression === '') {
            return false;
        }

        if (\strlen($expression) > $context->limits()->maxExpressionLength) {
            $context->diagnostics()->record(
                Diagnostics::SSI_EXPR_ERROR,
                'SSI expression is too long.',
                ['length' => \strlen($expression)],
            );

            return false;
        }

        $parser = new self($context);

        try {
            $parser->tokens = $parser->tokenize($expression);
            $result = $parser->parseOr();

            if ($parser->position < \count($parser->tokens)) {
                $context->diagnostics()->record(
                    Diagnostics::SSI_EXPR_ERROR,
                    'Trailing input in SSI expression.',
                    ['expression' => $expression],
                );

                return false;
            }

            return self::truthy($result);
        } catch (ExpressionSyntaxError $error) {
            $context->diagnostics()->record(
                Diagnostics::SSI_EXPR_ERROR,
                'Invalid SSI expression: ' . $error->getMessage(),
                ['expression' => $expression],
            );

            return false;
        }
    }

    /**
     * mod_include truthiness: '' and '0' are false, '1' from comparisons.
     */
    public static function truthy(string $value): bool
    {
        return $value !== '' && $value !== '0';
    }

    // ---------------------------------------------------------------- lexer

    /**
     * @return list<array{0: string, 1: string}>
     */
    private function tokenize(string $source): array
    {
        $tokens = [];
        $length = \strlen($source);
        $index = 0;

        while ($index < $length) {
            $char = $source[$index];

            if ($char === ' ' || $char === "\t" || $char === "\n" || $char === "\r") {
                ++$index;
                continue;
            }

            if ($char === '"' || $char === "'") {
                [$value, $index] = $this->readQuoted($source, $index);
                $tokens[] = ['string', $value];
                continue;
            }

            if ($char === '$') {
                [$value, $index] = $this->readVariable($source, $index);
                $tokens[] = ['var', $value];
                continue;
            }

            if ($char === '/' && $this->regexAllowed($tokens)) {
                [$value, $index] = $this->readRegex($source, $index);
                $tokens[] = ['regex', $value];
                continue;
            }

            if ($char === '!' && ($source[$index + 1] ?? '') === '=') {
                $tokens[] = ['!=', '!='];
                $index += 2;
                continue;
            }

            if ($char === '(' || $char === ')' || $char === '!') {
                $tokens[] = [$char, $char];
                ++$index;
                continue;
            }

            if ($char === '&' || $char === '|') {
                $pair = substr($source, $index, 2);

                if ($pair === '&&' || $pair === '||') {
                    $tokens[] = [$pair, $pair];
                    $index += 2;
                    continue;
                }

                if ($char === '|' && ($source[$index + 1] ?? '') !== '|') {
                    // Single | is not supported; treat as or with a warning-free fallback.
                    $tokens[] = ['||', '||'];
                    ++$index;
                    continue;
                }

                throw new ExpressionSyntaxError('unexpected "' . $char . '"');
            }

            if ($char === '<' || $char === '>' || $char === '=') {
                $next = $source[$index + 1] ?? '';
                $operator = $char;

                if ($next === '=' || ($char === '=' && $next === '=')) {
                    $operator = $char . '=';
                    $index += 2;
                } else {
                    ++$index;
                }

                $tokens[] = [$operator, $operator];
                continue;
            }

            if ($char === '-' && $this->fileTestAt($source, $index)) {
                $tokens[] = ['filetest', substr($source, $index, 2)];
                $index += 2;
                continue;
            }

            if (preg_match('~[A-Za-z0-9_.,:;@+/\\\\*-]+~', $source, $matches, 0, $index) === 1) {
                $tokens[] = ['word', $matches[0]];
                $index += \strlen($matches[0]);
                continue;
            }

            throw new ExpressionSyntaxError('unexpected character "' . $char . '"');
        }

        return $tokens;
    }

    /**
     * @return array{0: string, 1: int}
     */
    private function readQuoted(string $source, int $index): array
    {
        $quote = $source[$index];
        $length = \strlen($source);
        $value = '';
        ++$index;

        while ($index < $length) {
            $char = $source[$index];

            if ($char === '\\' && $index + 1 < $length) {
                $next = $source[$index + 1];
                $value .= match ($next) {
                    'n' => "\n",
                    't' => "\t",
                    'r' => "\r",
                    default => $next,
                };
                $index += 2;
                continue;
            }

            if ($char === $quote) {
                return [$value, $index + 1];
            }

            $value .= $char;
            ++$index;
        }

        throw new ExpressionSyntaxError('unterminated string literal');
    }

    /**
     * @return array{0: string, 1: int}
     */
    private function readVariable(string $source, int $index): array
    {
        if (($source[$index + 1] ?? '') === '{') {
            if (preg_match('~\$\{([A-Za-z_][A-Za-z0-9_.-]*)\}~A', $source, $matches, 0, $index) === 1) {
                return [$matches[1], $index + \strlen($matches[0])];
            }

            throw new ExpressionSyntaxError('malformed ${NAME} reference');
        }

        if (preg_match('~\$([A-Za-z_][A-Za-z0-9_.-]*)~A', $source, $matches, 0, $index) === 1) {
            return [$matches[1], $index + \strlen($matches[0])];
        }

        throw new ExpressionSyntaxError('malformed $NAME reference');
    }

    /**
     * @return array{0: string, 1: int}
     */
    private function readRegex(string $source, int $index): array
    {
        $length = \strlen($source);
        $value = '';
        ++$index;

        while ($index < $length) {
            $char = $source[$index];

            if ($char === '\\' && $index + 1 < $length) {
                $value .= $char . $source[$index + 1];
                $index += 2;
                continue;
            }

            if ($char === '/') {
                return [$value, $index + 1];
            }

            $value .= $char;
            ++$index;
        }

        throw new ExpressionSyntaxError('unterminated regular expression');
    }

    /**
     * A slash opens a regex only after an operator, '(' or ',' — never
     * after a value (there "a / b" would be a division we do not have).
     *
     * @param list<array{0: string, 1: string}> $tokens
     */
    private function regexAllowed(array $tokens): bool
    {
        if ($tokens === []) {
            return true;
        }

        $previous = $tokens[\count($tokens) - 1][0];

        // After a file-test operator ("/" starts a PATH word, not a regex).
        return \in_array($previous, ['=', '==', '!=', '(', '!', '&&', '||'], true);
    }

    private function fileTestAt(string $source, int $index): bool
    {
        $pair = substr($source, $index, 2);

        return \in_array($pair, ['-f', '-d', '-e', '-s', '-x', '-r', '-w', '-A', '-F', '-U'], true)
            && !preg_match('~[A-Za-z0-9_]~', $source[$index + 2] ?? ' ');
    }

    // ---------------------------------------------------------------- parser

    /** @return array{0: string, 1: string}|null */
    private function peek(): ?array
    {
        return $this->tokens[$this->position] ?? null;
    }

    /** @return array{0: string, 1: string} */
    private function consume(): array
    {
        $token = $this->peek();

        if ($token === null) {
            throw new ExpressionSyntaxError('unexpected end of expression');
        }

        ++$this->position;

        return $token;
    }

    private function parseOr(): string
    {
        $left = $this->parseAnd();

        while (($token = $this->peek()) !== null && $token[0] === '||') {
            ++$this->position;
            $right = $this->parseAnd();
            $left = (self::truthy($left) || self::truthy($right)) ? '1' : '';
        }

        return $left;
    }

    private function parseAnd(): string
    {
        $left = $this->parseNot();

        while (($token = $this->peek()) !== null && $token[0] === '&&') {
            ++$this->position;
            $right = $this->parseNot();
            $left = (self::truthy($left) && self::truthy($right)) ? '1' : '';
        }

        return $left;
    }

    private function parseNot(): string
    {
        if (($token = $this->peek()) !== null && $token[0] === '!') {
            ++$this->position;

            return self::truthy($this->parseNot()) ? '' : '1';
        }

        return $this->parseComparison();
    }

    private function parseComparison(): string
    {
        [$leftValue, $leftRegex] = $this->parseOperand();
        $token = $this->peek();

        if ($token === null || !\in_array($token[0], ['=', '==', '!=', '<', '<=', '>', '>='], true)) {
            if ($leftRegex) {
                throw new ExpressionSyntaxError('a /regex/ needs a comparison operator');
            }

            return $leftValue;
        }

        ++$this->position;
        [$rightValue, $rightRegex] = $this->parseOperand();
        $operator = $token[0] === '==' ? '=' : $token[0];

        return $this->compare($operator, $leftValue, $leftRegex, $rightValue, $rightRegex) ? '1' : '';
    }

    /**
     * @return array{0: string, 1: bool} value + "is regex" flag
     */
    private function parseOperand(): array
    {
        $token = $this->peek();

        if ($token !== null && $token[0] === 'filetest') {
            ++$this->position;
            [$value] = $this->parseOperand();

            return [$this->fileTest($token[1], $value) ? '1' : '', false];
        }

        $token = $this->consume();

        return match ($token[0]) {
            '(' => [$this->parseGrouped(), false],
            'string', 'word' => [$token[1], false],
            'regex' => [$token[1], true],
            'var' => [$this->resolveVariable($token[1]), false],
            default => throw new ExpressionSyntaxError('unexpected token "' . $token[1] . '"'),
        };
    }

    private function parseGrouped(): string
    {
        $value = $this->parseOr();
        $token = $this->peek();

        if ($token === null || $token[0] !== ')') {
            throw new ExpressionSyntaxError('missing closing parenthesis');
        }

        ++$this->position;

        return $value;
    }

    private function compare(string $operator, string $left, bool $leftRegex, string $right, bool $rightRegex): bool
    {
        if ($operator === '=' || $operator === '!=') {
            if ($rightRegex) {
                $matched = $this->regexMatch($right, $left);

                return $operator === '=' ? $matched : !$matched;
            }

            if ($leftRegex) {
                $matched = $this->regexMatch($left, $right);

                return $operator === '=' ? $matched : !$matched;
            }

            $equal = $left === $right;

            return $operator === '=' ? $equal : !$equal;
        }

        if ($leftRegex || $rightRegex) {
            throw new ExpressionSyntaxError('ordering comparisons do not accept /regex/ operands');
        }

        if (Str::isNumericString($left) && Str::isNumericString($right)) {
            $a = Str::numericValue($left);
            $b = Str::numericValue($right);

            return match ($operator) {
                '<' => $a < $b,
                '<=' => $a <= $b,
                '>' => $a > $b,
                '>=' => $a >= $b,
                default => false,
            };
        }

        $order = strcmp($left, $right);

        return match ($operator) {
            '<' => $order < 0,
            '<=' => $order <= 0,
            '>' => $order > 0,
            '>=' => $order >= 0,
            default => false,
        };
    }

    private function regexMatch(string $pattern, string $subject): bool
    {
        $delimited = '~' . str_replace('~', '\\~', $pattern) . '~';
        $result = @preg_match($delimited, $subject);

        if ($result === false) {
            $this->context->diagnostics()->record(
                Diagnostics::SSI_EXPR_ERROR,
                'Invalid regular expression in SSI condition.',
                ['pattern' => $pattern],
            );

            return false;
        }

        return $result === 1;
    }

    private function fileTest(string $operator, string $path): bool
    {
        if ($path === '' || str_contains($path, "\0")) {
            return false;
        }

        if ($operator === '-A' || $operator === '-U') {
            // Apache answers these with internal subrequests; a template
            // engine must not perform network I/O, so they evaluate to
            // false here (recorded for visibility).
            $this->context->diagnostics()->record(
                Diagnostics::SSI_EXPR_ERROR,
                'SSI file test ' . $operator . ' (subrequest) is not supported and evaluates to false.',
                ['path' => $path],
            );

            return false;
        }

        // Path containment mirrors #include semantics.
        $resolved = $this->context->resolvePath($path);

        if ($operator === '-d') {
            $absolute = str_starts_with($path, '/') || str_starts_with($path, '\\')
                ? rtrim($this->context->documentRoot(), "/\\") . '/' . ltrim(str_replace('\\', '/', $path), '/')
                : null;

            if ($absolute !== null) {
                $real = realpath($absolute);

                if ($real !== false && is_dir($real)) {
                    if ($this->context->config()->allowParentPaths
                        || Files::isInside($real, $this->context->documentRoot())
                    ) {
                        return true;
                    }
                }
            }

            return false;
        }

        if ($resolved === null) {
            return false;
        }

        return match ($operator) {
            '-f', '-F' => is_file($resolved),
            '-e' => true,
            '-s' => (@filesize($resolved) ?: 0) > 0,
            '-x' => is_executable($resolved),
            '-r' => is_readable($resolved),
            '-w' => is_writable($resolved),
            default => false,
        };
    }

    /**
     * Variable lookup shared with #echo and #set expansion: built-ins win,
     * then #set variables, then the injected scope. Reserved names and the
     * echo allow-list are enforced inside the context.
     */
    private function resolveVariable(string $name): string
    {
        return $this->context->variable($name);
    }
}

/**
 * Internal signal for an unparseable `#if` expression.
 *
 * Never escapes the engine: {@see Expression::evaluate()} catches it,
 * records a diagnostic and yields `false` (mod_include parity).
 */
final class ExpressionSyntaxError extends \Exception {}

/**
 * Apache mod_include compatible SSI processor.
 *
 * Instance-based in v4 (v3 used statics + `$GLOBALS`): one Processor per
 * engine, all state per render inside {@see SsiContext}.
 *
 * ```php
 * $html = $engine->ssi()->process($content, new DocumentInfo(file: __FILE__));
 * ```
 *
 * Supported directives: `#config`, `#set`, `#include` (file/virtual,
 * `stub=`, `wait=` accepted), `#echo` (encoding none/url/base64/entity),
 * `#if`/`#elif`/`#else`/`#endif`, `#exec` (policy-gated), `#fsize`,
 * `#flastmod`, `#printenv`, `#block`/`#endblock` and host-registered
 * custom directives. The legacy v2 `##name` and `@var` comment forms were
 * removed in v4.
 */
final class Processor
{
    private readonly Exec $exec;
    private readonly DirectiveRegistry $registry;
    private int $lastProcessed = 0;

    public function __construct(
        private readonly Config $config,
        private readonly Diagnostics $diagnostics,
        private readonly Dispatcher $events,
        private readonly Escaper $escaper,
        private readonly ClockInterface $clock,
    ) {
        $this->exec = new Exec($config->ssi, $config->limits, $config->security, $diagnostics);
        $this->registry = new DirectiveRegistry();
    }

    /** Custom/overriding directives (checked before built-ins). */
    public function directives(): DirectiveRegistry
    {
        return $this->registry;
    }

    /**
     * Processes every SSI directive in `$html`.
     *
     * @param DocumentInfo|null $document anchors relative includes,
     *        LAST_MODIFIED and the containment root; `null` behaves like a
     *        string render rooted at the configured document root
     */
    public function process(string $html, ?DocumentInfo $document = null): string
    {
        if (!$this->config->ssi->enabled || $html === '' || !str_contains($html, '<!--')) {
            return $html;
        }

        $document ??= DocumentInfo::forString($this->config->ssi->documentRoot);

        $context = new SsiContext(
            $document,
            $this->config->ssi,
            $this->config->security,
            $this->config->limits,
            $this->diagnostics,
            $this->events,
            $this->clock,
        );

        $output = (new Scanner($context, $this->escaper, $this->exec, $this->registry))->run($html);
        $this->lastProcessed = $context->processed;

        return $output;
    }

    /** Directives processed by the most recent {@see self::process()} call. */
    public function lastProcessed(): int
    {
        return $this->lastProcessed;
    }

    /**
     * Processes with an existing context (nested renders that must share
     * budgets — used by the Engine when SSI runs inside a render pass).
     */
    public function processWithContext(string $html, SsiContext $context): string
    {
        return (new Scanner($context, $this->escaper, $this->exec, $this->registry))->run($html);
    }

    /**
     * The built-in variable map for a document (diagnostics, WP-CLI info,
     * `html_ssi_variables()` successor).
     *
     * @return array<string, string>
     */
    public function variables(?DocumentInfo $document = null): array
    {
        $document ??= DocumentInfo::forString($this->config->ssi->documentRoot);

        $context = new SsiContext(
            $document,
            $this->config->ssi,
            $this->config->security,
            $this->config->limits,
            $this->diagnostics,
            $this->events,
            $this->clock,
        );

        return $context->builtins();
    }
}

/**
 * Single-document SSI scanner.
 *
 * One Scanner runs one document (the root template or one `#include`d
 * file); recursion creates a new Scanner over a child context so budgets
 * and cycle guards stay shared while conditional frames stay per-document
 * — exactly like mod_include.
 *
 * @internal instantiated by {@see Processor} only
 */
final class Scanner
{
    /** Scanner pattern: every modern SSI comment in one match. */
    private const string DIRECTIVE_PATTERN = '~<!--(?<body>\#[a-zA-Z]+)(?<rest>.*?)-->~is';

    /** Block extractor: `<!--#block name="x"-->…<!--#endblock-->`. */
    private const string BLOCK_PATTERN =
        '~<!--\#block\s+name\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s>]+))\s*-->(.*?)<!--\#endblock\s*-->~is';

    /** Maximum #if nesting depth (independent of include depth). */
    private const int MAX_CONDITIONAL_DEPTH = 64;

    /** @var list<array{active: bool, taken: bool}> */
    private array $frames = [];

    /** @var array<string, string> pre-scanned `#block` sections by name */
    private array $blocks = [];

    public function __construct(
        private readonly SsiContext $context,
        private readonly Escaper $escaper,
        private readonly Exec $exec,
        private readonly DirectiveRegistry $registry,
    ) {}

    public function run(string $html): string
    {
        $html = $this->extractBlocks($html);

        return $this->scan($html);
    }

    /**
     * Removes `#block … #endblock` sections from the flow and remembers
     * them for `#include … stub="name"` fallbacks (nginx/Apache parity:
     * block content never appears twice).
     */
    private function extractBlocks(string $html): string
    {
        if (!str_contains($html, '#block')) {
            return $html;
        }

        $result = Pcre::replaceCallback(
            self::BLOCK_PATTERN,
            function (array $m): string {
                $name = (string) ($m[1] !== '' ? $m[1] : ($m[2] !== '' ? $m[2] : ($m[3] ?? '')));

                if ($name !== '') {
                    $this->blocks[$name] = (string) ($m[4] ?? '');
                }

                return '';
            },
            $html,
        );

        return $result;
    }

    private function scan(string $html): string
    {
        if ($html === '' || !str_contains($html, '<!--')) {
            return $html;
        }

        $parts = preg_split(self::DIRECTIVE_PATTERN, $html, -1, PREG_SPLIT_DELIM_CAPTURE);

        if ($parts === false || \count($parts) === 1) {
            return $html;
        }

        // preg_split with two capture groups yields: text, body, rest, text, …
        // Text outside the currently active conditional branch is dropped.
        $output = $this->active() ? $parts[0] : '';
        $count = \count($parts);

        for ($index = 1; $index + 2 < $count; $index += 3) {
            $body = (string) $parts[$index];
            $rest = (string) $parts[$index + 1];
            $output .= $this->dispatch($body, $rest);
            $output .= $this->active() ? (string) $parts[$index + 2] : '';
        }

        return $output;
    }

    /** Routes one directive; maintains the conditional frame stack. */
    private function dispatch(string $body, string $rest): string
    {
        $original = '<!--' . $body . $rest . '-->';
        $name = strtolower(substr($body, 1));

        // Conditional directives are always tracked (nesting), but their
        // expressions are only evaluated while the enclosing branch runs.
        if ($name === 'if' || $name === 'elif' || $name === 'elseif' || $name === 'else' || $name === 'endif') {
            $this->conditional($name, $rest);

            return '';
        }

        if (!$this->active()) {
            return '';
        }

        $attributes = Attributes::parse($rest);

        // Host-registered directives win over built-ins.
        $custom = $this->registry->get($name);

        if ($custom !== null) {
            ++$this->context->processed;

            return Str::stringify($custom->render($attributes, $this->context));
        }

        return match ($name) {
            'config' => $this->configDirective($attributes),
            'set' => $this->setDirective($attributes),
            'include' => $this->includeDirective($attributes),
            'echo' => $this->echoDirective($attributes),
            'exec' => $this->execDirective($attributes),
            'flastmod' => $this->lastmodDirective($attributes),
            'fsize' => $this->sizeDirective($attributes),
            'printenv' => $this->printenvDirective(),
            'block', 'endblock' => '', // consumed by the pre-pass
            // Unknown directives stay in the output verbatim (mod_include
            // compatibility: they are ordinary HTML comments to us).
            default => $this->unknownDirective($name, $original),
        };
    }

    private function unknownDirective(string $name, string $original): string
    {
        $this->context->diagnostics()->record(
            Diagnostics::SSI_UNKNOWN_DIRECTIVE,
            'Unknown SSI directive left in output.',
            ['directive' => $name],
        );

        return $original;
    }

    /** Current branch activity (top of the conditional frame stack). */
    private function active(): bool
    {
        return $this->frames === [] || $this->frames[array_key_last($this->frames)]['active'];
    }

    private function parentActive(): bool
    {
        $depth = \count($this->frames);

        return $depth === 0 || $this->frames[$depth - 1]['active'];
    }

    /** Activity of the frames below the top one (used by #elif/#else). */
    private function parentActiveExcludingTop(): bool
    {
        $depth = \count($this->frames);

        return $depth <= 1 || $this->frames[$depth - 2]['active'];
    }

    /** Handles #if / #elif / #else / #endif frame transitions. */
    private function conditional(string $name, string $rest): void
    {
        $diagnostics = $this->context->diagnostics();

        if ($name === 'endif') {
            if ($this->frames === []) {
                $diagnostics->record(Diagnostics::SSI_EXPR_ERROR, 'SSI #endif without a matching #if.');

                return;
            }

            array_pop($this->frames);

            return;
        }

        if ($name === 'if') {
            if (\count($this->frames) >= self::MAX_CONDITIONAL_DEPTH) {
                $diagnostics->record(Diagnostics::SSI_EXPR_ERROR, 'SSI conditional nesting is too deep.');
                $this->frames[] = ['active' => false, 'taken' => true];

                return;
            }

            $result = $this->parentActive() && $this->evaluate($rest);
            $this->frames[] = ['active' => $result, 'taken' => $result];

            return;
        }

        // #elif / #else without an open #if are ignored (mod_include parity).
        if ($this->frames === []) {
            $diagnostics->record(Diagnostics::SSI_EXPR_ERROR, 'SSI #' . $name . ' without a matching #if.');

            return;
        }

        $top = &$this->frames[\count($this->frames) - 1];

        if ($name === 'else') {
            $top['active'] = $this->parentActiveExcludingTop() && !$top['taken'];
            $top['taken'] = true;

            return;
        }

        // #elif / #elseif
        if ($top['taken'] || !$this->parentActiveExcludingTop()) {
            $top['active'] = false;

            return;
        }

        $result = $this->evaluate($rest);
        $top['active'] = $result;
        $top['taken'] = $result;

        unset($top);
    }

    /** Extracts and evaluates the `expr="…"` payload of #if/#elif. */
    private function evaluate(string $rest): bool
    {
        $attributes = Attributes::parse($rest);

        // mod_include also accepts expr=v (unquoted); Attributes keeps it.
        return Expression::evaluate($attributes['expr'] ?? '', $this->context);
    }

    // ------------------------------------------------------------- directives

    /** @param array<string, string> $attributes */
    private function configDirective(array $attributes): string
    {
        if (isset($attributes['timefmt']) && $attributes['timefmt'] !== '') {
            $this->context->timefmt = $attributes['timefmt'];
            $this->context->resetBuiltins();
        }

        if (isset($attributes['sizefmt']) && $attributes['sizefmt'] !== '') {
            $this->context->sizefmt = strtolower($attributes['sizefmt']);
        }

        if (\array_key_exists('errmsg', $attributes)) {
            $this->context->errmsg = $attributes['errmsg'];
        }

        return '';
    }

    /** @param array<string, string> $attributes */
    private function setDirective(array $attributes): string
    {
        $name = trim($attributes['var'] ?? '');
        $value = $attributes['value'] ?? '';

        if ($this->context->isWritableName($name)) {
            $this->context->vars[$name] = $this->expandVariables($value);
        } else {
            $this->context->diagnostics()->record(
                Diagnostics::SSI_EXEC_DENIED,
                'SSI #set target name is reserved or invalid.',
                ['name' => $name],
            );
        }

        return '';
    }

    /** @param array<string, string> $attributes */
    private function includeDirective(array $attributes): string
    {
        $virtual = $attributes['virtual'] ?? '';
        $file = $attributes['file'] ?? '';
        $stub = $attributes['stub'] ?? '';
        // `wait="yes"` is accepted and ignored: the engine is sequential.

        if ($virtual === '' && $file === '') {
            return '';
        }

        $label = $virtual !== '' ? $virtual : $file;
        $fallback = fn(): string => $this->includeFallback($stub, $label);

        if (!$this->context->budgetAllows()) {
            return $fallback();
        }

        // file= is strictly relative to the directory of the current document.
        $path = $file !== ''
            ? $this->resolveFileAttribute($file)
            : $this->context->resolvePath($virtual);

        if ($path === null) {
            $this->context->diagnostics()->record(
                Diagnostics::SSI_INCLUDE_FAILED,
                'SSI include could not be resolved or is outside the document root.',
                ['target' => $label],
            );

            return $fallback();
        }

        $filtered = $this->context->events()->filter('htmlphp.ssi.include_path', $path, $label);
        $path = Str::stringify($filtered);

        if ($path === '' || isset($this->context->stack[$path])) {
            $this->context->diagnostics()->record(
                Diagnostics::SSI_INCLUDE_CYCLE,
                'SSI include cycle detected.',
                ['target' => $label, 'path' => $path],
            );

            return $fallback();
        }

        $contents = Files::slurp($path, $this->context->limits()->maxIncludeBytes);

        if ($contents === null) {
            $this->context->diagnostics()->record(
                Diagnostics::SSI_INCLUDE_FAILED,
                'SSI include could not be read.',
                ['path' => $path],
            );

            return $fallback();
        }

        ++$this->context->processed;

        $child = $this->context->child($path);
        $this->context->stack[$path] = true;

        try {
            $scanner = new self($child, $this->escaper, $this->exec, $this->registry);

            return $scanner->run($contents);
        } finally {
            unset($this->context->stack[$path]);
        }
    }

    /** Stub block when set, otherwise the configured `errmsg`. */
    private function includeFallback(string $stub, string $label): string
    {
        $stub = trim($stub);

        if ($stub !== '' && isset($this->blocks[$stub])) {
            return $this->blocks[$stub];
        }

        if ($stub !== '') {
            $this->context->diagnostics()->record(
                Diagnostics::SSI_INCLUDE_FAILED,
                'SSI include stub block was not found in this document.',
                ['target' => $label, 'stub' => $stub],
            );
        }

        return $this->context->errorText();
    }

    /**
     * Apache `file=` semantics: relative to the containing document only,
     * still under document-root containment.
     */
    private function resolveFileAttribute(string $file): ?string
    {
        if ($file === '' || str_contains($file, "\0")) {
            return null;
        }

        if (preg_match('~^[a-zA-Z][a-zA-Z0-9+.-]*://~', $file) === 1
            || str_starts_with($file, '/') || str_starts_with($file, '\\')
        ) {
            return null;
        }

        if (!$this->context->config()->allowParentPaths
            && preg_match('~(?:^|/)\.\.(?:/|$)~', $file) === 1
        ) {
            return null;
        }

        $relativeDir = $this->context->relativeDir();

        if ($relativeDir === null || $relativeDir === '') {
            return null;
        }

        $candidate = rtrim($relativeDir, "/\\") . DIRECTORY_SEPARATOR
            . str_replace('/', DIRECTORY_SEPARATOR, ltrim($file, './'));

        return $this->context->resolveCandidate($candidate);
    }

    /** @param array<string, string> $attributes */
    private function echoDirective(array $attributes): string
    {
        $name = trim($attributes['var'] ?? '');
        $value = $this->context->variable($name);
        $encoding = strtolower($attributes['encoding'] ?? '');

        $escaped = match ($encoding) {
            'none' => $value,
            'url' => rawurlencode($value),
            'base64' => base64_encode($value),
            'entity' => $this->escaper->html($value),
            default => $this->context->config()->escapeEcho ? $this->escaper->html($value) : $value,
        };

        return Str::stringify($this->context->events()->filter('htmlphp.ssi.echo', $escaped, $name));
    }

    /** @param array<string, string> $attributes */
    private function execDirective(array $attributes): string
    {
        $cmd = $attributes['cmd'] ?? '';
        $cgi = $attributes['cgi'] ?? '';

        if ($cmd !== '') {
            return $this->exec->runCmd($cmd, $this->context);
        }

        if ($cgi !== '') {
            return $this->exec->runCgi($cgi, $this->context);
        }

        return '';
    }

    /** @param array<string, string> $attributes */
    private function lastmodDirective(array $attributes): string
    {
        $path = $this->targetPath($attributes);

        if ($path === null) {
            return $this->context->errorText();
        }

        $modified = @filemtime($path);

        if ($modified === false) {
            return $this->context->errorText();
        }

        return TimeFormat::format($modified, $this->context->timefmt);
    }

    /** @param array<string, string> $attributes */
    private function sizeDirective(array $attributes): string
    {
        $path = $this->targetPath($attributes);

        if ($path === null) {
            return $this->context->errorText();
        }

        $size = @filesize($path);

        if ($size === false) {
            return $this->context->errorText();
        }

        return SizeFormat::format($size, $this->context->sizefmt);
    }

    /**
     * `#printenv` — dumps every visible variable, one `NAME=value` per line
     * (mod_include parity). Values honour the echo escaping and allow-list.
     */
    private function printenvDirective(): string
    {
        if (!$this->context->config()->printenvEnabled) {
            return '';
        }

        $variables = $this->context->builtins();

        foreach ($this->context->vars as $name => $value) {
            $variables[$name] = $value;
        }

        foreach ($this->context->document->vars as $name => $value) {
            if (\is_string($name) && !isset($variables[$name]) && !isset(SsiContext::RESERVED[$name])) {
                $variables[$name] = Str::stringify($value);
            }
        }

        ksort($variables);

        $lines = [];

        foreach ($variables as $name => $value) {
            if (!$this->context->echoAllowed((string) $name)) {
                continue;
            }

            $value = (string) $value;
            $lines[] = $name . '=' . ($this->context->config()->escapeEcho
                ? $this->escaper->html($value)
                : $value);
        }

        return implode("\n", $lines) . ($lines === [] ? '' : "\n");
    }

    /** @param array<string, string> $attributes */
    private function targetPath(array $attributes): ?string
    {
        $virtual = $attributes['virtual'] ?? '';
        $file = $attributes['file'] ?? '';

        if ($file !== '') {
            return $this->resolveFileAttribute($file);
        }

        if ($virtual !== '') {
            return $this->context->resolvePath($virtual);
        }

        // Default (Apache): the current document.
        $current = $this->context->document->file;

        return \is_string($current) && $current !== '' && is_file($current) ? $current : null;
    }

    // ------------------------------------------------------------- variables

    /**
     * Expands `$VAR` / `${VAR}` inside a `#set` value payload.
     *
     * Unknown names are kept verbatim; a backslash escapes a literal dollar
     * sign; reserved names expand to `''`.
     */
    public function expandVariables(string $value): string
    {
        if ($value === '' || !str_contains($value, '$')) {
            return $value;
        }

        $protected = Pcre::replace('~\\\\\$~', "\x01", $value);
        $context = $this->context;

        $expanded = Pcre::replaceCallback(
            '~\$(?:\{([A-Za-z_][A-Za-z0-9_]*)\}|([A-Za-z_][A-Za-z0-9_]*))~',
            static function (array $matches) use ($context): string {
                $name = ($matches[1] ?? '') !== '' ? $matches[1] : ($matches[2] ?? '');

                if ($name === '') {
                    return '';
                }

                if (isset(SsiContext::RESERVED[$name])) {
                    return '';
                }

                return $context->resolve($name) ?? $matches[0];
            },
            $protected,
        );

        return str_replace("\x01", '$', $expanded);
    }
}

/**
 * Formats byte counts the way Apache's `#fsize` does.
 *
 * The style is passed in by the caller (from `#config sizefmt`); this class
 * reads no configuration of its own.
 */
final class SizeFormat
{
    private function __construct() {}

    public static function format(int $bytes, string $style = 'abbrev'): string
    {
        return Str::formatSize($bytes, \in_array(strtolower($style), ['bytes', 'byte'], true) ? 'bytes' : 'abbrev');
    }
}

/**
 * Per-render SSI state: budget counters, `#config`/`#set` variables, the
 * include stack (cycle guard) and path resolution.
 *
 * Every value comes from the injected configuration, document info and
 * request context — the class reads no superglobals and no globals.
 */
final class SsiContext
{
    /** Reserved names: never writable via `#set`, never echo-able. */
    public const array RESERVED = [
        'GLOBALS' => true, '_GET' => true, '_POST' => true, '_COOKIE' => true,
        '_SESSION' => true, '_FILES' => true, '_SERVER' => true, '_ENV' => true,
        '_REQUEST' => true, 'HTTP_SERVER_VARS' => true, 'this' => true,
        'HTML_Prepare_Count' => true, 'TAGS' => true, 'html' => true,
        'parity' => true, 'entities' => true,
    ];

    /** Names computed on demand from the request + clock. */
    public const array BUILTIN_NAMES = [
        'DATE_LOCAL' => true, 'DATE_GMT' => true, 'DOCUMENT_URI' => true,
        'DOCUMENT_NAME' => true, 'DOCUMENT_ROOT' => true, 'QUERY_STRING' => true,
        'SERVER_NAME' => true, 'SERVER_SOFTWARE' => true, 'SERVER_PROTOCOL' => true,
        'REQUEST_METHOD' => true, 'REQUEST_URI' => true, 'SCRIPT_NAME' => true,
        'CONTENT_TYPE' => true, 'REMOTE_ADDR' => true, 'HTTP_USER_AGENT' => true,
        'LAST_MODIFIED' => true,
    ];

    public int $depth = 0;
    public int $processed = 0;

    /** @var array<string, true> realpath stack guarding include cycles */
    public array $stack = [];

    public string $timefmt;
    public string $sizefmt;
    public ?string $errmsg;

    /** @var array<string, string> variables defined through `#set` */
    public array $vars = [];

    /** @var array<string, string>|null computed on first use, reset by `#config timefmt` */
    private ?array $builtins = null;

    private readonly RequestContext $requestContext;

    public function __construct(
        public readonly DocumentInfo $document,
        private readonly SsiConfig $config,
        private readonly SecurityConfig $security,
        private readonly Limits $limits,
        private readonly Diagnostics $diagnostics,
        private readonly Dispatcher $events,
        private readonly ClockInterface $clock,
        private readonly int $now = 0,
    ) {
        $this->timefmt = $config->timeFormat !== '' ? $config->timeFormat : TimeFormat::DEFAULT_FORMAT;
        $this->sizefmt = $config->sizeFormat->value;
        $this->errmsg = $config->errorMessage;
        $this->requestContext = $document->request ?? RequestContext::cli();
    }

    public function config(): SsiConfig
    {
        return $this->config;
    }

    public function security(): SecurityConfig
    {
        return $this->security;
    }

    public function limits(): Limits
    {
        return $this->limits;
    }

    public function diagnostics(): Diagnostics
    {
        return $this->diagnostics;
    }

    public function events(): Dispatcher
    {
        return $this->events;
    }

    /** Current timestamp, stable for the whole render. */
    public function timestamp(): int
    {
        return $this->now !== 0 ? $this->now : $this->clock->now();
    }

    public function request(): RequestContext
    {
        return $this->requestContext;
    }

    /**
     * Child context for an included file: shares budgets and `#config` state
     * (by reference, exactly like mod_include where directives affect the
     * whole request), but has its own current-file anchor.
     */
    public function child(string $file): self
    {
        $child = new self(
            new DocumentInfo($file, $this->document->root, $this->requestContext, $this->document->vars),
            $this->config,
            $this->security,
            $this->limits,
            $this->diagnostics,
            $this->events,
            $this->clock,
            $this->timestamp(),
        );

        $child->depth = $this->depth + 1;
        $child->processed = &$this->processed;
        $child->stack = &$this->stack;
        $child->timefmt = &$this->timefmt;
        $child->sizefmt = &$this->sizefmt;
        $child->errmsg = &$this->errmsg;
        $child->vars = &$this->vars;
        $child->builtins = &$this->builtins;

        return $child;
    }

    /**
     * Built-in SSI variables, computed once per render.
     *
     * @return array<string, string>
     */
    public function builtins(): array
    {
        if ($this->builtins !== null) {
            return $this->builtins;
        }

        $map = Builtins::map($this);
        $filtered = $this->events->filter('htmlphp.ssi.builtins', $map);

        return $this->builtins = \is_array($filtered) ? $filtered : $map;
    }

    public function resetBuiltins(): void
    {
        $this->builtins = null;
    }

    /**
     * Value of a variable name for `#echo`, `#if` and `$VAR` expansion.
     *
     * Order (mod_include-like): built-ins first, then `#set` variables, then
     * the injected document/scope variables. Reserved names never resolve.
     */
    public function variable(string $name): string
    {
        return $this->resolve($name) ?? '';
    }

    /**
     * Same chain as {@see self::variable()} but distinguishes "unknown"
     * (`null`) from "known and empty" — `#set` expansion keeps unknown
     * `$NAME` references verbatim, exactly like mod_include.
     */
    public function resolve(string $name): ?string
    {
        $name = trim($name);

        if ($name === '' || str_contains($name, "\0") || isset(self::RESERVED[$name])) {
            return null;
        }

        if (isset(self::BUILTIN_NAMES[$name])) {
            if (!$this->echoAllowed($name)) {
                return '';
            }

            return $this->builtins()[$name] ?? '';
        }

        if (\array_key_exists($name, $this->vars)) {
            return $this->vars[$name];
        }

        if (str_starts_with($name, 'HTTP_')) {
            $value = $this->request()->http($name);

            return $value === null ? null : $value;
        }

        if (\array_key_exists($name, $this->document->vars)) {
            return Str::stringify($this->document->vars[$name]);
        }

        return null;
    }

    /** True when the name passes the `ssi.echo_allow` gate (empty = allow all). */
    public function echoAllowed(string $name): bool
    {
        $allow = $this->config->echoAllow;

        return $allow === [] || isset($allow[$name]) || \in_array($name, $allow, true);
    }

    /** True when `#set` may define this name. */
    public function isWritableName(string $name): bool
    {
        return Str::isValidVariableName($name)
            && !isset(self::RESERVED[$name])
            && !isset(self::BUILTIN_NAMES[$name]);
    }

    /** The document root includes resolve against. */
    public function documentRoot(): string
    {
        $root = $this->document->root;

        if ($root === null || $root === '') {
            $root = $this->config->documentRoot ?? '';
        }

        if ($root === '') {
            $root = $this->request()->documentRoot;
        }

        if ($root === '') {
            $root = getcwd() ?: '.';
        }

        $resolved = realpath($root);

        if ($resolved !== false && is_dir($resolved)) {
            return $resolved;
        }

        $trimmed = rtrim($root, "/\\");

        return $trimmed !== '' ? $trimmed : DIRECTORY_SEPARATOR;
    }

    /** Directory that relative (`file=`) includes resolve against. */
    public function relativeDir(): ?string
    {
        $current = $this->document->file;

        if ($current === null || $current === '') {
            return null;
        }

        if (is_dir($current)) {
            return $current;
        }

        $directory = \dirname($current);

        return $directory === '' || $directory === '.' ? null : $directory;
    }

    /** Error replacement text for failed directives (`#config errmsg`). */
    public function errorText(): string
    {
        return $this->errmsg ?? '';
    }

    /** True while another include/directive budget remains. */
    public function budgetAllows(): bool
    {
        if ($this->depth >= $this->limits->maxSsiDepth) {
            $this->diagnostics->record(
                Diagnostics::SSI_LIMIT_REACHED,
                'SSI include depth limit reached.',
                ['depth' => $this->depth],
            );

            return false;
        }

        if ($this->processed >= $this->limits->maxSsiTags) {
            $this->diagnostics->record(
                Diagnostics::SSI_LIMIT_REACHED,
                'SSI directive budget exhausted.',
                ['processed' => $this->processed],
            );

            return false;
        }

        return true;
    }

    /** One candidate include path: containment-, extension- and size-checked. */
    public function resolveCandidate(string $candidate): ?string
    {
        $resolved = realpath($candidate);

        if ($resolved === false || !is_file($resolved) || !is_readable($resolved)) {
            return null;
        }

        if (!$this->config->allowParentPaths) {
            $root = realpath($this->documentRoot());

            if ($root === false || !is_dir($root) || !Files::isInside($resolved, $root)) {
                return null;
            }
        }

        if (!$this->extensionAllowed($resolved)) {
            return null;
        }

        $size = @filesize($resolved);

        if ($size === false || $size > $this->limits->maxIncludeBytes) {
            return null;
        }

        return $resolved;
    }

    /**
     * Resolves an SSI path (from `#include`/`#fsize`/`#flastmod`/file tests).
     *
     * Absolute paths (`/ssi/x.htm`) resolve from the document root, relative
     * ones (`ssi/x.htm`, `./ssi/x.htm`) from the directory of the file
     * containing the directive first, then the document root.
     */
    public function resolvePath(string $virtual): ?string
    {
        if ($virtual === '' || str_contains($virtual, "\0")) {
            return null;
        }

        $absolute = str_starts_with($virtual, '/') || str_starts_with($virtual, '\\');

        $virtual = str_replace('\\', '/', $virtual);
        $virtual = ltrim($virtual, '/');
        $virtual = (string) preg_replace('~/+~', '/', $virtual);

        // Reject URLs and (unless explicitly allowed) parent traversal.
        if ($virtual === '' || preg_match('~^[a-zA-Z][a-zA-Z0-9+.-]*://~', $virtual) === 1) {
            return null;
        }

        if (!$this->config->allowParentPaths && preg_match('~(?:^|/)\.\.(?:/|$)~', $virtual) === 1) {
            return null;
        }

        $relative = str_replace('/', DIRECTORY_SEPARATOR, $virtual);
        $candidates = [];

        if (!$absolute) {
            $relativeDir = $this->relativeDir();

            if ($relativeDir !== null && $relativeDir !== '') {
                $candidates[] = rtrim($relativeDir, "/\\") . DIRECTORY_SEPARATOR . $relative;
            }
        }

        $candidates[] = $this->documentRoot() . DIRECTORY_SEPARATOR . $relative;

        foreach ($candidates as $candidate) {
            $resolved = $this->resolveCandidate($candidate);

            if ($resolved !== null) {
                return $resolved;
            }
        }

        return null;
    }

    /**
     * Resolves a `#exec cgi=` target: document-root containment like
     * {@see self::resolvePath()}, but the extension gate is *inverted* —
     * only the configured `exec_cgi_extensions` may execute. This keeps
     * `#include` from ever serving script sources while `#exec cgi` can
     * still run them under an explicit allow-list policy.
     */
    public function resolveExecutable(string $virtual): ?string
    {
        if ($virtual === '' || str_contains($virtual, "\0")) {
            return null;
        }

        $normalized = str_replace('\\', '/', $virtual);
        $normalized = ltrim($normalized, '/');
        $normalized = (string) preg_replace('~/+~', '/', $normalized);

        if ($normalized === ''
            || preg_match('~^[a-zA-Z][a-zA-Z0-9+.-]*://~', $normalized) === 1
            || (!$this->config->allowParentPaths && preg_match('~(?:^|/)\.\.(?:/|$)~', $normalized) === 1)
        ) {
            return null;
        }

        $candidate = $this->documentRoot() . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $normalized);
        $resolved = realpath($candidate);

        if ($resolved === false || !is_file($resolved) || !is_readable($resolved)) {
            return null;
        }

        if (!$this->config->allowParentPaths && !Files::isInside($resolved, $this->documentRoot())) {
            return null;
        }

        $size = @filesize($resolved);

        if ($size === false || $size > $this->limits->maxIncludeBytes) {
            return null;
        }

        return $resolved;
    }

    /** Deny-list check shared with {@see \HtmlPhp\Io\PathGuard}. */
    private function extensionAllowed(string $path): bool
    {
        $base = basename(str_replace('\\', '/', $path));

        if (str_starts_with($base, '.') && $base !== '.' && $base !== '..') {
            return false;
        }

        $extension = Files::extension($base);

        if ($extension === '') {
            return true;
        }

        return !\in_array($extension, $this->security->deniedExtensions, true);
    }
}

/**
 * strftime()-style formatting without the deprecated strftime().
 *
 * Apache's `#config timefmt` speaks strftime tokens; this converts them to
 * date() tokens (escaping literals) so no deprecation is emitted on 8.3+.
 */
final class TimeFormat
{
    public const string DEFAULT_FORMAT = '%A, %d-%b-%Y %H:%M:%S %Z';

    /** Sentinel for %j (one-based day of year); date() only has zero-based 'z'. */
    private const string DOY_MARKER = "\x02\x03";

    /**
     * strftime() token => date() token map.
     */
    private const array MAP = [
        'Y' => 'Y', 'y' => 'y', 'C' => 'Y', 'm' => 'm', 'd' => 'd',
        'e' => 'j', 'H' => 'H', 'k' => 'G', 'I' => 'h', 'l' => 'g',
        'M' => 'i', 'S' => 's', 'p' => 'A', 'P' => 'a', 'B' => 'F',
        'h' => 'M', 'b' => 'M', 'A' => 'l', 'a' => 'D', 'Z' => 'T',
        'z' => 'O', 'u' => 'N', 'w' => 'w', 'G' => 'o', 'V' => 'W',
        'U' => 'W', 'W' => 'W', 'D' => 'm/d/y', 'F' => 'Y-m-d',
        'T' => 'H:i:s', 'R' => 'H:i', 'r' => 'h:i:s A',
        'c' => 'Y-m-d\TH:i:sP', 'x' => 'm/d/y', 'X' => 'H:i:s',
        's' => 'U', 'n' => "\n", 't' => "\t", '%' => '%',
    ];

    /** Every date() formatting character; literals must be escaped. */
    private const string DATE_TOKENS = 'dDjlNSwzWFmMntLoYyaABgGXxhHisuevIOPTZcrUp';

    private function __construct() {}

    /**
     * Converts a strftime()-style format into a date()-compatible one.
     *
     * Literal characters are escaped because date() would reinterpret
     * them. %j (one-based day of year) becomes the DOY marker because
     * date() only has zero-based "z".
     */
    public static function strftimeToDate(string $format): string
    {
        $converted = '';
        $length = \strlen($format);

        $escapeLiteral = static function (string $char): string {
            if ($char === '\\') {
                return '\\\\';
            }

            return str_contains(self::DATE_TOKENS, $char) ? '\\' . $char : $char;
        };

        for ($index = 0; $index < $length; ++$index) {
            $character = $format[$index];

            if ($character !== '%' || $index + 1 >= $length) {
                $converted .= $escapeLiteral($character);
                continue;
            }

            $token = $format[++$index];

            if ($token === 'j') {
                $converted .= self::DOY_MARKER;
                continue;
            }

            if (isset(self::MAP[$token])) {
                $converted .= self::MAP[$token];
                continue;
            }

            $converted .= $escapeLiteral($token);
        }

        return $converted;
    }

    /**
     * Formats a timestamp using a strftime()-style format.
     */
    public static function format(int $timestamp, string $format, bool $gmt = false): string
    {
        if ($format === '') {
            $format = self::DEFAULT_FORMAT;
        }

        $dateFormat = self::strftimeToDate($format);
        $result = $gmt ? gmdate($dateFormat, $timestamp) : date($dateFormat, $timestamp);

        if (str_contains($dateFormat, self::DOY_MARKER)) {
            $dayOfYear = (int) ($gmt ? gmdate('z', $timestamp) : date('z', $timestamp)) + 1;
            $result = str_replace(self::DOY_MARKER, \sprintf('%03d', $dayOfYear), $result);
        }

        return $result;
    }

}

}

namespace HtmlPhp\I18n {

use HtmlPhp\Config;
use HtmlPhp\Config\I18n as I18nConfig;
use HtmlPhp\Container;
use HtmlPhp\Diagnostics;
use HtmlPhp\Event\Dispatcher;
use HtmlPhp\Io\Files;
use HtmlPhp\Support\ClockInterface;
use HtmlPhp\Support\Pcre;
use HtmlPhp\Support\Str;

/**
 * Compares extracted template messages against a locale's catalogue.
 *
 * The maintenance question it answers: *"which strings will show up in
 * English on my German site, and which translations are dead weight?"*
 * Wired into `bin/htmlphp i18n:audit`, `wp htmlphp i18n audit` and the
 * WordPress admin screen.
 */
final class Auditor
{
    public function __construct(private readonly Translator $translator) {}

    /**
     * @param list<array{msgid: string, msgid_plural: ?string, context: string, domain: string, references: list<string>}> $entries
     * @return array{locale: string, missing: list<array{msgid: string, context: string, domain: string}>, unused: list<array{msgid: string, context: string, domain: string}>, total: int, translated: int}
     */
    public function audit(array $entries, string $locale, string $domain = 'messages'): array
    {
        $locale = Locale::normalize($locale);
        $missing = [];
        $used = [];
        $total = 0;

        foreach ($entries as $entry) {
            if (($entry['domain'] ?? 'messages') !== $domain) {
                continue;
            }

            $total++;

            $catalog = $this->translator->catalogue($locale, $domain);
            $translated = $catalog?->get($entry['msgid'], $entry['context'] ?? '');

            $used[$domain . "\x04" . ($entry['context'] ?? '') . "\x04" . $entry['msgid']] = true;

            // gettext catalogues also store the plural source form as a key.
            if (($entry['msgid_plural'] ?? null) !== null && $entry['msgid_plural'] !== '') {
                $used[$domain . "\x04" . ($entry['context'] ?? '') . "\x04" . $entry['msgid_plural']] = true;
            }

            if ($translated === null) {
                $missing[] = [
                    'msgid' => $entry['msgid'],
                    'context' => $entry['context'] ?? '',
                    'domain' => $domain,
                ];
            }
        }

        $unused = [];
        $catalog = $this->translator->catalogue($locale, $domain);

        if ($catalog !== null) {
            foreach ($catalog->ids() as $id) {
                $key = $domain . "\x04" . $id['context'] . "\x04" . $id['msgid'];

                if (!isset($used[$key])) {
                    $unused[] = [
                        'msgid' => $id['msgid'],
                        'context' => $id['context'],
                        'domain' => $domain,
                    ];
                }
            }
        }

        return [
            'locale' => $locale,
            'missing' => $missing,
            'unused' => $unused,
            'total' => $total,
            'translated' => $total - \count($missing),
        ];
    }

    /**
     * Human-readable report (CLI / admin screen).
     *
     * @param array{locale: string, missing: list<array{msgid: string, context: string, domain: string}>, unused: list<array{msgid: string, context: string, domain: string}>, total: int, translated: int} $report
     * @return list<string>
     */
    public static function format(array $report): array
    {
        $lines = [];
        $percent = $report['total'] > 0
            ? (int) round($report['translated'] / $report['total'] * 100)
            : 100;

        $lines[] = \sprintf(
            'Locale %s: %d/%d messages translated (%d%%), %d unused.',
            $report['locale'],
            $report['translated'],
            $report['total'],
            $percent,
            \count($report['unused']),
        );

        foreach (\array_slice($report['missing'], 0, 50) as $entry) {
            $lines[] = '  missing: ' . self::label($entry);
        }

        if (\count($report['missing']) > 50) {
            $lines[] = \sprintf('  … and %d more missing.', \count($report['missing']) - 50);
        }

        foreach (\array_slice($report['unused'], 0, 20) as $entry) {
            $lines[] = '  unused:  ' . self::label($entry);
        }

        if (\count($report['unused']) > 20) {
            $lines[] = \sprintf('  … and %d more unused.', \count($report['unused']) - 20);
        }

        return $lines;
    }

    /** @param array{msgid: string, context: string} $entry */
    private static function label(array $entry): string
    {
        return ($entry['context'] !== '' ? $entry['context'] . "\x04" : '') . $entry['msgid'];
    }
}

/**
 * A message catalogue: gettext PO/MO plus (new in v4) JSON/PHP arrays.
 *
 * Stores singular/plural forms per (context, msgid), parses PO headers
 * (charset conversion included) and derives plural selection from the
 * `Plural-Forms` header via {@see PluralForms}.
 */
final class Catalog
{
    private const string CONTEXT_SEPARATOR = "\x04";

    public readonly string $locale;
    public readonly string $domain;

    /** @var array<string, array{single: ?string, plurals: list<string>, fuzzy: bool}> */
    private array $messages = [];

    /** @var array<string, string> lower-cased header name => value */
    private array $headers = [];

    private ?PluralForms $pluralForms = null;
    private string $charset = 'utf-8';

    private function __construct(string $locale, string $domain)
    {
        $this->locale = $locale;
        $this->domain = $domain;
    }

    /**
     * Loads a catalogue from a file, sniffed by magic bytes and extension:
     * `.mo` (gettext binary), `.po` (gettext text), `.json` and `.php`
     * (arrays shaped `'msgid' => 'translation'` or
     * `'msgid' => ['singular', 'plural', …]`; contexts use a `\x04`
     * separator inside the key, and a `headers` key may carry PO headers).
     */
    public static function load(
        string $path,
        string $locale,
        string $domain = 'messages',
        ?Diagnostics $diagnostics = null,
    ): ?self {
        $extension = strtolower(pathinfo($path, PATHINFO_EXTENSION));

        if ($extension === 'php') {
            if (!is_file($path)) {
                $diagnostics?->record(Diagnostics::CATALOG_PARSE, 'Translation catalogue is not readable.', ['path' => $path]);

                return null;
            }

            $messages = include $path;

            return \is_array($messages)
                ? self::fromArray($messages, $locale, $domain)
                : self::failed($diagnostics, 'PHP catalogue did not return an array.', $path);
        }

        $contents = Files::slurp($path, 32 * 1024 * 1024);

        if ($contents === null) {
            return self::failed($diagnostics, 'Translation catalogue is not readable.', $path);
        }

        $magic = substr($contents, 0, 4);

        if ($magic === "\xde\x12\x04\x95" || $magic === "\x95\x04\x12\xde") {
            return self::fromMo($contents, $locale, $domain, $diagnostics);
        }

        if ($extension === 'mo') {
            return self::failed($diagnostics, 'File has a .mo extension but no MO magic.', $path);
        }

        if ($extension === 'json') {
            $decoded = json_decode($contents, true);

            return \is_array($decoded)
                ? self::fromArray($decoded, $locale, $domain)
                : self::failed($diagnostics, 'JSON catalogue is malformed.', $path);
        }

        return self::fromPo($contents, $locale, $domain);
    }

    private static function failed(?Diagnostics $diagnostics, string $message, string $path): null
    {
        $diagnostics?->record(Diagnostics::CATALOG_PARSE, $message, ['path' => $path]);

        return null;
    }

    // ------------------------------------------------------------------- PO

    public static function fromPo(string $source, string $locale, string $domain = 'messages'): self
    {
        $catalog = new self(Locale::normalize($locale), $domain);

        /**
         * Parse state, mutated by reference from the loop below. Typed loosely
         * on purpose: the literal initializer shape does not survive
         * reference-flow analysis and would fake "always false" guards.
         *
         * @var array<string, mixed>
         */
        $entry = ['context' => '', 'id' => '', 'idPlural' => '', 'forms' => [], 'fuzzy' => false];
        $target = null; // ['id'|'context'|'idPlural'|'form', int]
        $lines = preg_split('~\r\n|\r|\n~', $source) ?: [];

        $flush = static function () use (&$entry, $catalog): void {
            // $entry is mutated by reference below; typed locals keep the
            // guard honest for static analysis (the literal init shape does
            // not survive reference flow).
            $id = (string) $entry['id'];
            $forms = (array) $entry['forms'];

            if ($id !== '' || $forms !== []) {
                $catalog->store(
                    (string) $entry['context'],
                    $id,
                    (string) $entry['idPlural'],
                    $forms,
                    (bool) $entry['fuzzy'],
                );
            }

            $entry = ['context' => '', 'id' => '', 'idPlural' => '', 'forms' => [], 'fuzzy' => false];
        };

        foreach ($lines as $rawLine) {
            $line = trim($rawLine);

            if ($line === '') {
                $flush();
                $target = null;
                continue;
            }

            if ($line[0] === '#') {
                if (str_starts_with($line, '#,')) {
                    $flags = array_map('trim', explode(',', substr($line, 2)));
                    $entry['fuzzy'] = $entry['fuzzy'] || \in_array('fuzzy', $flags, true);
                }

                // #. #: #| and plain # comments carry no payload for us.
                continue;
            }

            if (preg_match('~^(msgctxt|msgid_plural|msgid|msgstr(?:\[(\d+)\])?)\s+(.*)$~', $line, $m) === 1) {
                $keyword = $m[1];
                $payload = $m[3];

                if (str_starts_with($keyword, 'msgstr[')) {
                    $target = ['form', (int) $m[2]];
                } elseif ($keyword === 'msgstr') {
                    $target = ['form', 0];
                } elseif ($keyword === 'msgid') {
                    $target = ['id', 0];
                } elseif ($keyword === 'msgid_plural') {
                    $target = ['idPlural', 0];
                } else {
                    $target = ['context', 0];
                }

                $string = self::poString($payload);

                if ($string !== null) {
                    $catalog->appendEntry($entry, $target, $string);
                }

                continue;
            }

            // Continuation line: a bare quoted string.
            if ($line[0] === '"' && $target !== null) {
                $string = self::poString($line);

                if ($string !== null) {
                    $catalog->appendEntry($entry, $target, $string);
                }
            }
        }

        $flush();
        $catalog->finalizeHeaders();

        return $catalog;
    }

    /**
     * Appends a parsed string fragment to the current entry slot.
     *
     * @param array{context: string, id: string, idPlural: string, forms: array<int, string>, fuzzy: bool} $entry
     * @param array{0: string, 1: int} $target
     */
    private function appendEntry(array &$entry, array $target, string $fragment): void
    {
        match ($target[0]) {
            'context' => $entry['context'] .= $fragment,
            'id' => $entry['id'] .= $fragment,
            'idPlural' => $entry['idPlural'] .= $fragment,
            default => $entry['forms'][$target[1]] = ($entry['forms'][$target[1]] ?? '') . $fragment,
        };
    }

    /**
     * Parses one PO quoted string ("…" with escapes); null when invalid.
     */
    private static function poString(string $payload): ?string
    {
        $payload = trim($payload);

        if ($payload === '' || $payload[0] !== '"') {
            return null;
        }

        $length = \strlen($payload);
        $value = '';

        for ($index = 1; $index < $length; ++$index) {
            $char = $payload[$index];

            if ($char === '\\' && $index + 1 < $length) {
                $next = $payload[++$index];
                $value .= match ($next) {
                    'n' => "\n",
                    't' => "\t",
                    'r' => "\r",
                    '0' => "\0",
                    default => $next,
                };
                continue;
            }

            if ($char === '"') {
                return $value;
            }

            $value .= $char;
        }

        return null; // Unterminated string.
    }

    // ------------------------------------------------------------------- MO

    public static function fromMo(
        string $binary,
        string $locale,
        string $domain = 'messages',
        ?Diagnostics $diagnostics = null,
    ): ?self {
        $length = \strlen($binary);

        if ($length < 28) {
            $diagnostics?->record(Diagnostics::CATALOG_PARSE, 'MO catalogue is truncated.');

            return null;
        }

        $magic = substr($binary, 0, 4);
        $endian = $magic === "\xde\x12\x04\x95" ? 'V' : 'N';

        $header = unpack($endian . 'revision/' . $endian . 'count/' . $endian . 'origOffset/'
            . $endian . 'transOffset/' . $endian . 'hashSize/' . $endian . 'hashOffset', substr($binary, 4, 24));

        if ($header === false) {
            return null;
        }

        $majorRevision = ($header['revision'] >> 16) & 0xFFFF;

        if ($majorRevision > 1) {
            $diagnostics?->record(
                Diagnostics::CATALOG_PARSE,
                \sprintf('Unsupported MO revision %d.', $majorRevision),
            );

            return null;
        }

        $count = (int) $header['count'];
        $origOffset = (int) $header['origOffset'];
        $transOffset = (int) $header['transOffset'];

        if ($count < 0 || $count > 1_000_000
            || $origOffset < 0 || $origOffset + $count * 8 > $length
            || $transOffset < 0 || $transOffset + $count * 8 > $length
        ) {
            $diagnostics?->record(Diagnostics::CATALOG_PARSE, 'MO catalogue tables are out of bounds.');

            return null;
        }

        $catalog = new self(Locale::normalize($locale), $domain);

        for ($index = 0; $index < $count; ++$index) {
            $origMeta = unpack($endian . 'len/' . $endian . 'off', substr($binary, $origOffset + $index * 8, 8));
            $transMeta = unpack($endian . 'len/' . $endian . 'off', substr($binary, $transOffset + $index * 8, 8));

            if ($origMeta === false || $transMeta === false) {
                continue;
            }

            $origLen = (int) $origMeta['len'];
            $origOff = (int) $origMeta['off'];
            $transLen = (int) $transMeta['len'];
            $transOff = (int) $transMeta['off'];

            if ($origOff < 0 || $origOff + $origLen > $length
                || $transOff < 0 || $transOff + $transLen > $length
            ) {
                continue;
            }

            $original = substr($binary, $origOff, $origLen);
            $translation = substr($binary, $transOff, $transLen);

            if ($original === '') {
                // Metadata entry: headers (and possibly a NUL-separated
                // comment block we do not need).
                $catalog->storeHeaders($translation);
                continue;
            }

            $context = '';

            if (str_contains($original, self::CONTEXT_SEPARATOR)) {
                [$context, $original] = explode(self::CONTEXT_SEPARATOR, $original, 2);
            }

            $idParts = explode("\0", $original);
            $id = (string) $idParts[0];
            $idPlural = (string) ($idParts[1] ?? '');
            $forms = [];

            foreach (explode("\0", $translation) as $position => $form) {
                $forms[$position] = $form;
            }

            $catalog->store($context, $id, $idPlural, $forms, false);
        }

        $catalog->finalizeHeaders();

        return $catalog;
    }

    // -------------------------------------------------------------- storage

    /**
     * @param array<int, string> $forms
     */
    private function store(string $context, string $id, string $idPlural, array $forms, bool $fuzzy): void
    {
        if ($id === '') {
            $joined = '';

            foreach ($forms as $form) {
                $joined .= $form;
            }

            if ($joined !== '') {
                $this->storeHeaders($joined);
            }

            return;
        }

        ksort($forms);

        $this->messages[self::key($context, $id)] = [
            'single' => $forms[0] ?? null,
            'plurals' => array_values(array_map('strval', $forms)),
            'fuzzy' => $fuzzy,
        ];

        if ($idPlural !== '') {
            $this->messages[self::key($context, $idPlural)] ??= $this->messages[self::key($context, $id)];
        }
    }

    private function storeHeaders(string $raw): void
    {
        foreach (preg_split('~\r\n|\r|\n~', $raw) ?: [] as $line) {
            if (preg_match('~^([A-Za-z][A-Za-z0-9_-]*)\s*:\s*(.*)$~', trim($line), $m) === 1) {
                $this->headers[strtolower($m[1])] = trim($m[2]);
            }
        }

        $charsetHeader = $this->headers['content-type'] ?? '';

        if (preg_match('~charset\s*=\s*([A-Za-z0-9_-]+)~i', $charsetHeader, $m) === 1) {
            $this->charset = strtolower($m[1]);
        }
    }

    /**
     * Converts non-UTF-8 payloads once, right after parsing.
     */
    private function finalizeHeaders(): void
    {
        $this->pluralForms = PluralForms::parse($this->headers['plural-forms'] ?? null, $this->locale);

        if (\in_array($this->charset, ['utf-8', 'utf8', 'ascii', 'us-ascii'], true)) {
            return;
        }

        $charset = $this->charset;

        $convert = static function (string $text) use ($charset): string {
            if (\function_exists('iconv')) {
                $converted = @iconv($charset, 'UTF-8//TRANSLIT', $text);

                if ($converted !== false) {
                    return $converted;
                }
            }

            if (\function_exists('mb_convert_encoding')) {
                $converted = @mb_convert_encoding($text, 'UTF-8', $charset);

                if (\is_string($converted)) {
                    return $converted;
                }
            }

            return $text;
        };

        foreach ($this->messages as $key => $entry) {
            $this->messages[$key] = [
                'single' => $entry['single'] === null ? null : $convert($entry['single']),
                'plurals' => array_map($convert, $entry['plurals']),
                'fuzzy' => $entry['fuzzy'],
            ];
        }
    }

    private static function key(string $context, string $msgid): string
    {
        return $context === '' ? $msgid : $context . self::CONTEXT_SEPARATOR . $msgid;
    }

    // --------------------------------------------------------------- lookup

    /**
     * Singular translation or null (fuzzy entries are ignored).
     */
    public function get(string $msgid, string $context = ''): ?string
    {
        $entry = $this->messages[self::key($context, $msgid)] ?? null;

        if ($entry === null || $entry['fuzzy'] || $entry['single'] === null || $entry['single'] === '') {
            return null;
        }

        return $entry['single'];
    }

    /**
     * Plural translation form or null.
     */
    public function getPlural(string $msgid, int $formIndex, string $context = ''): ?string
    {
        $entry = $this->messages[self::key($context, $msgid)] ?? null;

        if ($entry === null || $entry['fuzzy'] || $entry['plurals'] === []) {
            return null;
        }

        $form = $entry['plurals'][$formIndex] ?? null;

        return \is_string($form) && $form !== '' ? $form : null;
    }

    public function has(string $msgid, string $context = ''): bool
    {
        return $this->get($msgid, $context) !== null;
    }

    public function pluralForms(): PluralForms
    {
        return $this->pluralForms ??= PluralForms::parse(null, $this->locale);
    }

    /**
     * @return array<string, string>
     */
    public function headers(): array
    {
        return $this->headers;
    }

    public function count(): int
    {
        return \count($this->messages);
    }

    /**
     * Builds a catalogue from a plain PHP/JSON array.
     *
     * Accepted shapes per key (contexts are encoded as `"ctx\x04msgid"`):
     *  - `'msgid' => 'translation'`
     *  - `'msgid' => ['singular', 'plural form 1', …]`
     *  - `'headers' => ['Plural-Forms' => 'nplurals=2; plural=n != 1;']`
     *
     * @param array<array-key, mixed> $messages
     */
    public static function fromArray(array $messages, string $locale, string $domain = 'messages'): self
    {
        $catalog = new self(Locale::normalize($locale), $domain);

        $headers = $messages['headers'] ?? null;

        if (\is_array($headers)) {
            $lines = [];

            foreach ($headers as $name => $value) {
                if (\is_string($name) && \is_scalar($value)) {
                    $lines[] = $name . ': ' . $value;
                }
            }

            $catalog->storeHeaders(implode("\n", $lines));
        }

        foreach ($messages as $key => $value) {
            if (!\is_string($key) || $key === 'headers') {
                continue;
            }

            [$context, $msgid] = str_contains($key, self::CONTEXT_SEPARATOR)
                ? explode(self::CONTEXT_SEPARATOR, $key, 2)
                : ['', $key];

            if (\is_string($value)) {
                $catalog->store($context, $msgid, '', [0 => $value], false);
                continue;
            }

            if (\is_array($value) && $value !== []) {
                $forms = [];

                foreach (array_values($value) as $index => $form) {
                    if (\is_scalar($form) || $form === null) {
                        $forms[$index] = (string) $form;
                    }
                }

                if ($forms !== []) {
                    $catalog->store($context, $msgid, '', $forms, false);
                }
            }
        }

        $catalog->finalizeHeaders();

        return $catalog;
    }

    /**
     * Merges another catalogue's messages into this one.
     *
     * Existing entries win unless `$otherWins` — used when several
     * configured paths contribute to the same locale/domain (first path
     * takes precedence, like WordPress theme-over-plugin overrides).
     */
    public function mergeFrom(self $other, bool $otherWins = false): void
    {
        foreach ($other->messages as $key => $entry) {
            if ($otherWins || !isset($this->messages[$key])) {
                $this->messages[$key] = $entry;
            }
        }
    }

    /**
     * Every stored message id with its context — used by the i18n auditor.
     *
     * @return list<array{context: string, msgid: string}>
     */
    public function ids(): array
    {
        $ids = [];

        foreach (array_keys($this->messages) as $key) {
            [$context, $msgid] = str_contains($key, self::CONTEXT_SEPARATOR)
                ? explode(self::CONTEXT_SEPARATOR, $key, 2)
                : ['', $key];

            $ids[] = ['context' => $context, 'msgid' => $msgid];
        }

        return $ids;
    }
}

/**
 * Extracts translatable messages from template sources.
 *
 * Recognised syntax:
 *  - `@{Some.Key}` — static message id;
 *  - `<!--@Trans count="%{n}" domain="d" context="c"-->singular body
 *    <!--@Plural-->plural body<!--@EndTrans-->` — the bodies become the
 *    msgid/msgid_plural with every `%{expr}` normalised to a positional
 *    `{0}`, `{1}`, … placeholder (exactly what the renderer looks up).
 *
 * `%{dynamic|translate}` cannot be extracted (runtime value) and is
 * reported through {@see self::dynamicHits()} so CI can flag it.
 *
 * Feed the result to {@see self::toPo()} (POT skeleton) or the auditor.
 */
final class Extractor
{
    /** @var list<array{msgid: string, msgid_plural: ?string, context: string, domain: string, references: list<string>}> */
    private array $entries = [];

    /** @var list<string> "file:line" of dynamic translate filters */
    private array $dynamic = [];

    /** @var array<string, int> entry key => index */
    private array $index = [];

    /**
     * Scans one template source. `$name` is used for reference annotations.
     */
    public function scan(string $source, string $name = '-'): self
    {
        $this->scanAtKeys($source, $name);
        $this->scanTransBlocks($source, $name);
        $this->scanDynamic($source, $name);

        return $this;
    }

    /**
     * Recursively scans every `.html`/`.htm`/`.txt` template below `$dir`.
     *
     * @return list<string> scanned files
     */
    public function scanDirectory(string $dir, string $extension = 'html'): array
    {
        $scanned = [];

        if (!is_dir($dir)) {
            return $scanned;
        }

        $iterator = new \RecursiveIteratorIterator(
            new \RecursiveDirectoryIterator($dir, \FilesystemIterator::SKIP_DOTS),
        );

        /** @var \SplFileInfo $info */
        foreach ($iterator as $info) {
            if (!$info->isFile() || $info->getExtension() !== $extension) {
                continue;
            }

            $contents = @file_get_contents($info->getPathname());

            if (\is_string($contents)) {
                $this->scan($contents, $info->getPathname());
                $scanned[] = $info->getPathname();
            }
        }

        return $scanned;
    }

    /** @return list<array{msgid: string, msgid_plural: ?string, context: string, domain: string, references: list<string>}> */
    public function entries(): array
    {
        return $this->entries;
    }

    /** @return list<string> */
    public function dynamicHits(): array
    {
        return $this->dynamic;
    }

    public function reset(): void
    {
        $this->entries = [];
        $this->dynamic = [];
        $this->index = [];
    }

    /**
     * Renders a PO/POT skeleton of everything extracted so far.
     */
    public function toPo(string $projectId = 'HTML.PHP templates', bool $pot = true): string
    {
        $out = "msgid \"\"\nmsgstr \"\"\n"
            . '"Project-Id-Version: ' . self::escapePo($projectId) . "\\n\"\n"
            . '"MIME-Version: 1.0\\n"' . "\n"
            . '"Content-Type: text/plain; charset=UTF-8\\n"' . "\n"
            . '"Content-Transfer-Encoding: 8bit\\n"' . "\n\n";

        foreach ($this->entries as $entry) {
            if ($entry['references'] !== []) {
                $out .= '#: ' . implode(', ', $entry['references']) . "\n";
            }

            if ($entry['context'] !== '') {
                $out .= 'msgctxt "' . self::escapePo($entry['context']) . "\"\n";
            }

            $out .= 'msgid "' . self::escapePo($entry['msgid']) . "\"\n";

            if ($entry['msgid_plural'] !== null) {
                $out .= 'msgid_plural "' . self::escapePo($entry['msgid_plural']) . "\"\n";
                $out .= 'msgstr[0] ""' . "\n";
                $out .= 'msgstr[1] ""' . "\n";
            } else {
                $out .= 'msgstr ""' . "\n";
            }

            $out .= "\n";
        }

        return $pot ? $out : $out;
    }

    // ---------------------------------------------------------------- scanning

    private function scanAtKeys(string $source, string $name): void
    {
        if (preg_match_all('~@\{([^{}<>]{1,200}?)\}~', $source, $matches, PREG_OFFSET_CAPTURE) === 0) {
            return;
        }

        foreach ($matches[1] as $index => $match) {
            $msgid = trim(explode('|', (string) $match[0])[0]);

            if ($msgid === '') {
                continue;
            }

            $this->add($msgid, null, '', 'messages', $this->reference($source, $name, (int) $match[1]));
        }
    }

    private function scanTransBlocks(string $source, string $name): void
    {
        $count = preg_match_all(
            '~<!--@Trans\b(.*?)-->(.*?)<!--@EndTrans\s*(?:[^>]*)?-->~is',
            $source,
            $matches,
            PREG_OFFSET_CAPTURE,
        );

        if ($count === 0 || $count === false) {
            return;
        }

        foreach ($matches[0] as $index => $whole) {
            $attrs = \HtmlPhp\Ssi\Attributes::parse((string) $matches[1][$index][0]);
            $body = (string) $matches[2][$index][0];

            $parts = preg_split('~<!--@Plural\s*-->~i', $body, 2);
            $singular = self::literalize((string) ($parts[0] ?? ''));
            $plural = isset($parts[1]) ? self::literalize($parts[1]) : null;

            if (trim($singular) === '' && $plural === null) {
                continue;
            }

            $domain = trim($attrs['domain'] ?? '');

            $this->add(
                $singular,
                $plural,
                trim($attrs['context'] ?? ''),
                $domain !== '' ? $domain : 'messages',
                $this->reference($source, $name, (int) $whole[1]),
            );
        }
    }

    private function scanDynamic(string $source, string $name): void
    {
        if (preg_match_all('~[%#]\{[^}]*\|\s*translate\b~', $source, $matches, PREG_OFFSET_CAPTURE) > 0) {
            foreach ($matches[0] as $match) {
                $this->dynamic[] = $this->reference($source, $name, (int) $match[1]);
            }
        }
    }

    /**
     * Turns a trans-block body into its msgid form: `%{expr}` becomes `{n}`,
     * whitespace runs collapse to single spaces, edges are trimmed.
     */
    private static function literalize(string $body): string
    {
        $index = 0;

        $body = Pcre::replaceCallback(
            '~[%#]\{\s*([^}|]+?)(?:\|[^}]*)?\}~',
            static function () use (&$index): string {
                return '{' . $index++ . '}';
            },
            $body,
        );

        $body = (string) preg_replace('~\s+~', ' ', $body);

        return trim($body);
    }

    private function add(string $msgid, ?string $plural, string $context, string $domain, string $reference): void
    {
        $key = $domain . "\x04" . $context . "\x04" . $msgid . "\x04" . ($plural ?? '');

        if (isset($this->index[$key])) {
            $entry = &$this->entries[$this->index[$key]];

            if (!\in_array($reference, $entry['references'], true)) {
                $entry['references'][] = $reference;
            }

            unset($entry);

            return;
        }

        $this->index[$key] = \count($this->entries);
        $this->entries[] = [
            'msgid' => $msgid,
            'msgid_plural' => $plural,
            'context' => $context,
            'domain' => $domain,
            'references' => [$reference],
        ];
    }

    private function reference(string $source, string $name, int $offset): string
    {
        if ($offset <= 0 || $offset > \strlen($source)) {
            return $name;
        }

        $line = substr_count($source, "\n", 0, $offset) + 1;

        return $name . ':' . $line;
    }

    private static function escapePo(string $text): string
    {
        return str_replace(
            ["\x00", "\\", '"', "\n", "\t", "\r"],
            ['', '\\\\', '\\"', '\\n', '\\t', '\\r'],
            $text,
        );
    }
}

/**
 * Locale-aware number/date formatting.
 *
 * Separator conventions for ~30 common locales ship built in; anything
 * else falls back to the configured defaults (`i18n.decimal_point`,
 * `i18n.thousands_separator`, `i18n.date_format`, …). Extensible through
 * the `htmlphp.i18n.locale_formats` container override or by subclassing.
 */
class Formats
{
    /** language => [decimal point, thousands separator] */
    protected const array SEPARATORS = [
        'en' => ['.', ','], 'ja' => ['.', ','], 'zh' => ['.', ','], 'ko' => ['.', ','],
        'de' => [',', '.'], 'es' => [',', '.'], 'it' => [',', '.'], 'nl' => [',', '.'],
        'pt' => [',', '.'], 'tr' => [',', '.'], 'el' => [',', '.'], 'ro' => [',', '.'],
        'hu' => [',', ' '], 'pl' => [',', ' '], 'ru' => [',', ' '], 'uk' => [',', ' '],
        'cs' => [',', ' '], 'sk' => [',', ' '], 'bg' => [',', ' '], 'kk' => [',', ' '],
        'fr' => [',', "\u{202F}"], 'ar' => [',', '.'], 'he' => ['.', ','],
        'fi' => [',', ' '], 'sv' => [',', ' '], 'no' => [',', ' '], 'nb' => [',', ' '],
        'nn' => [',', ' '], 'da' => [',', '.'], 'id' => [',', '.'], 'vi' => [',', '.'],
        'th' => ['.', ','], 'hi' => ['.', ','], 'fa' => ['.', ','],
        'et' => [',', ' '], 'lv' => [',', ' '], 'lt' => [',', ' '], 'hr' => [',', '.'],
        'sl' => [',', '.'], 'sr' => [',', '.'], 'ka' => [',', ' '], 'hy' => [',', ' '],
    ];

    public function __construct(
        protected readonly I18nConfig $config,
        protected readonly ?ClockInterface $clock = null,
    ) {}

    /**
     * Formats a number with the locale's separators.
     */
    public function number(float|int|string $value, ?string $locale = null, ?int $decimals = null): string
    {
        [$point, $thousands] = $this->separators($locale);

        return Str::number(
            Str::numericValue($value),
            $decimals ?? $this->config->numberDecimals,
            $point,
            $thousands,
        );
    }

    /**
     * Formats a UNIX timestamp, numeric string or DateTime with a `date()`
     * pattern (defaults to the configured `i18n.date_format`).
     */
    public function date(int|string|\DateTimeInterface $value, ?string $format = null, ?string $timezone = null): string
    {
        return $this->formatDate($value, $format ?? $this->config->dateFormat, $timezone);
    }

    public function time(int|string|\DateTimeInterface $value, ?string $format = null, ?string $timezone = null): string
    {
        return $this->formatDate($value, $format ?? $this->config->timeFormat, $timezone);
    }

    public function datetime(int|string|\DateTimeInterface $value, ?string $format = null, ?string $timezone = null): string
    {
        return $this->formatDate($value, $format ?? $this->config->dateTimeFormat, $timezone);
    }

    /**
     * Human-friendly elapsed time ("3 minutes ago") — the filter behind
     * `%{updated|ago}`; English wording, hosts localise through the
     * `htmlphp.i18n.ago` event or by subclassing.
     */
    public function ago(int|string|\DateTimeInterface $value, ?int $now = null): string
    {
        $timestamp = $this->timestampOf($value);

        if ($timestamp === null) {
            return Str::stringify($value);
        }

        $diff = ($now ?? $this->clock?->now() ?? time()) - $timestamp;
        $future = $diff < 0;
        $diff = abs($diff);

        $unit = match (true) {
            $diff < 60 => ['second', $diff],
            $diff < 3600 => ['minute', intdiv($diff, 60)],
            $diff < 86400 => ['hour', intdiv($diff, 3600)],
            $diff < 2592000 => ['day', intdiv($diff, 86400)],
            $diff < 31536000 => ['month', intdiv($diff, 2592000)],
            default => ['year', intdiv($diff, 31536000)],
        };

        return $future
            ? \sprintf('in %d %s%s', $unit[1], $unit[0], $unit[1] === 1 ? '' : 's')
            : \sprintf('%d %s%s ago', $unit[1], $unit[0], $unit[1] === 1 ? '' : 's');
    }

    /** @return array{0: string, 1: string} */
    protected function separators(?string $locale): array
    {
        $locale = $locale !== null ? Locale::normalize($locale) : $this->config->locale;
        $language = Locale::language($locale);

        return self::SEPARATORS[$language]
            ?? [$this->config->decimalPoint, $this->config->thousandsSeparator];
    }

    protected function formatDate(int|string|\DateTimeInterface $value, string $format, ?string $timezone): string
    {
        $timestamp = $this->timestampOf($value);

        if ($timestamp === null) {
            return Str::stringify($value);
        }

        $tz = $timezone !== null && $timezone !== '' ? new \DateTimeZone($timezone) : null;

        return (new \DateTimeImmutable('@' . $timestamp))
            ->setTimezone($tz ?? new \DateTimeZone(date_default_timezone_get()))
            ->format($format);
    }

    protected function timestampOf(int|string|\DateTimeInterface $value): ?int
    {
        if ($value instanceof \DateTimeInterface) {
            return $value->getTimestamp();
        }

        if (\is_int($value)) {
            return $value;
        }

        $value = trim($value);

        if ($value === '') {
            return null;
        }

        if (Str::isNumericString($value)) {
            return (int) Str::numericValue($value);
        }

        $parsed = strtotime($value);

        return $parsed === false ? null : $parsed;
    }
}

/**
 * Locale normalisation, `Accept-Language` parsing and negotiation.
 *
 * No superglobals: callers pass the header value explicitly (typically
 * `RequestContext::$acceptLanguage`).
 */
final class Locale
{
    public const DEFAULT_LOCALE = 'en';

    private function __construct() {}

    /**
     * Normalises any locale spelling to "ll_CC":
     *   en-us, EN_US.utf8, en_US.UTF-8@euro, en-usoed → en_US / en.
     */
    public static function normalize(string $locale): string
    {
        $locale = trim($locale);

        if ($locale === '') {
            return self::DEFAULT_LOCALE;
        }

        // Drop codeset and modifier: ru_RU.UTF-8@euro → ru_RU
        $locale = preg_replace('~[.@].*$~', '', $locale) ?? $locale;
        $locale = str_replace('-', '_', $locale);

        if (preg_match('~^([A-Za-z]{2,3})(?:_([A-Za-z]{4}))?(?:_([A-Za-z]{2}|[0-9]{3}))?$~', $locale, $m) !== 1) {
            return self::DEFAULT_LOCALE;
        }

        $language = strtolower($m[1]);

        if (($m[3] ?? '') !== '') {
            return $language . '_' . strtoupper($m[3]);
        }

        if (($m[2] ?? '') !== '') {
            // Script subtag only (zh_Hant): keep as zh_Hant.
            return $language . '_' . ucfirst(strtolower($m[2]));
        }

        return $language;
    }

    /**
     * Language part of a locale ("ru_RU" → "ru").
     */
    public static function language(string $locale): string
    {
        $normalized = self::normalize($locale);
        $position = strpos($normalized, '_');

        return $position === false ? $normalized : substr($normalized, 0, $position);
    }

    /**
     * Parses an Accept-Language header into q-sorted candidates.
     *
     * @return list<array{locale: string, q: float}>
     */
    public static function parseAcceptLanguage(?string $header): array
    {
        if ($header === null || trim($header) === '') {
            return [];
        }

        $candidates = [];

        foreach (explode(',', $header) as $part) {
            $segments = explode(';', trim($part));
            $tag = self::normalize(trim((string) $segments[0]));
            $quality = 1.0;

            foreach (\array_slice($segments, 1) as $parameter) {
                if (preg_match('~^\s*q\s*=\s*([0-9.]+)\s*$~i', $parameter, $m) === 1) {
                    $quality = max(0.0, min(1.0, (float) $m[1]));
                }
            }

            if ($tag !== '' && $tag !== '*') {
                $candidates[] = ['locale' => $tag, 'q' => $quality];
            } elseif ($tag === '*') {
                $candidates[] = ['locale' => '*', 'q' => $quality];
            }
        }

        usort($candidates, static fn(array $a, array $b): int => $b['q'] <=> $a['q']);

        return $candidates;
    }

    /**
     * Picks the best available locale for an Accept-Language header.
     *
     * Match order: exact tag → same language with any territory → any
     * available locale sharing the language prefix → $default.
     *
     * @param list<string>|array<string, mixed> $available
     */
    public static function negotiate(array $available, ?string $header = null, ?string $default = null): string
    {
        $availableList = array_values(array_map(
            static fn(mixed $locale): string => self::normalize((string) $locale),
            $available,
        ));

        if ($availableList === []) {
            return self::normalize($default ?? self::DEFAULT_LOCALE);
        }

        $fallback = self::normalize($default ?? $availableList[0]);

        foreach (self::parseAcceptLanguage($header) as $candidate) {
            $wanted = $candidate['locale'];

            if ($wanted === '*') {
                continue;
            }

            if (\in_array($wanted, $availableList, true)) {
                return $wanted;
            }

            $language = self::language($wanted);

            foreach ($availableList as $option) {
                if (self::language($option) === $language) {
                    return $option;
                }
            }
        }

        return $fallback;
    }
}

/**
 * Safe evaluator for gettext `Plural-Forms` header expressions.
 *
 * Implements the C-subset grammar gettext actually emits (ternary, ||, &&,
 * ==/!=, </<=/>/>=, %/arithmetics, n) as a tokenizing recursive-descent
 * evaluator — never `eval()`. Ships built-in rules for 60+ languages so a
 * catalogue without the header still pluralises correctly.
 */
final class PluralForms
{
    /** Hard cap — gettext plural counts never legitimately exceed this. */
    public const int MAX_FORMS = 6;

    private const int MAX_EXPRESSION_LENGTH = 512;

    /**
     * Built-in plural rules per language, used when a catalogue has no
     * Plural-Forms header. Key = language code.
     */
    private const array LANGUAGE_RULES = [
        // Single form
        'ay' => 'nplurals=1; plural=0;', 'bo' => 'nplurals=1; plural=0;',
        'cgg' => 'nplurals=1; plural=0;', 'dz' => 'nplurals=1; plural=0;',
        'fa' => 'nplurals=1; plural=0;', 'id' => 'nplurals=1; plural=0;',
        'ja' => 'nplurals=1; plural=0;', 'jbo' => 'nplurals=1; plural=0;',
        'ka' => 'nplurals=1; plural=0;', 'kk' => 'nplurals=1; plural=0;',
        'km' => 'nplurals=1; plural=0;', 'ko' => 'nplurals=1; plural=0;',
        'ky' => 'nplurals=1; plural=0;', 'lo' => 'nplurals=1; plural=0;',
        'ms' => 'nplurals=1; plural=0;', 'my' => 'nplurals=1; plural=0;',
        'sah' => 'nplurals=1; plural=0;', 'sa' => 'nplurals=1; plural=0;',
        'ta' => 'nplurals=1; plural=0;', 'th' => 'nplurals=1; plural=0;',
        'tt' => 'nplurals=1; plural=0;', 'ug' => 'nplurals=1; plural=0;',
        'vi' => 'nplurals=1; plural=0;', 'wo' => 'nplurals=1; plural=0;',
        'zh' => 'nplurals=1; plural=0;',
        // Slavic 3-form family
        'be' => 'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);',
        'bs' => 'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);',
        'hr' => 'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);',
        'ru' => 'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);',
        'sr' => 'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);',
        'uk' => 'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);',
        // Czech/Slovak
        'cs' => 'nplurals=3; plural=(n==1) ? 0 : (n>=2 && n<=4) ? 1 : 2;',
        'sk' => 'nplurals=3; plural=(n==1) ? 0 : (n>=2 && n<=4) ? 1 : 2;',
        // Polish
        'pl' => 'nplurals=3; plural=(n==1 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);',
        // Baltic
        'lt' => 'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && (n%100<10 || n%100>=20) ? 1 : 2);',
        'lv' => 'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n!=0 ? 1 : 2);',
        // Romanian / Moldavian
        'ro' => 'nplurals=3; plural=(n==1 ? 0 : (n==0 || (n%100>0 && n%100<20)) ? 1 : 2);',
        'mo' => 'nplurals=3; plural=(n==1 ? 0 : (n==0 || (n%100>0 && n%100<20)) ? 1 : 2);',
        // Celtic
        'cy' => 'nplurals=4; plural=(n==1) ? 0 : (n==2) ? 1 : (n != 8 && n != 11) ? 2 : 3;',
        'ga' => 'nplurals=5; plural=(n==1 ? 0 : n==2 ? 1 : n<7 ? 2 : n<11 ? 3 : 4);',
        'gd' => 'nplurals=4; plural=(n==1 || n==11) ? 0 : (n==2 || n==12) ? 1 : (n>2 && n<20) ? 2 : 3;',
        // Slovenian
        'sl' => 'nplurals=4; plural=(n%100==1 ? 1 : n%100==2 ? 2 : n%100==3 || n%100==4 ? 3 : 0);',
        // Arabic
        'ar' => 'nplurals=6; plural=(n==0 ? 0 : n==1 ? 1 : n==2 ? 2 : n%100>=3 && n%100<=10 ? 3 : n%100>=11 ? 4 : 5);',
        // "n > 1" family (French treats 0 and 1 as singular)
        'fr' => 'nplurals=2; plural=(n > 1);',
        'pt' => 'nplurals=2; plural=(n > 1);',
        'kab' => 'nplurals=2; plural=(n > 1);',
        // Icelandic / Macedonian edge cases
        'is' => 'nplurals=2; plural=(n%10!=1 || n%100==11);',
        'mk' => 'nplurals=2; plural=(n%10==1 && n%100!=11);',
        // Maltese
        'mt' => 'nplurals=4; plural=(n==1 ? 0 : n==0 || ( n%100>1 && n%100<11) ? 1 : (n%100>10 && n%100<20 ) ? 2 : 3);',
    ];

    private int $count;
    /** @var list<array{0: string, 1: string}> */
    private array $tokens;
    private int $position = 0;

    /** @param list<array{0: string, 1: string}> $tokens */
    private function __construct(int $count, array $tokens)
    {
        $this->count = $count;
        $this->tokens = $tokens;
    }

    /**
     * Parses a "Plural-Forms" header (or a bare plural expression).
     *
     * Falls back to the built-in rule for $language and finally to the
     * English rule (nplurals=2; plural=(n != 1)).
     */
    public static function parse(?string $header, string $language = 'en'): self
    {
        $language = Locale::language($language);
        $count = 2;
        $expression = 'n != 1';

        $header = \is_string($header) ? trim($header) : '';

        if ($header !== '') {
            if (preg_match('~nplurals\s*=\s*(\d+)~i', $header, $m) === 1) {
                $count = max(1, min(self::MAX_FORMS, (int) $m[1]));
            }

            if (preg_match('~plural\s*=\s*(.+?)\s*;?\s*$~is', $header, $m) === 1) {
                $candidate = trim($m[1]);

                if ($candidate !== '' && \strlen($candidate) <= self::MAX_EXPRESSION_LENGTH) {
                    $expression = $candidate;
                }
            }
        } elseif (isset(self::LANGUAGE_RULES[$language])) {
            return self::parse(self::LANGUAGE_RULES[$language], $language);
        }

        $tokens = self::tokenize($expression);

        return new self($count, $tokens ?? [['int', '0']]);
    }

    public function count(): int
    {
        return $this->count;
    }

    /**
     * Selects the plural form index for $n (clamped, never negative).
     */
    public function select(int $n): int
    {
        if ($this->count === 1) {
            return 0;
        }

        try {
            $this->position = 0;
            $value = $this->parseTernary($n);

            if ($this->position < \count($this->tokens)) {
                return $n === 1 ? 0 : min(1, $this->count - 1);
            }
        } catch (\RuntimeException) {
            return $n === 1 ? 0 : min(1, $this->count - 1);
        }

        $index = (int) $value;

        return max(0, min($this->count - 1, $index));
    }

    // --------------------------------------------------------------- lexer

    /**
     * @return list<array{0: string, 1: string}>|null
     */
    private static function tokenize(string $expression): ?array
    {
        $tokens = [];
        $length = \strlen($expression);
        $index = 0;

        while ($index < $length) {
            $char = $expression[$index];

            if (ctype_space($char)) {
                ++$index;
                continue;
            }

            if (ctype_digit($char)) {
                preg_match('~\d+~A', $expression, $m, 0, $index);
                $tokens[] = ['int', $m[0]];
                $index += \strlen($m[0]);
                continue;
            }

            if ($char === 'n') {
                $tokens[] = ['n', 'n'];
                ++$index;
                continue;
            }

            $two = substr($expression, $index, 2);

            if (\in_array($two, ['==', '!=', '<=', '>=', '&&', '||'], true)) {
                $tokens[] = [$two, $two];
                $index += 2;
                continue;
            }

            if (str_contains('()<>=!?:+-*/%', $char)) {
                $tokens[] = [$char, $char];
                ++$index;
                continue;
            }

            return null;
        }

        return $tokens;
    }

    // ---------------------------------------------------------------- parser

    /** @return array{0: string, 1: string}|null */
    private function peek(): ?array
    {
        return $this->tokens[$this->position] ?? null;
    }

    private function accept(string $type): bool
    {
        $token = $this->peek();

        if ($token !== null && $token[0] === $type) {
            ++$this->position;

            return true;
        }

        return false;
    }

    private function parseTernary(int $n): int
    {
        $condition = $this->parseOr($n);

        if ($this->accept('?')) {
            $whenTrue = $this->parseTernary($n);

            if (!$this->accept(':')) {
                throw new \RuntimeException('expected ":" in plural expression');
            }

            $whenFalse = $this->parseTernary($n);

            return $condition !== 0 ? $whenTrue : $whenFalse;
        }

        // Not a ternary: pass the integer value through unchanged so
        // literal form indices ("plural=2") survive. Logical operators
        // already normalise their results to 0/1.
        return $condition;
    }

    private function parseOr(int $n): int
    {
        $left = $this->parseAnd($n);

        while ($this->accept('||')) {
            $right = $this->parseAnd($n);
            $left = ($left !== 0 || $right !== 0) ? 1 : 0;
        }

        return $left;
    }

    private function parseAnd(int $n): int
    {
        $left = $this->parseEquality($n);

        while ($this->accept('&&')) {
            $right = $this->parseEquality($n);
            $left = ($left !== 0 && $right !== 0) ? 1 : 0;
        }

        return $left;
    }

    private function parseEquality(int $n): int
    {
        $left = $this->parseRelational($n);

        while (($token = $this->peek()) !== null && ($token[0] === '==' || $token[0] === '!=' || $token[0] === '=')) {
            ++$this->position;
            $right = $this->parseRelational($n);
            $equal = $left === $right;

            if ($token[0] === '!=') {
                $equal = !$equal;
            }

            $left = $equal ? 1 : 0;
        }

        return $left;
    }

    private function parseRelational(int $n): int
    {
        $left = $this->parseAdditive($n);

        while (($token = $this->peek()) !== null
            && \in_array($token[0], ['<', '<=', '>', '>='], true)) {
            ++$this->position;
            $right = $this->parseAdditive($n);
            $left = match ($token[0]) {
                '<' => $left < $right ? 1 : 0,
                '<=' => $left <= $right ? 1 : 0,
                '>' => $left > $right ? 1 : 0,
                '>=' => $left >= $right ? 1 : 0,
            };
        }

        return $left;
    }

    private function parseAdditive(int $n): int
    {
        $left = $this->parseMultiplicative($n);

        while (($token = $this->peek()) !== null && ($token[0] === '+' || $token[0] === '-')) {
            ++$this->position;
            $right = $this->parseMultiplicative($n);
            $left = $token[0] === '+' ? $left + $right : $left - $right;
        }

        return $left;
    }

    private function parseMultiplicative(int $n): int
    {
        $left = $this->parseUnary($n);

        while (($token = $this->peek()) !== null
            && \in_array($token[0], ['*', '/', '%'], true)) {
            ++$this->position;
            $right = $this->parseUnary($n);

            if (($token[0] === '/' || $token[0] === '%') && $right === 0) {
                return 0;
            }

            $left = match ($token[0]) {
                '*' => $left * $right,
                '/' => intdiv($left, $right),
                '%' => $left % $right,
            };
        }

        return $left;
    }

    private function parseUnary(int $n): int
    {
        if ($this->accept('!')) {
            return $this->parseUnary($n) === 0 ? 1 : 0;
        }

        if ($this->accept('-')) {
            return -$this->parseUnary($n);
        }

        return $this->parsePrimary($n);
    }

    private function parsePrimary(int $n): int
    {
        $token = $this->peek();

        if ($token === null) {
            throw new \RuntimeException('unexpected end of plural expression');
        }

        ++$this->position;

        return match ($token[0]) {
            'int' => (int) $token[1],
            'n' => $n,
            '(' => $this->parseGrouped($n),
            default => throw new \RuntimeException('unexpected token "' . $token[1] . '"'),
        };
    }

    private function parseGrouped(int $n): int
    {
        $value = $this->parseTernary($n);

        if (!$this->accept(')')) {
            throw new \RuntimeException('missing closing parenthesis');
        }

        return $value;
    }
}

/**
 * The library's own translator: gettext-compatible catalogues, plural
 * forms, contexts, domains, fallback chains and optional WordPress
 * delegation — as an *instance* wired through the container (v3 kept all
 * of this in statics + `$GLOBALS`).
 *
 * Resolution order for every lookup:
 *  1. WordPress delegation (when enabled and the functions exist);
 *  2. own catalogues along the locale fallback chain;
 *  3. source-language fallback (`count === 1 ? singular : plural`);
 * then `{name}`/sprintf interpolation, then the `htmlphp.translate` filter.
 */
final class Translator implements TranslatorInterface
{
    /** @var array<string, array<string, Catalog>> domain => locale => catalogue */
    private array $catalogs = [];

    /** @var array<string, true> "locale|path|domain" load guard */
    private array $loaded = [];

    private string $locale;

    /** @var array<string, true> locales whose configured paths were scanned */
    private array $booted = [];

    public function __construct(
        private readonly I18nConfig $config,
        private readonly Diagnostics $diagnostics,
        private readonly Dispatcher $events,
        private readonly ?string $acceptLanguage = null,
    ) {
        $this->locale = $this->detectLocale();
    }

    private function detectLocale(): string
    {
        $locale = Locale::normalize($this->config->locale);

        if ($this->config->detect && ($locale === '' || $locale === Locale::DEFAULT_LOCALE)) {
            $negotiated = Locale::negotiate($this->availableLocales(), $this->acceptLanguage, Locale::DEFAULT_LOCALE);

            if ($negotiated !== '') {
                $locale = $negotiated;
            }
        }

        return $locale !== '' ? $locale : Locale::DEFAULT_LOCALE;
    }

    // ------------------------------------------------------------- catalogues

    /**
     * Loads a catalogue file (or a directory searched for
     * `{domain}-{locale}.mo|po|json|php`, `{locale}.mo|po|json|php`,
     * `{locale}/LC_MESSAGES/{domain}.mo|po`) into the given domain.
     */
    public function load(string $locale, string $path, string $domain = 'messages'): bool
    {
        $locale = Locale::normalize($locale);

        foreach (self::catalogueCandidates($locale, $path, $domain) as $candidate) {
            $key = $locale . '|' . $candidate . '|' . $domain;

            if (isset($this->loaded[$key])) {
                return true;
            }

            if (!is_file($candidate)) {
                continue;
            }

            $catalog = Catalog::load($candidate, $locale, $domain, $this->diagnostics);

            if ($catalog !== null) {
                $existing = $this->catalogs[$domain][$locale] ?? null;

                if ($existing !== null) {
                    $existing->mergeFrom($catalog);
                } else {
                    $this->catalogs[$domain][$locale] = $catalog;
                }

                $this->loaded[$key] = true;

                return true;
            }
        }

        return false;
    }

    /**
     * Registers an in-memory catalogue (database-backed translations,
     * tests, WordPress bridges that prefer their own storage).
     */
    public function register(string $locale, string $domain, Catalog $catalog): void
    {
        $locale = Locale::normalize($locale);
        $existing = $this->catalogs[$domain][$locale] ?? null;

        if ($existing !== null) {
            $existing->mergeFrom($catalog, true); // explicit registration wins

            return;
        }

        $this->catalogs[$domain][$locale] = $catalog;
    }

    /**
     * Loads every configured `i18n.paths` directory for a locale.
     *
     * @return list<string> loaded file paths
     */
    public function loadConfigured(string $locale, string $domain = 'messages'): array
    {
        $loaded = [];

        foreach ($this->config->paths as $path) {
            foreach (self::catalogueCandidates(Locale::normalize($locale), (string) $path, $domain) as $candidate) {
                if (is_file($candidate) && $this->load($locale, $candidate, $domain)) {
                    $loaded[] = $candidate;
                    break;
                }
            }
        }

        return $loaded;
    }

    /**
     * @return list<string>
     */
    public static function catalogueCandidates(string $locale, string $path, string $domain): array
    {
        if ($path !== '' && is_file($path)) {
            return [$path];
        }

        if ($path === '' || !is_dir($path)) {
            return [];
        }

        $root = rtrim($path, "/\\");
        $candidates = [];

        foreach (['mo', 'po', 'json', 'php'] as $extension) {
            $candidates[] = $root . DIRECTORY_SEPARATOR . $domain . '-' . $locale . '.' . $extension;
            $candidates[] = $root . DIRECTORY_SEPARATOR . $locale . '.' . $extension;
        }

        foreach (['mo', 'po'] as $extension) {
            $candidates[] = $root . DIRECTORY_SEPARATOR . $locale . DIRECTORY_SEPARATOR
                . 'LC_MESSAGES' . DIRECTORY_SEPARATOR . $domain . '.' . $extension;
        }

        return $candidates;
    }

    public function hasCatalogue(string $locale, string $domain = 'messages'): bool
    {
        $this->ensureLoaded($locale);

        return isset($this->catalogs[$domain][Locale::normalize($locale)]);
    }

    public function catalogue(string $locale, string $domain = 'messages'): ?Catalog
    {
        $this->ensureLoaded($locale);

        return $this->catalogs[$domain][Locale::normalize($locale)] ?? null;
    }

    /**
     * Scans the configured `i18n.paths` once per locale (lazy — a process
     * that never translates pays no I/O).
     */
    private function ensureLoaded(?string $locale = null): void
    {
        if ($this->config->paths === []) {
            return;
        }

        $locales = $locale !== null
            ? [Locale::normalize($locale)]
            : [$this->locale, ...array_map(Locale::normalize(...), $this->config->fallback)];

        foreach ($locales as $candidate) {
            if ($candidate === '' || isset($this->booted[$candidate])) {
                continue;
            }

            $this->booted[$candidate] = true;
            $this->loadConfigured($candidate, $this->config->domain);
        }
    }

    /**
     * Diagnostics: loaded catalogues and their message counts.
     *
     * @return array<string, array<string, int>>
     */
    public function stats(): array
    {
        $stats = [];

        foreach ($this->catalogs as $domain => $locales) {
            foreach ($locales as $locale => $catalog) {
                $stats[$domain][$locale] = $catalog->count();
            }
        }

        return $stats;
    }

    /** Drops every loaded catalogue (tests, long-running workers). */
    public function reset(): void
    {
        $this->catalogs = [];
        $this->loaded = [];
    }

    // ---------------------------------------------------------------- locale

    public function locale(): string
    {
        return $this->locale;
    }

    public function setLocale(string $locale): void
    {
        $normalized = Locale::normalize($locale);
        $this->locale = $normalized !== '' ? $normalized : Locale::DEFAULT_LOCALE;
    }

    /**
     * Every locale that has at least one loaded catalogue.
     *
     * @return list<string>
     */
    public function availableLocales(): array
    {
        $this->ensureLoaded();
        $locales = [];

        foreach ($this->catalogs as $byLocale) {
            foreach (array_keys($byLocale) as $locale) {
                $locales[$locale] = true;
            }
        }

        return array_keys($locales);
    }

    /**
     * Negotiates the best locale from an Accept-Language header against the
     * loaded catalogues (public helper — the engine never reads `$_SERVER`).
     */
    public function negotiate(?string $acceptLanguage = null): string
    {
        return Locale::negotiate(
            $this->availableLocales(),
            $acceptLanguage ?? $this->acceptLanguage,
            $this->locale,
        );
    }

    /**
     * Current locale followed by the configured fallback chain.
     *
     * @return list<string>
     */
    public function fallbackChain(): array
    {
        $chain = [$this->locale()];

        foreach ($this->config->fallback as $locale) {
            $normalized = Locale::normalize(Str::stringify($locale));

            if ($normalized !== '' && !\in_array($normalized, $chain, true)) {
                $chain[] = $normalized;
            }
        }

        return $chain;
    }

    // ------------------------------------------------------------ translation

    /** @param array<array-key, mixed> $args */
    public function t(string $msgid, array $args = [], ?string $domain = null): string
    {
        return $this->translate($msgid, null, 0, '', $args, $domain);
    }

    /** @param array<array-key, mixed> $args */
    public function n(string $singular, string $plural, int $count, array $args = [], ?string $domain = null): string
    {
        return $this->translate($singular, $plural, $count, '', $args, $domain);
    }

    /** @param array<array-key, mixed> $args */
    public function x(string $msgid, string $context, array $args = [], ?string $domain = null): string
    {
        return $this->translate($msgid, null, 0, $context, $args, $domain);
    }

    /** @param array<array-key, mixed> $args */
    public function nx(
        string $singular,
        string $plural,
        int $count,
        string $context,
        array $args = [],
        ?string $domain = null,
    ): string {
        return $this->translate($singular, $plural, $count, $context, $args, $domain);
    }

    /**
     * @param string|null $plural plural source form (null = singular message)
     * @param array<array-key, mixed> $args
     */
    private function translate(
        string $msgid,
        ?string $plural,
        int $count,
        string $context,
        array $args,
        ?string $domain,
    ): string {
        $domain = $domain ?? $this->config->domain;

        if ($domain === '') {
            $domain = 'messages';
        }

        $this->ensureLoaded();

        $result = null;

        // 1. WordPress delegation.
        if ($this->wordpressMode()) {
            $result = $this->viaWordpress($msgid, $plural, $count, $context, $domain);
        }

        // 2. Own catalogues along the fallback chain.
        if ($result === null) {
            foreach ($this->fallbackChain() as $locale) {
                $catalog = $this->catalogs[$domain][$locale] ?? null;

                if ($catalog === null) {
                    continue;
                }

                if ($plural === null) {
                    $result = $catalog->get($msgid, $context);
                } else {
                    $index = $catalog->pluralForms()->select($count);
                    $result = $catalog->getPlural($msgid, $index, $context);
                    $result ??= $catalog->getPlural($plural, $index, $context);
                    $result ??= $catalog->get($msgid, $context);
                }

                if ($result !== null) {
                    break;
                }
            }
        }

        // 3. Source fallback.
        if ($result === null) {
            $result = $plural !== null ? ($count === 1 ? $msgid : $plural) : $msgid;

            $this->events->dispatch('htmlphp.translate.miss', $msgid, $domain, $this->locale());
        }

        $result = self::interpolate($result, $args);

        return Str::stringify($this->events->filter(
            'htmlphp.translate',
            $result,
            $msgid,
            $domain,
            $this->locale(),
        ));
    }

    /**
     * True when WordPress i18n functions should be consulted first.
     *
     * `i18n.use_wordpress`: `null` (default) = auto-detect WordPress,
     * `true` = force, `false` = never.
     */
    public function wordpressMode(): bool
    {
        $mode = $this->config->useWordPress;

        if (\is_bool($mode)) {
            return $mode;
        }

        return \defined('ABSPATH') && \function_exists('__') && \function_exists('determine_locale');
    }

    private function viaWordpress(
        string $msgid,
        ?string $plural,
        int $count,
        string $context,
        string $domain,
    ): ?string {
        $result = null;

        try {
            if ($plural !== null && \function_exists('_nx') && \function_exists('_n')) {
                $result = $context !== ''
                    ? _nx($msgid, $plural, $count, $context, $domain)
                    : _n($msgid, $plural, $count, $domain);
            } elseif ($context !== '' && \function_exists('_x')) {
                $result = _x($msgid, $context, $domain);
            } elseif (\function_exists('__')) {
                $result = __($msgid, $domain);
            }
        } catch (\Throwable) {
            return null;
        }

        if (!\is_string($result) || $result === '') {
            return null;
        }

        // A miss is signalled by gettext returning the source string.
        $source = $plural !== null ? ($count === 1 ? $msgid : $plural) : $msgid;

        return $result === $source ? null : $result;
    }

    /**
     * Applies named (`{key}`) and sprintf-style (`%1$s`) interpolation.
     *
     * @param array<array-key, mixed> $args
     */
    public static function interpolate(string $text, array $args): string
    {
        if ($args === []) {
            return $text;
        }

        $named = [];

        foreach ($args as $key => $value) {
            $named['{' . $key . '}'] = Str::stringify($value);
        }

        $text = strtr($text, $named);

        if (array_is_list($args) && str_contains($text, '%')) {
            try {
                return vsprintf($text, $args);
            } catch (\ValueError) {
                return $text;
            }
        }

        return $text;
    }
}

/**
 * Builds the default translator from the container.
 *
 * Hosts that want a fully custom implementation register it themselves:
 * `$container->instance(TranslatorInterface::class, $myTranslator);`
 */
final class TranslatorFactory
{
    private function __construct() {}

    public static function create(Container $container): TranslatorInterface
    {
        /** @var Config $config */
        $config = $container->get(Config::class);

        return new Translator(
            $config->i18n,
            $container->service(Diagnostics::class),
            $container->service(Dispatcher::class),
        );
    }
}

/**
 * Translation contract.
 *
 * The engine depends only on this interface: swap in
 * {@see Translator} (own catalogues), a WordPress-delegating
 * implementation, or your own (database-backed, API-backed, …) through
 * the container.
 */
interface TranslatorInterface
{
    /**
     * Translates a message id with optional `{name}`/sprintf interpolation.
     *
     * @param array<array-key, mixed> $args
     */
    public function t(string $msgid, array $args = [], ?string $domain = null): string;

    /**
     * Plural-aware translation.
     *
     * @param array<array-key, mixed> $args
     */
    public function n(string $singular, string $plural, int $count, array $args = [], ?string $domain = null): string;

    /**
     * Translation with a message context (`msgctxt`).
     *
     * @param array<array-key, mixed> $args
     */
    public function x(string $msgid, string $context, array $args = [], ?string $domain = null): string;

    /**
     * Plural + context translation.
     *
     * @param array<array-key, mixed> $args
     */
    public function nx(
        string $singular,
        string $plural,
        int $count,
        string $context,
        array $args = [],
        ?string $domain = null,
    ): string;

    /** Active locale, normalised (`ll` or `ll_CC`). */
    public function locale(): string;

    public function setLocale(string $locale): void;
}

}

namespace HtmlPhp\Template {

use HtmlPhp\Config;
use HtmlPhp\Config\ExecMode;
use HtmlPhp\Config\Limits;
use HtmlPhp\Config\MissingVarPolicy;
use HtmlPhp\Config\Security as SecurityConfig;
use HtmlPhp\Config\Syntax as SyntaxConfig;
use HtmlPhp\Config\Templates as TemplatesConfig;
use HtmlPhp\Contracts\CacheInterface;
use HtmlPhp\Diagnostics;
use HtmlPhp\Event\Dispatcher;
use HtmlPhp\Exception\TemplateException;
use HtmlPhp\Exception\TemplateNotFoundException;
use HtmlPhp\Exception\TemplateSyntaxException;
use HtmlPhp\Html\Escaper;
use HtmlPhp\I18n\Extractor;
use HtmlPhp\I18n\Formats;
use HtmlPhp\I18n\Translator;
use HtmlPhp\I18n\TranslatorInterface;
use HtmlPhp\Io\Files;
use HtmlPhp\Io\PathGuard;
use HtmlPhp\RequestContext;
use HtmlPhp\Scope;
use HtmlPhp\Ssi\Attributes;
use HtmlPhp\Ssi\DocumentInfo;
use HtmlPhp\Ssi\Processor;
use HtmlPhp\Support\Pcre;
use HtmlPhp\Support\Str;
use HtmlPhp\Version;

/**
 * Safe expression language for `<!--@If-->`, `<!--@Elif-->`, `<!--@Set-->`,
 * loop ranges, `<!--@Trans count-->` and (since v5) inline `%{= …}`
 * substitutions.
 *
 * A hand-written tokenizer + precedence-climbing parser evaluates against
 * the render {@see Scope}. There is **no** `eval()`, no dynamic function
 * calls and no property writes: only literals, dotted names, index access,
 * arithmetic, comparisons, logical operators, ternary/coalesce, `in`,
 * `matches`, string concatenation (`~`) and a whitelist of pure functions.
 *
 * Grammar (loosest first):
 *   expr      := ternary
 *   ternary   := coalesce ('?' expr ':' expr)?
 *   coalesce  := or ('??' or)*
 *   or        := and ('||' and)*            (alias: `or`)
 *   and       := not ('&&' not)*            (alias: `and`)
 *   not       := ('!'|'not') not | compare
 *   compare   := additive (('=='|'!='|'==='|'!=='|'<'|'<='|'>'|'>='|'in'|'matches') additive)*
 *   additive  := concat (('+'|'-') concat)*
 *   concat    := multiplicative ('~' multiplicative)*
 *   multiplicative := unary (('*'|'/'|'%') unary)*
 *   unary     := ('-'|'+') unary | postfix
 *   postfix   := primary ('[' expr ']' | '.' name)*   (v5: index/property chains)
 *   primary   := literal | name ('.' name)* | call | '(' expr ')' | range
 *
 * Security budget (v5): parse trees are memoized behind a hard FIFO cap,
 * every walk of host-supplied iterables is capped at
 * {@see Str::MAX_AGGREGATE_ITEMS}, dynamic keys pass
 * {@see Scope::index()} and indirect names pass {@see Scope::find()} only
 * after {@see Str::isValidVariableName()} — an expression can compute with
 * data but can never touch the filesystem, the network, a class name or a
 * callable.
 */
final class Expression
{
    /** Whitelisted pure functions callable from expressions. */
    public const array FUNCTIONS = [
        'count', 'length', 'empty', 'defined', 'min', 'max', 'abs',
        'round', 'floor', 'ceil', 'int', 'float', 'str', 'lower',
        'upper', 'number', 'default',
        // v5 — math & indirect access:
        'pow', 'sqrt', 'sum', 'avg', 'clamp', 'get',
    ];

    private const int MAX_DEPTH = 32;

    /** FIFO cap on the memoized-AST registry (unbounded memos are a DoS vector). */
    private const int MAX_AST_CACHE = 4096;

    /** Ceiling for a dynamic (`get()`) path — a lookup key is data, not a document. */
    private const int MAX_PATH_LENGTH = 256;

    /** @var list<array{0: string, 1: mixed}> */
    private array $tokens = [];

    private int $position = 0;
    private int $depth = 0;

    /** @var array<string, array<array-key, mixed>> memoized ASTs keyed by source */
    private static array $asts = [];

    private function __construct() {}

    /**
     * Evaluates `$source` against `$scope`.
     *
     * Parse results are memoized per expression string, so the same
     * condition inside a 10 000-row loop is parsed once. The memo is a
     * bounded FIFO: a template full of unique expressions can evict old
     * parses but can never grow the registry without limit.
     *
     * @throws TemplateSyntaxException on malformed expressions (strict
     *         language design: a broken condition is a template bug)
     */
    public static function evaluate(string $source, Scope $scope, int $maxLength = 4096): mixed
    {
        return self::reduceNode(self::ast($source, $maxLength), $scope);
    }

    /** @return array<array-key, mixed> */
    private static function ast(string $source, int $maxLength): array
    {
        $key = $maxLength . '|' . $source;

        if (isset(self::$asts[$key])) {
            return self::$asts[$key];
        }

        $expression = new self();
        $expression->tokens = $expression->tokenize(self::guardLength($source, $maxLength));
        $expression->position = 0;
        $tree = $expression->parseExpression();
        $expression->expectEnd($source);

        if (\count(self::$asts) >= self::MAX_AST_CACHE) {
            $oldest = array_key_first(self::$asts);

            if ($oldest !== null) {
                unset(self::$asts[$oldest]);
            }
        }

        return self::$asts[$key] = $tree;
    }

    /** Truthiness used by `<!--@If-->`: PHP rules, `'0'`/`''`/`[]`/null are false. */
    public static function truthy(mixed $value): bool
    {
        if (\is_string($value)) {
            return $value !== '' && $value !== '0';
        }

        if (\is_array($value)) {
            return $value !== [];
        }

        return (bool) $value;
    }

    /** Validates syntax without evaluating (used by the linter). */
    public static function validate(string $source, int $maxLength = 4096): void
    {
        self::ast($source, $maxLength);
    }

    /** Drops memoized parse trees (long-running workers after deploys). */
    public static function reset(): void
    {
        self::$asts = [];
    }

    private static function guardLength(string $source, int $maxLength): string
    {
        $source = trim($source);

        if ($source === '') {
            throw new TemplateSyntaxException('Empty expression.');
        }

        if (\strlen($source) > $maxLength) {
            throw new TemplateSyntaxException(
                'Expression is too long.',
                ['length' => \strlen($source), 'limit' => $maxLength],
            );
        }

        return $source;
    }

    // ------------------------------------------------------------------ lexer

    /**
     * @return list<array{0: string, 1: mixed}>
     */
    private function tokenize(string $source): array
    {
        $tokens = [];
        $length = \strlen($source);
        $index = 0;

        while ($index < $length) {
            $char = $source[$index];

            if (ctype_space($char)) {
                ++$index;
                continue;
            }

            if ($char === '"' || $char === "'") {
                [$value, $index] = $this->readString($source, $index);
                $tokens[] = ['str', $value];
                continue;
            }

            if (ctype_digit($char) || ($char === '.' && ctype_digit($source[$index + 1] ?? ''))) {
                preg_match('~\d+(?:\.\d+)?(?:[eE][+-]?\d+)?|\.\d+~A', $source, $m, 0, $index);
                $tokens[] = ['num', str_contains($m[0], '.') || str_contains($m[0], 'e') || str_contains($m[0], 'E')
                    ? (float) $m[0]
                    : (int) $m[0]];
                $index += \strlen($m[0]);
                continue;
            }

            if ($char === '.' && ($source[$index + 1] ?? '') === '.') {
                $tokens[] = ['op', '..'];
                $index += 2;
                continue;
            }

            // `.name` only tokenizes standalone directly after a postfix
            // (`rows[0].name`); everywhere else a dot is part of a dotted
            // name or a numeric literal, both handled above.
            if ($char === '.' && (ctype_alpha($source[$index + 1] ?? '') || ($source[$index + 1] ?? '') === '_')) {
                $tokens[] = ['op', '.'];
                ++$index;
                continue;
            }

            if (ctype_alpha($char) || $char === '_') {
                preg_match('~[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)*~A', $source, $m, 0, $index);
                $word = $m[0];
                $index += \strlen($word);
                $lower = strtolower($word);
                $tokens[] = match ($lower) {
                    'true' => ['bool', true],
                    'false' => ['bool', false],
                    'null' => ['null', null],
                    'and' => ['op', '&&'],
                    'or' => ['op', '||'],
                    'not' => ['op', '!'],
                    'in' => ['op', 'in'],
                    'matches' => ['op', 'matches'],
                    default => ['name', $word],
                };
                continue;
            }

            foreach (['===', '!==', '==', '!=', '<=', '>=', '&&', '||', '??', '<', '>', '!',
                '+', '-', '*', '/', '%', '~', '(', ')', '[', ']', ',', '?', ':'] as $candidate) {
                if (str_starts_with(substr($source, $index), $candidate)) {
                    $tokens[] = ['op', $candidate];
                    $index += \strlen($candidate);
                    continue 2;
                }
            }

            throw new TemplateSyntaxException(
                'Unexpected character "' . $char . '" in expression.',
                ['position' => $index],
            );
        }

        return $tokens;
    }

    /** @return array{0: string, 1: int} */
    private function readString(string $source, int $index): array
    {
        $quote = $source[$index];
        $length = \strlen($source);
        $value = '';
        ++$index;

        while ($index < $length) {
            $char = $source[$index];

            if ($char === '\\' && $index + 1 < $length) {
                $next = $source[$index + 1];
                $value .= match ($next) {
                    'n' => "\n",
                    't' => "\t",
                    'r' => "\r",
                    default => $next,
                };
                $index += 2;
                continue;
            }

            if ($char === $quote) {
                return [$value, $index + 1];
            }

            $value .= $char;
            ++$index;
        }

        throw new TemplateSyntaxException('Unterminated string literal in expression.');
    }

    // ----------------------------------------------------------------- parser
    // The parser emits nested arrays instead of evaluating directly, so one
    // tokenize+parse can be reused (memoized) across loop iterations.

    /** @return array<array-key, mixed> */
    private function parseExpression(): array
    {
        if (++$this->depth > self::MAX_DEPTH) {
            throw new TemplateSyntaxException('Expression nesting is too deep.');
        }

        try {
            return $this->parseTernary();
        } finally {
            $this->depth--;
        }
    }

    /** @return array<array-key, mixed> */
    private function parseTernary(): array
    {
        $node = $this->parseCoalesce();

        if ($this->isOp('?')) {
            $this->next();
            $then = $this->parseExpression();
            $this->expectOp(':');
            $else = $this->parseExpression();

            return ['ternary', $node, $then, $else];
        }

        return $node;
    }

    /** @return array<array-key, mixed> */
    private function parseCoalesce(): array
    {
        $node = $this->parseBinary(['||'], 'parseAnd');

        while ($this->isOp('??')) {
            $this->next();
            $node = ['coalesce', $node, $this->parseAnd()];
        }

        return $node;
    }

    /** @return array<array-key, mixed> */
    private function parseAnd(): array
    {
        return $this->parseBinary(['&&'], 'parseNot');
    }

    /** @return array<array-key, mixed> */
    private function parseNot(): array
    {
        if ($this->isOp('!')) {
            $this->next();

            return ['not', $this->parseNot()];
        }

        return $this->parseComparison();
    }

    /** @return array<array-key, mixed> */
    private function parseComparison(): array
    {
        $operators = ['==', '!=', '===', '!==', '<', '<=', '>', '>=', 'in', 'matches'];
        $left = $this->parseAdditive();

        while (($token = $this->peek()) !== null && $token[0] === 'op' && \in_array($token[1], $operators, true)) {
            $operator = $token[1];
            $this->next();

            if ($operator === 'matches') {
                $pattern = $this->parseAdditive();

                if ($pattern[0] !== 'lit' || !\is_string($pattern[1])) {
                    throw new TemplateSyntaxException('The right side of "matches" must be a string literal.');
                }

                $left = ['matches', $left, $pattern[1]];
                continue;
            }

            $left = [$operator, $left, $this->parseAdditive()];
        }

        return $left;
    }

    /** @return array<array-key, mixed> */
    private function parseAdditive(): array
    {
        return $this->parseBinary(['+', '-'], 'parseConcat');
    }

    /** @return array<array-key, mixed> */
    private function parseConcat(): array
    {
        return $this->parseBinary(['~'], 'parseMultiplicative');
    }

    /** @return array<array-key, mixed> */
    private function parseMultiplicative(): array
    {
        return $this->parseBinary(['*', '/', '%'], 'parseUnary');
    }

    /**
     * @param list<string> $operators
     * @return array<array-key, mixed>
     */
    private function parseBinary(array $operators, string $next): array
    {
        $left = $this->{$next}();

        while (($token = $this->peek()) !== null && $token[0] === 'op' && \in_array($token[1], $operators, true)) {
            $operator = $token[1];
            $this->next();
            $left = [$operator, $left, $this->{$next}()];
        }

        return $left;
    }

    /** @return array<array-key, mixed> */
    private function parseUnary(): array
    {
        if ($this->isOp('-') || $this->isOp('+')) {
            $operator = $this->next()[1];

            return [$operator === '-' ? 'neg' : 'pos', $this->parseUnary()];
        }

        return $this->parsePostfix();
    }

    /**
     * postfix := primary ('[' expr ']' | '.' name)*
     *
     * Index and property chains (`rows[0].name`, `hash[keyVar].total`) hang
     * off any primary — names, calls and parenthesised expressions alike.
     * Every `[` opens a nested {@see self::parseExpression()}, so the
     * existing depth guard bounds arbitrarily chained access.
     *
     * @return array<array-key, mixed>
     */
    private function parsePostfix(): array
    {
        $node = $this->parsePrimary();

        while (true) {
            if ($this->isOp('[')) {
                $this->next();
                $index = $this->parseExpression();
                $this->expectOp(']');
                $node = ['index', $node, $index];
                continue;
            }

            if ($this->isOp('.')) {
                $this->next();
                $token = $this->peek();

                if ($token === null || $token[0] !== 'name') {
                    throw new TemplateSyntaxException('Expected a property name after ".".');
                }

                $this->next();
                $node = ['prop', $node, (string) $token[1]];
                continue;
            }

            break;
        }

        return $node;
    }

    /** @return array<array-key, mixed> */
    private function parsePrimary(): array
    {
        $token = $this->peek();

        if ($token === null) {
            throw new TemplateSyntaxException('Unexpected end of expression.');
        }

        if ($token[0] === 'num' || $token[0] === 'str' || $token[0] === 'bool' || $token[0] === 'null') {
            $this->next();
            $node = ['lit', $token[1]];

            // Numeric range literal: `1..10` (integer ranges, loop semantics).
            if ($token[0] === 'num' && $this->isOp('..')) {
                $this->next();

                return ['range', $node, $this->parseUnary()];
            }

            return $node;
        }

        if ($token[0] === 'op' && $token[1] === '(') {
            $this->next();
            $node = $this->parseExpression();

            // Range: (a..b) or a..b handled at name level too.
            if ($this->isOp('..')) {
                $this->next();
                $to = $this->parseExpression();
                $this->expectOp(')');

                return ['range', $node, $to];
            }

            $this->expectOp(')');

            return $node;
        }

        if ($token[0] === 'name') {
            $this->next();
            $name = (string) $token[1];

            // function call
            if ($this->isOp('(')) {
                $this->next();
                $args = [];

                if (!$this->isOp(')')) {
                    $args[] = $this->parseExpression();

                    while ($this->isOp(',')) {
                        $this->next();
                        $args[] = $this->parseExpression();
                    }
                }

                $this->expectOp(')');

                return ['call', strtolower($name), $args];
            }

            // range over names/numbers: 1..10, first..last
            if ($this->isOp('..')) {
                $this->next();
                $to = $this->parseUnary();

                return ['range', ['name', $name], $to];
            }

            return ['name', $name];
        }

        throw new TemplateSyntaxException('Unexpected token in expression.', ['token' => (string) $token[1]]);
    }

    /** @return array{0: string, 1: mixed}|null */
    private function peek(): ?array
    {
        return $this->tokens[$this->position] ?? null;
    }

    /** @return array{0: string, 1: mixed} */
    private function next(): array
    {
        $token = $this->peek();

        if ($token === null) {
            throw new TemplateSyntaxException('Unexpected end of expression.');
        }

        ++$this->position;

        return $token;
    }

    private function isOp(string $op): bool
    {
        $token = $this->peek();

        return $token !== null && $token[0] === 'op' && $token[1] === $op;
    }

    private function expectOp(string $op): void
    {
        if (!$this->isOp($op)) {
            throw new TemplateSyntaxException('Expected "' . $op . '" in expression.');
        }

        $this->next();
    }

    private function expectEnd(string $source): void
    {
        if ($this->position < \count($this->tokens)) {
            throw new TemplateSyntaxException('Trailing input in expression.', ['expression' => $source]);
        }
    }

    // -------------------------------------------------------------- evaluator

    /** @param array<array-key, mixed> $node */
    private static function reduceNode(array $node, Scope $scope): mixed
    {
        $op = (string) ($node[0] ?? '');

        return match ($op) {
            'lit' => $node[1],
            'name' => $scope->get((string) $node[1]),
            'index' => self::indexInto(self::reduceNode($node[1], $scope), self::reduceNode($node[2], $scope)),
            'prop' => self::property(self::reduceNode($node[1], $scope), (string) $node[2]),
            'neg' => -self::numeric(self::reduceNode($node[1], $scope)),
            'pos' => self::numeric(self::reduceNode($node[1], $scope)),
            'not' => !self::truthy(self::reduceNode($node[1], $scope)),
            '&&' => self::truthy(self::reduceNode($node[1], $scope)) && self::truthy(self::reduceNode($node[2], $scope)),
            '||' => self::truthy(self::reduceNode($node[1], $scope)) || self::truthy(self::reduceNode($node[2], $scope)),
            'coalesce' => self::reduceNode($node[1], $scope) ?? self::reduceNode($node[2], $scope),
            'ternary' => self::truthy(self::reduceNode($node[1], $scope))
                ? self::reduceNode($node[2], $scope)
                : self::reduceNode($node[3], $scope),
            '==' => self::loose(self::reduceNode($node[1], $scope), self::reduceNode($node[2], $scope)),
            '!=' => !self::loose(self::reduceNode($node[1], $scope), self::reduceNode($node[2], $scope)),
            '===' => self::reduceNode($node[1], $scope) === self::reduceNode($node[2], $scope),
            '!==' => self::reduceNode($node[1], $scope) !== self::reduceNode($node[2], $scope),
            '<', '<=', '>', '>=' => self::ordering($op, self::reduceNode($node[1], $scope), self::reduceNode($node[2], $scope)),
            '+' => self::numeric(self::reduceNode($node[1], $scope)) + self::numeric(self::reduceNode($node[2], $scope)),
            '-' => self::numeric(self::reduceNode($node[1], $scope)) - self::numeric(self::reduceNode($node[2], $scope)),
            '*' => self::numeric(self::reduceNode($node[1], $scope)) * self::numeric(self::reduceNode($node[2], $scope)),
            '/' => self::divide(self::reduceNode($node[1], $scope), self::reduceNode($node[2], $scope)),
            '%' => self::modulo(self::reduceNode($node[1], $scope), self::reduceNode($node[2], $scope)),
            '~' => Str::stringify(self::reduceNode($node[1], $scope)) . Str::stringify(self::reduceNode($node[2], $scope)),
            'in' => self::in(self::reduceNode($node[1], $scope), self::reduceNode($node[2], $scope)),
            'matches' => self::matches(self::reduceNode($node[1], $scope), (string) $node[2]),
            'range' => self::range(self::reduceNode($node[1], $scope), self::reduceNode($node[2], $scope)),
            'call' => self::call((string) $node[1], $node[2], $scope),
            default => throw new TemplateSyntaxException('Unknown expression node.', ['op' => $op]),
        };
    }

    private static function loose(mixed $left, mixed $right): bool
    {
        if (is_numeric($left) && is_numeric($right)) {
            return Str::numericValue($left) == Str::numericValue($right);
        }

        if (\is_string($left) && \is_string($right)) {
            return $left === $right;
        }

        return $left == $right;
    }

    private static function ordering(string $op, mixed $left, mixed $right): bool
    {
        if (is_numeric($left) || is_numeric($right)) {
            $a = Str::numericValue($left);
            $b = Str::numericValue($right);

            return match ($op) {
                '<' => $a < $b,
                '<=' => $a <= $b,
                '>' => $a > $b,
                default => $a >= $b,
            };
        }

        $order = strcmp(Str::stringify($left), Str::stringify($right));

        return match ($op) {
            '<' => $order < 0,
            '<=' => $order <= 0,
            '>' => $order > 0,
            default => $order >= 0,
        };
    }

    private static function divide(mixed $left, mixed $right): float|int
    {
        $divisor = Str::numericValue($right);

        if ($divisor === 0.0) {
            return 0;
        }

        $result = Str::numericValue($left) / $divisor;

        return is_finite($result) ? $result : 0;
    }

    private static function modulo(mixed $left, mixed $right): int
    {
        $divisor = (int) Str::numericValue($right);

        return $divisor === 0 ? 0 : (int) Str::numericValue($left) % $divisor;
    }

    private static function in(mixed $needle, mixed $haystack): bool
    {
        if (\is_array($haystack)) {
            return \in_array($needle, $haystack, false);
        }

        if (\is_string($haystack) && (\is_string($needle) || is_numeric($needle))) {
            return $haystack !== '' && str_contains($haystack, Str::stringify($needle));
        }

        if ($haystack instanceof \Traversable) {
            $seen = 0;

            foreach ($haystack as $item) {
                if (++$seen > Str::MAX_AGGREGATE_ITEMS) {
                    break; // iteration budget: an infinite generator must not hang the render
                }

                if ($item == $needle) {
                    return true;
                }
            }
        }

        return false;
    }

    private static function matches(mixed $subject, string $pattern): bool
    {
        $delimited = $pattern;

        // The probe must distinguish "invalid pattern" (false) from "valid
        // pattern that does not match the empty string" (0) — hence the raw
        // call here; the real match then goes through the Pcre guard so a
        // backtrack-limit hit (ReDoS-shaped pattern) is a clean no-match.
        if ($pattern === '' || @preg_match($pattern, '') === false) {
            $delimited = '~' . str_replace('~', '\\~', $pattern) . '~';
        }

        return Pcre::match($delimited, Str::stringify($subject));
    }

    /**
     * `value[key]` — the nested-variable primitive.
     *
     * Keys and container kinds are validated in {@see Scope::index()}:
     * int/string keys only, arrays / `ArrayAccess` / string offsets only,
     * capped key length, no dynamic property or method access on objects.
     * A miss is `null`, never a warning or a fatal.
     */
    private static function indexInto(mixed $value, mixed $key): mixed
    {
        [$found, $result] = Scope::index($value, $key);

        return $found ? $result : null;
    }

    /**
     * `value.name` after a postfix (`rows[0].name`) — the same walk the
     * dotted-name resolver uses, applied to an intermediate value.
     */
    private static function property(mixed $value, string $path): mixed
    {
        [$found, $result] = Scope::step($value, $path);

        return $found ? $result : null;
    }

    /** @return list<int> */
    private static function range(mixed $from, mixed $to): array
    {
        $start = (int) Str::numericValue($from);
        $end = (int) Str::numericValue($to);
        $span = abs($end - $start);

        if ($span > 100_000) {
            throw new TemplateSyntaxException('Loop range is too large.', ['span' => $span]);
        }

        return range($start, $end);
    }

    /** @param list<array<array-key, mixed>> $args */
    private static function call(string $name, array $args, Scope $scope): mixed
    {
        if (!\in_array($name, self::FUNCTIONS, true)) {
            throw new TemplateSyntaxException(
                'Function "' . $name . '" is not allowed in expressions.',
                ['allowed' => self::FUNCTIONS],
            );
        }

        $values = array_map(static fn(array $node): mixed => self::reduceNode($node, $scope), $args);

        return match ($name) {
            'count', 'length' => self::countOf($values[0] ?? null),
            'empty' => !self::truthy($values[0] ?? null),
            'defined' => \is_string($values[0] ?? null) ? $scope->has((string) $values[0]) : ($values[0] ?? null) !== null,
            'min' => $values === [] ? 0 : min(array_map(Str::numericValue(...), $values)),
            'max' => $values === [] ? 0 : max(array_map(Str::numericValue(...), $values)),
            'abs' => abs(Str::numericValue($values[0] ?? 0)),
            'round' => Str::numericValue(round(Str::numericValue($values[0] ?? 0), (int) Str::numericValue($values[1] ?? 0))),
            'floor' => (float) floor(Str::numericValue($values[0] ?? 0)),
            'ceil' => (float) ceil(Str::numericValue($values[0] ?? 0)),
            'int' => (int) Str::numericValue($values[0] ?? 0),
            'float' => Str::numericValue($values[0] ?? 0),
            'str' => Str::stringify($values[0] ?? ''),
            'lower' => Str::lower(Str::stringify($values[0] ?? '')),
            'upper' => Str::upper(Str::stringify($values[0] ?? '')),
            'number' => Str::number(Str::numericValue($values[0] ?? 0), (int) ($values[1] ?? 2)),
            'default' => ($values[0] ?? null) ?? ($values[1] ?? ''),
            // v5 additions — all pure, all budget-guarded:
            'pow' => Str::power(Str::numericValue($values[0] ?? 0), Str::numericValue($values[1] ?? 0)),
            'sqrt' => Str::sqrt(Str::numericValue($values[0] ?? 0)),
            'sum' => Str::accumulate($values[0] ?? null)[0],
            'avg' => self::average($values[0] ?? null),
            'clamp' => self::clamp(
                Str::numericValue($values[0] ?? 0),
                Str::numericValue($values[1] ?? 0),
                Str::numericValue($values[2] ?? 0),
            ),
            'get' => self::indirect($values, $scope),
        };
    }

    /**
     * `get(name)` / `get(name, default)` — indirect access: resolves a
     * variable whose *name* is itself template data ("a variable inside a
     * variable").
     *
     * Accepted path grammar (parsed by {@see self::parsePath()}, never
     * evaluated): a dotted head name plus literal `[…]` segments and
     * `.name` continuations — `user.email`, `rows[1].name`, `hash['x-1 y']`.
     * Malformed, overlong or hostile paths (null bytes, unquoted bracket
     * keys, leading dots/digits) resolve to the default. Lookups go
     * **only** through the render scope stack — there is no global,
     * constant, environment or filesystem fallback, so data-controlled
     * names cannot escape the sandbox.
     *
     * @param list<mixed> $values
     */
    private static function indirect(array $values, Scope $scope): mixed
    {
        $name = $values[0] ?? null;
        $default = $values[1] ?? null;

        if (!\is_string($name)) {
            return $default;
        }

        $path = self::parsePath($name);

        if ($path === null) {
            return $default;
        }

        [$found, $value] = $scope->find($path['head']);

        if (!$found) {
            return $default;
        }

        foreach ($path['steps'] as $step) {
            [$found, $value] = $step[0] === 'index'
                ? Scope::index($value, $step[1])
                : Scope::step($value, $step[1]);

            if (!$found) {
                return $default;
            }
        }

        return $value;
    }

    /**
     * Validates and segments a dynamic path for {@see self::indirect()}.
     *
     * Returns `['head' => dotted-name, 'steps' => [['index', int|string] |
     * ['path', dotted-name], …]]` or `null` when anything about the path is
     * not strictly well-formed. This is a *parser*, not an evaluator: the
     * only bracket keys are integer literals or single/double-quoted string
     * literals (no null bytes, ≤ 255 chars), name runs use the same
     * character class as {@see Str::isValidVariableName()} and a name run
     * after `]` must start with `.`.
     *
     * @return array{head: string, steps: list<array{0: string, 1: int|string}>}|null
     */
    private static function parsePath(string $path): ?array
    {
        if ($path === '' || \strlen($path) > self::MAX_PATH_LENGTH || str_contains($path, "\0")) {
            return null;
        }

        /** @var list<array{0: string, 1: int|string}> $steps */
        $steps = [];
        $length = \strlen($path);

        // Head: a plain dotted name (`user.email`) resolved through Scope::find().
        if (preg_match('~\A[A-Za-z_][A-Za-z0-9_.-]*~', $path, $m) !== 1) {
            return null;
        }

        $head = $m[0];

        if (!self::isSaneDottedRun($head)) {
            return null;
        }

        $index = \strlen($head);

        while ($index < $length) {
            if ($path[$index] === '[') {
                $close = strpos($path, ']', $index);

                if ($close === false) {
                    return null;
                }

                $key = self::parseBracketKey(substr($path, $index + 1, $close - $index - 1));

                if ($key === null) {
                    return null;
                }

                $steps[] = ['index', $key];
                $index = $close + 1;
                continue;
            }

            if ($path[$index] === '.') {
                if (preg_match('~\G\.[A-Za-z0-9_][A-Za-z0-9_.-]*~', $path, $m, 0, $index) !== 1) {
                    return null;
                }

                $run = substr($m[0], 1);

                if (!self::isSaneDottedRun($run)) {
                    return null;
                }

                $steps[] = ['path', $run];
                $index += \strlen($m[0]);
                continue;
            }

            // A name run directly after `]` (no dot) — rejected: `a[0]b` is
            // ambiguous nonsense; `a[0].b` is the documented form.
            return null;
        }

        return ['head' => $head, 'steps' => $steps];
    }

    /**
     * No empty segments (`a..b`), no trailing dots (`a.`). Every segment is
     * a word run; digits may start any segment but the first — the head's
     * first character is checked by the caller's anchor regex, mirroring
     * {@see Str::isValidVariableName()}.
     */
    private static function isSaneDottedRun(string $run): bool
    {
        foreach (explode('.', $run) as $segment) {
            if ($segment === '' || preg_match('~^[A-Za-z0-9_][A-Za-z0-9_-]*$~', $segment) !== 1) {
                return false;
            }
        }

        return true;
    }

    /** Integer literal or quoted string literal; anything else is rejected. */
    private static function parseBracketKey(string $raw): int|string|null
    {
        if (preg_match('~^-?\d{1,18}$~', $raw) === 1) {
            return (int) $raw;
        }

        $quote = $raw[0] ?? '';

        if (($quote === "'" || $quote === '"')
            && \strlen($raw) >= 2
            && $raw[\strlen($raw) - 1] === $quote
            && !str_contains($raw, "\0")
        ) {
            $key = substr($raw, 1, -1);

            // No quote of the same kind inside — keeps the literal unambiguous.
            return str_contains($key, $quote) ? null : ($key === '' ? null : $key);
        }

        return null;
    }

    private static function average(mixed $value): float
    {
        [$sum, $count] = Str::accumulate($value);

        return $count === 0 ? 0.0 : $sum / $count;
    }

    private static function clamp(float $value, float $min, float $max): float
    {
        if ($min > $max) {
            [$min, $max] = [$max, $min];
        }

        return max($min, min($max, $value));
    }

    private static function countOf(mixed $value): int
    {
        return match (true) {
            \is_array($value) => \count($value),
            $value instanceof \Countable => \count($value),
            // Capped walk: an infinite host-supplied generator degrades to
            // the iteration budget instead of hanging the render.
            $value instanceof \Traversable => Str::accumulate($value)[1],
            \is_string($value) => Str::length($value),
            default => $value === null ? 0 : 1,
        };
    }

    private static function numeric(mixed $value): float|int
    {
        if (\is_int($value)) {
            return $value;
        }

        if (\is_float($value)) {
            return is_finite($value) ? $value : 0.0;
        }

        return Str::numericValue($value);
    }
}

/**
 * The filter registry behind `%{NAME|filter:arg|filter2}`.
 *
 * Instance-based in v4 (v3 kept custom filters in a static map). Filters
 * receive and return `mixed` — array/object-aware filters (`join`, `first`,
 * `length`, …) are first-class citizens; the final stringification happens
 * once, in {@see Substitution}.
 *
 * Register your own: `$engine->filters()->add('shout', fn($v) => strtoupper((string) $v) . '!');`
 */
final class Filters
{
    /** @var array<string, callable(mixed, list<string>): mixed> */
    private array $custom = [];

    public function __construct(
        private readonly Diagnostics $diagnostics,
        private readonly Dispatcher $events,
        private readonly Escaper $escaper,
        private readonly TranslatorInterface $translator,
        private readonly Formats $formats,
        private readonly bool $strict = false,
    ) {}

    /** Registers (or replaces) a filter. Names are lower-cased `[a-z0-9_]+`. */
    public function add(string $name, callable $callback): void
    {
        $name = strtolower(trim($name));

        if ($name === '' || preg_match('~^[a-z0-9_]+$~', $name) !== 1) {
            throw new \InvalidArgumentException('Filter names must match [a-z0-9_]+.');
        }

        $this->custom[$name] = $callback;
    }

    public function has(string $name): bool
    {
        $name = strtolower($name);

        return isset($this->custom[$name]) || isset(self::BUILTIN[$name]);
    }

    /**
     * Every known filter name (built-ins + custom) — used by the linter.
     *
     * @return list<string>
     */
    public function names(): array
    {
        return array_values(array_unique([...array_keys(self::BUILTIN), ...array_keys($this->custom)]));
    }

    public function remove(string $name): void
    {
        unset($this->custom[strtolower($name)]);
    }

    public function reset(): void
    {
        $this->custom = [];
    }

    /** Built-in name list (kept as a constant for cheap `has()` checks). */
    private const array BUILTIN = [
        'escape' => true, 'esc' => true, 'e' => true, 'attr' => true, 'url' => true,
        'json' => true, 'js' => true, 'css' => true, 'upper' => true, 'lower' => true,
        'ucfirst' => true, 'title' => true, 'words' => true, 'number' => true,
        'round' => true, 'cleanround' => true, 'int' => true, 'float' => true,
        'div' => true, 'abs' => true, 'date' => true, 'ago' => true, 'truncate' => true,
        'excerpt' => true, 'nl2br' => true, 'striptags' => true, 'slug' => true,
        'default' => true, 'raw' => true, 'pad' => true, 'repeat' => true,
        'translate' => true, 'join' => true, 'split' => true, 'length' => true,
        'first' => true, 'last' => true, 'reverse' => true, 'sort' => true,
        'unique' => true, 'slice' => true, 'replace' => true, 'trim' => true,
        'base64' => true, 'md5' => true, 'sha1' => true, 'keys' => true,
        // v5 — arithmetic (arguments are literals; use `%{= a * b}` for
        // data-driven math): add sub mul mod pow sqrt pct sum avg clamp
        'add' => true, 'sub' => true, 'mul' => true, 'mod' => true,
        'pow' => true, 'sqrt' => true, 'pct' => true, 'sum' => true,
        'avg' => true, 'clamp' => true,
    ];

    /**
     * Applies one filter with its arguments.
     *
     * @param list<string> $args
     */
    public function apply(string $name, mixed $value, array $args = []): mixed
    {
        $name = strtolower(trim($name));

        $this->events->dispatch('htmlphp.filter.apply', $name, $args);

        if (isset($this->custom[$name])) {
            return ($this->custom[$name])($value, $args);
        }

        if (!isset(self::BUILTIN[$name])) {
            return $this->unknown($name, $value);
        }

        return $this->builtin($name, $value, $args);
    }

    /** @param list<string> $args */
    private function builtin(string $name, mixed $value, array $args): mixed
    {
        $string = Str::stringify($value);

        return match ($name) {
            'escape', 'esc', 'e' => $this->escaper->byStrategy($args[0] ?? 'html', $value),
            'attr' => $this->escaper->attr($string),
            'url' => $this->escaper->url($string),
            'json' => $this->escaper->json($value),
            'js' => $this->escaper->js($value),
            'css' => $this->escaper->css($string),
            'upper' => Str::upper($string),
            'lower' => Str::lower($string),
            'ucfirst' => Str::ucfirst($string),
            'title' => Str::words($string),
            'words' => str_word_count($string),
            'number' => isset($args[1]) || isset($args[2])
                ? Str::number(
                    Str::numericValue($value),
                    (int) ($args[0] ?? 2),
                    (string) ($args[1] ?? '.'),
                    (string) ($args[2] ?? ','),
                )
                : $this->formats->number(
                    Str::numericValue($value),
                    null,
                    isset($args[0]) ? (int) $args[0] : null,
                ),
            'round' => Str::round(Str::numericValue($value), $args[0] ?? 0),
            'cleanround' => Str::cleanRound(Str::numericValue($value), $args[0] ?? 0),
            'int' => (string) (int) round(Str::numericValue($value)),
            'float' => Str::stringify(Str::numericValue($value)),
            'div' => Str::stringify(Str::divide($value, $args[0] ?? 0)),
            'mul' => Str::stringify(self::finite(Str::numericValue($value) * Str::numericValue($args[0] ?? 0))),
            'add' => Str::stringify(self::finite(Str::numericValue($value) + Str::numericValue($args[0] ?? 0))),
            'sub' => Str::stringify(self::finite(Str::numericValue($value) - Str::numericValue($args[0] ?? 0))),
            'mod' => Str::stringify(self::modulo(Str::numericValue($value), Str::numericValue($args[0] ?? 0))),
            'pow' => Str::stringify(Str::power(Str::numericValue($value), Str::numericValue($args[0] ?? 1))),
            'sqrt' => Str::stringify(Str::sqrt(Str::numericValue($value))),
            'pct' => Str::round(
                self::finite(Str::divide($value, $args[0] ?? 0) * 100),
                $args[1] ?? 0,
            ),
            'sum' => Str::stringify(Str::accumulate($value)[0]),
            'avg' => Str::stringify(self::average($value)),
            'clamp' => Str::stringify(self::clamp(
                Str::numericValue($value),
                Str::numericValue($args[0] ?? 0),
                Str::numericValue($args[1] ?? 0),
            )),
            'abs' => Str::stringify(abs(Str::numericValue($value))),
            'date' => $this->formats->date($value, $args[0] ?? null),
            'ago' => $this->formats->ago($value),
            'truncate' => Str::truncate($string, (int) ($args[0] ?? 80), $args[1] ?? '…'),
            'excerpt' => Str::truncate(strip_tags($string), (int) ($args[0] ?? 160), $args[1] ?? '…'),
            'nl2br' => nl2br($this->escaper->html($string)),
            'striptags' => strip_tags($string),
            'slug' => Str::slugify($string, $args[0] ?? '-'),
            'default' => $string !== '' ? $string : ($args[0] ?? ''),
            'raw' => $value,
            'pad' => str_pad(
                $string,
                (int) ($args[0] ?? 0),
                $args[1] ?? ' ',
                (int) ($args[2] ?? 0) === 1 ? STR_PAD_LEFT : STR_PAD_RIGHT,
            ),
            'repeat' => str_repeat($string, max(0, min(1000, (int) ($args[0] ?? 2)))),
            'translate' => $this->translator->t($string),
            'join' => self::isIterableValue($value)
                ? implode($args[0] ?? ', ', array_map(Str::stringify(...), self::toArray($value)))
                : $string,
            'split' => explode($args[0] ?? ',', $string),
            'length' => (string) self::lengthOf($value),
            'first' => Str::stringify(self::edge($value, true)),
            'last' => Str::stringify(self::edge($value, false)),
            'reverse' => self::isIterableValue($value)
                ? array_reverse(self::toArray($value))
                : implode('', array_reverse(preg_split('//u', $string, -1, PREG_SPLIT_NO_EMPTY) ?: [])),
            'sort' => self::sorted($value, ($args[0] ?? '') !== ''),
            'unique' => self::isIterableValue($value)
                ? array_values(array_unique(self::toArray($value), SORT_REGULAR))
                : $string,
            'slice' => self::sliced($value, (int) ($args[0] ?? 0), isset($args[1]) ? (int) $args[1] : null),
            'replace' => str_replace($args[0] ?? '', $args[1] ?? '', $string),
            'trim' => $args === [] ? trim($string) : trim($string, (string) $args[0]),
            'base64' => base64_encode($string),
            'md5' => md5($string),
            'sha1' => sha1($string),
            'keys' => self::isIterableValue($value) ? implode(', ', array_map(Str::stringify(...), array_keys(self::toArray($value)))) : '',
            default => $value, // unreachable: BUILTIN gates the match
        };
    }

    private function unknown(string $name, mixed $value): mixed
    {
        if ($this->strict) {
            throw new TemplateException('Unknown template filter.', ['filter' => $name]);
        }

        $this->diagnostics->record(Diagnostics::FILTER_UNKNOWN, 'Unknown template filter.', ['filter' => $name]);

        return $value;
    }

    private static function isIterableValue(mixed $value): bool
    {
        return \is_array($value) || $value instanceof \Traversable;
    }

    /** Non-finite arithmetic results degrade to 0 (html4.pl `Divide()` spirit). */
    private static function finite(float $value): float
    {
        return is_finite($value) ? $value : 0.0;
    }

    /** Integer modulo with the zero-divisor guard (`0`, never a fatal). */
    private static function modulo(float $value, float $divisor): int
    {
        $divisor = (int) $divisor;

        return $divisor === 0 ? 0 : (int) $value % $divisor;
    }

    /** Capped mean over arrays/iterables (scalars count as one item). */
    private static function average(mixed $value): float
    {
        [$sum, $count] = Str::accumulate($value);

        return $count === 0 ? 0.0 : self::finite($sum / $count);
    }

    private static function clamp(float $value, float $min, float $max): float
    {
        if ($min > $max) {
            [$min, $max] = [$max, $min];
        }

        return max($min, min($max, $value));
    }

    /** @return array<array-key, mixed> */
    private static function toArray(mixed $value): array
    {
        if (\is_array($value)) {
            return $value;
        }

        return $value instanceof \Traversable ? iterator_to_array($value) : [];
    }

    private static function lengthOf(mixed $value): int
    {
        return match (true) {
            \is_array($value) => \count($value),
            $value instanceof \Countable => \count($value),
            $value instanceof \Traversable => iterator_count($value),
            \is_string($value) => Str::length($value),
            default => $value === null ? 0 : 1,
        };
    }

    private static function edge(mixed $value, bool $first): mixed
    {
        if (\is_string($value)) {
            $length = Str::length($value);

            return $length === 0 ? '' : ($first ? Str::substr($value, 0, 1) : Str::substr($value, $length - 1, 1));
        }

        $array = self::toArray($value);

        if ($array === []) {
            return '';
        }

        return $first ? array_values($array)[0] : array_values($array)[\count($array) - 1];
    }

    private static function sorted(mixed $value, bool $descending): mixed
    {
        if (!self::isIterableValue($value)) {
            return $value;
        }

        $array = self::toArray($value);
        $descending ? arsort($array) : asort($array);

        return $array;
    }

    private static function sliced(mixed $value, int $offset, ?int $length): mixed
    {
        if (\is_string($value)) {
            return Str::substr($value, $offset, $length);
        }

        if (!self::isIterableValue($value)) {
            return $value;
        }

        return \array_slice(self::toArray($value), $offset, $length, true);
    }
}

/**
 * One linter finding.
 *
 * Severity: `error` (render would fail or misbehave), `warning` (probably
 * a bug), `info` (worth knowing). Codes are stable identifiers for CI
 * baselines (`--ignore=unresolved-include`).
 */
final readonly class LintIssue
{
    /**
     * @param array<string, mixed> $context
     */
    public function __construct(
        public string $severity,
        public string $code,
        public string $message,
        public string $file = '-',
        public int $line = 0,
        public array $context = [],
    ) {}

    public function isError(): bool
    {
        return $this->severity === 'error';
    }

    public function format(): string
    {
        return \sprintf(
            '%s:%d %s [%s] %s',
            $this->file,
            $this->line,
            strtoupper($this->severity),
            $this->code,
            $this->message,
        );
    }

    /** @return array<string, mixed> */
    public function toArray(): array
    {
        return get_object_vars($this);
    }
}

/**
 * Static template analysis: unbalanced tags, unknown tags/filters,
 * malformed expressions, unresolvable partials/layouts and translatable
 * strings missing from the catalogue.
 *
 * Powers `Engine::lint()`, `bin/htmlphp lint`, `wp htmlphp lint` and the
 * WordPress admin screen — the "will this template explode in production?"
 * check that runs in CI instead of at 3 a.m.
 */
final class Linter
{
    /** @var array<string, true> */
    private const array KNOWN_STANDALONE = [
        'extends' => true, 'include' => true, 'set' => true,
        'sectionparent' => true, 'break' => true, 'continue' => true,
    ];

    /**
     * Filters whose arguments must be numeric literals — used for the
     * "that looks like a variable name" warning (filter arguments are
     * never resolved against the scope).
     *
     * @var array<string, true>
     */
    private const array NUMERIC_ARG_FILTERS = [
        'add' => true, 'sub' => true, 'mul' => true, 'div' => true,
        'mod' => true, 'pow' => true, 'pct' => true, 'clamp' => true,
        'round' => true,
    ];

    public function __construct(
        private readonly Config $config,
        private readonly Diagnostics $diagnostics,
        private readonly Filters $filters,
        private readonly TemplateLocator $locator,
        private readonly ?Translator $translator = null,
    ) {}

    /**
     * Lints one template source.
     *
     * @return list<LintIssue>
     */
    public function lint(string $source, string $origin = '-'): array
    {
        $issues = [];

        foreach ($this->structureIssues($source, $origin) as $issue) {
            $issues[] = $issue;
        }

        // The structure pass already produced a node tree when it did not
        // throw; re-parse defensively behind a try/catch for the deep checks.
        try {
            $nodes = (new TagParser())->parse($source, $origin);
        } catch (\Throwable) {
            // Structural failure already reported — still check substitutions
            // so one broken tag cannot hide unknown filters.
            $this->textIssues($source, $origin, $issues);

            return $issues;
        }

        $this->walk($nodes, $source, $origin, $issues);
        $this->ssiIssues($source, $origin, $issues);

        return $issues;
    }

    /**
     * Lints a file.
     *
     * @return list<LintIssue>
     */
    public function lintFile(string $path): array
    {
        $contents = \HtmlPhp\Io\Files::slurp($path, $this->config->limits->maxTemplateBytes);

        if ($contents === null) {
            return [new LintIssue('error', 'template-unreadable', 'Template is not readable or too large.', $path, 0)];
        }

        return $this->lint($contents, $path);
    }

    /**
     * Lints every template below a directory.
     *
     * @return array<string, list<LintIssue>> issues keyed by file
     */
    public function lintDirectory(string $directory): array
    {
        $report = [];

        if (!is_dir($directory)) {
            return $report;
        }

        $iterator = new \RecursiveIteratorIterator(
            new \RecursiveDirectoryIterator($directory, \FilesystemIterator::SKIP_DOTS),
        );

        /** @var \SplFileInfo $info */
        foreach ($iterator as $info) {
            if (!$info->isFile()) {
                continue;
            }

            $extension = strtolower($info->getExtension());

            if (!\in_array($extension, ['html', 'htm', 'txt', 'shtml', 'xhtml'], true)) {
                continue;
            }

            $issues = $this->lintFile($info->getPathname());

            if ($issues !== []) {
                $report[$info->getPathname()] = $issues;
            }
        }

        return $report;
    }

    // ------------------------------------------------------------- structure

    /**
     * Cheap pre-pass over the raw tag stream: unknown tags and unbalanced
     * blocks are reported with line numbers even when the parser throws on
     * the first one.
     *
     * @return list<LintIssue>
     */
    private function structureIssues(string $source, string $origin): array
    {
        $issues = [];

        if (!str_contains($source, '<!--@')) {
            return $issues;
        }

        $count = preg_match_all(
            '~<!--@([A-Za-z][A-Za-z0-9]*)(.*?)-->~s',
            $source,
            $matches,
            PREG_OFFSET_CAPTURE | PREG_SET_ORDER,
        );

        if ($count === 0 || $count === false) {
            return $issues;
        }

        $open = [];
        $known = [
            'loop' => 'endloop', 'if' => 'endif', 'unless' => 'endunless',
            'section' => 'endsection', 'trans' => 'endtrans',
            'raw' => 'endraw', 'comment' => 'endcomment',
        ];
        $mids = ['else' => true, 'elif' => true, 'plural' => true];

        foreach ($matches as $match) {
            $name = strtolower((string) $match[1][0]);
            $offset = (int) $match[0][1];
            $line = substr_count($source, "\n", 0, $offset) + 1;

            if (!isset($known[$name])
                && !isset($mids[$name])
                && !isset(self::KNOWN_STANDALONE[$name])
                && !\in_array($name, ['endloop', 'endif', 'endunless', 'endsection', 'endtrans', 'endraw', 'endcomment'], true)
            ) {
                $issues[] = new LintIssue('error', 'unknown-tag', 'Unknown template tag "@' . $name . '".', $origin, $line);
                continue;
            }

            if (isset($known[$name])) {
                $open[] = [$name, $line];
                continue;
            }

            $closes = array_search($name, $known, true);

            if ($closes !== false) {
                $top = $open === [] ? null : $open[\count($open) - 1];

                if ($top === null || $top[0] !== $closes) {
                    $issues[] = new LintIssue(
                        'error',
                        'unbalanced-tag',
                        \sprintf(
                            '"@%s" closes %s.',
                            $name,
                            $top === null ? 'nothing' : 'an open "@' . $top[0] . '" from line ' . $top[1],
                        ),
                        $origin,
                        $line,
                    );

                    continue; // the opener stays open — it is still unclosed
                }

                array_pop($open);
                continue;
            }

            if (isset($mids[$name]) && $open === []) {
                $issues[] = new LintIssue('error', 'orphan-mid', '"@' . $name . '" without an opening block.', $origin, $line);
            }
        }

        foreach ($open as [$name, $line]) {
            $issues[] = new LintIssue('error', 'unclosed-tag', 'Block "@' . $name . '" is never closed.', $origin, $line);
        }

        return $issues;
    }

    // ----------------------------------------------------------- deep checks

    /**
     * @param list<Node> $nodes
     * @param list<LintIssue> $issues
     */
    private function walk(array $nodes, string $source, string $origin, array &$issues, int $depth = 0): void
    {
        foreach ($nodes as $node) {
            $line = (int) ($node->attribute('line') ?? 0);

            switch ($node->kind) {
                case 'text':
                    $this->textIssues((string) $node->attribute('value', ''), $origin, $issues);
                    break;

                case 'loop':
                    $this->loopIssues($node, $origin, $issues);
                    $this->walk($node->children, $source, $origin, $issues, $depth + 1);
                    $this->walk($node->attribute('else', []), $source, $origin, $issues, $depth + 1);
                    break;

                case 'if':
                    foreach ($node->attribute('branches', []) as $branch) {
                        $this->expressionIssues((string) ($branch['expr'] ?? ''), $origin, $line, $issues);
                        $this->walk($branch['nodes'], $source, $origin, $issues, $depth + 1);
                    }
                    $this->walk($node->attribute('else', []), $source, $origin, $issues, $depth + 1);
                    break;

                case 'section':
                    $this->walk($node->children, $source, $origin, $issues, $depth + 1);
                    break;

                case 'trans':
                    $this->transIssues($node, $origin, $issues);
                    $this->walk($node->attribute('singular', []), $source, $origin, $issues, $depth + 1);
                    $this->walk($node->attribute('plural', []), $source, $origin, $issues, $depth + 1);
                    break;

                case 'include':
                case 'extends':
                    $this->referenceIssues($node, $origin, $line, $issues);
                    break;

                case 'set':
                    $this->expressionIssues((string) $node->attribute('expr', ''), $origin, $line, $issues);
                    break;

                case 'break':
                case 'continue':
                    if ($depth === 0) {
                        $issues[] = new LintIssue('warning', 'loop-signal-outside-loop', '"@' . $node->kind . '" outside of any loop.', $origin, $line);
                    }
                    break;

                default:
                    break;
            }
        }
    }

    /** @param list<LintIssue> $issues */
    private function textIssues(string $text, string $origin, array &$issues): void
    {
        if ($text === '') {
            return;
        }

        Pcre::replaceCallback(
            '~([%#@])\{([^{}]*)\}~',
            function (array $m) use ($origin, &$issues): string {
                $payload = (string) $m[2];
                $line = 0;

                // `%= { … }` / `#{= …}` — inline expression form (v5).
                if (($m[1] === '%' || $m[1] === '#') && str_starts_with(ltrim($payload), '=')) {
                    $this->inlineExpressionIssues(ltrim(substr(ltrim($payload), 1)), $origin, $line, $issues);

                    return $m[0];
                }

                [$name, $filters] = Substitution::splitFilters($payload);

                if ($m[1] === '@') {
                    $this->messageIssue(trim(explode('|', $name)[0]), $origin, $line, $issues);
                }

                foreach ($filters as [$filterName, $args]) {
                    $this->filterIssues($filterName, $args, $origin, $line, $issues);
                }

                return $m[1] . '{' . $payload . '}';
            },
            $text,
        );
    }

    /**
     * Validates one inline-expression payload (`%= {…}` form): the config
     * gate, the expression syntax and the trailing filter chain.
     *
     * @param list<LintIssue> $issues
     */
    private function inlineExpressionIssues(string $payload, string $origin, int $line, array &$issues): void
    {
        if (!$this->config->syntax->expressions) {
            $issues[] = new LintIssue(
                'error',
                'expressions-disabled',
                'Inline expressions ("%{= …}") are disabled by configuration (syntax.expressions).',
                $origin,
                $line,
                ['expression' => $payload],
            );

            return;
        }

        [$source, $filters] = Substitution::splitExpressionPayload($payload);

        if (trim($source) === '') {
            $issues[] = new LintIssue('error', 'bad-expression', 'Empty inline expression.', $origin, $line, ['expression' => $payload]);
        } else {
            $this->expressionIssues($source, $origin, $line, $issues);
        }

        foreach ($filters as [$filterName, $args]) {
            $this->filterIssues($filterName, $args, $origin, $line, $issues);
        }
    }

    /**
     * One filter segment: registry check, disabled-`raw` check and the
     * numeric-argument heuristic (a bare word where a number belongs is
     * almost always a variable reference that filter arguments do not
     * support — point the author at `%{= …}`).
     *
     * @param list<string> $args
     * @param list<LintIssue> $issues
     */
    private function filterIssues(string $filterName, array $args, string $origin, int $line, array &$issues): void
    {
        $lower = strtolower($filterName);

        if ($lower === 'raw' && !$this->config->syntax->allowRawFilter) {
            $issues[] = new LintIssue('error', 'filter-disabled', 'Filter "raw" is disabled by configuration.', $origin, $line);

            return;
        }

        if (!$this->filters->has($lower)) {
            $issues[] = new LintIssue('error', 'unknown-filter', 'Unknown filter "' . $filterName . '".', $origin, $line);

            return;
        }

        if (!isset(self::NUMERIC_ARG_FILTERS[$lower])) {
            return;
        }

        foreach ($args as $argument) {
            if (preg_match('~^[A-Za-z_][A-Za-z0-9_.]*$~', $argument) === 1) {
                $issues[] = new LintIssue(
                    'warning',
                    'filter-arg-not-numeric',
                    \sprintf(
                        'Filter "%s" expects numeric arguments but got "%s" — filter arguments are literals, '
                        . 'never variable references. Compute with data in an inline expression instead: %%{= …}.',
                        $filterName,
                        $argument,
                    ),
                    $origin,
                    $line,
                    ['filter' => $filterName, 'argument' => $argument],
                );
            }
        }
    }

    /** @param list<LintIssue> $issues */
    private function loopIssues(Node $node, string $origin, array &$issues): void
    {
        $spec = $node->attribute('spec');

        if (!\is_array($spec)) {
            return;
        }

        $line = (int) ($spec['line'] ?? 0);

        if (($spec['mode'] ?? '') === 'range') {
            $span = abs((int) $spec['to'] - (int) $spec['source']);

            if ($span > $this->config->limits->maxLoopRows) {
                $issues[] = new LintIssue('warning', 'loop-range-too-large', \sprintf('Loop range spans %d rows (limit %d).', $span, $this->config->limits->maxLoopRows), $origin, $line);
            }
        }
    }

    /** @param list<LintIssue> $issues */
    private function expressionIssues(string $expression, string $origin, int $line, array &$issues): void
    {
        $expression = trim($expression);

        if ($expression === '') {
            return;
        }

        try {
            Expression::validate($expression, $this->config->limits->maxExpressionLength);
        } catch (\Throwable $error) {
            $issues[] = new LintIssue('error', 'bad-expression', $error->getMessage(), $origin, $line, ['expression' => $expression]);
        }
    }

    /** @param list<LintIssue> $issues */
    private function referenceIssues(Node $node, string $origin, int $line, array &$issues): void
    {
        $template = (string) $node->attribute('template', '');

        if ($template === '') {
            $issues[] = new LintIssue('error', 'missing-reference', '"@' . $node->kind . '" has no template name.', $origin, $line);

            return;
        }

        if ($this->locator->roots() === [] && $this->config->templates->namespaces === []) {
            return; // nothing to resolve against; skip silently
        }

        if ($this->locator->locate($template) === null && !$node->attribute('ignoreMissing', false)) {
            $issues[] = new LintIssue(
                'error',
                'unresolved-' . $node->kind,
                \sprintf('"%s" cannot be located in the configured template paths.', $template),
                $origin,
                $line,
                ['template' => $template],
            );
        }
    }

    /** @param list<LintIssue> $issues */
    private function transIssues(Node $node, string $origin, array &$issues): void
    {
        $attrs = $node->attribute('attrs', []);
        $line = (int) ($node->attribute('line') ?? 0);
        $plural = $node->attribute('plural', []);

        if (isset($attrs['count']) && $plural === []) {
            $issues[] = new LintIssue('warning', 'trans-count-without-plural', '"@Trans" has count= but no <!--@Plural--> body.', $origin, $line);
        }

        if (!isset($attrs['count']) && $plural !== []) {
            $issues[] = new LintIssue('warning', 'trans-plural-without-count', '"@Trans" has a plural body but no count= attribute.', $origin, $line);
        }

        foreach ($node->attribute('singular', []) as $child) {
            if ($child->kind !== 'text') {
                $issues[] = new LintIssue('error', 'trans-nested-tag', '"@Trans" bodies may only contain text and substitutions.', $origin, $line);
                break;
            }
        }
    }

    /** @param list<LintIssue> $issues */
    private function messageIssue(string $msgid, string $origin, int $line, array &$issues): void
    {
        if ($msgid === '' || $this->translator === null) {
            return;
        }

        $locale = $this->translator->locale();
        $catalogue = $this->translator->catalogue($locale, $this->config->i18n->domain);

        if ($catalogue !== null && !$catalogue->has($msgid)) {
            $issues[] = new LintIssue('warning', 'untranslated-message', \sprintf('"%s" has no %s translation.', $msgid, $locale), $origin, $line, ['msgid' => $msgid]);
        }
    }

    // -------------------------------------------------------------------- SSI

    /**
     * Validates SSI directives: unknown names, `#if` expressions and
     * `#include`/`#echo` attribute presence.
     *
     * @param list<LintIssue> $issues
     */
    private function ssiIssues(string $source, string $origin, array &$issues): void
    {
        $count = preg_match_all('~<!--\#([a-zA-Z]+)((?:(?!<!--).)*?)-->~s', $source, $matches, PREG_OFFSET_CAPTURE | PREG_SET_ORDER);

        if ($count === 0 || $count === false) {
            return;
        }

        $known = [
            'config', 'echo', 'exec', 'flastmod', 'fsize', 'include',
            'printenv', 'set', 'if', 'elif', 'else', 'endif', 'block', 'endblock',
        ];

        foreach ($matches as $match) {
            $name = strtolower((string) $match[1][0]);
            $payload = (string) $match[2][0];
            $line = substr_count($source, "\n", 0, (int) $match[0][1]) + 1;

            if (!\in_array($name, $known, true)) {
                $issues[] = new LintIssue('warning', 'unknown-ssi-directive', 'Unknown SSI directive "#' . $name . '" (left in output).', $origin, $line);
                continue;
            }

            $attributes = \HtmlPhp\Ssi\Attributes::parse($payload);

            if ($name === 'if' || $name === 'elif') {
                $expression = $attributes['expr'] ?? '';

                if ($expression === '') {
                    $issues[] = new LintIssue('error', 'ssi-missing-expr', '"#' . $name . '" has no expr= attribute.', $origin, $line);
                    continue;
                }

                // SSI expressions never throw: syntax errors surface as
                // diagnostics, which the linter converts into issues.
                $before = $this->diagnostics->count(Diagnostics::SSI_EXPR_ERROR);
                \HtmlPhp\Ssi\Expression::evaluate($expression, $this->lintContext());

                foreach (\array_slice($this->diagnostics->byCode(Diagnostics::SSI_EXPR_ERROR), $before) as $entry) {
                    $issues[] = new LintIssue('error', 'ssi-bad-expr', $entry['message'], $origin, $line, ['expression' => $expression]);
                }
                continue;
            }

            if ($name === 'include' && ($attributes['file'] ?? '') === '' && ($attributes['virtual'] ?? '') === '') {
                $issues[] = new LintIssue('error', 'ssi-include-target', '"#include" needs file= or virtual=.', $origin, $line);
                continue;
            }

            if ($name === 'echo' && ($attributes['var'] ?? '') === '') {
                $issues[] = new LintIssue('error', 'ssi-echo-var', '"#echo" needs var=.', $origin, $line);
                continue;
            }

            if ($name === 'set' && ($attributes['var'] ?? '') === '') {
                $issues[] = new LintIssue('error', 'ssi-set-var', '"#set" needs var=.', $origin, $line);
            }

            if ($name === 'exec' && $this->config->ssi->execMode === ExecMode::Deny) {
                $issues[] = new LintIssue('info', 'ssi-exec-denied', '"#exec" is present but the policy denies execution.', $origin, $line);
            }
        }
    }

    private function lintContext(): \HtmlPhp\Ssi\SsiContext
    {
        return new \HtmlPhp\Ssi\SsiContext(
            new \HtmlPhp\Ssi\DocumentInfo(null, $this->config->ssi->documentRoot),
            $this->config->ssi,
            $this->config->security,
            $this->config->limits,
            $this->diagnostics,
            new \HtmlPhp\Event\Dispatcher(),
            new \HtmlPhp\Support\SystemClock(),
        );
    }

    /**
     * Extracts translatable messages from a source (CLI/admin helper).
     */
    public function extract(string $source, string $origin = '-'): Extractor
    {
        return (new Extractor())->scan($source, $origin);
    }
}

/**
 * Internal control-flow signal for `<!--@Break-->` / `<!--@Continue-->`.
 *
 * @internal caught by {@see TreeRenderer}; never escapes the engine
 */
final class LoopSignal extends \Exception
{
    public function __construct(public readonly string $kind)
    {
        parent::__construct('loop-' . $kind);
    }
}

/**
 * One node of the parsed template tree.
 *
 * The parser turns the flat comment-tag syntax into a tree so loops,
 * conditionals, blocks and partials nest correctly by construction rather
 * than by balanced-regex luck. Node kinds are plain strings (no enum) to
 * keep the compiled/cached representation cheap.
 *
 * Kind catalog:
 *  - `text`      raw output (`value` = string)
 *  - `var`       `%{NAME|filter}` (`value` = name, `filters` = list, `raw` = bool)
 *  - `translate` `@{KEY}` (`value` = message id)
 *  - `loop`      (`name`, `body`, `else`, `maxRows`)
 *  - `if`        (`branches` = list of [expr, body], `else` = nodes)
 *  - `block`     inheritance slot (`name`, `body`)
 *  - `extends`   (`value` = parent template name)
 *  - `partial`   (`value` = template, `with`, `only`, `ignoreMissing`)
 *  - `set`       (`name`, `value` expression)
 *  - `trans`     (`msgid`, `plural`, `count`, `args`, `body` nodes)
 *  - `raw`       verbatim, unprocessed (`value`)
 *  - `comment`   dropped
 */
final class Node
{
    /**
     * @param array<string, mixed> $attributes kind-specific payload
     * @param list<Node> $children
     */
    public function __construct(
        public readonly string $kind,
        public readonly array $attributes = [],
        public readonly array $children = [],
    ) {}

    /** @param list<Node> $children */
    public function withChildren(array $children): self
    {
        return new self($this->kind, $this->attributes, $children);
    }

    public function attribute(string $key, mixed $default = null): mixed
    {
        return $this->attributes[$key] ?? $default;
    }
}

/**
 * Mutable per-render state shared by the renderer and the tree walker:
 * effective options, counters, layout-inheritance overrides and the
 * section resolution stack.
 *
 * @internal created by {@see Renderer} for each render call
 */
final class RenderContext
{
    /**
     * Layout overrides: section name => stack of override bodies (child first).
     *
     * @var array<string, list<list<Node>>>
     */
    public array $overrides = [];

    /** Set when walking a child template that `@Extends` a layout. */
    public bool $collectMode = false;

    /** Template requested by the first `<!--@Extends-->` of the walk. */
    public ?string $extendsTemplate = null;

    /**
     * Section resolution stack for `<!--@SectionParent-->`.
     *
     * @var list<array{0: string, 1: int, 2: list<Node>}>
     */
    public array $sectionFrames = [];

    public int $loopDepth = 0;
    public int $extendsDepth = 0;

    /** File of the template currently being walked (partial anchors). */
    public ?string $currentFile = null;

    public bool $autoEscape;
    public MissingVarPolicy $missingVar;
    public bool $structure;

    public function __construct(
        public readonly Scope $scope,
        public readonly RenderStats $stats,
        public readonly Diagnostics $diagnostics,
        bool $autoEscape,
        MissingVarPolicy $missingVar,
        bool $structure,
    ) {
        $this->autoEscape = $autoEscape;
        $this->missingVar = $missingVar;
        $this->structure = $structure;
    }

    /**
     * Registers a child override for a section (layout inheritance).
     *
     * @param list<Node> $nodes
     */
    public function pushOverride(string $name, array $nodes): void
    {
        $this->overrides[$name][] = $nodes;
    }

    /**
     * Nodes to render for a section at the given inheritance level:
     * the deepest override that exists, else the inline default body.
     *
     * @param list<Node> $defaultNodes
     * @return list<Node>
     */
    public function sectionNodes(string $name, int $level, array $defaultNodes): array
    {
        return $this->overrides[$name][$level] ?? $defaultNodes;
    }
}

/**
 * Per-call render overrides (all optional; `null` = take the engine config).
 *
 * Replaces the v3 `$options` array — typed, documented, IDE-friendly:
 *
 * ```php
 * $engine->renderFile('page.html', $vars, new RenderOptions(
 *     ssi: false,
 *     cache: true,
 *     ttl: 300,
 * ));
 * ```
 */
final readonly class RenderOptions
{
    public function __construct(
        /** Document path anchoring relative SSI includes and LAST_MODIFIED. */
        public ?string $file = null,
        /** Document-root override for SSI containment. */
        public ?string $root = null,
        /** Request environment for SSI built-ins (else CLI context). */
        public ?RequestContext $request = null,
        /** Run the SSI pass. */
        public ?bool $ssi = null,
        /** Process structure tags (loops/ifs/sections/partials). */
        public ?bool $structure = null,
        /** Auto-escape substitutions. */
        public ?bool $autoEscape = null,
        /** Missing-variable policy override. */
        public ?MissingVarPolicy $missingVar = null,
        /** Use the render cache for this call. */
        public ?bool $cache = null,
        /** Cache TTL override (seconds, 0 = backend default). */
        public ?int $ttl = null,
        /** Locale override for this render (translator switch, restored after). */
        public ?string $locale = null,
        /**
         * Extra variables visible to SSI `#if`/`#echo` ($NAME lookups).
         *
         * @var array<string, mixed>|null
         */
        public ?array $ssiVars = null,
    ) {}

    /**
     * Convenience constructor from a v3-style options array (migration aid).
     *
     * @param array<string, mixed> $options
     */
    public static function fromArray(array $options): self
    {
        return new self(
            file: isset($options['file']) && \is_string($options['file']) ? $options['file'] : null,
            root: isset($options['root']) && \is_string($options['root']) ? $options['root'] : null,
            ssi: isset($options['ssi']) ? (bool) $options['ssi'] : null,
            structure: isset($options['loops']) ? (bool) $options['loops'] : (isset($options['structure']) ? (bool) $options['structure'] : null),
            autoEscape: isset($options['escape']) ? (bool) $options['escape'] : null,
            cache: isset($options['cache']) ? (bool) $options['cache'] : null,
            ttl: isset($options['ttl']) ? (int) $options['ttl'] : null,
            locale: isset($options['locale']) && \is_string($options['locale']) ? $options['locale'] : null,
        );
    }
}

/**
 * Counters and timings for one render — the engine's profiler.
 *
 * Exposed via `Engine::stats()` (last render) and the
 * `htmlphp.rendered` event; the WordPress bridge surfaces it in the
 * admin bar when `WP_DEBUG` is on.
 */
final class RenderStats
{
    // PHP 8.4 asymmetric visibility: readable everywhere, writable only here.
    public private(set) string $template = '';
    public float $startedAt = 0.0;
    public float $durationMs = 0.0;
    public bool $cacheHit = false;
    public int $substitutions = 0;
    public int $loops = 0;
    public int $loopRows = 0;
    public int $conditionals = 0;
    public int $includes = 0;
    public int $sections = 0;
    public int $translations = 0;
    public int $ssiDirectives = 0;
    public int $outputBytes = 0;
    public int $peakMemoryKb = 0;

    /** @var list<string> every template file touched (partials, layouts) */
    public private(set) array $templates = [];

    /** PHP 8.4 property hook: a computed, always-fresh one-liner. */
    public string $summary {
        get => sprintf(
            '%.2fms · %d template(s) · %d loop(s)/%d row(s) · %d include(s) · %d SSI directive(s) · cache %s · %d B out',
            $this->durationMs,
            count($this->templates),
            $this->loops,
            $this->loopRows,
            $this->includes,
            $this->ssiDirectives,
            $this->cacheHit ? 'hit' : 'miss',
            $this->outputBytes
        );
    }

    /** Records a template file touched by the render (partials, layouts). */
    public function trackTemplate(string $template): void
    {
        $this->templates[] = $template;
    }

    public function start(string $template): void
    {
        $this->reset();
        $this->template = $template;
        $this->trackTemplate($template);
        $this->startedAt = microtime(true);
        $this->peakMemoryKb = (int) (memory_get_usage(true) / 1024);
    }

    public function stop(int $outputBytes): void
    {
        $this->durationMs = round((microtime(true) - $this->startedAt) * 1000, 3);
        $this->outputBytes = $outputBytes;
    }

    public function reset(): void
    {
        $this->durationMs = 0.0;
        $this->cacheHit = false;
        $this->substitutions = 0;
        $this->loops = 0;
        $this->loopRows = 0;
        $this->conditionals = 0;
        $this->includes = 0;
        $this->sections = 0;
        $this->translations = 0;
        $this->ssiDirectives = 0;
        $this->outputBytes = 0;
        $this->peakMemoryKb = 0;
        $this->templates = [];
    }

    /** @return array<string, mixed> */
    #[\NoDiscard]
    public function toArray(): array
    {
        return [
            'template' => $this->template,
            'startedAt' => $this->startedAt,
            'durationMs' => $this->durationMs,
            'cacheHit' => $this->cacheHit,
            'substitutions' => $this->substitutions,
            'loops' => $this->loops,
            'loopRows' => $this->loopRows,
            'conditionals' => $this->conditionals,
            'includes' => $this->includes,
            'sections' => $this->sections,
            'translations' => $this->translations,
            'ssiDirectives' => $this->ssiDirectives,
            'outputBytes' => $this->outputBytes,
            'peakMemoryKb' => $this->peakMemoryKb,
            'templates' => $this->templates,
            'summary' => $this->summary,
        ];
    }
}

/**
 * The render pipeline (PHP 8.5 edition overlay: pipe operator in render(),
 * array_find() in findExtends(), #[\NoDiscard] annotations).
 *
 * ```
 * source → parse (memoized) → layout inheritance (@Extends/@Section)
 *        → tree render (loops/ifs/partials/set/trans + %{} substitution)
 *        → SSI pass (mod_include directives, incl. from partials)
 *        → optional re-substitution pass (SSI output containing %{} tags)
 *        → 'htmlphp.render' filter → output cache → stats/events
 * ```
 *
 * Order rationale: the template language runs first so SSI sees the final
 * document (Apache semantics); one guarded re-substitution pass keeps the
 * v3 ability of `#include`d fragments carrying template tags.
 */
final class Renderer
{
    private readonly Substitution $substitution;
    private readonly TreeRenderer $tree;
    private readonly TagParser $parser;

    /** @var array<string, list<Node>> parse memo: sha1(source) => nodes */
    private array $parsed = [];

    public function __construct(
        private readonly Config $config,
        private readonly Diagnostics $diagnostics,
        private readonly Dispatcher $events,
        private readonly CacheInterface $cache,
        private readonly Processor $ssi,
        private readonly Filters $filters,
        private readonly TranslatorInterface $translator,
        private readonly Escaper $escaper,
        private readonly TemplateLocator $locator
    ) {
        $this->substitution = new Substitution(
            $config->syntax,
            $config->limits,
            $filters,
            $escaper,
            $translator,
            $diagnostics
        );

        $this->parser = new TagParser();
        $this->tree = new TreeRenderer(
            $config,
            $diagnostics,
            $this->substitution,
            $locator,
            $this,
            $translator
        );
    }

    public function escaper(): Escaper
    {
        return $this->escaper;
    }

    public function filters(): Filters
    {
        return $this->filters;
    }

    public function locator(): TemplateLocator
    {
        return $this->locator;
    }

    // ------------------------------------------------------------------ API

    /**
     * Renders a template **string**.
     *
     * @param array<string, mixed> $vars
     */
    #[\NoDiscard('Rendering without using the result is always a bug.')]
    public function render(string $source, array $vars = [], ?RenderOptions $options = null, string $origin = 'string'): string
    {
        $options ??= new RenderOptions();
        $stats = new RenderStats();
        $stats->start($origin);

        $maxBytes = $this->config->limits->maxTemplateBytes;

        if (strlen($source) > $maxBytes) {
            throw new TemplateException(
                'Template exceeds the configured size limit.',
                ['bytes' => strlen($source), 'limit' => $maxBytes]
            );
        }

        $useCache = $options->cache ?? $this->config->cache->enabled;
        $ttl = $options->ttl ?? $this->config->cache->ttl;
        $cacheKey = $useCache ? $this->cacheKey($source, $vars, $options) : '';

        if ($useCache && $cacheKey !== '') {
            $cached = $this->cache->get($cacheKey);

            if ($cached !== null) {
                $stats->cacheHit = true;
                $stats->stop(strlen($cached));
                $this->events->dispatch('htmlphp.rendered', $stats);

                return $cached;
            }
        }

        // PHP 8.5 pipe operator: the pipeline reads like the docs.
        $applyRenderFilter = fn(string $text): string => ($filtered = $this->events->filter('htmlphp.render', $text, $origin, $vars)) !== null && is_string($filtered)
            ? $filtered
            : $text;

        $finalize = function (string $text) use ($useCache, $cacheKey, $ttl, $stats): string {
            if ($useCache && $cacheKey !== '') {
                $this->cache->set($cacheKey, $text, $ttl);
            }

            $stats->stop(strlen($text));
            $this->events->dispatch('htmlphp.rendered', $stats);

            return $text;
        };

        return $this->renderUncached($source, $vars, $options, $origin, $stats)
            |> $applyRenderFilter
            |> $finalize;
    }

    /**
     * Reads (size-guarded) and renders a template **file**. The path anchors
     * relative SSI includes and becomes the partial-resolution base.
     *
     * @param array<string, mixed> $vars
     */
    #[\NoDiscard]
    public function renderFile(string $path, array $vars = [], ?RenderOptions $options = null): string
    {
        if ($path === '' || str_contains($path, "\0")) {
            throw new TemplateException('The template file path is invalid.', ['path' => $path]);
        }

        $contents = Files::slurp($path, $this->config->limits->maxTemplateBytes);

        if ($contents === null) {
            throw new TemplateNotFoundException(
                "Template file '{$path}' is not readable or exceeds the size limit.",
                ['path' => $path]
            );
        }

        $options ??= new RenderOptions(file: $path);

        if ($options->file === null) {
            $options = new RenderOptions(
                file: $path,
                root: $options->root,
                request: $options->request,
                ssi: $options->ssi,
                structure: $options->structure,
                autoEscape: $options->autoEscape,
                missingVar: $options->missingVar,
                cache: $options->cache,
                ttl: $options->ttl,
                locale: $options->locale,
                ssiVars: $options->ssiVars
            );
        }

        return $this->render($contents, $vars, $options, $path);
    }

    /**
     * Renders a located partial inside a parent render (structure +
     * substitution only; SSI runs once over the assembled document).
     *
     * @param array<string, mixed> $vars
     * @internal used by {@see TreeRenderer}
     */
    public function renderPartial(string $path, array $vars, RenderContext $rc, bool $isolated = false): string
    {
        if ($rc->extendsDepth >= $this->config->limits->maxBlockDepth) {
            $this->diagnostics->record(
                Diagnostics::LOOP_GUARD,
                'Partial/layout nesting is too deep; skipped.',
                ['path' => $path]
            );

            return '';
        }

        $contents = Files::slurp($path, $this->config->limits->maxIncludeBytes);

        if ($contents === null) {
            throw new TemplateNotFoundException(
                "Partial template '{$path}' could not be read.",
                ['path' => $path]
            );
        }

        $nodes = $this->parseCached($contents, $path);
        $rc->stats->trackTemplate($path);

        $previousFile = $rc->currentFile;
        $rc->currentFile = $path;
        $rc->extendsDepth++;

        // Partials with their own @Extends are legal: run the same
        // inheritance dance on a nested context.
        $hasExtends = $this->findExtends($nodes) !== null;

        try {
            if ($hasExtends || $isolated) {
                $subRc = new RenderContext(
                    new Scope($vars),
                    $rc->stats,
                    $this->diagnostics,
                    $rc->autoEscape,
                    $rc->missingVar,
                    $rc->structure
                );
                $subRc->currentFile = $path;

                return $hasExtends
                    ? $this->renderWithInheritance($nodes, $subRc, $path, $vars)
                    : $this->tree->render($nodes, $subRc);
            }

            $rc->scope->push($vars);

            try {
                return $this->tree->render($nodes, $rc);
            } finally {
                $rc->scope->pop();
            }
        } finally {
            $rc->currentFile = $previousFile;
            $rc->extendsDepth--;
        }
    }

    // -------------------------------------------------------------- pipeline

    /**
     * @param array<string, mixed> $vars
     */
    private function renderUncached(
        string $source,
        array $vars,
        RenderOptions $options,
        string $origin,
        RenderStats $stats
    ): string {
        $previousLocale = null;

        if ($options->locale !== null && $options->locale !== '') {
            $previousLocale = $this->translator->locale();
            $this->translator->setLocale($options->locale);
        }

        try {
            $scope = new Scope($vars);
            $rc = new RenderContext(
                $scope,
                $stats,
                $this->diagnostics,
                $options->autoEscape ?? $this->config->syntax->autoEscape,
                $options->missingVar ?? $this->config->syntax->missingVar,
                $options->structure ?? true
            );
            $rc->currentFile = $options->file ?? (is_file($origin) ? $origin : null);

            $this->events->dispatch('htmlphp.render.before', $origin, $vars, $rc);

            if (!$rc->structure) {
                // Structure processing disabled: substitution over raw source.
                $text = $this->substitution->process($source, $scope, $rc->autoEscape, $rc->missingVar);
            } else {
                $nodes = $this->parseCached($source, $origin);
                $text = $this->renderWithInheritance($nodes, $rc, $origin, $vars);
            }

            $text = $this->runSsi($text, $vars, $options, $scope, $rc);

            $this->events->dispatch('htmlphp.render.after', $origin, $text);

            return $text;
        } finally {
            if ($previousLocale !== null) {
                $this->translator->setLocale($previousLocale);
            }
        }
    }

    /**
     * @param list<Node> $nodes
     * @param array<string, mixed> $vars
     */
    private function renderWithInheritance(array $nodes, RenderContext $rc, string $origin, array $vars): string
    {
        $extends = $this->findExtends($nodes);

        if ($extends === null) {
            return $this->tree->render($nodes, $rc);
        }

        // 1. Collect this template's section overrides.
        $rc->collectMode = true;
        $rc->extendsTemplate = $extends;

        try {
            $this->tree->render($nodes, $rc);
        } finally {
            $rc->collectMode = false;
        }

        $overrides = $rc->overrides;

        // 2. Walk up the parent chain.
        $template = $extends;
        $depth = 0;
        $baseDir = $rc->currentFile !== null ? dirname($rc->currentFile) : null;

        while ($template !== null && $template !== '') {
            if (++$depth > 8) {
                throw new TemplateException(
                    'Layout inheritance is too deep (cycle between layouts?).',
                    ['template' => $template, 'depth' => $depth]
                );
            }

            $path = $this->locator->locate($template, $baseDir);

            if ($path === null) {
                throw new TemplateNotFoundException(
                    "Layout template '{$template}' could not be located.",
                    ['template' => $template, 'child' => $origin]
                );
            }

            $contents = Files::slurp($path, $this->config->limits->maxTemplateBytes);

            if ($contents === null) {
                throw new TemplateNotFoundException(
                    "Layout template '{$path}' is not readable.",
                    ['path' => $path]
                );
            }

            $parentNodes = $this->parseCached($contents, $path);
            $rc->stats->trackTemplate($path);
            $parentExtends = $this->findExtends($parentNodes);

            if ($parentExtends !== null) {
                // Intermediate layout: collect its overrides too, keep walking.
                $rc->collectMode = true;
                $previousExtends = $rc->extendsTemplate;
                $rc->extendsTemplate = null;

                try {
                    $this->tree->render($parentNodes, $rc);
                } finally {
                    $rc->collectMode = false;
                }

                $overrides = $rc->overrides;
                $template = $rc->extendsTemplate ?? $parentExtends;
                $baseDir = dirname($path);
                continue;
            }

            // 3. Render the root layout with the merged override stacks.
            $rc->overrides = $overrides;
            $rc->currentFile = $path;

            return $this->tree->render($parentNodes, $rc);
        }

        throw new TemplateException('Layout inheritance ended without a root layout.', ['child' => $origin]);
    }

    /**
     * @param list<Node> $nodes
     */
    private function findExtends(array $nodes): ?string
    {
        // PHP 8.4 array_find(): first matching node, or null.
        $node = array_find($nodes, static fn(Node $candidate): bool => $candidate->kind === 'extends');

        return $node === null ? null : (string) $node->attribute('template', '');
    }

    /**
     * @param array<string, mixed> $vars
     */
    private function runSsi(string $text, array $vars, RenderOptions $options, Scope $scope, RenderContext $rc): string
    {
        $enabled = $options->ssi ?? $this->config->ssi->enabled;

        if (!$enabled || !str_contains($text, '<!--')) {
            return $text;
        }

        $document = new DocumentInfo(
            file: $options->file ?? $rc->currentFile,
            root: $options->root ?? $this->config->ssi->documentRoot,
            request: $options->request,
            vars: [...$vars, ...(is_array($options->ssiVars) ? $options->ssiVars : [])]
        );

        $before = $text;
        $text = $this->ssi->process($text, $document);
        $rc->stats->ssiDirectives += $this->ssi->lastProcessed();

        // One guarded re-substitution pass: SSI-included fragments may
        // contain template tags (the documented successor of v3's passes=2).
        if ($this->config->ssi->processRenderedOutput
            && $text !== $before
            && (str_contains($text, $this->config->syntax->varOpen)
                || str_contains($text, $this->config->syntax->transOpen)
                || str_contains($text, '<!--@'))
        ) {
            $nodes = $this->parseCached($text, 'ssi-output');
            $text = $this->tree->render($nodes, $rc);
        }

        return $text;
    }

    // ------------------------------------------------------------------ misc

    /**
     * @return list<Node>
     */
    private function parseCached(string $source, string $origin): array
    {
        $key = hash('sha1', $source);

        if (isset($this->parsed[$key])) {
            return $this->parsed[$key];
        }

        if (count($this->parsed) >= 512) {
            $oldest = array_key_first($this->parsed);

            if ($oldest !== null) {
                unset($this->parsed[$oldest]);
            }
        }

        return $this->parsed[$key] = $this->parser->parse($source, $origin);
    }

    /** Drops memoized parse trees (deploy hooks, long-running workers). */
    public function clearParsed(): void
    {
        $this->parsed = [];
        $this->locator->clearCache();
    }

    /**
     * @param array<string, mixed> $vars
     */
    private function cacheKey(string $source, array $vars, RenderOptions $options): string
    {
        return hash('sha256', implode('|', [
            Version::VERSION,
            $this->translator->locale(),
            ($options->autoEscape ?? $this->config->syntax->autoEscape) ? '1' : '0',
            ($options->missingVar ?? $this->config->syntax->missingVar)->value,
            ($options->ssi ?? $this->config->ssi->enabled) ? '1' : '0',
            (string) ($options->file ?? ''),
            (string) ($options->root ?? ''),
            hash('sha256', $source),
            hash('sha256', serialize(self::scalarView($vars))),
        ]));
    }

    /**
     * Reduces variables to a serialisable, order-stable scalar view.
     *
     * @param array<array-key, mixed> $vars
     * @return array<array-key, mixed>
     */
    private static function scalarView(array $vars): array
    {
        $view = [];

        foreach ($vars as $key => $value) {
            $view[$key] = match (true) {
                is_array($value) => self::scalarView($value),
                $value instanceof \Stringable => (string) $value,
                is_object($value) => $value::class,
                is_scalar($value), $value === null => $value,
                default => gettype($value),
            };
        }

        ksort($view);

        return $view;
    }
}

/**
 * Variable substitution: `%{NAME|filter:arg}`, `%{= expr |filter:arg}`,
 * `#{NAME}` and `@{KEY}`.
 *
 * v5 adds the inline-expression form `%{= …}` (and `#{= …}`): the payload
 * after `=` is evaluated by the sandboxed {@see Expression} language — the
 * exact evaluator `@If`/`@Set` already use, so no new trust surface opens:
 * no `eval()`, no calls outside the function whitelist, no I/O. Results
 * flow through the same filter chain and auto-escaping as plain names.
 * The form is gated by `syntax.expressions` for hosts that render
 * user-editable templates.
 *
 * v4 differences from v3:
 *  - the legacy forms `%[NAME]`, `%{%{NAME}}` and the html4.pl numeric
 *    directives (`.Round`, `.Div`, …) are gone — use filters
 *    (`%{N|round:2}`, `%{N|pct:total}`) or inline math (`%{= n / total * 100}`);
 *  - `@{KEY}` goes through the injected {@see TranslatorInterface}
 *    (no `Translate.KEY` globals);
 *  - missing-variable handling follows {@see MissingVarPolicy};
 *  - auto-escaping is on by default (config `syntax.auto_escape`), the
 *    `raw` filter opts out per-variable.
 */
final class Substitution
{
    /** Filters that already produce safe output (skip auto-escaping). */
    private const array ESCAPING_FILTERS = [
        'escape', 'esc', 'e', 'attr', 'url', 'json', 'js', 'css', 'nl2br', 'raw',
    ];

    /** @var array<string, true> names/expressions already reported this render */
    private array $reported = [];

    public function __construct(
        private readonly SyntaxConfig $syntax,
        private readonly Limits $limits,
        private readonly Filters $filters,
        private readonly Escaper $escaper,
        private readonly TranslatorInterface $translator,
        private readonly Diagnostics $diagnostics,
    ) {}

    /**
     * Applies every substitution form to `$html` (single pass per form).
     */
    public function process(
        string $html,
        Scope $scope,
        bool $autoEscape,
        MissingVarPolicy $missingPolicy,
    ): string {
        if ($html === '') {
            return '';
        }

        $open = preg_quote($this->syntax->varOpen, '~');
        $close = preg_quote($this->syntax->varClose, '~');
        $alt = preg_quote($this->syntax->altOpen, '~');
        $trans = preg_quote($this->syntax->transOpen, '~');

        // @{KEY} — translation with optional filter chain.
        $html = Pcre::replaceCallback(
            '~' . $trans . '([^{}]*?)\}~',
            function (array $matches) use ($autoEscape): string {
                [$key, $filters] = self::splitFilters((string) $matches[1]);

                if ($key === '') {
                    return $matches[0];
                }

                $value = $this->translator->t($key);

                return $this->finish($value, $filters, $autoEscape);
            },
            $html,
        );

        // #{NAME} — alternate brace form.
        $html = Pcre::replaceCallback(
            '~' . $alt . '([^{}]*?)\}~',
            function (array $matches) use ($scope, $autoEscape, $missingPolicy): string {
                return $this->substitute((string) $matches[1], $matches[0], $scope, $autoEscape, $missingPolicy);
            },
            $html,
        );

        // %{NAME} — the primary form.
        $html = Pcre::replaceCallback(
            '~' . $open . '([^{}]*?)' . $close . '~',
            function (array $matches) use ($scope, $autoEscape, $missingPolicy): string {
                return $this->substitute((string) $matches[1], $matches[0], $scope, $autoEscape, $missingPolicy);
            },
            $html,
        );

        // {NAME} / {= expr} — opt-in single-brace form (off by default: clashes with CSS/JS).
        if ($this->syntax->singleBraces) {
            $html = Pcre::replaceCallback(
                '~(?<![%#@\\\\\w])\{(=[^{}]*|[A-Za-z_][A-Za-z0-9_.]*(?:\|[^{}]*)?)\}(?!\w)~',
                function (array $matches) use ($scope, $autoEscape, $missingPolicy): string {
                    return $this->substitute((string) $matches[1], $matches[0], $scope, $autoEscape, $missingPolicy);
                },
                $html,
            );
        }

        return $html;
    }

    /**
     * Resolves and filters one `%{payload}`-style substitution.
     */
    private function substitute(
        string $payload,
        string $original,
        Scope $scope,
        bool $autoEscape,
        MissingVarPolicy $missingPolicy,
    ): string {
        $trimmed = ltrim($payload);

        // `= expr` — inline expression form (v5). Explicit prefix, so a
        // plain name can never be reinterpreted as an expression and
        // CSS/JS braces stay untouched.
        if (str_starts_with($trimmed, '=')) {
            return $this->substituteExpression(substr($trimmed, 1), $original, $scope, $autoEscape);
        }

        [$name, $filters] = self::splitFilters($payload);

        if ($name === '' || !Str::isValidVariableName($name)) {
            // Not a variable reference at all (CSS, JS, literal braces).
            return $original;
        }

        [$found, $value] = $scope->find($name);

        if (!$found) {
            return $this->missing($name, $original, $missingPolicy);
        }

        return $this->finish($value, $filters, $autoEscape, $scope);
    }

    /**
     * Evaluates one `%{= expr |filters}` payload.
     *
     * Failure handling mirrors `@If`: lenient mode records a diagnostic
     * (once per unique expression) and leaves the tag in the output — a
     * broken expression is visible, never silently blank; strict mode
     * throws. A disabled gate (`syntax.expressions: false`) always leaves
     * the tag untouched without throwing: fail-closed, no evaluation.
     */
    private function substituteExpression(
        string $payload,
        string $original,
        Scope $scope,
        bool $autoEscape,
    ): string {
        if (!$this->syntax->expressions) {
            $this->reportExpression(
                Diagnostics::EXPR_DISABLED,
                'Inline expression is disabled by configuration (syntax.expressions).',
                $payload,
            );

            return $original;
        }

        [$source, $filters] = self::splitExpressionPayload($payload);

        try {
            $value = Expression::evaluate($source, $scope, $this->limits->maxExpressionLength);
        } catch (TemplateException $error) {
            $this->reportExpression(
                Diagnostics::EXPR_INVALID,
                'Invalid inline expression: ' . $error->getMessage(),
                $payload,
            );

            if ($this->syntax->strict) {
                throw $error;
            }

            return $original;
        }

        return $this->finish($value, $filters, $autoEscape, $scope);
    }

    /** Records an expression problem once per unique payload. */
    private function reportExpression(string $code, string $message, string $payload): void
    {
        $payload = trim($payload);
        $key = 'expr:' . substr(sha1($payload), 0, 16);

        if (isset($this->reported[$key])) {
            return;
        }

        $this->reported[$key] = true;
        $this->diagnostics->record($code, $message, ['expression' => $payload]);
    }

    private function missing(string $name, string $original, MissingVarPolicy $policy): string
    {
        if (!isset($this->reported[$name])) {
            $this->reported[$name] = true;
            $this->diagnostics->record(
                Diagnostics::MISSING_VAR,
                'Template variable is not defined.',
                ['name' => $name, 'policy' => $policy->value],
            );
        }

        return match ($policy) {
            MissingVarPolicy::Empty => '',
            MissingVarPolicy::Keep => $original,
            MissingVarPolicy::Placeholder => \sprintf($this->syntax->missingPlaceholderFormat, $name),
            MissingVarPolicy::Throw => throw new TemplateException(
                "Template variable '{$name}' is not defined.",
                ['name' => $name],
            ),
        };
    }

    /**
     * Applies the filter chain, then auto-escapes unless a chain filter
     * already produced safe output (or `raw` was requested).
     *
     * @param list<array{0: string, 1: list<string>}> $filters
     */
    private function finish(mixed $value, array $filters, bool $autoEscape, ?Scope $scope = null): string
    {
        $hasRaw = false;

        foreach ($filters as [$name, $args]) {
            $lower = strtolower($name);

            if ($lower === 'raw') {
                if (!$this->syntax->allowRawFilter) {
                    $this->diagnostics->record(
                        Diagnostics::FILTER_UNKNOWN,
                        'The "raw" filter is disabled by configuration.',
                        [],
                    );

                    continue;
                }

                $hasRaw = true;
                continue;
            }

            if ($lower === 'translate' && $scope !== null) {
                $value = $this->translator->t(Str::stringify($value), $this->translateArgs($args, $scope));
                continue;
            }

            $value = $this->filters->apply($lower, $value, $args);
        }

        $string = Str::stringify($value);

        if (!$autoEscape || $hasRaw) {
            return $string;
        }

        foreach ($filters as [$name]) {
            $lower = strtolower($name);

            if ($lower === 'raw' && !$this->syntax->allowRawFilter) {
                continue; // a disabled raw filter must not suppress escaping
            }

            if (\in_array($lower, self::ESCAPING_FILTERS, true)) {
                return $string;
            }
        }

        return $this->escaper->html($string);
    }

    /**
     * `|translate:'%name%':user.name` style arguments — pairs of
     * placeholder/value resolved against the scope.
     *
     * @param list<string> $args
     * @return array<string, string>
     */
    private function translateArgs(array $args, Scope $scope): array
    {
        $pairs = [];

        for ($index = 0, $count = \count($args); $index + 1 < $count; $index += 2) {
            $placeholder = $args[$index];
            $value = $args[$index + 1];

            [$found, $resolved] = $scope->find($value);

            $pairs[$placeholder] = $found ? Str::stringify($resolved) : $value;
        }

        return $pairs;
    }

    /**
     * Splits `NAME|filter:arg|filter2` into `[name, [[filter, [args]], …]]`.
     *
     * @return array{0: string, 1: list<array{0: string, 1: list<string>}>}
     */
    public static function splitFilters(string $payload): array
    {
        if (!str_contains($payload, '|')) {
            return [trim($payload), []];
        }

        $segments = explode('|', $payload);
        $name = trim((string) array_shift($segments));

        return [$name, self::parseSegments($segments)];
    }

    /**
     * Splits an inline-expression payload `expr | filter:arg | filter2` at
     * **top-level** pipes only: the first separates the expression from the
     * filter chain, the rest separate the filters from each other.
     *
     * Quote-aware — `'|'` inside a string literal belongs to the expression
     * (`%{= 'a|b' | upper }`), and pipes inside `()`/`[]` are never treated
     * as separators (defensive: `|` is not an operator in the expression
     * language). Unterminated quotes simply yield no split; the expression
     * parser then reports the payload as invalid.
     *
     * @return array{0: string, 1: list<array{0: string, 1: list<string>}>}
     */
    public static function splitExpressionPayload(string $payload): array
    {
        $cuts = [];
        $quote = null;
        $depth = 0;
        $length = \strlen($payload);

        for ($index = 0; $index < $length; ++$index) {
            $char = $payload[$index];

            if ($quote !== null) {
                if ($char === '\\' && $index + 1 < $length) {
                    ++$index;
                    continue;
                }

                if ($char === $quote) {
                    $quote = null;
                }

                continue;
            }

            if ($char === "'" || $char === '"') {
                $quote = $char;
                continue;
            }

            if ($char === '(' || $char === '[') {
                ++$depth;
                continue;
            }

            if ($char === ')' || $char === ']') {
                $depth = max(0, $depth - 1);
                continue;
            }

            if ($char === '|' && $depth === 0) {
                $cuts[] = $index;
            }
        }

        if ($cuts === []) {
            return [trim($payload), []];
        }

        $expression = trim(substr($payload, 0, $cuts[0]));
        $segments = [];
        $start = $cuts[0] + 1;

        foreach (\array_slice($cuts, 1) as $cut) {
            $segments[] = substr($payload, $start, $cut - $start);
            $start = $cut + 1;
        }

        $segments[] = substr($payload, $start);

        return [$expression, self::parseSegments($segments)];
    }

    /**
     * @param list<string> $segments
     * @return list<array{0: string, 1: list<string>}>
     */
    public static function parseSegments(array $segments): array
    {
        $filters = [];

        foreach ($segments as $segment) {
            $segment = trim((string) $segment);

            if ($segment === '') {
                continue;
            }

            $parts = self::splitArguments($segment);
            $name = trim((string) array_shift($parts));

            $filters[] = [$name, $parts];
        }

        return $filters;
    }

    /**
     * Splits `name:arg1:'an:arg':arg3` into `[name, arg1, an:arg, arg3]`.
     * Quoted arguments may contain the `:` separator (date formats!);
     * backslashes escape inside quotes.
     *
     * @return list<string>
     */
    public static function splitArguments(string $segment): array
    {
        $parts = [];
        $current = '';
        $quote = null;
        $length = \strlen($segment);

        for ($index = 0; $index < $length; ++$index) {
            $char = $segment[$index];

            if ($quote !== null) {
                if ($char === '\\' && $index + 1 < $length) {
                    $current .= $segment[++$index];
                    continue;
                }

                if ($char === $quote) {
                    $quote = null;
                    continue;
                }

                $current .= $char;
                continue;
            }

            if ($char === "'" || $char === '"') {
                $quote = $char;
                continue;
            }

            if ($char === ':') {
                $parts[] = trim($current);
                $current = '';
                continue;
            }

            $current .= $char;
        }

        $parts[] = trim($current);

        return $parts;
    }
}

/**
 * Parses the comment-tag template syntax into a {@see Node} tree.
 *
 * Recognised tags (`<!--@Name … -->`):
 *
 * | Tag | Form | Notes |
 * |---|---|---|
 * | Loop     | `<!--@Loop rows-->`, `<!--@Loop item in rows-->`, `<!--@Loop k, v in map-->`, `<!--@Loop i in 1..10-->` | `<!--@Else-->` = empty-iterable branch, `<!--@Break-->`/`<!--@Continue-->` honoured, `<!--@EndLoop rows-->` |
 * | If       | `<!--@If EXPR-->` | `<!--@Elif EXPR-->`, `<!--@Else-->`, `<!--@EndIf-->`; EXPR is the safe expression language |
 * | Unless   | `<!--@Unless EXPR-->` | sugar for `If !EXPR` |
 * | Section  | `<!--@Section name-->` | layout slot; override via child template, `<!--@SectionParent-->` inserts the parent default |
 * | Extends  | `<!--@Extends "base.html"-->` | layout inheritance (multi-level) |
 * | Include  | `<!--@Include "card.html" with="a,b" only ignore-missing-->` | scoped partial |
 * | Set      | `<!--@Set total="price * qty"-->` | writes into the current scope frame |
 * | Trans    | `<!--@Trans count="%{n}" domain="d" context="c"-->one<!--@Plural-->%{n} many<!--@EndTrans-->` | gettext-plural block |
 * | Raw      | `<!--@Raw-->…<!--@EndRaw-->` | verbatim |
 * | Comment  | `<!--@Comment-->…<!--@EndComment-->` | dropped |
 * | Break / Continue | `<!--@Break-->`, `<!--@Continue-->` | inside loops |
 *
 * Everything between tags becomes `text` nodes whose raw source is later
 * run through {@see Substitution} (`%{NAME|filters}`, `#{NAME}`, `@{KEY}`).
 */
final class TagParser
{
    /**
     * Tag scanner: name + payload up to the first `-->`.
     *
     * The payload is deliberately permissive (`.*?`): `<!--@If count > 2-->`
     * carries a bare `>` that a quote-aware character class would choke on.
     * Consequence: a literal `-->` inside a quoted attribute value ends the
     * tag early — documented, and the linter flags the fallout.
     */
    private const string TAG_PATTERN = '~<!--@([A-Za-z][A-Za-z0-9]*)(.*?)-->~s';

    private const array OPENERS = ['loop', 'if', 'unless', 'section', 'trans'];
    private const array CLOSERS = [
        'endloop' => 'loop', 'endif' => 'if', 'endunless' => 'unless',
        'endsection' => 'section', 'endtrans' => 'trans',
    ];

    private string $source = '';
    private string $origin = '-';

    /**
     * @return list<Node>
     * @throws TemplateSyntaxException on unbalanced/unknown structure
     */
    public function parse(string $source, string $origin = '-'): array
    {
        $this->source = $source;
        $this->origin = $origin;

        if (!str_contains($source, '<!--@')) {
            return $source === '' ? [] : [self::text($source)];
        }

        $tokens = $this->tokenize($source);
        $root = $this->buildTree($tokens);

        return $root;
    }

    // --------------------------------------------------------------- tokenize

    /**
     * @return list<array{name: string, payload: string, start: int, end: int}>
     */
    private function tokenize(string $source): array
    {
        $tokens = [];
        $count = preg_match_all(self::TAG_PATTERN, $source, $matches, PREG_OFFSET_CAPTURE | PREG_SET_ORDER);

        if ($count === false) {
            throw new TemplateSyntaxException('Template tag scan failed.', ['file' => $this->origin]);
        }

        foreach ($matches as $match) {
            $start = (int) $match[0][1];
            $tokens[] = [
                'name' => strtolower((string) $match[1][0]),
                'payload' => trim((string) $match[2][0]),
                'start' => $start,
                'end' => $start + \strlen((string) $match[0][0]),
            ];
        }

        return $tokens;
    }

    // ------------------------------------------------------------------ tree

    /**
     * @param list<array{name: string, payload: string, start: int, end: int}> $tokens
     * @return list<Node>
     */
    private function buildTree(array $tokens): array
    {
        /** @var list<array{type: string, payload: string, children: list<Node>, branches: list<array{expr: ?string, nodes: list<Node>}>, else: list<Node>, inElse: bool, start: int}> $stack */
        $stack = [];
        $children = [];
        $cursor = 0;
        $skipTo = 0;

        $flushText = function (int $from, int $to) use (&$stack, &$children): void {
            if ($to <= $from) {
                return;
            }

            $slice = substr($this->source, $from, $to - $from);

            if ($slice === '') {
                return;
            }

            if ($stack === []) {
                $children[] = self::text($slice);

                return;
            }

            $top = &$stack[\count($stack) - 1];

            if ($top['inElse']) {
                $top['else'][] = self::text($slice);
            } elseif ($top['branches'] !== [] && ($top['type'] === 'if' || $top['type'] === 'unless')) {
                $last = \count($top['branches']) - 1;
                $top['branches'][$last]['nodes'][] = self::text($slice);
            } else {
                $top['children'][] = self::text($slice);
            }

            unset($top);
        };

        $appendNode = function (Node $node) use (&$stack, &$children): void {
            if ($stack === []) {
                $children[] = $node;

                return;
            }

            $top = &$stack[\count($stack) - 1];

            if ($top['inElse']) {
                $top['else'][] = $node;
            } elseif ($top['branches'] !== [] && ($top['type'] === 'if' || $top['type'] === 'unless')) {
                $last = \count($top['branches']) - 1;
                $top['branches'][$last]['nodes'][] = $node;
            } else {
                $top['children'][] = $node;
            }

            unset($top);
        };

        $count = \count($tokens);

        for ($index = 0; $index < $count; ++$index) {
            $token = $tokens[$index];

            if ($token['start'] < $skipTo) {
                continue; // inside a Raw/Comment slice
            }

            $flushText($cursor, $token['start']);
            $cursor = $token['end'];
            $name = $token['name'];
            $payload = $token['payload'];

            // ---- verbatim regions -------------------------------------
            if ($name === 'raw' || $name === 'comment') {
                $endTag = '<!--@End' . ($name === 'raw' ? 'Raw' : 'Comment');
                $close = $this->findCi($endTag, $token['end']);

                if ($close === null) {
                    throw $this->error('Unclosed <!--@' . ucfirst($name) . '--> block.', $token['start']);
                }

                $closeEnd = strpos($this->source, '-->', $close);
                $closeEnd = $closeEnd === false ? \strlen($this->source) : $closeEnd + 3;

                if ($name === 'raw') {
                    $appendNode(new Node('raw', [
                        'value' => substr($this->source, $token['end'], $close - $token['end']),
                    ]));
                }

                $skipTo = $closeEnd;
                $cursor = $closeEnd;
                continue;
            }

            // ---- openers ----------------------------------------------
            if (\in_array($name, self::OPENERS, true)) {
                if ($name === 'trans' && $stack !== [] && $stack[\count($stack) - 1]['type'] === 'trans') {
                    throw $this->error('Nested <!--@Trans--> blocks are not allowed.', $token['start']);
                }

                $stack[] = [
                    'type' => $name,
                    'payload' => $payload,
                    'children' => [],
                    'branches' => $name === 'if' || $name === 'unless'
                        ? [['expr' => $name === 'unless' ? self::negate($payload) : $payload, 'nodes' => []]]
                        : [],
                    'else' => [],
                    'inElse' => false,
                    'start' => $token['start'],
                ];
                continue;
            }

            // ---- closers ----------------------------------------------
            if (isset(self::CLOSERS[$name])) {
                $expected = self::CLOSERS[$name];

                if ($stack === [] || $stack[\count($stack) - 1]['type'] !== $expected) {
                    throw $this->error(
                        'Unexpected <!--@' . $name . '-->'
                        . ($stack === [] ? ' without an opener.' : ' inside <!--@' . $stack[\count($stack) - 1]['type'] . '-->.'),
                        $token['start'],
                    );
                }

                $frame = array_pop($stack);
                $appendNode($this->frameToNode($frame, $token['start']));
                continue;
            }

            // ---- mid markers -------------------------------------------
            if ($name === 'else' || $name === 'elif' || $name === 'plural') {
                if ($stack === []) {
                    throw $this->error('Unexpected <!--@' . ucfirst($name) . '--> without an opener.', $token['start']);
                }

                $top = &$stack[\count($stack) - 1];

                if ($name === 'plural') {
                    if ($top['type'] !== 'trans') {
                        throw $this->error('<!--@Plural--> is only valid inside <!--@Trans-->.', $token['start']);
                    }

                    $top['inElse'] = true; // plural body reuses the else slot
                    unset($top);
                    continue;
                }

                if ($top['type'] === 'if' || $top['type'] === 'unless') {
                    if ($name === 'else') {
                        $top['inElse'] = true;
                    } else {
                        if ($top['inElse']) {
                            throw $this->error('<!--@Elif--> after <!--@Else-->.', $token['start']);
                        }

                        $top['branches'][] = ['expr' => $payload, 'nodes' => []];
                    }
                } elseif ($top['type'] === 'loop') {
                    if ($name !== 'else') {
                        throw $this->error('<!--@Elif--> is not valid inside <!--@Loop-->.', $token['start']);
                    }

                    $top['inElse'] = true;
                } else {
                    throw $this->error('<!--@' . ucfirst($name) . '--> is not valid inside <!--@' . $top['type'] . '-->.', $token['start']);
                }

                unset($top);
                continue;
            }

            // ---- standalone --------------------------------------------
            $node = $this->standaloneNode($name, $payload, $token['start']);

            if ($node !== null) {
                $appendNode($node);
                continue;
            }

            throw $this->error('Unknown template tag "' . $name . '".', $token['start']);
        }

        $flushText($cursor, \strlen($this->source));

        if ($stack !== []) {
            $frame = $stack[\count($stack) - 1];
            throw $this->error('Unclosed <!--@' . ucfirst((string) $frame['type']) . '--> block.', (int) $frame['start']);
        }

        return $children;
    }

    /**
     * @param array{type: string, payload: string, children: list<Node>, branches: list<array{expr: ?string, nodes: list<Node>}>, else: list<Node>, inElse: bool, start: int} $frame
     */
    private function frameToNode(array $frame, int $offset): Node
    {
        $line = $this->line($offset);

        return match ($frame['type']) {
            'loop' => new Node('loop', [
                'spec' => self::parseLoopSpec($frame['payload'], $line),
                'else' => $frame['else'],
                'line' => $line,
            ], $frame['children']),
            'if', 'unless' => new Node('if', [
                'branches' => $frame['branches'],
                'else' => $frame['else'],
                'line' => $line,
            ]),
            'section' => new Node('section', [
                'name' => self::bareName($frame['payload'], $line),
                'line' => $line,
            ], $frame['children']),
            'trans' => new Node('trans', [
                'attrs' => Attributes::parse($frame['payload']),
                'singular' => $frame['children'],
                'plural' => $frame['else'],
                'line' => $line,
            ]),
            default => throw $this->error('Internal parser error for frame "' . $frame['type'] . '".', $offset),
        };
    }

    private function standaloneNode(string $name, string $payload, int $offset): ?Node
    {
        $line = $this->line($offset);

        return match ($name) {
            'extends' => new Node('extends', ['template' => self::bareName($payload, $line), 'line' => $line]),
            'sectionparent' => new Node('section-parent', ['line' => $line]),
            'include' => self::includeNode($payload, $line),
            'set' => self::setNode($payload, $line),
            'break' => new Node('break', ['line' => $line]),
            'continue' => new Node('continue', ['line' => $line]),
            default => null,
        };
    }

    private static function includeNode(string $payload, int $line): Node
    {
        $flags = [];

        foreach (['ignore-missing', 'ignore_missing', 'only', 'missing'] as $flag) {
            if (preg_match('~(?:^|\s)' . preg_quote($flag, '~') . '(?:\s|$)~i', $payload) === 1) {
                $flags[str_replace('_', '-', $flag)] = true;
                $payload = trim((string) preg_replace('~(?:^|\s)' . preg_quote($flag, '~') . '(?:\s|$)~i', ' ', $payload));
            }
        }

        $attributes = Attributes::parse($payload);

        // The template reference is either quoted or the leftover bare word.
        $template = '';

        if (preg_match('~^(?:"([^"]*)"|\'([^\']*)\')~', $payload, $m) === 1) {
            $template = (string) ($m[1] !== '' ? $m[1] : ($m[2] ?? ''));
        } else {
            $leftover = trim(preg_replace('~[A-Za-z_][A-Za-z0-9_-]*\s*=\s*(?:"[^"]*"|\'[^\']*\'|[^\s"\']+)~', ' ', $payload) ?? $payload);
            $template = trim($leftover, " \t\n\r\"'");
        }

        $with = isset($attributes['with']) && $attributes['with'] !== ''
            ? array_values(array_filter(array_map(
                static fn(string $part): string => trim($part),
                explode(',', $attributes['with']),
            ), static fn(string $part): bool => $part !== ''))
            : null;

        return new Node('include', [
            'template' => $template,
            'with' => $with,
            'only' => isset($flags['only']),
            'ignoreMissing' => isset($flags['ignore-missing']) || isset($flags['missing']),
            'line' => $line,
        ]);
    }

    private static function setNode(string $payload, int $line): Node
    {
        $attributes = Attributes::parse($payload);

        if (isset($attributes['name']) || isset($attributes['var'])) {
            return new Node('set', [
                'name' => (string) ($attributes['name'] ?? $attributes['var']),
                'expr' => (string) ($attributes['value'] ?? ''),
                'line' => $line,
            ]);
        }

        // `<!--@Set total="price * qty" -->` — single name="expr" attribute.
        if (\count($attributes) === 1) {
            $name = (string) array_key_first($attributes);

            if (preg_match('~^[A-Za-z_][A-Za-z0-9_.]*$~', $name) === 1) {
                return new Node('set', ['name' => $name, 'expr' => (string) $attributes[$name], 'line' => $line]);
            }
        }

        // `<!--@Set total = price * qty -->` — bare form.
        if (preg_match('~^([A-Za-z_][A-Za-z0-9_.]*)\s*=\s*(.+)$~s', $payload, $m) === 1) {
            return new Node('set', ['name' => $m[1], 'expr' => trim($m[2]), 'line' => $line]);
        }

        throw new TemplateSyntaxException(
            '<!--@Set--> requires name="expression" syntax.',
            ['payload' => $payload, 'line' => $line],
        );
    }

    /**
     * Parses the four loop header forms.
     *
     * @return array{mode: string, source: string, value: ?string, key: ?string, to: ?string, line: int}
     */
    public static function parseLoopSpec(string $payload, int $line = 0): array
    {
        $payload = trim($payload);

        if ($payload === '') {
            throw new TemplateSyntaxException('<!--@Loop--> requires an iterable name.', ['line' => $line]);
        }

        // "k, v in source" | "v in source" | "i in 1..10"
        if (preg_match('~^(?:([A-Za-z_][A-Za-z0-9_.]*)\s*,\s*)?([A-Za-z_][A-Za-z0-9_.]*)\s+in\s+(.+)$~is', $payload, $m) === 1) {
            $source = trim((string) $m[3]);

            if (preg_match('~^(-?\d+)\s*\.\.\s*(-?\d+)$~', $source, $range) === 1) {
                return [
                    'mode' => 'range', 'source' => $range[1], 'value' => (string) $m[2],
                    'key' => $m[1] !== '' ? (string) $m[1] : null, 'to' => $range[2], 'line' => $line,
                ];
            }

            return [
                'mode' => $m[1] !== '' ? 'kv' : 'alias',
                'source' => $source,
                'value' => (string) $m[2],
                'key' => $m[1] !== '' ? (string) $m[1] : null,
                'to' => null,
                'line' => $line,
            ];
        }

        // range without alias is not valid; plain iterable name:
        if (preg_match('~^[A-Za-z_][A-Za-z0-9_.]*$~', $payload) === 1) {
            return ['mode' => 'rows', 'source' => $payload, 'value' => null, 'key' => null, 'to' => null, 'line' => $line];
        }

        throw new TemplateSyntaxException(
            'Cannot parse <!--@Loop--> header.',
            ['payload' => $payload, 'line' => $line],
        );
    }

    private static function bareName(string $payload, int $line): string
    {
        $payload = trim($payload);

        if (preg_match('~^(?:"([^"]*)"|\'([^\']*)\')$~', $payload, $m) === 1) {
            $payload = (string) ($m[1] !== '' ? $m[1] : ($m[2] ?? ''));
        }

        $payload = trim($payload);

        if ($payload === '' || preg_match('~^[\w.@/-]+$~', $payload) !== 1) {
            throw new TemplateSyntaxException('Expected a quoted template name or identifier.', [
                'payload' => $payload, 'line' => $line,
            ]);
        }

        return $payload;
    }

    private static function negate(string $expression): string
    {
        $expression = trim($expression);

        return str_starts_with($expression, '!') ? substr($expression, 1) : '!' . $expression;
    }

    private static function text(string $value): Node
    {
        return new Node('text', ['value' => $value]);
    }

    private function findCi(string $needle, int $offset): ?int
    {
        $position = stripos($this->source, $needle, $offset);

        return $position === false ? null : $position;
    }

    private function line(int $offset): int
    {
        return substr_count($this->source, "\n", 0, max(0, min($offset, \strlen($this->source)))) + 1;
    }

    private function error(string $message, int $offset): TemplateSyntaxException
    {
        return new TemplateSyntaxException($message, [
            'file' => $this->origin,
            'line' => $this->line($offset),
        ]);
    }
}

/**
 * Resolves template names to files.
 *
 * Search order: `@namespace/name` roots first, then each configured
 * `templates.paths` root, then (for partials) the directory of the
 * including document. The default extension is appended when the name
 * has none. Everything passes through {@see PathGuard}: absolute paths,
 * traversal outside the roots and denied extensions (`*.php`, `*.env`, …)
 * are rejected — template *data* can never make the engine read an
 * arbitrary file.
 */
final class TemplateLocator
{
    /** @var array<string, PathGuard> per-root guards */
    private array $guards = [];

    /** @var array<string, string|false> memoized name => realpath (false = miss) */
    private array $resolved = [];

    public function __construct(
        private readonly TemplatesConfig $config,
        private readonly SecurityConfig $security,
    ) {}

    private function guardFor(string $root): PathGuard
    {
        return $this->guards[$root] ??= new PathGuard([$root], $this->security->deniedExtensions, false);
    }

    /**
     * @param string|null $baseDir directory of the including document
     *        (partials may resolve relative to their parent template)
     */
    public function locate(string $name, ?string $baseDir = null): ?string
    {
        $name = trim($name);

        if ($name === '' || str_contains($name, "\0")) {
            return null;
        }

        $key = $name . '|' . ($baseDir ?? '');

        if (\array_key_exists($key, $this->resolved)) {
            $cached = $this->resolved[$key];

            return $cached === false ? null : $cached;
        }

        $path = $this->search($name, $baseDir);
        $this->resolved[$key] = $path ?? false;

        return $path;
    }

    private function search(string $name, ?string $baseDir): ?string
    {
        // Absolute references are template-data attacks; refuse them.
        if (str_starts_with($name, '/') || preg_match('~^[A-Za-z]:[\\\\/]~', $name) === 1) {
            return null;
        }

        [$namespace, $relative] = $this->splitNamespace($name);

        $roots = $namespace !== null
            ? (isset($this->config->namespaces[$namespace]) ? [$this->config->namespaces[$namespace]] : [])
            : $this->config->paths;

        if ($namespace === null && $baseDir !== null && $baseDir !== '') {
            // Partials resolve relative to the including document first.
            $roots = [$baseDir, ...$roots];
        }

        foreach ($this->candidates($relative) as $candidate) {
            foreach ($roots as $root) {
                $root = (string) $root;
                $resolved = $this->guardFor($root)->resolve($candidate, $root);

                if ($resolved !== null) {
                    return $resolved;
                }
            }
        }

        return null;
    }

    /**
     * Name variants to try: verbatim, then with the default extension.
     *
     * @return list<string>
     */
    private function candidates(string $name): array
    {
        $candidates = [$name];

        $extension = $this->config->extension;

        if ($extension !== '' && !str_ends_with($name, $extension)) {
            $candidates[] = $name . $extension;
        }

        return $candidates;
    }

    /** @return array{0: ?string, 1: string} [namespace, relative] */
    private function splitNamespace(string $name): array
    {
        if (str_starts_with($name, '@') && preg_match('~^@([A-Za-z0-9_-]+)/(.+)$~', $name, $m) === 1) {
            return [$m[1], $m[2]];
        }

        return [null, ltrim($name, '@')];
    }

    public function clearCache(): void
    {
        $this->resolved = [];
    }

    /** @return list<string> */
    public function roots(): array
    {
        return $this->config->paths;
    }
}

/**
 * Walks the parsed {@see Node} tree and produces output.
 *
 * Handles loops (four header forms, magic variables, `@Else`, `@Break`,
 * `@Continue`, row/depth guards), expression conditionals, layout sections
 * (with `@SectionParent`), scoped partials, `@Set` and `@Trans` blocks.
 * Text nodes are delegated to {@see Substitution}.
 */
final class TreeRenderer
{
    public function __construct(
        private readonly Config $config,
        private readonly Diagnostics $diagnostics,
        private readonly Substitution $substitution,
        private readonly TemplateLocator $locator,
        private readonly Renderer $renderer,
        private readonly TranslatorInterface $translator,
    ) {}

    /**
     * @param list<Node> $nodes
     */
    public function render(array $nodes, RenderContext $rc): string
    {
        $output = '';

        foreach ($nodes as $node) {
            $output .= $this->renderNode($node, $rc);
        }

        return $output;
    }

    private function renderNode(Node $node, RenderContext $rc): string
    {
        return match ($node->kind) {
            'text' => $this->renderText((string) $node->attribute('value', ''), $rc),
            'raw' => (string) $node->attribute('value', ''),
            'loop' => $this->renderLoop($node, $rc),
            'if' => $this->renderIf($node, $rc),
            'section' => $this->renderSection($node, $rc),
            'section-parent' => $this->renderSectionParent($rc),
            'extends' => $this->registerExtends($node, $rc),
            'include' => $this->renderInclude($node, $rc),
            'set' => $this->renderSet($node, $rc),
            'trans' => $this->renderTrans($node, $rc),
            'break' => throw new LoopSignal('break'),
            'continue' => throw new LoopSignal('continue'),
            default => throw new TemplateException('Unknown node kind.', ['kind' => $node->kind]),
        };
    }

    private function renderText(string $text, RenderContext $rc): string
    {
        if ($text === '') {
            return '';
        }

        if ($rc->collectMode) {
            return ''; // child-of-layout: only sections contribute output
        }

        $rc->stats->substitutions++;

        return $this->substitution->process($text, $rc->scope, $rc->autoEscape, $rc->missingVar);
    }

    // ------------------------------------------------------------------ loops

    private function renderLoop(Node $node, RenderContext $rc): string
    {
        /** @var array{mode: string, source: string, value: ?string, key: ?string, to: ?string, line: int} $spec */
        $spec = $node->attribute('spec');

        if ($rc->loopDepth >= $this->config->limits->maxLoopDepth) {
            $this->diagnostics->record(
                Diagnostics::LOOP_GUARD,
                'Loop nesting is too deep; block skipped.',
                ['line' => $spec['line'] ?? 0],
            );

            return '';
        }

        $rc->stats->loops++;

        $rows = $this->loopIterable($spec, $rc);
        $total = \count($rows);

        if ($total === 0) {
            $else = $node->attribute('else', []);

            return $rc->collectMode ? '' : $this->render($else, $rc);
        }

        $output = '';
        $maxRows = $this->config->limits->maxLoopRows;
        $truncated = false;
        $index = 0;
        $rc->loopDepth++;

        try {
            foreach ($rows as $key => $row) {
                if ($index >= $maxRows) {
                    $truncated = true;
                    break;
                }

                $frame = $this->loopFrame($spec, $key, $row, $index, $total);
                $rc->scope->push($frame);
                $rc->stats->loopRows++;

                try {
                    $output .= $this->render($node->children, $rc);
                } catch (LoopSignal $signal) {
                    if ($signal->kind === 'break') {
                        $rc->scope->pop();
                        break;
                    }
                    // continue: fall through to pop + next iteration
                }

                $rc->scope->pop();
                $index++;
            }
        } finally {
            $rc->loopDepth--;
        }

        if ($truncated) {
            $this->diagnostics->record(
                Diagnostics::LOOP_GUARD,
                \sprintf('Loop truncated at the configured row limit (%d).', $maxRows),
                ['source' => $spec['source'], 'limit' => $maxRows],
            );
        }

        return $output;
    }

    /**
     * Materialises the iterable described by the loop spec.
     *
     * @param array{mode: string, source: string, value: ?string, key: ?string, to: ?string} $spec
     * @return array<array-key, mixed>
     */
    private function loopIterable(array $spec, RenderContext $rc): array
    {
        if ($spec['mode'] === 'range') {
            $from = (int) Str::numericValue($spec['source']);
            $to = (int) Str::numericValue((string) $spec['to']);

            // Generate at most maxLoopRows+1 values so the iteration guard
            // performs the (diagnosed) truncation uniformly for all modes.
            $limit = $this->config->limits->maxLoopRows;
            $step = $from <= $to ? 1 : -1;
            $cappedTo = abs($to - $from) > $limit ? $from + $step * $limit : $to;

            return range($from, $cappedTo, $step);
        }

        $source = $spec['source'];

        // The source may be a dotted name or a small expression.
        $value = strpbrk($source, ' +-*~/()') !== false
            ? Expression::evaluate($source, $rc->scope, $this->config->limits->maxExpressionLength)
            : ($rc->scope->find($source)[0] ? $rc->scope->get($source) : null);

        if ($value === null) {
            if (!$rc->scope->has($source)) {
                $this->diagnostics->record(
                    Diagnostics::MISSING_VAR,
                    'Loop source is not defined; treated as empty.',
                    ['name' => $source],
                );
            }

            return [];
        }

        return self::normalizeIterable($value);
    }

    /**
     * Arrays, Countable/Traversable objects, public-property objects and
     * scalars (single-row loops, exposed as `value`) all iterate.
     *
     * @return array<array-key, mixed>
     */
    public static function normalizeIterable(mixed $value): array
    {
        if (\is_array($value)) {
            return $value;
        }

        if ($value instanceof \Traversable) {
            return iterator_to_array($value);
        }

        if ($value instanceof \ArrayAccess && $value instanceof \Countable) {
            $items = [];
            $total = \count($value);

            for ($index = 0; $index < $total; ++$index) {
                $items[$index] = $value[$index];
            }

            return $items;
        }

        if (\is_object($value)) {
            return get_object_vars($value);
        }

        if ($value === null || $value === '') {
            return [];
        }

        return [0 => $value];
    }

    /**
     * Builds the scope frame for one row: aliases per spec mode, row fields
     * (rows mode, v3-compatible shadowing) and the magic variables.
     *
     * @param array{mode: string, source: string, value: ?string, key: ?string, to: ?string} $spec
     * @return array<string, mixed>
     */
    private function loopFrame(array $spec, string|int $key, mixed $row, int $index, int $total): array
    {
        $frame = [];

        if ($spec['mode'] === 'rows') {
            // v3 semantics: the row's own fields enter the scope directly.
            if (\is_array($row) || \is_object($row)) {
                foreach (self::normalizeIterable($row) as $name => $field) {
                    $frame[(string) $name] = $field;
                }
            }

            $frame['value'] = $row;
        } else {
            if ($spec['value'] !== null) {
                $frame[$spec['value']] = $row;
            }

            if ($spec['key'] !== null) {
                $frame[$spec['key']] = $key;
            }
        }

        $first = $index === 0;
        $last = $index === $total - 1;

        $frame['_index'] = $index;
        $frame['_position'] = $index + 1;
        $frame['_key'] = $key;
        $frame['_first'] = $first;
        $frame['_last'] = $last;
        $frame['_count'] = $total;
        $frame['_odd'] = $index % 2 === 1;
        $frame['_even'] = $index % 2 === 0;
        $frame['loop'] = [
            'index' => $index + 1,
            'index0' => $index,
            'first' => $first,
            'last' => $last,
            'length' => $total,
            'key' => $key,
        ];

        return $frame;
    }

    // ------------------------------------------------------------ conditionals

    private function renderIf(Node $node, RenderContext $rc): string
    {
        if ($rc->collectMode) {
            return '';
        }

        $rc->stats->conditionals++;

        /** @var list<array{expr: ?string, nodes: list<Node>}> $branches */
        $branches = $node->attribute('branches', []);

        foreach ($branches as $branch) {
            $expression = trim((string) ($branch['expr'] ?? ''));

            if ($expression === '' || $this->branchTruthy($expression, $rc)) {
                return $this->render($branch['nodes'], $rc);
            }
        }

        /** @var list<Node> $else */
        $else = $node->attribute('else', []);

        return $this->render($else, $rc);
    }

    private function branchTruthy(string $expression, RenderContext $rc): bool
    {
        try {
            return Expression::truthy(
                Expression::evaluate($expression, $rc->scope, $this->config->limits->maxExpressionLength),
            );
        } catch (TemplateException $error) {
            if ($this->config->syntax->strict) {
                throw $error;
            }

            $this->diagnostics->record(
                Diagnostics::TEMPLATE_LINT,
                'Invalid condition expression; branch skipped: ' . $error->getMessage(),
                ['expression' => $expression],
            );

            return false;
        }
    }

    // ------------------------------------------------------- layout sections

    private function renderSection(Node $node, RenderContext $rc): string
    {
        $name = (string) $node->attribute('name', '');

        if ($rc->collectMode) {
            $rc->pushOverride($name, $node->children);
            $rc->stats->sections++;

            return '';
        }

        return $this->renderSectionLevel($name, 0, $node->children, $rc);
    }

    /**
     * @param list<Node> $defaultNodes
     */
    private function renderSectionLevel(string $name, int $level, array $defaultNodes, RenderContext $rc): string
    {
        $nodes = $rc->sectionNodes($name, $level, $defaultNodes);

        $rc->sectionFrames[] = [$name, $level, $defaultNodes];
        $rc->stats->sections++;

        try {
            return $this->render($nodes, $rc);
        } finally {
            array_pop($rc->sectionFrames);
        }
    }

    private function renderSectionParent(RenderContext $rc): string
    {
        $frame = $rc->sectionFrames[array_key_last($rc->sectionFrames)] ?? null;

        if ($frame === null) {
            $this->diagnostics->record(
                Diagnostics::TEMPLATE_LINT,
                '<!--@SectionParent--> used outside of a section.',
            );

            return '';
        }

        [$name, $level, $defaultNodes] = $frame;

        return $this->renderSectionLevel($name, $level + 1, $defaultNodes, $rc);
    }

    private function registerExtends(Node $node, RenderContext $rc): string
    {
        if ($rc->extendsTemplate === null) {
            $rc->extendsTemplate = (string) $node->attribute('template', '');
        }

        return '';
    }

    // --------------------------------------------------------------- partials

    private function renderInclude(Node $node, RenderContext $rc): string
    {
        if ($rc->collectMode) {
            return '';
        }

        $template = (string) $node->attribute('template', '');
        $ignoreMissing = (bool) $node->attribute('ignoreMissing', false);
        $only = (bool) $node->attribute('only', false);
        /** @var list<string>|null $with */
        $with = $node->attribute('with');

        $baseDir = $rc->currentFile !== null ? \dirname($rc->currentFile) : null;
        $path = $this->locator->locate($template, $baseDir);

        if ($path === null) {
            if ($ignoreMissing) {
                return '';
            }

            throw new TemplateNotFoundException(
                "Partial template '{$template}' could not be located.",
                ['template' => $template, 'line' => $node->attribute('line')],
            );
        }

        $isolated = $only || $with !== null;
        $frame = [];

        if (!$isolated) {
            $frame = $rc->scope->all();
        } elseif ($with !== null) {
            foreach ($with as $name) {
                [$found, $value] = $rc->scope->find($name);

                if ($found) {
                    $frame[$name] = $value;
                }
            }
        }

        $rc->stats->includes++;

        return $this->renderer->renderPartial($path, $frame, $rc, $isolated);
    }

    // ------------------------------------------------------------------- set

    private function renderSet(Node $node, RenderContext $rc): string
    {
        $name = (string) $node->attribute('name', '');
        $expression = (string) $node->attribute('expr', '');

        if ($name === '' || !Str::isValidVariableName($name)) {
            $this->diagnostics->record(
                Diagnostics::TEMPLATE_LINT,
                '<!--@Set--> target name is invalid.',
                ['name' => $name],
            );

            return '';
        }

        $value = Expression::evaluate($expression, $rc->scope, $this->config->limits->maxExpressionLength);
        $rc->scope->set($name, $value);

        return '';
    }

    // ----------------------------------------------------------------- trans

    private function renderTrans(Node $node, RenderContext $rc): string
    {
        if ($rc->collectMode) {
            return '';
        }

        /** @var list<Node> $singular */
        $singular = $node->attribute('singular', []);
        /** @var list<Node> $plural */
        $plural = $node->attribute('plural', []);
        /** @var array<string, string> $attrs */
        $attrs = $node->attribute('attrs', []);

        [$msgid, $args] = $this->msgidOf($singular, $rc);

        if ($msgid === null) {
            // Non-text content inside @Trans: render as a normal fragment.
            return $this->render($singular, $rc);
        }

        $domain = $attrs['domain'] ?? null;
        $context = $attrs['context'] ?? '';
        $rc->stats->translations++;

        if (isset($attrs['count']) && $attrs['count'] !== '' && $plural !== []) {
            [$pluralId] = $this->msgidOf($plural, $rc);
            $count = $this->countOf($attrs['count'], $rc);
            $args['count'] = Str::stringify($count);

            // The translator interpolates {0}, {1}, … and {count} itself.
            return $context !== ''
                ? $this->translator->nx($msgid, (string) $pluralId, $count, $context, $args, $domain)
                : $this->translator->n($msgid, (string) $pluralId, $count, $args, $domain);
        }

        return $context !== ''
            ? $this->translator->x($msgid, $context, $args, $domain)
            : $this->translator->t($msgid, $args, $domain);
    }

    /**
     * Derives the msgid and positional arguments from a trans body:
     * `%{expr}`/`#{expr}` become `{n}` placeholders, evaluated against the
     * current scope. Returns `null` when the body contains structure tags
     * (which cannot be part of a gettext message id).
     *
     * @param list<Node> $nodes
     * @return array{0: string|null, 1: array<array-key, string>}
     */
    private function msgidOf(array $nodes, RenderContext $rc): array
    {
        $msgid = '';
        $args = [];
        $index = 0;

        foreach ($nodes as $node) {
            if ($node->kind !== 'text') {
                return [null, []];
            }

            $text = (string) $node->attribute('value', '');

            $text = \HtmlPhp\Support\Pcre::replaceCallback(
                '~[%#]\{([^{}]*)\}~',
                function (array $m) use ($rc, &$args, &$index): string {
                    $payload = trim((string) $m[1]);
                    $placeholder = '{' . $index . '}';

                    $rendered = $this->substitution->process(
                        '%{' . $payload . '}',
                        $rc->scope,
                        false,
                        $rc->missingVar,
                    );

                    // Keys are the bare indices; Translator::interpolate()
                    // wraps them into `{0}`, `{1}`, … placeholders.
                    $args[(string) $index] = $rc->autoEscape
                        ? $this->renderer->escaper()->html($rendered)
                        : $rendered;
                    $index++;

                    return $placeholder;
                },
                $text,
            );

            $msgid .= $text;
        }

        return [trim((string) preg_replace('~\s+~', ' ', $msgid)), $args];
    }

    private function countOf(string $attribute, RenderContext $rc): int
    {
        if (str_contains($attribute, '{')) {
            $rendered = $this->substitution->process($attribute, $rc->scope, false, $rc->missingVar);

            return (int) Str::numericValue($rendered);
        }

        $value = Expression::evaluate($attribute, $rc->scope, $this->config->limits->maxExpressionLength);

        return (int) Str::numericValue($value);
    }

}

}

namespace HtmlPhp\WordPress\Maintenance {

use HtmlPhp\Exception\TemplateException;

final class Assets
{
    private function __construct() {}

    /**
     * Enqueues a stylesheet; the version is the file mtime when the file
     * is readable, so deploys bust proxies and browser caches.
     *
     * @param list<string> $deps
     */
    public static function style(string $handle, string $src, array $deps = [], string $media = 'all'): void
    {
        self::enqueue('style', $handle, $src, $deps, $media);
    }

    /**
     * @param list<string> $deps
     */
    public static function script(string $handle, string $src, array $deps = [], bool $inFooter = true): void
    {
        self::enqueue('script', $handle, $src, $deps, null, $inFooter);
    }


    /** @param list<string> $deps */
    private static function enqueue(string $kind, string $handle, string $src, array $deps, ?string $media, bool $inFooter = false): void
    {
        $version = self::version($src);

        if ($kind === 'style') {
            if (\function_exists('wp_register_style')) {
                wp_register_style($handle, $src, $deps, $version, $media);
            }

            if (\function_exists('wp_enqueue_style')) {
                wp_enqueue_style($handle);
            }

            return;
        }

        if (\function_exists('wp_register_script')) {
            wp_register_script($handle, $src, $deps, $version, $inFooter);
        }

        if (\function_exists('wp_enqueue_script')) {
            wp_enqueue_script($handle);
        }
    }

    /**
     * Resolves the cache-busting version for a URL or path.
     */
    public static function version(string $src): string
    {
        $path = $src;

        if (preg_match('~^https?://~i', $path) === 1) {
            if (\function_exists('home_url')) {
                $home = (string) home_url();

                if ($home !== '' && str_starts_with($path, $home)) {
                    $relative = substr($path, \strlen($home));

                    if (\function_exists('wp_normalize_path') && \defined('ABSPATH')) {
                        $path = rtrim((string) \ABSPATH, '/\\') . '/' . ltrim($relative, '/');
                    }
                }
            }
        }

        if (is_file($path)) {
            $mtime = @filemtime($path);

            if ($mtime !== false) {
                return (string) $mtime;
            }
        }

        return \HtmlPhp\Version::VERSION;
    }
}

final class Cron
{
    private function __construct() {}

    /**
     * Schedules a recurring event when it is not already scheduled.
     *
     * @param list<mixed> $args
     */
    public static function schedule(string $hook, string $recurrence = 'daily', array $args = []): bool
    {
        if (!\function_exists('wp_next_scheduled')) {
            throw new TemplateException('WP-Cron is not available.');
        }

        if (wp_next_scheduled($hook, $args) !== false) {
            return false;
        }

        return (bool) wp_schedule_event(time(), $recurrence, $hook, $args);
    }

    /**
     * @param list<mixed> $args
     */
    public static function unschedule(string $hook, array $args = []): bool
    {
        if (!\function_exists('wp_next_scheduled')) {
            throw new TemplateException('WP-Cron is not available.');
        }

        $timestamp = wp_next_scheduled($hook, $args);

        if ($timestamp === false) {
            return false;
        }

        return (bool) wp_unschedule_event((int) $timestamp, $hook, $args);
    }

    /**
     * @param list<mixed> $args
     */
    public static function next(string $hook, array $args = []): ?int
    {
        if (!\function_exists('wp_next_scheduled')) {
            return null;
        }

        $timestamp = wp_next_scheduled($hook, $args);

        return $timestamp === false ? null : (int) $timestamp;
    }

    /**
     * True when native WP-Cron appears to be disabled (external cron in use).
     */
    public static function disabledByConstant(): bool
    {
        return \defined('DISABLE_WP_CRON') && \DISABLE_WP_CRON === true;
    }
}

final class Db
{
    private function __construct() {}

    /**
     * The global $wpdb instance (or null outside WordPress).
     */
    public static function wpdb(): ?object
    {
        $wpdb = $GLOBALS['wpdb'] ?? null;

        return \is_object($wpdb) ? $wpdb : null;
    }

    /**
     * Prepares SQL through $wpdb->prepare().
     *
     * @param list<mixed> $params
     */
    public static function prepare(string $sql, array $params = []): string
    {
        $wpdb = self::wpdb();

        if ($wpdb === null) {
            throw new TemplateException('$wpdb is not available.');
        }

        return $params === [] ? $sql : (string) $wpdb->prepare($sql, ...$params);
    }

    /**
     * @param list<mixed> $params
     */
    public static function query(string $sql, array $params = []): int|bool
    {
        $wpdb = self::wpdb() ?? throw new TemplateException('$wpdb is not available.');

        return $wpdb->query(self::prepare($sql, $params));
    }

    /**
     * @param list<mixed> $params
     */
    public static function getVar(string $sql, array $params = []): mixed
    {
        $wpdb = self::wpdb() ?? throw new TemplateException('$wpdb is not available.');

        return $wpdb->get_var(self::prepare($sql, $params));
    }

    /**
     * @param list<mixed> $params
     * @return array<string, mixed>|null
     */
    public static function getRow(string $sql, array $params = []): ?array
    {
        $wpdb = self::wpdb() ?? throw new TemplateException('$wpdb is not available.');
        $row = $wpdb->get_row(self::prepare($sql, $params), \ARRAY_A);

        return \is_array($row) ? $row : null;
    }

    /**
     * @param list<mixed> $params
     * @return list<array<string, mixed>>
     */
    public static function getResults(string $sql, array $params = []): array
    {
        $wpdb = self::wpdb() ?? throw new TemplateException('$wpdb is not available.');
        $rows = $wpdb->get_results(self::prepare($sql, $params), \ARRAY_A);

        return \is_array($rows) ? array_values($rows) : [];
    }

    /**
     * Per-table row counts and byte sizes (information_schema based).
     *
     * @return list<array{table: string, rows: int, bytes: int}>
     */
    public static function tableSizes(): array
    {
        $rows = self::getResults(
            'SELECT TABLE_NAME AS table_name, TABLE_ROWS AS table_rows,
                    (DATA_LENGTH + INDEX_LENGTH) AS bytes
             FROM information_schema.TABLES
             WHERE TABLE_SCHEMA = DATABASE()
             ORDER BY bytes DESC',
        );

        $sizes = [];

        foreach ($rows as $row) {
            $sizes[] = [
                'table' => (string) ($row['table_name'] ?? ''),
                'rows' => (int) ($row['table_rows'] ?? 0),
                'bytes' => (int) ($row['bytes'] ?? 0),
            ];
        }

        return $sizes;
    }

    /**
     * Counts rows of a core table, e.g. posts, postmeta, options.
     */
    public static function countTable(string $table): int
    {
        $wpdb = self::wpdb() ?? throw new TemplateException('$wpdb is not available.');

        if (preg_match('~^[a-z0-9_]+$~i', $table) !== 1) {
            throw new TemplateException('Invalid table name.');
        }

        $prefixed = property_exists($wpdb, 'prefix') ? $wpdb->prefix . $table : $table;

        return (int) self::getVar('SELECT COUNT(*) FROM `' . $prefixed . '`');
    }
}

final class Health
{
    private function __construct() {}

    /**
     * @return list<array{code: string, severity: 'info'|'warning'|'critical', message: string}>
     */
    /**
     * Runs every check; pass the engine to include its diagnostics backlog.
     */
    /**
     * @return list<array{code: string, severity: string, message: string}>
     */
    public static function check(?\HtmlPhp\Engine $engine = null): array
    {
        $issues = [];

        // PHP version support window.
        if (\PHP_VERSION_ID < 80300) {
            $issues[] = self::issue('php-eol', 'critical', 'PHP ' . \PHP_VERSION . ' is below the 8.3 engine requirement.');
        }

        // Debug mode in what looks like production.
        if (\defined('WP_DEBUG') && \WP_DEBUG === true && \defined('WP_DEBUG_DISPLAY') && \WP_DEBUG_DISPLAY === true) {
            $issues[] = self::issue('debug-display', 'warning', 'WP_DEBUG_DISPLAY is on: errors leak into HTML output.');
        }

        // Memory limit.
        $memory = self::iniBytes((string) \ini_get('memory_limit'));

        if ($memory > 0 && $memory < 64 * 1024 * 1024) {
            $issues[] = self::issue('memory-low', 'warning', 'memory_limit is below 64M (' . \ini_get('memory_limit') . ').');
        }

        // Disk space.
        if (\function_exists('wp_upload_dir')) {
            $uploads = wp_upload_dir();
            $base = (string) ($uploads['basedir'] ?? '');

            if ($base !== '' && is_dir($base)) {
                if (!is_writable($base)) {
                    $issues[] = self::issue('uploads-ro', 'critical', 'The uploads directory is not writable.');
                }

                $free = @disk_free_space($base);

                if ($free !== false && $free < 100 * 1024 * 1024) {
                    $issues[] = self::issue('disk-low', 'critical', 'Less than 100 MB of free disk space.');
                } elseif ($free !== false && $free < 512 * 1024 * 1024) {
                    $issues[] = self::issue('disk-low', 'warning', 'Less than 512 MB of free disk space.');
                }
            }
        }

        // Database connectivity.
        $wpdb = $GLOBALS['wpdb'] ?? null;

        if (\is_object($wpdb) && method_exists($wpdb, 'check_connection')) {
            if (!$wpdb->check_connection($silent = true)) {
                $issues[] = self::issue('db-down', 'critical', 'The database connection is not alive.');
            }
        }

        // Cron.
        if (\defined('DISABLE_WP_CRON') && \DISABLE_WP_CRON === true) {
            $issues[] = self::issue('cron-external', 'info', 'DISABLE_WP_CRON is on: make sure a real crontab entry calls wp-cron.php.');
        }

        // Pending updates.
        if (class_exists(Updates::class) && \function_exists('get_site_transient')) {
            $pending = Updates::count();

            if ($pending > 0) {
                $issues[] = self::issue('updates-pending', 'info', $pending . ' update(s) available for core, plugins or themes.');
            }
        }

        // Engine diagnostics backlog.
        if ($engine !== null) {
            $errors = $engine->diagnostics()->count();

            if ($errors > 0) {
                $issues[] = self::issue('engine-errors', 'warning', $errors . ' template diagnostic(s) pending — inspect via $engine->diagnostics().');
            }
        }

        if ($issues === []) {
            $issues[] = self::issue('ok', 'info', 'No problems detected.');
        }

        return $issues;
    }

    /**
     * @return array{code: string, severity: string, message: string}
     */
    private static function issue(string $code, string $severity, string $message): array
    {
        return ['code' => $code, 'severity' => $severity, 'message' => $message];
    }

    /**
     * Parses shorthand byte values ("256M", "1G").
     */
    public static function iniBytes(string $value): int
    {
        $value = trim($value);

        if ($value === '' || $value === '-1') {
            return $value === '-1' ? \PHP_INT_MAX : 0;
        }

        if (preg_match('~^(\d+(?:\.\d+)?)\s*([kmg]?)b?$~i', $value, $m) !== 1) {
            return (int) $value;
        }

        $factor = match (strtolower($m[2])) {
            'g' => 1024 ** 3,
            'm' => 1024 ** 2,
            'k' => 1024,
            default => 1,
        };

        return (int) ((float) $m[1] * $factor);
    }
}

final class Logs
{
    private const array LEVELS = ['debug', 'info', 'warning', 'error', 'critical'];

    private function __construct() {}

    public static function directory(): string
    {
        $configured = \defined('HTML_WP_LOG_DIR') ? \constant('HTML_WP_LOG_DIR') : null;

        if (\is_string($configured) && $configured !== '') {
            return rtrim($configured, "/\\");
        }

        if (\function_exists('wp_upload_dir')) {
            $uploads = wp_upload_dir();
            $base = (string) ($uploads['basedir'] ?? '');

            if ($base !== '' && is_dir($base)) {
                return rtrim($base, "/\\") . \DIRECTORY_SEPARATOR . 'html-php-logs';
            }
        }

        return sys_get_temp_dir() . \DIRECTORY_SEPARATOR . 'html-php-logs';
    }

    public static function file(): string
    {
        return self::directory() . \DIRECTORY_SEPARATOR . 'html-php-' . date('Y-m-d') . '.log';
    }

    /**
     * @param array<string, mixed> $context
     */
    public static function write(string $level, string $message, array $context = []): bool
    {
        $level = \in_array($level, self::LEVELS, true) ? $level : 'info';
        $directory = self::directory();

        if (!is_dir($directory) && !@mkdir($directory, 0o755, true) && !is_dir($directory)) {
            return false;
        }

        $line = \sprintf(
            "[%s] %s: %s%s\n",
            date('Y-m-d H:i:s'),
            strtoupper($level),
            $message,
            $context === [] ? '' : ' ' . (string) json_encode($context, \JSON_UNESCAPED_SLASHES | \JSON_UNESCAPED_UNICODE),
        );

        $written = @file_put_contents(self::file(), $line, \FILE_APPEND | \LOCK_EX);

        self::rotate();

        return $written !== false;
    }

    /** @param array<string, mixed> $context */
    public static function info(string $message, array $context = []): bool
    {
        return self::write('info', $message, $context);
    }

    /** @param array<string, mixed> $context */
    public static function error(string $message, array $context = []): bool
    {
        return self::write('error', $message, $context);
    }

    /**
     * Keeps only the newest N log files.
     */
    public static function rotate(int $keep = 14): int
    {
        $keep = max(1, $keep);
        $files = (array) glob(self::directory() . \DIRECTORY_SEPARATOR . 'html-php-*.log');
        $files = array_values(array_filter($files, 'is_string'));
        sort($files);

        $removed = 0;

        while (\count($files) > $keep) {
            $oldest = (string) array_shift($files);

            if (@unlink($oldest)) {
                ++$removed;
            }
        }

        return $removed;
    }

    /**
     * Tail of today's log (newest last).
     *
     * @return list<string>
     */
    public static function tail(int $lines = 50): array
    {
        $file = self::file();

        if (!is_file($file)) {
            return [];
        }

        $content = (string) @file_get_contents($file);
        $all = array_values(array_filter(explode("\n", $content), static fn(string $l): bool => trim($l) !== ''));

        return \array_slice($all, -$lines);
    }
}

final class Nonces
{
    private function __construct() {}

    public static function create(string $action = 'htmlphp_action'): string
    {
        self::requireWordPress();

        return (string) wp_create_nonce($action);
    }

    public static function verify(?string $nonce, string $action = 'htmlphp_action'): bool
    {
        self::requireWordPress();

        if (!\is_string($nonce) || $nonce === '') {
            return false;
        }

        return (bool) wp_verify_nonce($nonce, $action);
    }

    /**
     * Verifies the request nonce from $_REQUEST['_wpnonce'] and dies-safe
     * returns false otherwise; use inside form handlers.
     */
    public static function verifyRequest(string $action = 'htmlphp_action'): bool
    {
        $nonce = isset($_REQUEST['_wpnonce']) ? (string) $_REQUEST['_wpnonce'] : null;

        return self::verify($nonce, $action);
    }

    public static function field(string $action = 'htmlphp_action', string $name = '_wpnonce'): string
    {
        self::requireWordPress();

        $escape = static fn(string $value): string => \function_exists('esc_attr')
            ? esc_attr($value)
            : htmlspecialchars($value, \ENT_QUOTES);

        return '<input type="hidden" id="' . $escape($name) . '" name="' . $escape($name)
            . '" value="' . $escape(self::create($action)) . '" />';
    }

    private static function requireWordPress(): void
    {
        if (!\function_exists('wp_create_nonce')) {
            throw new TemplateException('WordPress nonce API is not available.');
        }
    }
}

final class Notices
{
    private const string QUEUE_KEY = 'notices_queue';
    private static bool $installed = false;

    private function __construct() {}

    /**
     * Queues a notice for the next admin screen.
     *
     * @param string $type one of info|success|warning|error; anything else
     *                     is normalised to "info"
     */
    public static function add(string $text, string $type = 'info', bool $dismissible = true): void
    {
        $type = \in_array($type, ['info', 'success', 'warning', 'error'], true) ? $type : 'info';
        $queue = Options::getArray(self::QUEUE_KEY);
        $queue[] = ['text' => $text, 'type' => $type, 'dismissible' => $dismissible];
        Options::set(self::QUEUE_KEY, \array_slice($queue, -50));
    }

    public static function install(): void
    {
        if (self::$installed || !\function_exists('add_action')) {
            return;
        }

        add_action('admin_notices', [self::class, 'render']);
        self::$installed = true;
    }

    /**
     * Renders and clears the queue (called from admin_notices).
     */
    public static function render(): void
    {
        $queue = Options::getArray(self::QUEUE_KEY);

        if ($queue === []) {
            return;
        }

        Options::delete(self::QUEUE_KEY);

        $escape = static fn(string $value): string => \function_exists('esc_attr')
            ? esc_attr($value)
            : htmlspecialchars($value, \ENT_QUOTES);

        foreach ($queue as $notice) {
            $class = 'notice notice-' . (\is_string($notice['type'] ?? null) ? $notice['type'] : 'info');
            $class .= !empty($notice['dismissible']) ? ' is-dismissible' : '';

            echo '<div class="' . $escape($class) . '"><p>'
                . $escape((string) ($notice['text'] ?? '')) . '</p></div>';
        }
    }

    /**
     * The queued notices without rendering them (tests, CLI).
     *
     * @return list<array{text: string, type: string, dismissible: bool}>
     */
    public static function queued(): array
    {
        return Options::getArray(self::QUEUE_KEY);
    }

    public static function reset(): void
    {
        self::$installed = false;
    }
}

final class Options
{
    private function __construct() {}

    public static function get(string $key, mixed $default = null, string $prefix = 'htmlphp_'): mixed
    {
        if (!\function_exists('get_option')) {
            return $GLOBALS['htmlphp_options'][$prefix . $key] ?? $default;
        }

        $value = get_option($prefix . $key, $default);

        return $value === false ? $default : $value;
    }

    public static function set(string $key, mixed $value, string $prefix = 'htmlphp_'): bool
    {
        if (!\function_exists('update_option')) {
            $GLOBALS['htmlphp_options'][$prefix . $key] = $value;

            return true;
        }

        return (bool) update_option($prefix . $key, $value);
    }

    public static function delete(string $key, string $prefix = 'htmlphp_'): bool
    {
        if (!\function_exists('delete_option')) {
            unset($GLOBALS['htmlphp_options'][$prefix . $key]);

            return true;
        }

        return (bool) delete_option($prefix . $key);
    }

    public static function getInt(string $key, int $default = 0, string $prefix = 'htmlphp_'): int
    {
        $value = self::get($key, $default, $prefix);

        return is_numeric($value) ? (int) $value : $default;
    }

    public static function getBool(string $key, bool $default = false, string $prefix = 'htmlphp_'): bool
    {
        $value = self::get($key, $default, $prefix);

        return \is_bool($value) ? $value : filter_var($value, \FILTER_VALIDATE_BOOL);
    }

    /**
     * @return array<array-key, mixed>
     */
    public static function getArray(string $key, string $prefix = 'htmlphp_'): array
    {
        $value = self::get($key, [], $prefix);

        return \is_array($value) ? $value : [];
    }
}

final class Rest
{
    private function __construct() {}

    /**
     * Registers a route; refusing registrations without an explicit
     * permission callback is intentional (WP security guideline).
     */
    public static function route(
        string $namespace,
        string $route,
        callable $handler,
        string $methods = 'GET',
        ?callable $permission = null,
    ): void {
        if (!\function_exists('register_rest_route')) {
            throw new TemplateException('The REST API is not available.');
        }

        register_rest_route($namespace, $route, [
            'methods' => $methods,
            'callback' => $handler,
            'permission_callback' => $permission ?? static fn(): bool => current_user_can('manage_options'),
        ]);
    }

    /**
     * Standard JSON success envelope.
     *
     * @return array{success: true, data: mixed}
     */
    public static function ok(mixed $data): array
    {
        return ['success' => true, 'data' => $data];
    }

    /**
     * Standard JSON error envelope.
     *
     * @return array{success: false, code: string, message: string}
     */
    public static function fail(string $code, string $message): array
    {
        return ['success' => false, 'code' => $code, 'message' => $message];
    }
}

final class SystemInfo
{
    private function __construct() {}

    /**
     * @return array<string, mixed>
     */
    public static function collect(?\HtmlPhp\Engine $engine = null): array
    {
        global $wp_version, $wpdb;

        $info = [
            'wordpress' => [
                'version' => \is_string($wp_version ?? null)
                    ? $wp_version
                    : (\function_exists('get_bloginfo') ? (string) get_bloginfo('version') : 'unknown'),
                'multisite' => \function_exists('is_multisite') ? (bool) is_multisite() : false,
                'locale' => \function_exists('determine_locale') ? (string) determine_locale() : '',
                'debug' => \defined('WP_DEBUG') && \WP_DEBUG === true,
                'script_debug' => \defined('SCRIPT_DEBUG') && \SCRIPT_DEBUG === true,
                'cron_disabled' => \defined('DISABLE_WP_CRON') && \DISABLE_WP_CRON === true,
                'memory_limit' => \defined('WP_MEMORY_LIMIT') ? (string) \WP_MEMORY_LIMIT : '',
                'site_url' => \function_exists('home_url') ? (string) home_url('/') : '',
                'active_theme' => self::themeName(),
                'plugins_active' => self::activePlugins(),
                'db_version' => \is_object($wpdb ?? null) && property_exists($wpdb, 'db_version')
                    ? (string) $wpdb->db_version
                    : '',
                'db_charset' => \is_object($wpdb ?? null) && property_exists($wpdb, 'charset')
                    ? (string) $wpdb->charset
                    : '',
            ],
            'php' => [
                'version' => \PHP_VERSION,
                'sapi' => \PHP_SAPI,
                'memory_limit' => (string) \ini_get('memory_limit'),
                'max_execution_time' => (string) \ini_get('max_execution_time'),
                'upload_max_filesize' => (string) \ini_get('upload_max_filesize'),
                'post_max_size' => (string) \ini_get('post_max_size'),
                'opcache' => \function_exists('opcache_get_status')
                    && (bool) \ini_get('opcache.enable'),
                'extensions' => self::relevantExtensions(),
            ],
            'server' => [
                'software' => (string) ($_SERVER['SERVER_SOFTWARE'] ?? \PHP_OS_FAMILY),
                'os' => \PHP_OS . ' ' . php_uname('m'),
                'disk_free' => self::diskFree(),
                'time' => date('c'),
                'timezone' => date_default_timezone_get(),
            ],
            'engine' => [
                'version' => \HtmlPhp\Version::banner(),
                'php' => \PHP_VERSION,
                'loaded_catalogues' => $engine !== null && $engine->translator() instanceof \HtmlPhp\I18n\Translator
                    ? $engine->translator()->stats()
                    : [],
                'pending_errors' => $engine?->diagnostics()->count() ?? 0,
            ],
        ];

        return $info;
    }

    /**
     * @return list<string>
     */
    private static function relevantExtensions(): array
    {
        $wanted = ['mbstring', 'intl', 'iconv', 'curl', 'gd', 'imagick', 'zip', 'openssl', 'json', 'mysqli', 'pdo_mysql', 'opcache'];
        $loaded = [];

        foreach ($wanted as $extension) {
            if (\extension_loaded($extension)) {
                $loaded[] = $extension;
            }
        }

        return $loaded;
    }

    private static function themeName(): string
    {
        if (!\function_exists('wp_get_theme')) {
            return '';
        }

        $theme = wp_get_theme();

        return method_exists($theme, 'get') ? (string) $theme->get('Name') : '';
    }

    /**
     * @return list<string>
     */
    private static function activePlugins(): array
    {
        if (!\function_exists('get_option')) {
            return [];
        }

        $plugins = get_option('active_plugins', []);

        return \is_array($plugins) ? array_values(array_map('strval', $plugins)) : [];
    }

    private static function diskFree(): string
    {
        if (!\function_exists('wp_upload_dir')) {
            return '';
        }

        $uploads = wp_upload_dir();
        $base = (string) ($uploads['basedir'] ?? '');

        if ($base === '' || !is_dir($base)) {
            return '';
        }

        $free = @disk_free_space($base);

        return $free === false ? '' : (string) $free;
    }
}

final class Transients
{
    private function __construct() {}

    public static function get(string $key, mixed $default = null, string $prefix = 'htmlphp_'): mixed
    {
        if (!\function_exists('get_transient')) {
            return $default;
        }


        $value = get_transient($prefix . $key);

        return $value === false ? $default : $value;
    }

    public static function set(string $key, mixed $value, int $ttl = 3600, string $prefix = 'htmlphp_'): bool
    {
        if (!\function_exists('set_transient')) {
            return false;
        }


        return (bool) set_transient($prefix . $key, $value, max(1, $ttl));
    }

    public static function delete(string $key, string $prefix = 'htmlphp_'): bool
    {
        if (!\function_exists('delete_transient')) {
            return false;
        }


        return (bool) delete_transient($prefix . $key);
    }

    /**
     * get-or-compute with a TTL: the standard maintenance cache pattern.
     */
    public static function remember(string $key, int $ttl, callable $factory, string $prefix = 'htmlphp_'): mixed
    {
        $sentinel = "\0htmlphp-miss\0";
        $cached = self::get($key, $sentinel, $prefix);

        if ($cached !== $sentinel) {
            return $cached;
        }

        $value = $factory();
        self::set($key, $value, $ttl, $prefix);

        return $value;
    }
}

final class Updates
{
    private function __construct() {}

    /**
     * @return array{core: list<array<string, mixed>>, plugins: list<array<string, mixed>>, themes: list<array<string, mixed>>, last_checked: ?int}
     */
    public static function check(): array
    {
        $result = ['core' => [], 'plugins' => [], 'themes' => [], 'last_checked' => null];

        if (!\function_exists('get_site_transient')) {
            return $result;
        }

        $core = get_site_transient('update_core');

        if (\is_object($core)) {
            $result['last_checked'] = isset($core->last_checked) ? (int) $core->last_checked : null;

            foreach ((array) ($core->updates ?? []) as $update) {
                if (\is_object($update) && ($update->response ?? '') === 'upgrade') {
                    $result['core'][] = [
                        'version' => (string) ($update->version ?? ''),
                        'php' => (string) ($update->php_version ?? ''),
                        'locale' => (string) ($update->locale ?? ''),
                    ];
                }
            }
        }

        $plugins = get_site_transient('update_plugins');

        if (\is_object($plugins)) {
            foreach ((array) ($plugins->response ?? []) as $file => $update) {
                if (!\is_object($update)) {
                    continue;
                }

                $result['plugins'][] = [
                    'file' => (string) $file,
                    'slug' => (string) ($update->slug ?? ''),
                    'new_version' => (string) ($update->new_version ?? ''),
                ];
            }
        }

        $themes = get_site_transient('update_themes');

        if (\is_object($themes)) {
            foreach ((array) ($themes->response ?? []) as $slug => $update) {
                $result['themes'][] = [
                    'slug' => (string) $slug,
                    'new_version' => (string) (\is_array($update) ? ($update['new_version'] ?? '') : ''),
                ];
            }
        }

        return $result;
    }

    public static function count(): int
    {
        $update = self::check();

        return \count($update['core']) + \count($update['plugins']) + \count($update['themes']);
    }
}

}

namespace HtmlPhp\WordPress {

use HtmlPhp\Config;
use HtmlPhp\Config\Log as LogConfig;
use HtmlPhp\Container;
use HtmlPhp\Contracts\CacheInterface;
use HtmlPhp\Diagnostics;
use HtmlPhp\Engine;
use HtmlPhp\I18n\Auditor;
use HtmlPhp\I18n\Extractor;
use HtmlPhp\Log\AbstractLogger;
use HtmlPhp\Support\Str;
use HtmlPhp\Template\RenderOptions;
use HtmlPhp\Template\RenderStats;
use HtmlPhp\WordPress\Maintenance\Health;
use HtmlPhp\WordPress\Maintenance\Logs;
use HtmlPhp\WordPress\Maintenance\Nonces;
use HtmlPhp\WordPress\Maintenance\Options;
use HtmlPhp\WordPress\Maintenance\SystemInfo;

/**
 * Tools → “HTML.PHP” admin screen.
 *
 * Tabs: Health, Templates (lint), Cache, i18n (extract/audit), Logs, Info.
 * When a template named `admin/htmlphp/{tab}.html` exists in any configured
 * template path it is rendered through the engine itself (dog-fooding);
 * otherwise a minimal built-in markup is produced. All mutating actions go
 * through `admin_post_htmlphp_action` with a nonce and `manage_options`.
 */
final class AdminPage
{
    public const string SLUG = 'htmlphp';
    public const string NONCE_ACTION = 'htmlphp_admin';

    private static ?Engine $engine = null;

    private function __construct() {}

    public static function install(Engine $engine): void
    {
        self::$engine = $engine;

        if (!\function_exists('add_management_page')) {
            return;
        }

        add_management_page(
            'HTML.PHP',
            'HTML.PHP',
            'manage_options',
            self::SLUG,
            static fn(): string => self::renderPage(),
        );
    }

    /** POST endpoint (admin_post_htmlphp_action). */
    public static function handlePost(Engine $engine): void
    {
        self::$engine = $engine;

        if (!Nonces::verifyRequest(self::NONCE_ACTION) || !self::capable()) {
            self::redirect('error');

            return;
        }

        $action = (string) ($_POST['htmlphp_action'] ?? '');

        switch ($action) {
            case 'cache_clear':
                $engine->clearCache();
                Maintenance\Notices::add('HTML.PHP render cache cleared.', 'success');
                break;

            case 'log_rotate':
                Maintenance\Logs::rotate(7);
                Maintenance\Notices::add('HTML.PHP logs rotated.', 'success');
                break;
        }

        self::redirect('done', ['tab' => (string) ($_POST['tab'] ?? 'health')]);
    }

    private static function renderPage(): string
    {
        $engine = self::$engine ?? Bridge::engine();

        if (!self::capable()) {
            return '<p>Insufficient permissions.</p>';
        }

        $tab = self::currentTab();

        // Dog-fooding: prefer an engine template when the site provides one.
        $template = $engine->locator()->locate('admin/htmlphp/' . $tab . '.html');

        if ($template !== null) {
            try {
                return $engine->renderFile($template, [
                    'tab' => $tab,
                    'tabs' => self::tabs(),
                    'data' => self::tabData($engine, $tab),
                    'nonce_field' => Nonces::field(self::NONCE_ACTION),
                    'admin_post_url' => \function_exists('admin_url') ? admin_url('admin-post.php') : '',
                    'page_url' => \function_exists('admin_url') ? admin_url('tools.php?page=' . self::SLUG) : '',
                ]);
            } catch (\Throwable) {
                // fall through to the built-in markup
            }
        }

        return self::builtinPage($engine, $tab);
    }

    /** @return list<array{id: string, label: string}> */
    public static function tabs(): array
    {
        return [
            ['id' => 'health', 'label' => 'Health'],
            ['id' => 'templates', 'label' => 'Templates'],
            ['id' => 'cache', 'label' => 'Cache'],
            ['id' => 'i18n', 'label' => 'i18n'],
            ['id' => 'logs', 'label' => 'Logs'],
            ['id' => 'info', 'label' => 'Info'],
        ];
    }

    private static function currentTab(): string
    {
        $tab = isset($_GET['tab']) && \is_scalar($_GET['tab']) ? (string) $_GET['tab'] : 'health';

        foreach (self::tabs() as $entry) {
            if ($entry['id'] === $tab) {
                return $tab;
            }
        }

        return 'health';
    }

    /** @return array<string, mixed> */
    public static function tabData(Engine $engine, string $tab): array
    {
        return match ($tab) {
            'health' => ['findings' => Health::check($engine)],
            'templates' => ['lint' => self::lintReport($engine), 'roots' => $engine->config()->templates->paths],
            'cache' => [
                'driver' => $engine->config()->cache->driver->value,
                'enabled' => $engine->config()->cache->enabled,
            ],
            'i18n' => [
                'locale' => $engine->locale(),
                'catalogues' => $engine->translator() instanceof \HtmlPhp\I18n\Translator
                    ? $engine->translator()->stats()
                    : [],
            ],
            'logs' => ['tail' => Logs::tail(30), 'file' => Logs::file()],
            'info' => ['info' => SystemInfo::collect($engine), 'version' => $engine->version()],
            default => [],
        };
    }

    /** @return array<string, list<array<string, mixed>>> */
    private static function lintReport(Engine $engine): array
    {
        $report = [];

        foreach ($engine->config()->templates->paths as $root) {
            if (!is_dir($root)) {
                continue;
            }

            foreach ($engine->lintDirectory($root) as $file => $issues) {
                $report[$file] = array_map(
                    static fn(\HtmlPhp\Template\LintIssue $issue): array => $issue->toArray(),
                    $issues,
                );
            }
        }

        return $report;
    }

    private static function builtinPage(Engine $engine, string $tab): string
    {
        $esc = static fn(mixed $value): string => htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $url = \function_exists('admin_url') ? admin_url('tools.php?page=' . self::SLUG) : '';

        $nav = '';
        foreach (self::tabs() as $entry) {
            $active = $entry['id'] === $tab ? ' class="current"' : '';
            $nav .= \sprintf(
                '<a href="%s&amp;tab=%s"%s>%s</a> | ',
                $esc($url),
                $esc($entry['id']),
                $active,
                $esc($entry['label']),
            );
        }

        $body = match ($tab) {
            'health' => self::healthHtml($engine),
            'templates' => self::templatesHtml($engine),
            'cache' => self::cacheHtml($engine),
            'i18n' => self::i18nHtml($engine),
            'logs' => self::logsHtml(),
            default => self::infoHtml($engine),
        };

        return '<div class="wrap"><h1>HTML.PHP ' . $esc(\HtmlPhp\Version::VERSION) . '</h1>'
            . '<p>' . rtrim($nav, ' | ') . '</p>'
            . $body
            . '</div>';
    }

    private static function healthHtml(Engine $engine): string
    {
        $rows = '';

        foreach (Health::check($engine) as $finding) {
            $rows .= \sprintf(
                '<li><strong>%s</strong> [%s] %s</li>',
                htmlspecialchars((string) ($finding['code'] ?? ''), ENT_QUOTES, 'UTF-8'),
                htmlspecialchars((string) ($finding['severity'] ?? ''), ENT_QUOTES, 'UTF-8'),
                htmlspecialchars((string) ($finding['message'] ?? ''), ENT_QUOTES, 'UTF-8'),
            );
        }

        return '<h2>Health</h2><ul>' . $rows . '</ul>';
    }

    private static function templatesHtml(Engine $engine): string
    {
        $report = self::lintReport($engine);

        if ($report === []) {
            return '<h2>Templates</h2><p>All template roots lint clean.</p>';
        }

        $out = '<h2>Templates</h2><ul>';

        foreach ($report as $file => $issues) {
            $out .= '<li><code>' . htmlspecialchars((string) $file, ENT_QUOTES, 'UTF-8') . '</code><ul>';

            foreach ($issues as $issue) {
                $out .= \sprintf(
                    '<li>[%s] line %d: %s (%s)</li>',
                    htmlspecialchars((string) ($issue['severity'] ?? ''), ENT_QUOTES, 'UTF-8'),
                    (int) ($issue['line'] ?? 0),
                    htmlspecialchars((string) ($issue['message'] ?? ''), ENT_QUOTES, 'UTF-8'),
                    htmlspecialchars((string) ($issue['code'] ?? ''), ENT_QUOTES, 'UTF-8'),
                );
            }

            $out .= '</ul></li>';
        }

        return $out . '</ul>';
    }

    private static function cacheHtml(Engine $engine): string
    {
        $form = self::postForm('cache_clear', 'Clear render cache', 'cache');

        return '<h2>Cache</h2><p>Driver: <code>'
            . htmlspecialchars($engine->config()->cache->driver->value, ENT_QUOTES, 'UTF-8')
            . '</code> (' . ($engine->config()->cache->enabled ? 'enabled' : 'disabled') . ')</p>' . $form;
    }

    private static function i18nHtml(Engine $engine): string
    {
        $stats = $engine->translator() instanceof \HtmlPhp\I18n\Translator
            ? $engine->translator()->stats()
            : [];

        $rows = '';

        foreach ($stats as $domain => $locales) {
            foreach ($locales as $locale => $count) {
                $rows .= \sprintf(
                    '<li><code>%s/%s</code>: %d message(s)</li>',
                    htmlspecialchars((string) $domain, ENT_QUOTES, 'UTF-8'),
                    htmlspecialchars((string) $locale, ENT_QUOTES, 'UTF-8'),
                    (int) $count,
                );
            }
        }

        return '<h2>i18n</h2><p>Locale: <code>' . htmlspecialchars($engine->locale(), ENT_QUOTES, 'UTF-8')
            . '</code></p><ul>' . ($rows !== '' ? $rows : '<li>No catalogues loaded.</li>') . '</ul>'
            . '<p>Run <code>wp htmlphp i18n audit &lt;dir&gt;</code> for missing/unused analysis.</p>';
    }

    private static function logsHtml(): string
    {
        $tail = Logs::tail(30);
        $lines = $tail === [] ? '<li>No log entries.</li>' : '';

        foreach ($tail as $line) {
            $lines .= '<li><code>' . htmlspecialchars((string) $line, ENT_QUOTES, 'UTF-8') . '</code></li>';
        }

        return '<h2>Logs</h2><ul>' . $lines . '</ul>' . self::postForm('log_rotate', 'Rotate logs (keep 7)', 'logs');
    }

    private static function infoHtml(Engine $engine): string
    {
        $info = SystemInfo::collect($engine);
        $out = '<h2>Info</h2>';

        foreach ($info as $section => $values) {
            $out .= '<h3>' . htmlspecialchars((string) $section, ENT_QUOTES, 'UTF-8') . '</h3><ul>';

            foreach ((array) $values as $key => $value) {
                $out .= \sprintf(
                    '<li><strong>%s</strong>: <code>%s</code></li>',
                    htmlspecialchars((string) $key, ENT_QUOTES, 'UTF-8'),
                    htmlspecialchars(\is_scalar($value) || $value === null ? (string) $value : (string) json_encode($value), ENT_QUOTES, 'UTF-8'),
                );
            }

            $out .= '</ul>';
        }

        return $out;
    }

    private static function postForm(string $action, string $label, string $tab): string
    {
        $url = \function_exists('admin_url') ? admin_url('admin-post.php') : '';

        return '<form method="post" action="' . htmlspecialchars($url, ENT_QUOTES, 'UTF-8') . '">'
            . '<input type="hidden" name="action" value="htmlphp_action">'
            . '<input type="hidden" name="htmlphp_action" value="' . htmlspecialchars($action, ENT_QUOTES, 'UTF-8') . '">'
            . '<input type="hidden" name="tab" value="' . htmlspecialchars($tab, ENT_QUOTES, 'UTF-8') . '">'
            . Nonces::field(self::NONCE_ACTION)
            . '<button class="button">' . htmlspecialchars($label, ENT_QUOTES, 'UTF-8') . '</button>'
            . '</form>';
    }

    private static function capable(): bool
    {
        return !\function_exists('current_user_can') || current_user_can('manage_options');
    }

    /** @param array<string, string> $query */
    private static function redirect(string $status, array $query = []): void
    {
        if (!\function_exists('wp_safe_redirect') || !\function_exists('admin_url')) {
            return;
        }

        $url = admin_url('tools.php?page=' . self::SLUG . '&htmlphp=' . $status);

        foreach ($query as $key => $value) {
            $url .= '&' . $key . '=' . rawurlencode($value);
        }

        wp_safe_redirect($url);

        if (\function_exists('exit_after_redirect')) {
            exit_after_redirect();
        }
    }
}

/**
 * The WordPress bootstrap — the *only* place in the library that owns a
 * process-wide Engine instance (a plugin lifecycle needs one; plain PHP
 * hosts construct engines explicitly and never touch this class).
 *
 * ```php
 * // in your plugin, on plugins_loaded:
 * HtmlPhp\WordPress\Bridge::boot([
 *     'templates' => ['paths' => [__DIR__ . '/templates']],
 * ], shortcode: 'htmlphp');
 *
 * echo htmlphp_render('card.html', ['title' => get_the_title()]);
 * ```
 *
 * Booting wires: WP-flavoured config defaults (theme template dirs, uploads
 * cache dir, WP object-cache backend, rotating log, WP i18n delegation),
 * engine→WP event mirroring (`htmlphp.render` → `apply_filters('htmlphp_render')`),
 * the admin bar stats node (debug only), optional `the_content` SSI filter,
 * WP-CLI commands and the admin screen.
 */
final class Bridge
{
    private static ?Engine $engine = null;
    private static bool $booted = false;

    /** @var array<string, mixed> */
    private static array $options = [];

    private function __construct() {}

    /**
     * Boots (once) and returns the engine.
     *
     * @param Config|array<string, mixed> $config engine configuration; WP
     *        defaults are merged underneath, yours win
     * @param (callable(Container): void)|null $setup container overrides
     * @param array<string, mixed> $options bridge behaviour:
     *        `shortcode` (string|null — register `[shortcode]` with a
     *        `template` attribute), `content_ssi` (bool, default false —
     *        run SSI over `the_content`), `admin_bar` (bool, default
     *        WP_DEBUG), `cli` (bool, default true), `admin_page`
     *        (bool, default true), `mirror_events` (bool, default true)
     */
    public static function boot(Config|array $config = [], ?callable $setup = null, array $options = []): Engine
    {
        if (self::$booted && self::$engine !== null) {
            return self::$engine;
        }

        self::$options = $options + [
            'shortcode' => null,
            'content_ssi' => false,
            'admin_bar' => \defined('WP_DEBUG') && (bool) \constant('WP_DEBUG'),
            'cli' => true,
            'admin_page' => true,
            'mirror_events' => true,
        ];

        $config = $config instanceof Config ? $config->toArray() : $config;
        $engine = Engine::create(self::mergeDefaults($config), static function (Container $container) use ($setup): void {
            if ($setup !== null) {
                $setup($container);
            }
        });

        self::$engine = $engine;
        self::$booted = true;

        self::installHooks($engine);

        return $engine;
    }

    /**
     * WordPress-flavoured defaults under the caller's config.
     *
     * @param array<string, mixed> $config
     * @return array<string, mixed>
     */
    private static function mergeDefaults(array $config): array
    {
        $paths = $config['templates']['paths'] ?? [];
        $themePaths = [];

        if (\function_exists('get_stylesheet_directory')) {
            $themePaths[] = rtrim((string) get_stylesheet_directory(), '/\\') . '/htmlphp';
        }

        if (\function_exists('get_template_directory')) {
            $themePaths[] = rtrim((string) get_template_directory(), '/\\') . '/htmlphp';
        }

        $defaults = [
            'templates' => [
                'paths' => [...$themePaths, ...$paths],
            ],
            'ssi' => [
                'document_root' => \defined('ABSPATH') ? rtrim((string) \constant('ABSPATH'), '/\\') : null,
            ],
            'cache' => [
                'enabled' => true,
                'driver' => \function_exists('wp_cache_get') ? 'wordpress' : 'file',
                'directory' => self::uploadsCacheDir(),
            ],
            'log' => [
                'driver' => 'wordpress',
                'level' => 'warning',
            ],
        ];

        $merged = self::mergeDeep($defaults, $config);

        // document_root null is invalid for the strict config reader; drop it.
        if (($merged['ssi']['document_root'] ?? null) === null) {
            unset($merged['ssi']['document_root']);
        }

        return $merged;
    }

    /**
     * @param array<array-key, mixed> $base
     * @param array<array-key, mixed> $overrides
     * @return array<array-key, mixed>
     */
    private static function mergeDeep(array $base, array $overrides): array
    {
        foreach ($overrides as $key => $value) {
            if (\is_array($value) && isset($base[$key]) && \is_array($base[$key])) {
                $base[$key] = self::mergeDeep($base[$key], $value);
                continue;
            }

            $base[$key] = $value;
        }

        return $base;
    }

    private static function uploadsCacheDir(): string
    {
        if (\function_exists('wp_upload_dir')) {
            $uploads = wp_upload_dir();
            $base = (string) ($uploads['basedir'] ?? '');

            if ($base !== '') {
                return $base . '/htmlphp-cache';
            }
        }

        return sys_get_temp_dir() . '/htmlphp-cache';
    }

    private static function installHooks(Engine $engine): void
    {
        if (!\function_exists('add_action')) {
            return;
        }

        if (self::$options['mirror_events']) {
            self::mirrorEvents($engine);
        }

        if (\is_string(self::$options['shortcode']) && self::$options['shortcode'] !== '') {
            self::registerGenericShortcode($engine, (string) self::$options['shortcode']);
        }

        if (self::$options['content_ssi']) {
            add_filter('the_content', static function (string $content) use ($engine): string {
                if (!str_contains($content, '<!--#')) {
                    return $content;
                }

                try {
                    return $engine->processSsi($content);
                } catch (\Throwable $error) {
                    $engine->diagnostics()->record(
                        Diagnostics::WP_BRIDGE,
                        'Content SSI failed: ' . $error->getMessage(),
                    );

                    return $content;
                }
            }, 10, 1);
        }

        if (self::$options['admin_bar']) {
            add_action('admin_bar_menu', static function (mixed $bar) use ($engine): void {
                $stats = $engine->stats();

                if (!$stats instanceof RenderStats || !\is_object($bar) || !method_exists($bar, 'add_node')) {
                    return;
                }

                $bar->add_node([
                    'id' => 'htmlphp-stats',
                    'title' => \sprintf('HTML.PHP %.2fms/%d tpl', $stats->durationMs, \count($stats->templates)),
                    'href' => admin_url('tools.php?page=htmlphp'),
                ]);
            }, 999);
        }

        if (self::$options['cli'] && class_exists('\WP_CLI')) {
            \WP_CLI::add_command('htmlphp', Cli::class);
        }

        if (self::$options['admin_page']) {
            add_action('admin_menu', static function () use ($engine): void {
                AdminPage::install($engine);
            });
            add_action('admin_post_htmlphp_action', static function () use ($engine): void {
                AdminPage::handlePost($engine);
            });
        }
    }

    /**
     * Mirrors the engine's tagged events onto WordPress hooks so themes and
     * plugins can filter without knowing the engine exists.
     */
    private static function mirrorEvents(Engine $engine): void
    {
        $dispatcher = $engine->events();

        $dispatcher->on('htmlphp.render', static function (string $text, string $origin) {
            return \function_exists('apply_filters') ? apply_filters('htmlphp_render', $text, $origin) : $text;
        }, 1000);

        $dispatcher->on('htmlphp.error', static function (string $code, string $message, array $context): void {
            if (\function_exists('do_action')) {
                do_action('htmlphp_error', $code, $message, $context);
            }
        });

        $dispatcher->on('htmlphp.translate', static function (string $text, string $msgid, string $domain, string $locale) {
            return \function_exists('apply_filters')
                ? apply_filters('htmlphp_translate', $text, $msgid, $domain, $locale)
                : $text;
        }, 1000);
    }

    /**
     * `[tag template="card.html" key="value"]` — generic template shortcode.
     * The template name resolves through {@see TemplateLoader} and the
     * engine locator; attributes become variables.
     */
    private static function registerGenericShortcode(Engine $engine, string $tag): void
    {
        $tag = preg_replace('~[^a-z0-9_-]~i', '', $tag) ?? '';

        if ($tag === '' || !\function_exists('add_shortcode')) {
            return;
        }

        add_shortcode($tag, static function (mixed $atts, mixed $content = null) use ($engine): string {
            $attributes = \is_array($atts) ? $atts : [];
            $template = '';

            if (isset($attributes['template']) && \is_scalar($attributes['template'])) {
                $template = (string) $attributes['template'];
                unset($attributes['template']);
            }

            if ($template === '') {
                return '';
            }

            $vars = ['content' => \is_string($content) ? $content : ''];

            foreach ($attributes as $key => $value) {
                if (\is_string($key) && \HtmlPhp\Support\Str::isValidVariableName($key)) {
                    $vars[$key] = \is_scalar($value) || $value === null ? $value : '';
                }
            }

            try {
                $path = TemplateLoader::locate($template);

                return $path !== null
                    ? $engine->renderFile($path, $vars, new \HtmlPhp\Template\RenderOptions(file: $path))
                    : $engine->render($template, $vars);
            } catch (\Throwable $error) {
                $engine->diagnostics()->record(
                    Diagnostics::WP_BRIDGE,
                    'Shortcode render failed: ' . $error->getMessage(),
                    ['template' => $template],
                );

                return '';
            }
        });
    }

    public static function engine(): Engine
    {
        if (self::$engine === null) {
            throw new \RuntimeException(
                'HtmlPhp\WordPress\Bridge is not booted — call Bridge::boot() on plugins_loaded.',
            );
        }

        return self::$engine;
    }

    public static function booted(): bool
    {
        return self::$booted;
    }

    /** Drops the singleton (tests, and only tests). */
    public static function reset(): void
    {
        self::$engine = null;
        self::$booted = false;
        self::$options = [];
    }
}

/**
 * WP-CLI commands: `wp htmlphp …`
 *
 * Registered by {@see Bridge} when WP-CLI is present. Every command goes
 * through the booted engine — no private state.
 *
 *   wp htmlphp info                     versions, paths, catalogue stats
 *   wp htmlphp render <template> [--var=k:v]…
 *   wp htmlphp lint [<path>]            template or directory; exit 1 on errors
 *   wp htmlphp cache clear|size
 *   wp htmlphp i18n extract <dir> [--out=messages.pot]
 *   wp htmlphp i18n audit <dir> [--locale=de] [--domain=messages]
 *   wp htmlphp health                   actionable findings
 */
final class Cli
{
    /**
     * @param list<string> $args
     * @param array<string, mixed> $assoc
     */
    public function info(array $args = [], array $assoc = []): void
    {
        $engine = Bridge::engine();
        $info = SystemInfo::collect($engine);

        if (!empty($assoc['json'])) {
            $this->line((string) json_encode($info, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));

            return;
        }

        foreach (['wordpress', 'php', 'server', 'engine'] as $section) {
            $this->line('== ' . strtoupper($section) . ' ==');

            foreach ((array) ($info[$section] ?? []) as $key => $value) {
                $this->line(\sprintf('  %-22s %s', (string) $key, $this->flat($value)));
            }
        }
    }

    /**
     * @param list<string> $args
     * @param array<string, mixed> $assoc
     */
    public function render(array $args, array $assoc = []): void
    {
        $template = (string) ($args[0] ?? '');

        if ($template === '') {
            $this->error('Usage: wp htmlphp render <template> [--var=k:v]…');

            return;
        }

        $vars = [];

        foreach ((array) ($assoc['var'] ?? []) as $pair) {
            $parts = explode('=', (string) $pair, 2);

            if (\count($parts) === 2) {
                $vars[$parts[0]] = $parts[1];
            }
        }

        $engine = Bridge::engine();

        try {
            $path = TemplateLoader::locate($template);
            $out = $path !== null
                ? $engine->renderFile($path, $vars)
                : $engine->renderString($template, $vars);

            $this->line($out);
        } catch (\Throwable $error) {
            $this->error('Render failed: ' . $error->getMessage());
        }
    }

    /**
     * @param list<string> $args
     * @param array<string, mixed> $assoc
     */
    public function lint(array $args, array $assoc = []): void
    {
        $target = (string) ($args[0] ?? '');
        $engine = Bridge::engine();
        $hasErrors = false;

        if ($target === '') {
            foreach ($engine->config()->templates->paths as $root) {
                $hasErrors = $this->lintDirectory($engine, $root) || $hasErrors;
            }
        } elseif (is_dir($target)) {
            $hasErrors = $this->lintDirectory($engine, $target);
        } else {
            $path = TemplateLoader::locate($target) ?? $target;
            $issues = is_file($path) ? $engine->linter()->lintFile($path) : $engine->lint($target);

            foreach ($issues as $issue) {
                $this->report($issue->severity, $issue->format());
                $hasErrors = $hasErrors || $issue->isError();
            }
        }

        $hasErrors
            ? $this->error('Lint found errors.')
            : $this->success('Lint clean.');
    }

    private function lintDirectory(Engine $engine, string $dir): bool
    {
        $hasErrors = false;

        foreach ($engine->lintDirectory($dir) as $file => $issues) {
            foreach ($issues as $issue) {
                $this->report($issue->severity, $issue->format());
                $hasErrors = $hasErrors || $issue->isError();
            }
        }

        return $hasErrors;
    }

    /**
     * @param list<string> $args
     * @param array<string, mixed> $assoc
     */
    public function cache(array $args, array $assoc = []): void
    {
        $action = (string) ($args[0] ?? 'clear');
        $engine = Bridge::engine();

        if ($action === 'clear') {
            $removed = $engine->clearCache();
            $this->success(\sprintf('Removed %d cache entr%s.', $removed, $removed === 1 ? 'y' : 'ies'));

            return;
        }

        $this->error('Unknown cache action: ' . $action);
    }

    /**
     * @param list<string> $args
     * @param array<string, mixed> $assoc
     */
    public function i18n(array $args, array $assoc = []): void
    {
        $action = (string) ($args[0] ?? '');
        $dir = (string) ($args[1] ?? '');
        $engine = Bridge::engine();

        if ($dir === '' || !is_dir($dir)) {
            $this->error('Usage: wp htmlphp i18n extract|audit <template-dir> [--out=file] [--locale=de] [--domain=messages]');

            return;
        }

        $extractor = new Extractor();
        $files = $extractor->scanDirectory($dir, ltrim($engine->config()->templates->extension, '.'));

        if ($action === 'extract') {
            $pot = $extractor->toPo();
            $out = (string) ($assoc['out'] ?? '');

            if ($out !== '') {
                file_put_contents($out, $pot) === false
                    ? $this->error('Cannot write ' . $out)
                    : $this->success(\sprintf('Wrote %d message(s) from %d file(s) to %s.', \count($extractor->entries()), \count($files), $out));

                return;
            }

            $this->line($pot);

            return;
        }

        if ($action === 'audit') {
            $locale = (string) ($assoc['locale'] ?? $engine->locale());
            $domain = (string) ($assoc['domain'] ?? $engine->config()->i18n->domain);
            $translator = $engine->translator();

            if (!$translator instanceof \HtmlPhp\I18n\Translator) {
                $this->error('Audit needs the built-in translator (WP delegation has no local catalogue store).');

                return;
            }

            $report = (new Auditor($translator))->audit($extractor->entries(), $locale, $domain);

            foreach (Auditor::format($report) as $line) {
                $this->line($line);
            }

            foreach ($extractor->dynamicHits() as $hit) {
                $this->report('warning', 'dynamic translate at ' . $hit);
            }

            return;
        }

        $this->error('Unknown i18n action: ' . $action);
    }

    /**
     * @param list<string> $args
     * @param array<string, mixed> $assoc
     */
    public function health(array $args = [], array $assoc = []): void
    {
        foreach (Health::check(Bridge::engine()) as $finding) {
            $severity = (string) ($finding['severity'] ?? 'info');
            $this->report($severity, \sprintf('%s — %s', (string) ($finding['code'] ?? ''), (string) ($finding['message'] ?? '')));
        }
    }

    // ---------------------------------------------------------------- output

    private function report(string $severity, string $line): void
    {
        if (!class_exists('\WP_CLI')) {
            echo $line, "\n";

            return;
        }

        match ($severity) {
            'error', 'critical' => \WP_CLI::warning($line),
            'warning' => \WP_CLI::warning($line),
            default => \WP_CLI::log($line),
        };
    }

    private function line(string $text): void
    {
        class_exists('\WP_CLI') ? \WP_CLI::line($text) : print($text . "\n");
    }

    private function success(string $text): void
    {
        class_exists('\WP_CLI') ? \WP_CLI::success($text) : print($text . "\n");
    }

    private function error(string $text): void
    {
        if (class_exists('\WP_CLI')) {
            \WP_CLI::error($text);

            return;
        }

        fwrite(STDERR, $text . "\n");
    }

    /** @param mixed $value */
    private function flat($value): string
    {
        if (\is_scalar($value) || $value === null) {
            return (string) $value;
        }

        return (string) json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    }
}

/**
 * Templated email helper: render subject + body through the engine and
 * hand them to `wp_mail()`.
 *
 * ```php
 * Mailer::send('user@example.com', 'emails/welcome-subject.html', 'emails/welcome.html', [
 *     'name' => $user->display_name,
 * ]);
 * ```
 *
 * Both subject and body are templates; the body is rendered with SSI
 * enabled but auto-escaping appropriate for the `html` content type that
 * is set automatically (pass `$headers` to override).
 */
final class Mailer
{
    private function __construct() {}

    /**
     * @param string|list<string> $to
     * @param array<string, mixed> $vars
     * @param string|list<string> $headers extra headers (Content-Type is added unless present)
     * @param string|list<string> $attachments
     */
    public static function send(
        Engine $engine,
        string|array $to,
        string $subjectTemplate,
        string $bodyTemplate,
        array $vars = [],
        string|array $headers = [],
        string|array $attachments = [],
    ): bool {
        if (!\function_exists('wp_mail')) {
            return false;
        }

        // Subjects are plain text: render without HTML auto-escaping.
        $subject = trim(self::render($engine, $subjectTemplate, $vars, false));
        $body = self::render($engine, $bodyTemplate, $vars, true);

        // wp_mail accepts "string | string[]" for both; normalise once, here.
        $headerList = \is_string($headers) ? ($headers !== '' ? [$headers] : []) : array_values($headers);
        $attachmentList = \is_string($attachments)
            ? ($attachments !== '' ? [$attachments] : [])
            : array_values($attachments);

        $hasContentType = false;

        foreach ($headerList as $header) {
            if (\is_string($header) && stripos($header, 'content-type:') === 0) {
                $hasContentType = true;
                break;
            }
        }

        if (!$hasContentType) {
            $headerList[] = 'Content-Type: text/html; charset=UTF-8';
        }

        return (bool) wp_mail($to, $subject, $body, $headerList, $attachmentList);
    }

    /**
     * Renders a template by locator name, file path or inline string
     * (`@{key}` subjects often need no file at all).
     *
     * @param array<string, mixed> $vars
     */
    public static function render(Engine $engine, string $template, array $vars = [], bool $autoEscape = true): string
    {
        $options = new \HtmlPhp\Template\RenderOptions(autoEscape: $autoEscape);

        if (strpbrk($template, "\n") !== false || str_contains($template, '%{') || str_contains($template, '@{')) {
            return $engine->renderString($template, $vars, $options);
        }

        $path = TemplateLoader::locate($template) ?? $engine->locator()->locate($template);

        if ($path !== null) {
            return $engine->renderFile($path, $vars, $options);
        }

        return $engine->renderString($template, $vars, $options);
    }
}

/**
 * `[tag attr="value"]` shortcodes backed by engine templates.
 *
 * Attributes become scoped variables (invalid names are dropped), the
 * enclosed content is available as `%{content}`. Render failures never
 * take the page down: they return `''` and record a diagnostic.
 */
final class Shortcodes
{
    public function __construct(private readonly Engine $engine) {}

    /**
     * @param array<string, mixed> $defaults merged under the shortcode attributes
     */
    public function register(string $tag, string $template, array $defaults = []): void
    {
        $tag = preg_replace('~[^a-z0-9_-]~i', '', $tag) ?? '';

        if ($tag === '' || !\function_exists('add_shortcode')) {
            return;
        }

        $engine = $this->engine;

        $handler = static function (mixed $atts, mixed $content = null) use ($engine, $template, $defaults): string {
            $vars = $defaults;

            if (\is_array($atts)) {
                foreach ($atts as $key => $value) {
                    if (\is_string($key) && Str::isValidVariableName($key)) {
                        $vars[$key] = \is_scalar($value) || $value === null ? $value : '';
                    }
                }
            }

            $vars['content'] = \is_string($content) ? $content : '';

            try {
                $path = TemplateLoader::locate($template) ?? $template;

                return $engine->renderFile($path, $vars, new RenderOptions(file: $path));
            } catch (\Throwable $error) {
                $engine->diagnostics()->record(
                    Diagnostics::WP_BRIDGE,
                    'Shortcode render failed: ' . $error->getMessage(),
                    ['template' => $template],
                );

                return '';
            }
        };

        add_shortcode($tag, $handler);
    }
}

/**
 * WordPress-aware template discovery + rendering.
 *
 * Search order: child theme → parent theme (through `locate_template()`)
 * → the extra directories you pass. Unlike v3, `.php` files are never
 * treated as templates: a template is data, and rendering PHP source as
 * text would leak it.
 */
final class TemplateLoader
{
    /** Suffixes tried for a bare slug, in order. */
    private const array SUFFIXES = ['.ssi.htm', '.ssi.html', '.ssi', '.htm', '.html', '.tpl'];

    public function __construct(private readonly \HtmlPhp\Engine $engine) {}

    /**
     * Finds the first existing template among candidate names.
     *
     * Search order: child theme → parent theme (locate_template when
     * available) → each directory in $dirs.
     *
     * @param string|list<string> $names
     * @param list<string> $dirs
     */
    public static function locate(string|array $names, array $dirs = []): ?string
    {
        $names = \is_string($names) ? [$names] : $names;
        $candidates = [];

        foreach ($names as $name) {
            if ($name === '' || str_contains($name, "\0")) {
                continue;
            }

            // A template is data: script files are never located, even when
            // asked for by name (source-disclosure guard).
            $extension = strtolower(pathinfo($name, PATHINFO_EXTENSION));

            if (\in_array($extension, ['php', 'phtml', 'phar', 'php3', 'php4', 'php5', 'php7', 'php8', 'phps'], true)) {
                continue;
            }

            $candidates[] = $name;

            if (!str_contains($name, '.')) {
                foreach (self::SUFFIXES as $suffix) {
                    $candidates[] = $name . $suffix;
                }
            }
        }

        if ($candidates === []) {
            return null;
        }

        if (\function_exists('locate_template')) {
            $found = (string) locate_template($candidates);

            if ($found !== '' && is_file($found)) {
                return $found;
            }
        }

        foreach ($dirs as $dir) {
            if (!\is_string($dir) || !is_dir($dir)) {
                continue;
            }

            foreach ($candidates as $candidate) {
                $path = rtrim($dir, '/\\') . \DIRECTORY_SEPARATOR
                    . str_replace(['/', '\\'], \DIRECTORY_SEPARATOR, ltrim($candidate, '/\\'));

                if (is_file($path)) {
                    return $path;
                }
            }
        }

        foreach ($candidates as $candidate) {
            if (is_file($candidate)) {
                return $candidate;
            }
        }

        return null;
    }


    /**
     * Renders the first located template among $names with WP context vars.
     *
     * @param string|list<string> $names
     * @param array<string, mixed> $vars
     * @param list<string> $dirs
     */
    public function render(string|array $names, array $vars = [], array $dirs = []): string
    {
        $path = self::locate($names, $dirs);

        if ($path === null) {
            throw new \HtmlPhp\Exception\TemplateNotFoundException(
                'No WordPress template could be located.',
                ['names' => (array) $names],
            );
        }

        return $this->engine->renderFile(
            $path,
            $this->withWordPressContext($vars),
            new \HtmlPhp\Template\RenderOptions(file: $path),
        );
    }

    /**
     * get_template_part()-style rendering that returns the markup instead
     * of echoing it (slug + optional name, e.g. `content` + `single`).
     * Missing parts are a diagnostic, not a fatal — theme convention.
     *
     * @param array<string, mixed> $vars
     */
    public function renderPart(string $slug, ?string $name = null, array $vars = []): string
    {
        $names = $name !== null && $name !== '' ? [$slug . '-' . $name, $slug] : [$slug];

        $dirs = [];

        if (\function_exists('get_stylesheet_directory')) {
            $dirs[] = (string) get_stylesheet_directory() . '/template-parts';
            $dirs[] = (string) get_stylesheet_directory();
        }

        $path = self::locate($names, $dirs);

        if ($path === null) {
            $this->engine->diagnostics()->record(
                \HtmlPhp\Diagnostics::WP_BRIDGE,
                'Template part not found.',
                ['slug' => $slug, 'name' => $name ?? ''],
            );

            return '';
        }

        return $this->engine->renderFile(
            $path,
            $this->withWordPressContext($vars),
            new \HtmlPhp\Template\RenderOptions(file: $path),
        );
    }

    /**
     * Adds `wp_*` context variables every theme template can rely on.
     *
     * @param array<string, mixed> $vars
     * @return array<string, mixed>
     */
    private function withWordPressContext(array $vars): array
    {
        $context = [];

        if (\function_exists('get_bloginfo')) {
            $context['wp_blogname'] = (string) get_bloginfo('name');
            $context['wp_description'] = (string) get_bloginfo('description');
            $context['wp_version'] = (string) get_bloginfo('version');
            $context['wp_charset'] = (string) get_bloginfo('charset');
            $context['wp_language'] = (string) get_bloginfo('language');
        }

        if (\function_exists('home_url')) {
            $context['wp_home_url'] = (string) home_url('/');
        }

        $context['wp_locale'] = $this->engine->locale();
        $context['wp_year'] = date('Y');

        return $vars + $context;
    }
}

/**
 * WordPress cache backend.
 *
 * Two tiers: the object cache (`wp_cache_*`, group `htmlphp`) for fast
 * in-request/persistent hits when a drop-in is installed, and transients
 * for guaranteed cross-request persistence on plain installs. Keys are
 * tracked in an option so {@see self::clear()} can actually enumerate
 * them — something neither tier can do on its own.
 *
 * Multisite: options and transients are per-site by default; the group is
 * suffixed with the blog id to keep sites apart in shared object caches.
 */
final class WpCache implements CacheInterface
{
    private const string GROUP_BASE = 'htmlphp';
    private const string REGISTRY_KEY = 'cache_keys';
    private const int REGISTRY_CAP = 1000;

    private string $group;

    public function __construct(
        private readonly string $prefix = 'htmlphp',
        private readonly int $defaultTtl = 0,
        private readonly ?Diagnostics $diagnostics = null,
    ) {
        $blogId = \function_exists('get_current_blog_id') ? (int) get_current_blog_id() : 0;
        $this->group = self::GROUP_BASE . ($blogId > 0 ? '_' . $blogId : '');
    }

    public function get(string $key): ?string
    {
        if (!\function_exists('wp_cache_get')) {
            return null;
        }

        $found = false;
        $value = wp_cache_get($this->objectKey($key), $this->group, false, $found);

        if ($found && \is_string($value)) {
            return $value;
        }

        if (\function_exists('get_transient')) {
            $stored = get_transient($this->prefix . ':' . $key);

            if (\is_string($stored)) {
                wp_cache_set($this->objectKey($key), $stored, $this->group);

                return $stored;
            }
        }

        return null;
    }

    public function set(string $key, string $value, int $ttl = 0): bool
    {
        if (!\function_exists('wp_cache_set')) {
            $this->diagnostics?->record(
                Diagnostics::CACHE_IO,
                'WordPress object cache unavailable; entry was not stored.',
                ['key' => $key],
            );

            return false;
        }

        $ttl = $ttl > 0 ? $ttl : $this->defaultTtl;

        wp_cache_set($this->objectKey($key), $value, $this->group, $ttl > 0 ? $ttl : 0);

        if (\function_exists('set_transient')) {
            set_transient($this->prefix . ':' . $key, $value, $ttl > 0 ? $ttl : 0);
        }

        $this->register($key);

        return true;
    }

    public function has(string $key): bool
    {
        return $this->get($key) !== null;
    }

    public function delete(string $key): bool
    {
        if (\function_exists('wp_cache_delete')) {
            wp_cache_delete($this->objectKey($key), $this->group);
        }

        if (\function_exists('delete_transient')) {
            delete_transient($this->prefix . ':' . $key);
        }

        $this->unregister($key);

        return true;
    }

    public function clear(): int
    {
        $keys = Options::getArray(self::REGISTRY_KEY);
        $removed = 0;

        foreach ($keys as $key) {
            if (\is_string($key)) {
                $this->delete($key);
                $removed++;
            }
        }

        Options::set(self::REGISTRY_KEY, []);

        return $removed;
    }

    private function objectKey(string $key): string
    {
        return $this->prefix . ':' . $key;
    }

    private function register(string $key): void
    {
        $keys = Options::getArray(self::REGISTRY_KEY);

        if (\in_array($key, $keys, true)) {
            return;
        }

        $keys[] = $key;

        if (\count($keys) > self::REGISTRY_CAP) {
            $keys = \array_slice($keys, -self::REGISTRY_CAP);
        }

        Options::set(self::REGISTRY_KEY, $keys);
    }

    private function unregister(string $key): void
    {
        $keys = Options::getArray(self::REGISTRY_KEY);
        $keys = array_values(array_filter($keys, static fn($k): bool => $k !== $key));
        Options::set(self::REGISTRY_KEY, $keys);
    }
}

/**
 * WordPress logger: rotating daily files under `{uploads}/html-php-logs/`
 * (via {@see Logs}) plus an `error_log()` mirror when `WP_DEBUG_LOG` is on,
 * so entries also land in `wp-content/debug.log`.
 */
final class WpLogger extends AbstractLogger
{
    public function __construct(
        private readonly string $channel = 'htmlphp',
        private readonly string $minLevel = 'warning',
    ) {}

    /** @param array<string, mixed> $context */
    public function log(string $level, string $message, array $context = []): void
    {
        if (!LogConfig::levelAccepted($this->minLevel, $level)) {
            return;
        }

        $line = $this->interpolate($message, $context);

        if ($context !== []) {
            $encoded = json_encode($context, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
            $line .= ' ' . ($encoded === false ? '{}' : $encoded);
        }

        if (class_exists(Logs::class)) {
            Logs::write($level, $line);
        }

        if (\defined('WP_DEBUG_LOG') && \constant('WP_DEBUG_LOG')) {
            error_log(\sprintf('[%s] %s.%s', $this->channel, $level, $line));
        }
    }
}

}

